window.ENAMED_LOCAL_QUESTION_BANK=window.ENAMED_LOCAL_QUESTION_BANK||{};window.ENAMED_LOCAL_QUESTION_BANK["med:med-clinica-medica-med-clm-21"]={"block":"med:med-clinica-medica-med-clm-21","label":"MED · MED CLM 21","count":488,"questions":[{"id":"med-clinica-medica-med-clm-21-345447","number":"345447","sourceNumber":"345447","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Paciente de 36 anos, feminino, apresenta história de boca e olhos secos há um ano.\nEla também refere sudorese noturna e fadiga.\nAtualmente não faz uso de medicação. No exame\nfísico apresenta discreto aumento das glândulas parótidas e a mucosa oral está seca, pálida e com\nlábios fissurados. Há alguma hiperemia das conjuntivas e o restante do exame físico não\napresentou alterações. Exames complementares iniciais: FAN = 1/160 (normal até 1/80); anticorpo\nanti-Ro/SSA = reagente; eletroforese de proteínas = normal; complemento sérico (C3 e C4) =\nnormais; ultrassonografia das parótidas mostrou áreas hipoecoicas múltiplas. O melhor diagnóstico\npara essa paciente é:","options":{"A":"Linfoma.","B":"Lúpus eritematoso sistêmico.","C":"Arterite de Takayassu.","D":"Síndrome de Sjögren."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-283269","number":"283269","sourceNumber":"283269","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Paciente do sexo feminino, 23 anos, refere aumento de volume de região parotidea\ncom associação à xerostomia, xeroftalmia e\nhiperemia conjuntival. Refere ainda dor articular de\npadrão inflamatório e dor difusa com pontos gatilho. Nega sintomas genitourinários. Em relação às\nhipóteses diagnósticas, assinale a alternativa CORRETA.","options":{"A":"Doença de Behçet.","B":"Doença de Wegener.","C":"Lúpus eritematoso sistêmico.","D":"Síndrome de Sjögren."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-247149","number":"247149","sourceNumber":"247149","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Em pacientes com esclerose sistêmica, a presença de anticorpos antitopoisomerase I\nestá associada à:","options":{"A":"Forma limitada e hipertensão pulmonar.","B":"Forma limitada e melhor prognóstico de doença com maior acometimento vascular.","C":"Forma difusa, envolvimento pulmonar e maior mortalidade.","D":"Miosite e ulcerações digitais.","E":"Forma difusa e crise renal esclerodérmica."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-217691","number":"217691","sourceNumber":"217691","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Uma paciente de 23 anos de idade procurou o pronto-socorro por quadro de edema há\ntrês semanas. Referiu que, inicialmente, o edema se localizava em membros inferiores, porém,\napós duas semanas, já estava generalizado, até em face. Relatou ainda ter ganhado peso e ter\nusado anti-inflamatórios para dor de cabeça uma semana antes do quadro, mas negou quaisquer\noutras queixas. Na investigação, foram realizados os seguintes exames: hemograma; creatinina;\nureia; urina 1; relação proteína/creatinina em amostra isolada; complemento sérico; FAN e\nsorologias para hepatite B, C e HIV. Os únicos exames alterados foram: urina 1, com proteinúria\n\n+++ e discretas hemácias dismórficas, relação proteína/creatinina igual a 6 g/g e FAN positivo\n(padrão nuclear homogêneo altos títulos). Foi\nrealizada biópsia renal, que mostrou uma\nglomerulonefrite membranosa, com uma imunofluorescência rica em deposição de IgG, IgM, C1q,\nC3 e C4 (padrão full house). Nessa situação hipotética, o diagnóstico etiológico do quadro é de:","options":{"A":"Glomerulonefrite membranosa idiopática.","B":"Lúpus eritematoso sistêmico.","C":"Síndrome de Goodpasture.","D":"HIV em janela imunológica."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-182627","number":"182627","sourceNumber":"182627","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"NÃO é considerado critério diagnóstico de Lúpus Eritematoso Sistêmico:","options":{"A":"Complemento sérico baixo.","B":"Ascite.","C":"Anemia hemolítica.","D":"Úlceras orais."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-183133","number":"183133","sourceNumber":"183133","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"À doença de Behçet, é CORRETO afirmar que:","options":{"A":"Homens e mulheres são igualmente afetados na população japonesa.","B":"Uma das características menores da doença é o eritema nodoso.","C":"O envolvimento unilocular é visto em 50% dos casos.","D":"Neovascularização pode estar associada com vasculite retiniana.","E":"Associado com uveítes tem um bom prognóstico visual."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-159074","number":"159074","sourceNumber":"159074","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"NÃO se constitui em critério para diagnóstico da Doença de Kawasaki:","options":{"A":"Febre por mais de 5 dias.","B":"Conjuntivite exudativa.","C":"Linfadenomegalia cervical.","D":"Descamação de extremidades."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-159131","number":"159131","sourceNumber":"159131","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Advogada de 26 anos, refere que há 4 meses iniciou cansaço, mal estar geral e queda\nde cabelo; atribuía todos os sintomas ao\nestresse do trabalho. Porém, há duas semanas iniciou dor\nnos punhos, interfalangeanas proximais e joelhos, acompanhada de rigidez matinal de 1 hora e\nurina \"espumosa\". História familiar: irmão faleceu por lúpus há 8 anos. História prévia: G2PN0C0A2\nespontâneos. Ao exame: REG; úlcera região palato (indolor); queda de mais de 3 fios de cabelo à\ntração; AR: MV reduzido em bases; AC: BRNF 2T sem sopros; artrite visível em punhos e joelhos;\nFC 102 bpm; FR 20 irpm; PA = 160 x 100mmHg. Exames: Hb: 8; Ht 25%; VCM: 110; Leuco: 6.300\n(linf 10% seg 86%); Plaquetas: 143.000; creatinina: 1,5 mg/dl; EAS: proteínas +++; hemácias ++;\ncilindros +; FAN: negativo; C3: 50 (80-100); C4: 7 (20-40); Coombs direto positivo; Fator\nreumatoide: positivo. Neste caso, NÃO podemos afirmar que:","options":{"A":"O anti CCP se mostra útil neste caso para auxiliar no diagnóstico diferencial entre artrite\nreumatoide e lúpus, já que o padrão de dor articular fala mais a favor de artrite reumatoide.","B":"O exame do FAN por ser negativo não confere um prognóstico melhor para a doença.","C":"A dosagem dos anticorpos da Síndrome do anticorpo antifosfolípide não se faz necessária, pois\no lúpus não afeta a fertilidade, mas aumenta o risco de perda fetal, mesmo na ausência de SAAF.","D":"A anemia macricítica (VCM: 110), no caso acima, é muito sugestiva de anemia hemolítica\nautoimune, mas existem descritas outras causas\nde anemia macrocítica como deficiência de ácido\nfólico."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-135977","number":"135977","sourceNumber":"135977","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Pré-escolar de 4 anos dá entrada em unidade de saúde com queixa de febre diária\n38°C há 10 dias, dor em membros inferiores,\npetéquias difusas e aumento de volume abdominal.\nHemograma com 15.000 leucócitos, Bastões 0%, segmentados 10%, Linfócitos 85%, Monócitos\n\n5%, Hb 8,5%, VCM 90, HCM 32, Plaquetas 85.000. Qual o diagnóstico mais provável?","options":{"A":"Meningite meningocócica;","B":"Aplasia de medula óssea;","C":"Anemia carencial;","D":"Leucose aguda;"},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-84528","number":"84528","sourceNumber":"84528","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Correlacione as COLAGENOSES com seus respectivos sinais e sintomas. 1) Mulher de\nmeia-idade, com episódios de cianose nas mãos quando exposta ao frio e disfagia; 2) Paciente\njovem com poliartrite simétrica em punhos e interfalangianas, lesões eritematosas em face e\nhemograma apresentando leucopenia e linfopenia; 3) Mulher jovem com história de abortamento\nespontâneo ou parto prematuro prévio; 4) Colagenose que se caracteriza pela infiltração linfocitária\nde origem autoimune, das glândulas lacrimais e salivares; 5) Doença inflamatória que acomete ao\nmesmo tempo músculos esqueléticos e pele, podendo estar associada a uma neoplasia aguda. ( )\nLúpus eritematoso sistêmico; ( ) Síndrome do anticorpo antifosfolipídeo; ( ) Dermatomiosite; ( )\nSíndrome de Sjögren; ( ) Esclerodermia. A sequência CORRETA é:","options":{"A":"2 - 3 - 4 - 5 - 1.","B":"2 - 3 - 5 - 4 - 1.","C":"4 - 2 - 3 - 5 - 1.","D":"3 - 5 - 4 - 1 - 2.","E":"2 - 4 - 1 - 5 - 3."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-29415","number":"29415","sourceNumber":"29415","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"A presença de manifestação hemorrágica nos pacientes com leucemia aguda está\nrelacionada a:","options":{"A":"Hepatoesplenomegalia.","B":"Infecções oportunistas.","C":"Recidiva pós-tratamento.","D":"Lise tumoral.","E":"Trombocitopenia."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-29368","number":"29368","sourceNumber":"29368","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Paciente de 58 anos, sexo masculino, com quadro de fadiga, perda de peso, sudorese\ne febrícula. No exame físico apresenta palidez,\nesplenomegalia volumosa e manifestações\nhemorrágicas. O hemograma revela leucocitose de 50.000/ul com predomínio dos mielócitos. Tem\ncomo característica a presença do cromossomo Philadelphia:","options":{"A":"Síndrome mielodisplásica","B":"Leucemia Linfocítica aguda","C":"Leucemia Mielocítica Crônica","D":"Reação leucemoide","E":"Leucemia Mielocítica Aguda"},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-343188","number":"343188","sourceNumber":"343188","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Mulher, 30 anos, queixando-se de dor em membro superior esquerdo após esforços, de\ninício há 6 meses. Associa ao mesmo período episódios de febre, diária, não aferida e cefaleias\nesporádicas de resolução espontânea. Neste intervalo apresentou crises hipertensivas importantes.\nNega comorbidades. Nega tabagismo/etilismo. Ao exame físico encontra-se em bom estado geral,\nbulhas rítmicas em 2 tempos, sem sopros audíveis, pressão arterial sistólica em repouso de 160\nmmHg, ausculta pulmonar sem alterações. Ao exame: Perfusão lentificada no antebraço esquerdo,\nsem lesões de pele e fâneros, com pulso filiforme da a. braquial. Após coleta de exames séricos,\nnotou-se aumento de provas inflamatórias. A principal hipótese diagnóstica é:","options":{"A":"Esclerodermia vascular.","B":"Doença de Buerguer.","C":"Embolia arterial crônica.","D":"Arterite de Takayasu."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-343189","number":"343189","sourceNumber":"343189","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Mulher, 30 anos, queixando-se de dor em membro superior esquerdo após esforços, de\ninício há 6 meses. Associa ao mesmo período episódios de febre, diária, não aferida e cefaleias\nesporádicas de resolução espontânea. Neste intervalo apresentou crises hipertensivas importantes.\nNega comorbidades. Nega tabagismo/etilismo. Ao exame físico encontra-se em bom estado geral,\nbulhas rítmicas em 2 tempos, sem sopros audíveis, pressão arterial sistólica em repouso de 160\nmmHg, ausculta pulmonar sem alterações. Ao exame: Perfusão lentificada no antebraço esquerdo,\nsem lesões de pele e fâneros, com pulso filiforme da a. braquial. Após coleta de exames séricos,\nnotou-se aumento de provas inflamatórias. Das alternativas abaixo, a terapia mais adequada é:","options":{"A":"Corticoterapia e antiagregação plaquetária","B":"Trombólise química","C":"Trombólise mecânica","D":"Anticoagulação"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-283739","number":"283739","sourceNumber":"283739","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Casal jovem, ambos com 33 anos, vem ao consultório porque desejam ter um filho. Ela\né tercigesta, nulípara. Há três anos vem tentando engravidar sem sucesso. Paciente referiu que\nantes ela conseguia engravidar, porém sofreu 3 abortamentos precoces, sendo o último há 4 anos.\nEm todas as gestações os embriões paravam de apresentar batimento cardíaco fetal antes de 9\nsemanas de idade gestacional. Todos os exames hormonais realizados não evidenciaram\nalterações. Cariótipo da paciente e do esposo: normais. Exame de imagem na época do último\nabortamento não evidenciou malformações uterinas. Realizou curetagem uterina no primeiro e no\nterceiro abortamentos. Ciclo menstrual costuma ser regular, porém há 5 meses não menstrua.\n\nSabendo que um dos diagnósticos diferenciais para a causa do abortamento de repetição é a\nSíndrome do Anticorpo Antifosfolipídeo (SAAF), é CORRETO afirmar:","options":{"A":"Para confirmar o diagnóstico para SAAF nessa paciente, ela teria que ter histórico de um evento\ntrombótico.","B":"O diagnóstico de SAAF é baseado em um critério clínico e em dois critérios laboratoriais.","C":"O diagnóstico de SAAF é baseado, além do critério clínico, em um critério laboratorial; exemplo:\nanticoagulante lúpico presente em duas ou mais ocasiões com intervalo de 12 semanas.","D":"O diagnóstico de SAAF é baseado, além do critério clínico, em um critério laboratorial; exemplo:\nanticoagulante lúpico presente em exame isolado."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-212150","number":"212150","sourceNumber":"212150","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Assinale a alternativa CORRETA quanto aos critérios para lúpus eritematoso sistêmico\n(SLICC/ACR ? 2012):","options":{"A":"Complementos C3, C4 e CH50 com valor de referência dentro da normalidade.","B":"Teste de Coombs direto positivo na ausência de hemólise.","C":"Hemograma com presença de linfocitose.","D":"Artralgia em articulações dos punhos.","E":"Creatinina sérica > 2,0 mg/dl."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-212157","number":"212157","sourceNumber":"212157","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Conforme o Consenso de Chapel Hill de 2012, sobre as vasculites, é correto afirmar:","options":{"A":"Arterite de Takayasu é uma inflamação não granulomatosa da aorta e grandes ramos que ocorre\ngeralmente em pacientes acima dos 50 anos.","B":"Granulomatose de Wegner é uma inflamação granulomatosa necrotizante que acomete\npequenos vasos, envolvendo vias aéreas superiores e inferiores, além da glomerulonefrite\ncrescêntica.","C":"Púrpura de Henoch-Schölein é uma inflamação\n\ngranulomatosa e eosinofílica de pequenos vasos, onde os pacientes podem apresentar história de\nasma antecedendo o quadro vasculítico.","D":"Doença de Kawasaki é uma arterite que acomete vasos de médios e pequenos calibres, sendo\ntambém frequente o acometimento das artérias coronarianas; por isso, ocorre em pacientes acima\ndos 50 anos.","E":"Síndrome de Churg-Strauss é uma vasculite com depósitos predominantes de IgA que acomete\npequenos vasos, podendo apresentar envolvimento cutâneo, comprometimento gastrointestinal e\nartrite não deformante."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-216335","number":"216335","sourceNumber":"216335","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Assinale a alternativa que apresenta um fator de risco adquirido transitório para a\ntrombose venosa profunda.","options":{"A":"Próteses valvares.","B":"Doenças renais.","C":"Síndrome de aspiração de mecônio.","D":"Vasculites."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-216224","number":"216224","sourceNumber":"216224","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Assinale a alternativa INCORRETA em relação ao AAS.","options":{"A":"Pode ser usado como profilaxia de trombose no pós-operatório de cirurgia de Fontan.","B":"Usado como profilaxia na doença de Moya Moya.","C":"Usado como profilaxia de trombose na anemia falciforme.","D":"Usado como profilaxia na síndrome antifosfolípede."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-216265","number":"216265","sourceNumber":"216265","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Assinale a alternativa CORRETA sobre o tratamento do Lúpus Eritematoso Sistêmico\nJuvenil.","options":{"A":"Os exercícios de intensidade leve devem ser estimulados, ao passo que os de intensidade\nmoderada a alta devem ser evitados.","B":"As vacinas antipneumocócica e contra HPV são contraindicadas.","C":"O pronto diagnóstico e o tratamento das infecções são essenciais para os pacientes com Lupus\nEritematoso Sistêmico.","D":"O uso de proteção solar apenas em crianças maiores de 6 anos e adolescentes com\nfotossensibilidade e outras lesões cutâneas\n\nrelacionadas à atividade da doença é uma das medidas gerais do tratamento."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-219895","number":"219895","sourceNumber":"219895","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Diante de um paciente com sintomas resultantes do acometimento de vias aéreas altas\ne baixas, sem melhora após uso de\nantimicrobianos, associados a glomerulonefrite e anticorpo\nanticitoplasma de leucócito (ANCA) positivo, está INCORRETO afirmar que:","options":{"A":"A maioria dos pacientes apresenta anemia discreta, leucocitose leve e elevação de proteínas de\nfase aguda.","B":"Assim como infiltrados, nódulos, massas e cavitações pulmonares, derrame pleural e adenopatia\nhilar são achados radiográficos comuns.","C":"Granulomas são raramente observados em biópsia renal, mas são mais comumente\nevidenciados em biópsia pulmonares.","D":"Vários subtipos de ANCA são reconhecidos, mas os dois mais relevantes para vasculite\nsistêmica reagem contra Proteinase-3 (PR3) e Mieloperoxidase (MPO)."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-219846","number":"219846","sourceNumber":"219846","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Qual das seguintes condições é causa MAIS PROVÁVEL de hematúria?","options":{"A":"Acidose tubular renal.","B":"Crioglobulinemia mista.","C":"Estenose de artéria renal bilateral.","D":"Síndrome nefrótica por lesões mínimas."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-212217","number":"212217","sourceNumber":"212217","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"O Lúpus Eritematoso Sistêmico (LES) é uma doença caracterizada por inflamação,\nprodução de anticorpos antinucleares, como o\nanti-DNA da cadeia dupla, além de deposição de\ncomplexos imunes fixadores de complemento, que podem resultar em lesões a praticamente\nqualquer órgão ou tecido. Em aproximadamente 50% dos casos, não há um comprometimento\norgânico significativo, apresentando-se com manifestações predominantemente constitucionais,\ncutâneas ou musculoesqueléticas. Sobre as manifestações clínicas, é correto dizer que","options":{"A":"cerca de 20 a 75% dos pacientes com LES pediátrico desenvolvem nefrite, sendo a grande\nmaioria no primeiro ano de diagnóstico.","B":"o envolvimento pulmonar nos pacientes pediátricos com LES é incomum, sendo a hemorragia\nalveolar o mais habitualmente encontrado.","C":"a anormalidade endócrina mais comum no lúpus é o hipertireoidismo, devendo sua função\ntireoidiana ser avaliada no início da doença e anualmente.","D":"pacientes com LES pediátrico raramente apresentam artralgia e mialgia, que dificilmente se\nresolvem com tratamento, e frequentemente provocam sequelas.","E":"a prevalência das manifestações neuropsiquiátricas é menor do que a observada na doença em\nadultos, sendo os sintomas neurológicos mais comuns no desfecho final da doença."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-180154","number":"180154","sourceNumber":"180154","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Assinale a afirmativa correta sobre as vasculites.","options":{"A":"A granulomatose de Wegener apresenta associação com asma e eosinofilia maior que 10%.","B":"Arterite Temporal e Arterite de Takayasu\nrepresentam vasculites de vasos de médio calibre.","C":"A maioria dos casos de vasculite crioglobulinêmica, anteriormente denominada idiopática, pode\nser\n\natribuídaao virus da Hepatite B.","D":"A vasculite cutânea de pequenos vasos pode\nassociar-se a malignidades, especialmente a\ntumores sólidos.","E":"A vasculite cutânea de pequenos vasos é\n\ncaracterizada por variado espectro de lesões cutâneas, sendo a púrpura palpável a lesão\ndermatológica mais comum."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-181305","number":"181305","sourceNumber":"181305","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Paciente de 25 anos, sexo feminino, foi encaminhada para o ambulatório de\nreumatologia para investigação de\ncolagenose. Relata que há 6 meses iniciou um quadro de fadiga,\nmialgia, artralgia e febre baixa. Durante o exame físico, o residente da clínica médica observou que\na paciente apresentava fenômeno de Raynaud e edema nas mãos. Após discussão detalhada do\nquadro clínico da paciente, a principal hipótese diagnóstica foi Doença Mista do Tecido Conjuntivo\n(DMTC). Dadas as afirmativas: I. A DMTC tem como principal característica sorológica a presença\nde altos títulos do autoanticorpo anti-RNP; II. A neuropatia do trigêmio é a manifestação\nneurológica mais frequente; III. Paciente com DMTC geralmente não apresenta comprometimento\ngrave dos rins; IV. Hipertensão pulmonar corresponde à principal causa de morte em pacientes com\nDMTC. Verifica-se que estão CORRETAS:","options":{"A":"I, II, III e IV.","B":"II e IV, apenas.","C":"II e III, apenas.","D":"I e IV, apenas.","E":"I e III, apenas."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-181322","number":"181322","sourceNumber":"181322","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Paciente de 40 anos, sexo feminino, relata que há 3 anos iniciou um quadro de\nmudança de coloração dos dedos das mãos,\nquando estava exposta ao frio, sem outras queixas.\nDepois evoluiu com pirose e regurgitação alimentar, diariamente. Foi à consulta com\ngastroenterologista que prescreveu um inibidor da bomba de prótons. De forma progressiva,\ncomeçou a apresentar um endurecimento e espessamento da pele limitada às regiões distais, aos\ncotovelos e joelhos, e superiores às clavículas. A paciente ficou muito preocupada e conseguiu\numa consulta no ambulatório da clínica médica. O médico observou durante o exame físico\npresença de esclerodactilia e telangiectasias na face. Solicitou uma radiografia das mãos e\nvisualizou depósitos de cálcio. Diante desse quadro clínico, qual o anticorpo mais frequentemente\nencontrado?","options":{"A":"Anticentrômero.","B":"Anti-histonas.","C":"Anti-Scl-70.","D":"Anti-Sm.","E":"Anti-Ro."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-187772","number":"187772","sourceNumber":"187772","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Paciente sexo feminino, 46 anos, procura atendimento em hospital com queixa principal\nde \"dor no corpo inteiro\". Pela história da\ndoença atual, percebeu-se que as dores são intensas,\ncom início logo ao despertar e duração maior que 18 horas, alternando com dias sem dor e ausente\nem pelo menos 6 meses durante o ano. A história pregressa revelou que a paciente\nfrequentemente acorda com sensação de fadiga, independentemente de estar com dor. É\nportadora de cefaléia de forte intensidade com característica de ser de origem tensional e já fez\nconsulta psiquiátrica para tratamento de depressão. Ao exame físico percebe-se dor a\ndigitopressão em região occipital, músculo trapézio, quadrante superior externo da nádega,\nepicôndilo lateral e joelho (para todos os pontos a dor foi bilateral). Assinale a alternativa\nCORRETA quanto ao diagnóstico MAIS PROVÁVEL:","options":{"A":"Artrite reumatóide","B":"Esclerodermia","C":"Fibromialgia","D":"Gota"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-187783","number":"187783","sourceNumber":"187783","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Paciente sexo feminino, 46 anos, procura atendimento em hospital com queixa principal\nde \"dor no corpo inteiro\". Pela história da\ndoença atual, percebeu-se que as dores são intensas,\ncom início logo ao despertar e duração maior que 18 horas, alternando com dias sem dor e ausente\nem pelo menos 6 meses durante o ano. A história pregressa revelou que a paciente\nfrequentemente acorda com sensação de fadiga, independentemente de estar com dor. É\nportadora de cefaléia com forte intensidade com característica de ser de origem tensional e já fez\nconsulta psiquiátrica para tratamento de depressão. Ao exame físico percebe-se dor a\ndigitopressão em região occipital, músculo trapézio, quadrante superior externo da nádega,\nepicôndilo lateral e joelho (para todos os pontos a dor foi bilateral). Assinale a alternativa\nCORRETA quanto à terapia a ser instituída:","options":{"A":"Agentes antibióticos por 30 dias como doxiciclina por via oral","B":"Colchicina, anti-inflamatório não hormonal e aplicação de compressa gelada","C":"Tratar comorbidades, evitar opioides e utilizar medicação analgésica que promova sono como a\namitriptilina","D":"Utilizar cloreto de vinilia, bleomicina e pentazocina"},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-187855","number":"187855","sourceNumber":"187855","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Paciente com 50 anos, sexo feminino, informando dificuldade para lacrimejar e\nnecessidade de ingestão de líquido para deglutir. A história pregressa revelou que é portadora de\nartrite reumatoide. Resultados dos exames trazidos pela paciente: anticorpos antinuclear,\n\nanti-SSA/Ro e anti-SSB/La positivos; proteína C reativa elevada; e velocidade de\neritrosedimentação elevada. Assinale a\nalternativa CORRETA para o diagnóstico MAIS PROVÁVEL\nda doença:","options":{"A":"Granulotamose de Wegner","B":"Polimiosite","C":"Purpura de Henoch-schönlein","D":"Síndrome de Sjögren"},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-181375","number":"181375","sourceNumber":"181375","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"O lúpus eritematoso sistêmico é caracterizado por desregulação tanto da imunidade\nsistêmica quanto da adquirida. Na pediatria, acomete preferencialmente meninas na puberdade.\nQuanto às suas manifestações clínicas, é correto afirmar:","options":{"A":"crianças com lúpus eritematoso sistêmico frequentemente apresentam artralgia e mialgia, que\nusualmente provocam sequelas.","B":"a vasculite observada na doença cérebro-vascular lúpica é tipicamente de grandes vasos,\nfacilmente identificada em angiografia.","C":"o envolvimento pulmonar é incomum na criança lúpica; quando presente há predomínio do\npadrão restritivo ou prejuízo da difusão.","D":"manifestações gastrointestinais são frequentes e incluem dor abdominal, diarreia e/ou vômitos. A\npancreatite aguda é rara, mas potencialmente fatal.","E":"na pediatria, é normalmente mais grave que o do adulto e deve ser considerado em crianças\ncom febre prolongada, sem foco infeccioso, com\nserosites, visceromegalias, lesões cutâneas\nfotossensíveis e quadros neuropsiquiátrico de início recente."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-181397","number":"181397","sourceNumber":"181397","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Júlio, 3 anos, há 07 dias vem apresentando febre diária, hiperemia conjuntival bilateral,\nadenomegalia não dolorosa em cadeia cervical esquerda (2cm), língua em framboesa, exantema\nmaculopapular, edema em boca, mãos e pés, sendo realizados exames complementares que\nevidenciaram: leucocitose (22 mil), plaquetas: 550mil/mm³, PCR: 96mg/L, EAS com 40\nleucócitos/campo e bacterioscopia negativa. Qual o diagnóstico mais provável?","options":{"A":"Síndrome do choque tóxico.","B":"Doença de Kawasaki.","C":"Doença mão-pé-boca.","D":"Mononucleose.","E":"Escarlatina."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-158760","number":"158760","sourceNumber":"158760","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Paciente de 18 anos, sexo feminino, é internada com quadro de erupção malar,\nfotossensibilidade, úlceras orais, artrite e\nanemia hemolítica com reticulocitose. Paciente apresenta\ncritérios para diagnóstico de Lúpus Eritematoso Sistêmico (LES). Qual autoanticorpo tem maior\nespecificidade para o diagnóstico de LES?","options":{"A":"Anti-Sm.","B":"Anti-Ro.","C":"Anti-RNP.","D":"Anti-DNA.","E":"Anti-histonas."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-109743","number":"109743","sourceNumber":"109743","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Paciente do sexo feminino, 60 anos, com história de lombalgia, emagrecimento e\nadinamia há dois meses. Em tratamento com\nfluoxetina e paracetamol sem melhora efetiva. Traz os\nseguintes resultados de exames laboratoriais para sua avaliação: Hb = 8.0 mg/dl; leucócitos =\n9.500/mm³; plaquetas = 175.000/mm³; ureia = 95 mg/dl; creatinina = 2.8 mg/dl; cálcio iônico = 2.1\nmmol/l; TSH e T4 livre normais. Diante desse caso clínico, assinale a hipótese diagnóstica MAIS\nprovável.","options":{"A":"Adenoma de paratireoide.","B":"Insuficiência renal crônica.","C":"Transtorno depressivo.","D":"Mieloma múltiplo."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-298208","number":"298208","sourceNumber":"298208","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Em pacientes com diagnóstico de doença reumática autoimune como o lúpus\neritematoso sistêmico, com desejo de engravidar,\nquais os autoanticorpos que podem interferir\ndiretamente na gravidez? Assinale a alternativa com as opções CORRETAS.","options":{"A":"Anticoagulante lúpico, antibeta-2-glicoproteína 1, anti-SSA RO.","B":"Anti-SM, antibeta-2-glicoproteínas 1 e anticoagulante lúpico.","C":"Anticoagulante lúpico, anti-RNP e anti-SSA RO.","D":"Anti-SM, anticoagulante lúpico e anti-RNP."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-286714","number":"286714","sourceNumber":"286714","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Mulher, 20 anos de idade, evoluindo há 3 meses com artralgia inflamatória e artrite não\nerosiva em interfalangianas e punhos, presença de rash malar associado a fotossensibilidade e\núlceras orais. Tem anticorpo antinuclear (FAN) 1:160 nuclear homogêneo. Não apresenta\ncomprometimento de outros órgãos no momento. Diante deste quadro, NÃO está indicado o uso\nde:","options":{"A":"Hidroxicloroquina.","B":"Ciclofosfamida.","C":"Prednisona.","D":"Metotrexato."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-252237","number":"252237","sourceNumber":"252237","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"O esôfago é um dos órgãos que pode ser afetado pela doença reumatológica chamada\nde esclerodermia. Qual a característica\npredominante desta patologia?","options":{"A":"Atrofia da musculatura estriada.","B":"Atrofia da musculatura lisa.","C":"Hipertrofia da musculatura estriada.","D":"Hipertrofia da musculatura lisa."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-176024","number":"176024","sourceNumber":"176024","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"É considerada a mais frequente manifestação visceral da esclerose sistêmica:","options":{"A":"Dismotilidade esofágica.","B":"Crepitação tendínea.","C":"Fibrose pulmonar.","D":"Calcinose."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-176042","number":"176042","sourceNumber":"176042","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"João tem dois anos de idade, foi levado ao pronto-socorro pediátrico. A mãe relata\nfebre de 10 dias, congestão conjuntival\nbulbar bilateral geral, sem exsudato, eritema de mucosa\noral e faríngea com língua ?em morango? e lábios secos e fissurados, eritema e edema de mãos e\ndos pés, linfoadenopatia cervical unilateral não supurativa. O diagnóstico provável é:","options":{"A":"Ehlers-Danlos.","B":"Cardiopatia reumática.","C":"Doença de Kawasaki.","D":"Poliangeíte com granulomatose."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-103846","number":"103846","sourceNumber":"103846","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"O que caracteriza a arterite de Takayasu?","options":{"A":"Vasculite crônica dos grandes vasos caracterizada por ausência de pulso.","B":"Vasculite necrosante que compromete artérias de pequeno calibre.","C":"Vasculite com pulso, aguda, que compromete artérias de médio calibre.","D":"Doença com pulso, aguda, que compromete artérias de pequeno e médio calibre."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-82004","number":"82004","sourceNumber":"82004","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Num paciente com pancitopenia febril, hepatoesplenomegalia e linfonodomegalia\ngeneralizada, associadas a dor óssea e perda ponderal importante, deve-se atentar para\nocorrência das seguintes emergências, EXCETO:","options":{"A":"Síndrome de hiperviscosidade.","B":"Choque séptico.","C":"Crise vaso-oclusiva dolorosa falciforme.","D":"Hemorragia grave.","E":"Dispneia por compressão mediastinal."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-49804","number":"49804","sourceNumber":"49804","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Qual das entidades abaixo que não cursa com esplenomegalia volumosa?","options":{"A":"Leucemia mieloide crônica;","B":"Talassemia major (Anemia de Cooley);","C":"Leucemia mieloide aguda;","D":"Metaplasia mieloide agnogênica com mielofibrose;","E":"Leishmaniose visceral (Kalazar)."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-26617","number":"26617","sourceNumber":"26617","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Marque a alternativa com a hipótese diagnóstica mais provável para o caso descrito\nabaixo: O paciente é um homem de 58 anos que\nestá internado em um hospital geral para uma\ncirurgia de hérnia inguinal. Encontra-se em bom estado geral. O exame físico é normal, exceto por\nalguns nódulos em região cervical, 1 x 1 cm, indolores, não aderidos a planos profundos. O Ht:\n42%; plaquetas: 335.000/mm³; leucócitos: 50.000/mm³; granulócitos: 4%; monócitos: 1%; linfócitos:\n95%.","options":{"A":"Leucemia Linfocítica Crônica (LLC).","B":"Leucemia Mieloide Crônica (LMC).","C":"Leucemia Linfocítica Aguda (LLA).","D":"Leucemia Mieloide Aguda (LMA).","E":"Hairy cell leukemia."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-26676","number":"26676","sourceNumber":"26676","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"A paciente é uma mulher de 28 anos, referindo evolução de doença há dois meses com\nastenia, dispneia aos médios esforços que evoluiu para pequenos esforços. O exame físico revela\npalidez cutâneo-mucosa e sopro pansistólico. Petéquias estão presentes nos membros inferiores.\n\nNão há presença de visceromegalias palpáveis. Uma tênue hemorragia é notada no exame\noftalmoscópico. Ht = 19% (esfregaço\nnormocrômico normocítico), Reticulócitos = 1%, Plaquetas =\n8.000/mm³, Leucócitos = 50.000/mm³, Blastos = 95%, Granulócitos = 1%, Linfócitos = 4%. Marque\na alternativa com a hipótese diagnóstica mais provável para o caso descrito acima:","options":{"A":"Leucemia Mieloide Crônica (LMC).","B":"Leucemia Mieloide Aguda (LMA).","C":"Leucemia Linfocítica Aguda (LLA).","D":"Leucemia Linfocítica Crônica (LLC).","E":"Púrpura Trombocitopênica Imunológica (PTI)."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-7491","number":"7491","sourceNumber":"7491","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Com relação às artrites reativas, assinale a afirmativa CORRETA:","options":{"A":"O estreptococo é agente causal mais comum.","B":"O agente causal é cultivado facilmente a partir do líquido sinovial da articulação afetada.","C":"Os dois principais tipos de artrite reativa são pós-uretrite e pós-disentérica.","D":"Podem ocorrer manifestações associadas tais como conjuntivite, enterite, sacroileíte e GN.","E":"Antibioticoterapia é a principal medida terapêutica."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-7465","number":"7465","sourceNumber":"7465","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Artrite Reumatoide Juvenil (A.R.J.) associada à uveíte ocorre principalmente em\npacientes com:","options":{"A":"ARJ pauciarticular, FAN (-);","B":"ARJ poliarticular, FAN (+);","C":"ARJ poliarticular, FAN (-);","D":"ARJ pauciarticular, FAN (+);","E":"ARJ pauciarticular ou poliarticular com FAN (-)."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-62800","number":"62800","sourceNumber":"62800","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Paciente, sexo feminino, 25 anos de idade, admitida em unidade hospitalar com quadro\nde abdome agudo, é encaminhada para o centro\ncirúrgico com achado de isquemia mesentérica. A\npaciente não tinha queixas prévias a esse evento, mas relata avaliação laboratorial no mês anterior\ncom Hb: 7,5 g/dl; leucograma: 2.500; plaquetas: 46.000; creatinina: 0,6 mg/dl. Diante do quadro\ndescrito, o mais provável diagnóstico é:","options":{"A":"Púrpura trombocitopênica trombótica.","B":"Hemoglobinúria paroxística noturna.","C":"Anemia megaloblástica.","D":"Anemia de Fanconi.","E":"Síndrome de Shwachman."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-62803","number":"62803","sourceNumber":"62803","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Paciente, sexo feminino, 25 anos de idade, admitida em unidade hospitalar com quadro\nde abdome agudo, é encaminhada para o centro\ncirúrgico com achado de isquemia mesentérica. A\npaciente não tinha queixas prévias a esse evento, mas relata avaliação laboratorial no mês anterior\ncom Hb: 7,5 g/dl; leucograma: 2.500; plaquetas: 46.000; creatinina: 0,6 mg/dl. O exame que deve\nser solicitado para corroborar a principal suspeita diagnóstica é:","options":{"A":"Dosagem de vitamina B12.","B":"Biópsia de medula óssea.","C":"Lâmina do sangue periférico.","D":"Citometria de fluxo.","E":"Estudo genético."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-62821","number":"62821","sourceNumber":"62821","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Paciente, sexo feminino, 45 anos de idade, com quadro de artralgia, púrpura em\nmembros inferiores e fraqueza há cerca de um\nmês. Evolui, há uma semana, com redução do\ndébito urinário, hematúria e hipertensão. A paciente nega comorbidades, mas relata cesárea há 25\nanos, quando foi necessário transfusão sanguínea. O diagnóstico mais provável é de:","options":{"A":"Lúpus eritematoso sistêmico.","B":"Poliarterite nodosa.","C":"Crioglobulinemia.","D":"Púrpura de Henoch-Schönlein.","E":"Uso de cocaína."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-62826","number":"62826","sourceNumber":"62826","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Paciente, sexo feminino, 45 anos de idade, com quadro de artralgia, púrpura em\nmembros inferiores e fraqueza há cerca de um\nmês. Evolui, há uma semana, com redução do\ndébito urinário, hematúria e hipertensão. A paciente nega comorbidades, mas relata cesárea há 25\nanos, quando foi necessário transfusão sanguínea. A terapia mais efetiva para o caso é iniciar:","options":{"A":"Corticoide apenas.","B":"Plasmaférese e corticoide.","C":"Imunoglobulina e corticoide.","D":"Betabloqueador e suporte dialítico.","E":"Corticoide e azatioprina."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-34962","number":"34962","sourceNumber":"34962","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Paciente, 7 anos de idade, apresenta quadro de fraqueza, dores articulares, perda de\npeso. Ao exame físico, apresentava-se em regular estado geral; descorado; febril; aumento dos\ngânglios periféricos da cadeia cervical e inguinal; fígado a 5 cm do RCD e baço palpável a 4,5 cm.\nO hemograma apresentava Hb = 6,1 g/dl; Htc = 18%; leucócitos = 68.000/mm³ (com 20% de\nblastos, 10% de bastonetes, 21% de segmentados, 46% de linfócitos); plaquetas = 58.000/mm³. O\ndiagnóstico mais provável é:","options":{"A":"Leucemia.","B":"Calazar.","C":"Lúpus.","D":"Salmonelose septicêmica.","E":"Anemia falciforme."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-34967","number":"34967","sourceNumber":"34967","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Paciente, 7 anos de idade, apresenta quadro de fraqueza, dores articulares, perda de\npeso. Ao exame físico, apresentava-se em regular estado geral, descorado, febril, aumento dos\ngânglios periféricos da cadeia cervical e inguinal, fígado a 5 cm do RCD e baço palpável a 4,5 cm.\nO hemograma apresentava Hb: 6,1 g/dl, Htc: 18%, leucócitos: 68.000/mm³ (com 20% de blastos,\n10% de bastonetes, 21% de segmentados, 46% de linfócitos), plaquetas: 58.000/mm³. Para\ncomprovação diagnóstica, o exame a ser solicitado é:","options":{"A":"mielograma.","B":"punção esplênica.","C":"curva de fragilidade osmótica.","D":"mucoproteínas.","E":"eletroforese de hemoglobina."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-314287","number":"314287","sourceNumber":"314287","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"é uma vasculite sistêmica de etiologia desconhecida, e uma das\ncausas principais de cardiopatia adquirida na\ninfância, podendo se manifestar na forma de\nmiocardite aguda com insuficiência cardíaca, arritmias, endocardites e pericardites. A alternativa\nque preenche, corretamente, a lacuna do trecho acima é","options":{"A":"Doença de Devic","B":"Síndrome de Weil","C":"Doença de Krabbe","D":"Doença de Kawasaki","E":"Síndrome de Raynaud"},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-249997","number":"249997","sourceNumber":"249997","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Mulher de 23 anos, queixando-se de dor em antebraço esquerdo após atividades\nfísicas, de início há 4 meses. Queixa-se\ntambém no mesmo período de febre baixa, diária, não\naferida, associada à perda de peso, cefaleias esporádicas auto-limitadas e crises hipertensivas que\na fez procurar o pronto-socorro por 4 vezes. Nega comorbidades. Nega tabagismo/etilismo. Ao\nexame físico encontra-se em bom estado geral, bulhas rítmicas em 2 tempos, sem sopros audíveis,\npressão arterial sistólica em repouso de 150mmHg, ausculta pulmonar normal. Exame físico do\nantebraço esquerdo com tempo de enchimento capilar lentificado, sem lesões tróficas e redução da\namplitude do pulso da artéria braquial esquerda. Apresenta velocidade de hemossedimentação\naumentada. A principal hipótese diagnóstica é:","options":{"A":"Lupus Eritematoso Sistêmico.","B":"Tromboangeíte obliterante.","C":"Arterite de Takayasu.","D":"Embolia arterial aguda."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-249736","number":"249736","sourceNumber":"249736","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Sobre o Lúpus Eritematoso Sistêmico, é correto afirmar que","options":{"A":"se supõe que a testosterona atue como elemento protetor da doença.","B":"é uma doença multisistêmica que encontra na pele, no sistema nervoso central e nas\narticulações seus órgãos de choque principais.","C":"as manifestações articulares podem ser classificadas em: Lúpus Eritematoso Cutâneo crônico,\nLúpus eritematoso subagudo e Lúpus eritematoso agudo.","D":"os fatores envolvidos na gênese da doença são, exclusivamente, os seguintes: herança\ngenética, envolvimento hormonal, estresse, trauma físico, infecção viral e drogas.","E":"o rim é o órgão responsável pelo início da doença em mais de 85% dos casos, e o acometimento\ncutâneo é o determinante, na grande\nmaioria das vezes, do prognostico e da evolução da doença."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-350851","number":"350851","sourceNumber":"350851","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Paciente, 10 anos, sexo masculino, previamente hígido, é levado à emergência devido\na quadro de febre elevada há 3 dias associada\na conjuntivite sem exsudato, rash cutâneo, diarreia,\nvômitos e dor abdominal. Vacinação em dia. Há 3 semanas teve contato com primo que recebeu\ndiagnóstico de COVID-19. Ao exame: PA= 87 x 60mmHg; estado geral regular, taquipneico\n(FR=26irpm), taquicárdico (FC=120bpm), hipocorado (+/4+), febril. Ausculta cardíaca: ritmo regular,\nsem sopros. Ausculta pulmonar normal. Abdome: leve distensão abdominal, fígado palpável a 2 cm\ndo rebordo costal direito. Extremidades: pulsos palpáveis, sem edema. Exames: Hemograma:\nHemoglobina-12,7g/dL, Hematócrito-38% Leucócitos: 10.000 (Neutrófilos-79% Linfócitos-10%\nMonócitos-10% Eosiófilos-0% Bastões-1% Plaquetas: 123.000) ; VHS - 70mm ; TGO - 37; TGP- 35;\nSwab de nasofaringe (RT- PCR): negativo para SARS-CoV-2. Qual das seguintes alternativas é o\ndiagnóstico mais provável?","options":{"A":"Dengue grave.","B":"Doença de Kawasaki.","C":"Síndrome do choque tóxico.","D":"Síndrome inflamatória multissistêmica pediátrica (SIM-P)."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-321314","number":"321314","sourceNumber":"321314","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Mulher, 40 anos, há 1 ano apresenta episódios recorrentes de rinorreia purulenta. Há 5\nmeses com adinamia, perda ponderal, artralgia difusa e, há 2 semanas, hiperemia conjuntival e\ntosse com hemoptoicos. Exame físico: episclerite bilateral, estertores em terço superior de\nhemitórax direito e artrite em cotovelos. Exames: HB 10,7 (VR HB > 12-14.5), leucócitos 11 mil (VR\n4-10 mil), plaquetas 500 mil (VR 150-450 mil); PCR 8.6 mg/dl (VR < 0,6 mg/dl); Cr 1.4 mg/dl (VR\n0.5-1.1 mg/dl) Ur 70 mg/dl (VR 10-50 mg/dl); hematúria e proteinúria 400 mg em 24h; fator\nreumatoide 15 UI/ml (VR < 20 UI/ml); tomografia de tórax: nódulo cavitado em terço superior de\nhemitórax direito. Considerando a principal hipótese diagnóstica, que alteração laboratorial a\ncorroboraria?","options":{"A":"Anticorpo anticitoplasma de neutrófilo padrão perinuclear.","B":"Anticorpo anticitoplasma de neutrófilo padrão citoplasmático.","C":"Fator antinúcleo padrão pontilhado fino denso com título 1:80.","D":"Anticorpo contra peptídeo cíclico citrulinado com título 40 UI /ml (VR < 20UI)."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-199785","number":"199785","sourceNumber":"199785","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Paciente, 27 anos, sexo feminino, procura atendimento médico com queixa de\nartralgias em mãos e punhos há quatro meses.\nJuntamente com o quadro, surgiram máculas\neritematosas em braços e região do decote. Ao exame, úlcera oral em região de palato mole.\nPresença de sinovite da 1ª a 5ª metacarpofalangianas e punhos, bilateralmente. No momento da\nconsulta, mostra exames solicitados por outro profissional: FAN hep2: pontilhado fino denso\n1/1.280; anti-RO > 200 U/ml (VR: reagente > 20 U/ml) Fator reumatoide látex 7 UI/ml (VR: normal).\nLEGENDA: VR: valor de referência. Sobre o caso clínico em questão, indique a alternativa correta\nquanto às características laboratoriais, clínicas e histopatológicas referentes a esta doença.","options":{"A":"A presença de anti-P-ribossomal está associada a neuropatia periférica, bem como a vasculite\ncerebral.","B":"O auto-anticorpo anti-DNA dupla hélice é muito associado com lesões cutâneas subagudas e\nfotossensibilidade.","C":"Uma biópsia renal provavelmente mostrará depósitos subepiteliais em glomérulos para este tipo\nde acometimento renal.","D":"O padrão de FAN em célula hep-2 pontilhado fino denso é o mais específico para diagnóstico de\nlupus eritematoso sistêmico."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-150859","number":"150859","sourceNumber":"150859","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Paciente feminina, 24 anos, apresenta-se no ambulatório de clínica médica com queixa\nde dor e inchaço articular iniciados há 3\nmeses. Acometiam, inicialmente, as articulações\ninterfalangianas proximais e evoluíram, com adição ao longo dos meses, para cotovelos e joelhos,\nassociado à rigidez matinal de 30 minutos. Relatou temperaturas de até 38ºC associadas a astenia\ne hiporexia, com perda ponderal. Há 4 dias procurou serviço de emergência por quadro de uma\nsemana de tosse seca, dispneia e dor torácica ventilatório-dependente. Foi medicada com\nsintomáticos sem melhora e dispensada com solicitação de exames laboratoriais e tomografia de\ntórax que trouxe para consulta. Exame físico: estado geral regular, febril (37,9ºC); PA = 146 x 96\nmmHg; pulso = 104 bpm; FR = 24 irpm; SpO2 = 95% em ar ambiente. Turgência jugular\naumentada. AR: murmúrio vesicular e frêmito toracovocal diminuído em bases. AC: ritmo regular,\nhipofonese leve de bulhas. Sem sopros. Hemograma: Hb = 9,8 mg/dl; Coombs direto negativo;\nleucócitos (céls/mm³) = 7.530; segmentados = 5.798 (77%); linfócitos = 830 (11%); plaquetas:\n104.000/mm³; VHS = 82 mm; PCR = 4,3 mg/L; creatinina = 2,1 mg/dl; ureia = 82 mg/dl; ferritina =\n600 ng/ml (VR: 30-300); LDH = 270 U/L (VR: 50-250); C3 = 22 mg/dl (VR: 90-180); C4 = 4 mg/dl\n\n(VR: 10-40). Sumário de urina com 15 leucócitos por campo e 10 hemácias por campo. Proteínas\n3+. Relação de 1.580 mg de proteína por grama de\ncreatinina em amostra simples de urina. FAN\n1:320 padrão pontilhado grosso, fator reumatoide 16 UI/ml (VR < 14 UI/ml), anti-CCP negativo. A\npaciente foi admitida em enfermaria e iniciou prednisona 60 mg/dia com melhora parcial. Qual\nmedicação deve ser adicionada, para melhoria clínica da paciente?","options":{"A":"Infliximabe.","B":"Azatioprina.","C":"Metotrexato.","D":"Ciclofosfamida."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":["question_bank/media/medcurso/med-clinica-medica-med-clm-21/150859.png"],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-102177","number":"102177","sourceNumber":"102177","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Paciente feminina, 30 anos, com história de asma moderada e rinite alérgica\npersistente que se iniciaram há cerca de 10\nanos. Relata piora da dispneia e da obstrução nasal\nnos últimos 6 meses e aparecimento de parestesia dolorosa em pé direito. A investigação mostrou\nespirometria com padrão obstrutivo acentuado com resposta significativa à prova broncodilatadora;\ntomografia dos seios da face com sinusite maxilar; hemograma com Hb = 11 g/dl; leucograma =\n12.700/mm³ com 60% de neutrófilos, 26% de linfócitos, 13% de eosinófilos e 1% monócitos.\n\nPlaquetas = 190.000/mm³. A função renal, hepática e a dosagem sérica de IgE foram normais.\nConsiderando o contexto clínico e a imagem da radiografia de tórax abaixo, o diagnóstico mais\nprovável é: (VER IMAGEM)","options":{"A":"Granulomatose de Wegener.","B":"Síndrome de Churg-Strauss.","C":"Pneumonite eosinofílica crônica.","D":"Aspergilose broncopulmonar alérgica."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":["question_bank/media/medcurso/med-clinica-medica-med-clm-21/102177.png"],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-65721","number":"65721","sourceNumber":"65721","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Um homem de 44 anos apresenta dispneia aos médios esforços há 2 anos. Relata\npirose há 15 anos e disfagia para sólidos há\n12 meses. Ao exame físico, apresenta microstomia e\ncrepitações nas bases pulmonares (tipo ?velcro?). Era fumante até dois anos atrás. A manometria\nesofágica mostra ausência de contrações nos 2/3 distais do esôfago e hipotonia do esfíncter\ninferior. Um corte tomográfico dos pulmões é mostrado a seguir. Qual a melhor possibilidade\ndiagnóstica? (VER IMAGEM)","options":{"A":"Sarcoidose.","B":"Esclerodermia sistêmica.","C":"Fibrose pulmonar idiopática.","D":"Bronquiectasia por tabagismo.","E":"Pneumonite intersticial por doença do refluxo gastroesofágico."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":["question_bank/media/medcurso/med-clinica-medica-med-clm-21/65721.png"],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-65787","number":"65787","sourceNumber":"65787","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Considere uma paciente feminina, 42 anos, que iniciará tratamento quimioterápico, por\nneoplasia pulmonar de pequenas células, com regime que inclui etoposide e tem história familiar de\nleucemia. Que alteração genética aumentará o risco de ela desenvolver leucemia mieloide aguda?","options":{"A":"Inversão do cromossomo 16.","B":"Aberração do cromossomo 11q23.","C":"Translocação dos cromossomos 8; 21.","D":"Translocação dos cromossomos 15; 17.","E":"Translocação dos cromossomos q22; q12."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-51203","number":"51203","sourceNumber":"51203","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Homem de 26 anos é internado por quadro de febre, palidez e equimoses há uma\nsemana. O hemograma revela pancitopenia com blastos no sangue periférico. O mielograma\nmostra 23% de blastos. Qual o melhor teste para avaliação citogenética desse paciente?","options":{"A":"Real time PCR.","B":"Imuno-histoquímica.","C":"Análise de cariótipo por Banda G.","D":"Hibridização in situ com fluorescência."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-51226","number":"51226","sourceNumber":"51226","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Mulher com lúpus eritematoso sistêmico há 1 mês apresenta edema de MMII e ?urina\nespumosa?. Realizou exames laboratoriais que evidenciaram: Hb = 10,2 g/dl; Ht = 31%; leucócitos\n\n= 10.200/mm³ (diferencial normal); plaquetas = 120.000/mm³; ureia = 42 mg/dl; creatinina = 0,9\nmg/dl; sumário de urina = proteinúria 4+; sem\nhematúria ou leucocitúria; proteinúria de 24h = 4,5 g.\nCom relação à nefrite lúpica da paciente, qual o tipo mais provável?","options":{"A":"Classe I (lesão mínima).","B":"Classe II (proliferação mesangial).","C":"Classe IV (proliferativa difusa).","D":"Classe V (membranosa)."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-22825","number":"22825","sourceNumber":"22825","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Dentre as condições abaixo, o distúrbio mieloproliferativo mais comumente associado à\nleucopenia é:","options":{"A":"Mielofibrose.","B":"Leucemia mieloide crônica.","C":"Policitemia vera.","D":"Trombocitemia essencial.","E":"Hiperesplenismo."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-7301","number":"7301","sourceNumber":"7301","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Acerca da febre reumática, julgue os itens que se seguem. I - É mais frequente em\ncrianças com menos de três anos de idade. II - É uma poliartrite aguda, migratória de grandes\narticulações. III - A artrite apresenta pouca resposta aos anti-inflamatórios não-hormonais. IV - A\nsequela cardíaca mais comum é a insuficiência mitral. V - A coreia de Sydenham tem início\nprecoce e apresenta sequelas importantes. Estão certos apenas os itens:","options":{"A":"I e III.","B":"I e V.","C":"II e III.","D":"II e IV.","E":"IV e V."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-6951","number":"6951","sourceNumber":"6951","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Sobre as manifestações extra-articulares da Artrite Reumatoide (AR), marque o correto:","options":{"A":"Pacientes com fator reumatoide positivo apresentam nódulos reumatoides em até 30%.","B":"A vasculite reumatoide renal é comum e se correlaciona com formas soronegativas.","C":"A hipertensão pulmonar grave é a manifestação pulmonar mais comum.","D":"A Síndrome de Felty é comum nos estágios iniciais e consiste em esplenomegalia e leucocitose\ncom neutrofilia.","E":"Raramente ocorre neuropatia periférica, sendo o acometimento neurológico preferencialmente\nno sistema nervoso central."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-365649","number":"365649","sourceNumber":"365649","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Os critérios diagnósticos do lúpus eritematoso sistêmico inclui a pesquisa de\nautoanticorpos. Um dos autoanticorpos cuja positividade faz parte dos critérios diagnósticos do\nlúpus é","options":{"A":"anti-Sm.","B":"ASCA.","C":"antigliadina.","D":"alfafetoproteína."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-365659","number":"365659","sourceNumber":"365659","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"A respeito do lúpus eritematoso sistêmico, é correto afirmar que faz(em) parte das\npossíveis complicações dessa doença a (o)","options":{"A":"lesão cutânea que melhora com a exposição solar.","B":"artrite de característica continuamente progressiva e erosiva.","C":"edema, a oligúria e a hipertensão por nefrite.","D":"tamponamento cardíaco, que deve ser manejado com corticoide em altas doses."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-365611","number":"365611","sourceNumber":"365611","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Uma criança de 10 meses de vida foi levada ao pronto-socorro com história de febre\nalta há dois dias, sem outros sintomas. O\ndiagnóstico inicial foi febre sem sinais de localização,\nprovavelmente por um quadro viral inespecífico. Recebeu alta sintomático, e os pais foram\norientados a aguardar a resolução espontânea do quadro. No quinto dia de febre, retornou ao\npronto atendimento para reavaliação. Além da febre, observaram-se hiperemia de conjuntivas sem\nsecreção, exantema em tronco e região perineal, além de ressecamento e fissuras nos lábios. Ao\nexame físico, foram verificados linfonodo cervical direito palpável, medindo cerca de 1,5 cm,\ndiscreto edema em dorso das mãos e dos pés, sem descamação e orofaringe difusamente\nhiperemiada, sem placas de pus ou lesões aftosas. Realizou testes rápidos para Sars-CoV-2 e\ninfluenza, com resultados negativos. Nesse caso, a conduta mais adequada é","options":{"A":"manter sintomáticos e informar que se trata de um quadro viral autolimitado.","B":"iniciar antibioticoterapia de amplo espectro (amoxicilina+clavulanato ou cefalosporina de\nsegunda geração) por 10 dias.","C":"iniciar amoxicilina por 10 dias.","D":"solicitar hemograma, proteína-C-reativa, transaminases, EAS e ecocardiograma."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-322170","number":"322170","sourceNumber":"322170","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Um menino de 3 anos apresenta quadro febril há 6 dias e é levado para avaliação.\nDurante a consulta, são identificadas outras\nalterações: exantema polimorfo difuso, conjuntivite sem\nexsudato, mucosite oral, edema distal dos membros e adenomegalia cervical unilateral.\n\nSuspeitando-se de Doença de Kawasaki, qual dos sinais ou sintomas apresentados pelo paciente é\nconsiderado o critério mandatório para o diagnóstico?","options":{"A":"Febre.","B":"Exantema.","C":"Conjuntivite.","D":"Mucosite.","E":"Edema distal."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-322175","number":"322175","sourceNumber":"322175","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Você está atendendo um paciente com quadro de púrpura palpável, dor abdominal e\nartralgia. Sua suspeita inicial é de Púrpura de Henoch-Schönlein. Sobre esse diagnóstico, assinale\na alternativa correta.","options":{"A":"A púrpura palpável é um achado frequente nos pacientes acometidos, mas não obrigatório.","B":"Manifestações gastrointestinais são bastante incomuns e, quando presentes, são leves e\nautolimitadas.","C":"A doença não acomete os rins.","D":"A artrite aguda é um critério obrigatório para o diagnóstico, geralmente incapacitante, aditiva e\nde pequenas articulações.","E":"Pode ser primária ou desencadeada por infecções virais, bacterianas, alimentos, vacinas,\nmedicamentos e picadas de insetos."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-322209","number":"322209","sourceNumber":"322209","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Dr. Antônio atende na UBS uma paciente de 34 anos com queixa de poliartralgias a\nqual traz resultado de exames que demonstram anemia, linfopenia e fator antinuclear positivo em\ntítulos altos. Ao fim da consulta, o médico prescreve hidroxicloroquina para ela. Devido a essa\nprescrição, Dr. Antônio deve encaminhá-la para avaliação do","options":{"A":"cardiologista.","B":"nefrologista.","C":"hepatologista.","D":"oftalmologista.","E":"hematologista."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-298880","number":"298880","sourceNumber":"298880","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Uma paciente de 16 anos de idade, com oito horas de evolução, compareceu à\nemergência por apresentar vertigem,\ndiplopia e surdez. Além disso, demonstrou deficits motores.\nAo exame físico, verificaram-se SatO2 = 96% em ar ambiente, FC = 92 bpm regular e PA = 180\nmmHg x 100 mmHg. Tomografia de crânio e angiotomografia não evidenciaram malformação\nvascular nem sangramento. Aos 15 anos, a paciente teve trombose venosa profunda. Em relação a\nesse caso clínico e aos conhecimentos médicos correlatos, julgue o item a seguir. É importante\nsolicitar exames de fatores de coagulação, sendo o anticorpo anticardiolipina o mais prevalente em\npessoas abaixo de 50 anos de idade com essa enfermidade.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-274362","number":"274362","sourceNumber":"274362","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Dentre as seguintes doenças, assinale aquela que tem mais importante relação com\ntabagismo, com alta prevalência nos doentes.","options":{"A":"Acidente vascular cerebral.","B":"Infarto agudo do miocárdio.","C":"Trombose mesentérica.","D":"Trombose de seio cavernoso.","E":"Tromboangeíte obliterante."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-261243","number":"261243","sourceNumber":"261243","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Uma paciente de 35 anos de idade, afrodescendente, comparece à consulta por\napresentar artrite, anemia e rash em asa de\nborboleta na face. Realizou exames laboratoriais. Em\nrelação a esse caso clínico e com base nos conhecimentos médicos correlatos, julgue o item a\nseguir. Leucopenia é um achado esperado.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-261244","number":"261244","sourceNumber":"261244","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Uma paciente de 35 anos de idade, afrodescendente, comparece à consulta por\napresentar artrite, anemia e rash em asa de\nborboleta na face. Realizou exames laboratoriais. Em\nrelação a esse caso clínico e com base nos conhecimentos médicos correlatos, julgue o item a\nseguir. A prevalência no sexo feminino é semelhante em relação ao masculino.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-261245","number":"261245","sourceNumber":"261245","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Uma paciente de 35 anos de idade, afrodescendente, comparece à consulta por\napresentar artrite, anemia e rash em asa de\nborboleta na face. Realizou exames laboratoriais. Em\nrelação a esse caso clínico e com base nos conhecimentos médicos correlatos, julgue o item a\nseguir. A artrite é caracterizada por ser unilateral nessa patologia.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-261246","number":"261246","sourceNumber":"261246","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Uma paciente de 35 anos de idade, afrodescendente, comparece à consulta por\napresentar artrite, anemia e rash em asa de\nborboleta na face. Realizou exames laboratoriais. Em\nrelação a esse caso clínico e com base nos conhecimentos médicos correlatos, julgue o item a\nseguir. O rash é caracterizado por ser fotossensível.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-212002","number":"212002","sourceNumber":"212002","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Uma jovem com história de perda fetal por três vezes com menos de 10 semanas, com\ntrombocitopenia, artralgia e enxaqueca, vai ao consultório médico com quadro de trombose venosa\nprofunda e livedo reticular. Tem anticorpo anticardiolipina (aCL) e anticorpos anti-ß2GPI em títulos\nelevados. Nesse caso clínico, o quadro apresentado pela paciente chama a atenção para a\nsíndrome:","options":{"A":"De West.","B":"De Budd-Chiari.","C":"Oncológica trombótica.","D":"Do anticorpo antifosfolipídeo.","E":"Hemolítico-urêmica."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-211984","number":"211984","sourceNumber":"211984","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Uma criança de 2 anos de idade foi atendida na emergência com quadro de febre alta\nhá seis dias, acompanhado de gânglios no\npescoço, irritação nos olhos e rash cutâneo. Ao exame\nfísico, apresentava eritema de mãos e pés, eritema maculopapular polimorfo que se acentuava nas\nvirilhas, lábios secos e fissurados, língua em \"framboesa\", linfadenopatia cervical e conjuntivas\nhiperemiadas e congestas sem secreção, além de estar febril. Considerando esse caso clínico e os\nconhecimentos médicos correlatos, assinale a alternativa CORRETA.","options":{"A":"O quadro é compatível com gengivoestomatite herpética.","B":"Trata-se de varicela na primeira semana da doença, quando ainda não apareceram as\ncaracterísticas lesões vesiculobolhosas.","C":"A rubéola é bem característica nessa faixa etária, cursando com febre muito alta e língua em\n\"framboesa\".","D":"O quadro é de escarlatina, doença infecciosa febril estafilocócica característica dessa faixa\netária.","E":"Trata-se de uma vasculite febril da infância, conhecida como doença de Kawasaki."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-214502","number":"214502","sourceNumber":"214502","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Determinada paciente de 22 anos de idade chega ao posto de saúde da família com\nhistórico de ocorrências de dores musculares e episódios intermitentes de dores em punhos e em\nmãos bilateralmente e simetricamente no último mês. Relata os episódios de dor como\nindependentes da realização de esforços. Refere ter percebido, no último mês, o surgimento de\nregiões de hiperemia e lesões de pele escamosas em cotovelos, mãos e no couro cabeludo. Ao\nexame, apresenta-se em bom estado geral, corada, hidratada, eupneica em ar ambiente, com PA =\n110 mmHg x 70 mmHg, FC = 74 bpm, FR = 21 irpm e SatO? = 98%. Considerando esse caso\nclínico e os conhecimentos médicos correlatos, julgue o item a seguir. Na suspeita de um quadro\ninicial de lúpus eritematoso sistêmico, a artralgia apresentada pela paciente é um dos critérios\nutilizados para diagnóstico.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-134963","number":"134963","sourceNumber":"134963","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Em relação às leucemias na infância, julgue o item seguinte. No início do tratamento\nquimioterápico, a lise tumoral provoca elevação dos níveis plasmáticos de fósforo e de ácido úrico,\nbem como redução de potássio, devido à rápida destruição dos blastos no sangue.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-108211","number":"108211","sourceNumber":"108211","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Um menino de quatro anos de idade foi levado pela manhã ao pediatra porque, há vinte\ndias, vinha apresentando febre baixa, fraqueza progressiva, palidez e manchas roxas pelo corpo.\n\nNo exame físico, o médico detectou, além da palidez e das equimoses, edema e dor nas\narticulações dos joelhos e cotovelos, e\nhepatoesplenomegalia. A fim de esclarecer o caso, o médico\nsolicitou um hemograma completo que mostrou pancitopenia. Com base no caso clínico acima\napresentado, julgue o próximo item. O exame mais importante a ser realizado na criança com vistas\nao diagnóstico é o mielograma.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-82036","number":"82036","sourceNumber":"82036","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Um paciente de sessenta anos de idade, assintomático, compareceu a um consultório\nde clínica médica para mostrar os resultados\nde exames solicitados em consulta anterior. O\nhemograma completo do paciente apresentou os seguintes resultados: hemoglobina: 15 g/dl;\nhematócrito: 47%; hemácias: 5.000.000/µl; leucócitos: 56.000/mm³, com 90% de linfócitos maduros\ne 10% de neutrófilos; plaquetas: 200.000/mm³. Com relação a esse caso clínico, julgue o item a\nseguir: A principal hipótese diagnóstica é de mononucleose infecciosa.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-88626","number":"88626","sourceNumber":"88626","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"No que se refere à leucemia, à osteoporose pós-menopáusica e à litíase renal, julgue o\nitem a seguir. A leucemia mieloide crônica é uma neoplasia mieloproliferativa associada a uma\ntranslocação gênica; esta provoca a formação de um oncogene de fusão, denominado cromossomo\nPhiladelphia, que codifica a oncoproteína BCR-ABL.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-49161","number":"49161","sourceNumber":"49161","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Uma paciente de cinquenta e oito anos de idade, lavradora e residente na zona rural,\ndurante uma consulta médica em hospital de\nnível primário, relatou que, havia alguns meses,\napresentava fadiga, mal-estar, perda de peso, episódios de sudorese noturna, sensação de\nplenitude pós-prandial e discreta dor no quadrante superior esquerdo do abdome. Informou que se\nalimentava principalmente de alimentos à base de farinhas, doces e gorduras e ingeria carne\nvermelha duas a três vezes por semana. Negou etilismo e tabagismo, não tendo sido registradas\noutras anormalidades na anamnese. No exame físico, constatou-se esplenomegalia importante,\ncom baço palpável 12 cm abaixo da borda costal esquerda, pouco doloroso à palpação, sem outras\nanormalidades. O hemograma completo da paciente evidenciou os seguintes resultados (VER\nIMAGEM). Considerando o caso clínico e o hemograma acima apresentados, julgue o item\nseguinte. A pesquisa do cromossomo Philadelphia (Ph) ou a identificação do gene híbrido\n\nBCR-ABL são exames complementares decisivos para a confirmação da principal hipótese\ndiagnóstica.","options":{"A":"Certo.","B":"Errado."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-49162","number":"49162","sourceNumber":"49162","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Uma paciente de cinquenta e oito anos de idade, lavradora e residente na zona rural,\ndurante uma consulta médica em hospital de\nnível primário, relatou que, havia alguns meses,\napresentava fadiga, mal-estar, perda de peso, episódios de sudorese noturna, sensação de\nplenitude pós-prandial e discreta dor no quadrante superior esquerdo do abdome. Informou que se\nalimentava principalmente de alimentos à base de farinhas, doces e gorduras e ingeria carne\nvermelha duas a três vezes por semana. Negou etilismo e tabagismo, não tendo sido registradas\noutras anormalidades na anamnese. No exame físico, constatou-se esplenomegalia importante,\ncom baço palpável 12 cm abaixo da borda costal esquerda, pouco doloroso à palpação, sem outras\nanormalidades. O hemograma completo da paciente evidenciou os seguintes resultados (VER\nIMAGEM). Considerando o caso clínico e o hemograma acima apresentados, julgue o item\nseguinte. A principal hipótese diagnóstica é de reação leucemoide.","options":{"A":"Certo.","B":"Errado."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-8589","number":"8589","sourceNumber":"8589","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Fábio, 12 anos de idade, foi atendido na Unidade Básica de Saúde há 15 dias com\ninfecção de vias aéreas superiores (IVAS).\nRetorna hoje sem sintomas de IVAS, com queixa de\nfebre leve, mal-estar e dor articular em tornozelos, joelhos e punhos, que pioram com\nmovimentação ativa e passiva. Exames complementares mostraram leucocitose, Proteína C reativa\ne VHS aumentados. Aponte o diagnóstico de Fábio.","options":{"A":"Febre reumática.","B":"Imunodeficiência.","C":"Artrite séptica.","D":"Doença de Still.","E":"Doença linfoproliferativa."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-352379","number":"352379","sourceNumber":"352379","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Uma mulher de 23 anos relata sentir fadiga por aproximadamente 18 meses,\nacompanhada de mal-estar e diminuição do\napetite. Além disso, menciona uma perda de peso\ninvoluntária de 10 quilogramas nesse período. Ela passou por vários atendimentos médicos de\nurgência e emergência sem obter resolução para seus sintomas. A paciente também se queixa de\ndor na região do cíngulo do membro superior esquerdo, bem como de câimbras, principalmente\ndurante ou após atividades físicas, o que a tem impedido de realizar suas tarefas diárias. Nas\núltimas semanas, ela apresentou tinutus, alterações auditivas subjetivas e lipotimia. A situação se\nagravou na última semana com dois episódios de síncope, acompanhados da sensação de\n\"\"desmaiar acordada\"\", levando-a a procurar atendimento médico ambulatorial. A paciente trouxe\nconsigo diversos resultados de exames laboratoriais, que incluíram sorologias para infecções, um\n\"\"painel reumatológico\"\" e exames bioquímicos, todos dentro da faixa de normalidade, exceto por\numa anemia com características inflamatórias. Acerca do quadro clínico exposto, etiologias\npossíveis, considerando a imagem apresentada, bem como diagnósticos diferenciais e os\nconhecimentos correlatos que suscitam, julgue o item a seguir. No exame físico, a presença de\ndiminuição ou ausência de pulso nas artérias axilar, braquial ou radial do lado direito da paciente\npode ser indicativa dos critérios de classificação da Arterite de Takayasu.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-301257","number":"301257","sourceNumber":"301257","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"O acometimento pleuropulmonar em pacientes com doenças autoimunes sistêmicas é\ncomum e pode levar ao aumento da morbidade e mortalidade. O diagnóstico precoce dessas\nmanifestações oferece a melhor chance de intervir e melhorar o prognóstico. A respeito desse\nassunto, julgue o item a seguir. Em indivíduos com lúpus eritematoso sistêmico, a hemorragia\npulmonar é a manifestação pleuropulmonar mais comum, seguida de pneumonite lúpica.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-301258","number":"301258","sourceNumber":"301258","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"O acometimento pleuropulmonar em pacientes com doenças autoimunes sistêmicas é\ncomum e pode levar ao aumento da morbidade e mortalidade. O diagnóstico precoce dessas\nmanifestações oferece a melhor chance de intervir e melhorar o prognóstico. A respeito desse\nassunto, julgue o item a seguir. A esclerose sistêmica, principalmente na forma difusa, é a doença\nreumática com maior acometimento por doença pulmonar intersiticial.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-307108","number":"307108","sourceNumber":"307108","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Um paciente de 2 anos de idade apresenta quadro de febre persistente há sete dias,\neritema labial, hiperemia difusa de mucosa\norofaríngea e proeminência das papilas linguais, bem\ncomo hiperemia conjuntival bilateral, não purulenta, indolor. Além disso, tem também hiperemia\npalmar, edema de dorso de mãos e pés, exantema polimórfico, sem vesículas em tronco e períneo,\ne linfadenopatia cervical medindo 1,5 cm, unilateral. Exames laboratoriais indicaram leucocitose\ncom neutrofilia (> 15.000 mm³), trombocitose (> 450.000 mm³) e elevação de provas de atividade\ninflamatória (VHS e PCR). No que se refere ao melhor diagnóstico e à conduta nesse caso clínico,\nassinale a alternativa correta. Alternativas:","options":{"A":"Leucemia linfoblástica aguda ? Quimioterapia","B":"Eritema nodoso ? Gamaglobulina","C":"Púrpura de Henoch-Schönlein ? Corticosteroide","D":"Sarampo ? Tratamento de suporte","E":"Doença de Kawasaki ? Imunoglobulina humana intravenosa"},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-274592","number":"274592","sourceNumber":"274592","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Mulher, 28 anos, apresenta aborto de origem autoimune decorrente da presença de\nautoanticorpos circulantes de carga negativa, portadora de Lúpus Eritematoso Sistémico (LES) e\npresença confirmada de Anticoagulante Lúpico (LAC). É caracterizada pelo relato do caso\napresentado:","options":{"A":"Síndrome do desconforto respiratório agudo.","B":"Síndrome serotoninérgica.","C":"Síndrome antifosfolípide.","D":"Síndrome neuroléptica maligna."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-291484","number":"291484","sourceNumber":"291484","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Um paciente do sexo masculino, 3 anos de idade, é levado a serviço de emergência em\ndecorrência de febre e exantema há 7 dias. Mãe relata que a febre é diária e chegou a 39 ºC. O\nexantema surgiu há 2 dias. O paciente já passou por outros serviços de emergência sem conseguir\nfechar diagnóstico. Nega doenças prévias. Desenvolvimento normal para a idade. Ao exame,\nmostra-se em regular estado geral, descorado 1+/4+, febril (38,5 ºC), acianótico e hidratado.\n\nPresença de exantema maculopapular e edema e hiperemia nas mãos e pés, rash em tronco e\nperíneo, bem como de hiperemia conjuntival bilateral. Cavidade oral revela fissura em lábios. Há\nlinfonodomegalia cervical, unilateral direita, com 2 cm de diâmetro. Aparelho cardiovascular,\nrespiratório e abdome sem anormalidades. Considerando a história descrita acima, assinale a\nalternativa que contém o tratamento indicado.","options":{"A":"Imunoglobulina venosa.","B":"Anti-inflamatório não esteroidal.","C":"Antibioticoterapia.","D":"Plasmaférese."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-268910","number":"268910","sourceNumber":"268910","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Uma criança de 4 anos de idade é internada na enfermaria em razão de quadro de\nfebre alta (40ºC), extrema irritabilidade há\nseis dias, conjuntivite não purulenta, língua em\nframboesa, eritema de orofaringe, fissuras e eritema labial, e edema de mãos e pés com\ndescamação periungueal. Apresenta precórdio hiperdinâmico com taquicardia e sopro pansistólico,\nFC = 120 bpm, TAX = 40ºC, SatO2 = 97% e FR = 32 irpm. No exame laboratorial, identifica-se\ntrombocitose. Nesse caso clínico, o diagnóstico mais provável é","options":{"A":"parotidite epidêmica.","B":"escarlatina.","C":"arterite de Takayasu.","D":"púrpura trombocitopênica.","E":"doença de Kawasaki."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-291496","number":"291496","sourceNumber":"291496","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Um menino de 4 anos de idade, previamente hígido e com acompanhamento pediátrico\nregular, chega ao pronto atendimento com\nqueixa de febre (temperatura axilar superior a 38,5ºC em\ntodos os picos), há 6 dias, acompanhada de conjuntivite bilateral não exsudativa. Nega uso prévio\nde medicação nesses últimos dias, exceto o antitérmico habitual para controle da febre. Nega\nviagens recentes ou contato com indivíduos sabidamente doentes. Ao exame clínico, observa-se\nhiperemia de orofaringe sem exsudato ou ulcerações; presença de ressecamento, fissuras e\nhiperemia em lábios e proeminência das papilas linguais; gânglio cervical anterior à direita com\ncerca de 1,5 cm de diâmetro não doloroso; edema endurecido em dorso das mãos e pés com\neritema palmar e plantar difuso; e presença de exantema polimórfico mais intenso em tronco e\nperíneo. Sem outras alterações. Assinale a alternativa que contenha o diagnóstico provável para o\ncaso apresentado e uma complicação associada ao quadro.","options":{"A":"Escarlatina; glomerulonefrite difusa aguda.","B":"Doença de Kawasaki; aneurisma coronariano.","C":"Mononucleose; síndrome de Guillain-Barré.","D":"Sarampo; panencefalite esclerosante subaguda."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-266458","number":"266458","sourceNumber":"266458","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Uma menina de 3 anos de idade foi encaminhada ao pronto-socorro de um hospital por\napresentar, subitamente, dor abdominal e manchas avermelhadas em membros inferiores. As\nmanchas progrediram rapidamente, acompanhadas por inchaço e dor, impedindo-a de caminhar. A\nmãe referiu resfriado comum havia cerca de duas semanas. No exame físico, o médico observou\nque a criança estava em bom estado geral, afebril, com indicadores antropométricos no escore Z=\n0, micropoliadenopatia cervical, abdome indolor à palpação, sem visceromegalias, com lesões\npurpúricas em membros inferiores, edema bilateral em pés e tornozelos e dor à movimentação\npassiva e ativa. Os exames complementares de diagnóstico mostraram: hematócrito: 40%;\nhemoglobina: 13 g%; leucometria 13.000/mm³ com diferencial normal; plaquetas: 400.000/mm³;\nuréia: 20 mg/dL; creatinina: 0,3 mg/dL; glicemia: 85 mg/dL; BT: 1 mg/dL; BD: 0,4 mg/dL; TGO: 30\n\nmg/dL; TGP: 10 mg/dL; PT: 7,5 g/dL; albumina: 4,5 g/dL; EAS: pH 6; 10 piócitos/campo, 15\nhemácias/campo. Considerando o caso clínico hipotético precedente, julgue o item subsecutivo. O\ntratamento indicado para a criança deve ser somente de suporte, com hidratação e nutrição, e\nanti-inflamatórios não esteroides, para aliviar a artrite, não estando indicada, nesse caso,\ndesnecessária a administração de corticosteroides.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-266459","number":"266459","sourceNumber":"266459","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Uma menina de 3 anos de idade foi encaminhada ao pronto-socorro de um hospital por\napresentar, subitamente, dor abdominal e manchas avermelhadas em membros inferiores. As\nmanchas progrediram rapidamente, acompanhadas por inchaço e dor, impedindo-a de caminhar. A\nmãe referiu resfriado comum havia cerca de duas semanas. No exame físico, o médico observou\nque a criança estava em bom estado geral, afebril, com indicadores antropométricos no escore Z=\n0, micropoliadenopatia cervical, abdome indolor à palpação, sem visceromegalias, com lesões\npurpúricas em membros inferiores, edema bilateral em pés e tornozelos e dor à movimentação\npassiva e ativa. Os exames complementares de diagnóstico mostraram: hematócrito: 40%;\nhemoglobina: 13 g%; leucometria 13.000/mm³ com diferencial normal; plaquetas: 400.000/mm³;\nuréia: 20 mg/dL; creatinina: 0,3 mg/dL; glicemia: 85 mg/dL; BT: 1 mg/dL; BD: 0,4 mg/dL; TGO: 30\n\nmg/dL; TGP: 10 mg/dL; PT: 7,5 g/dL; albumina: 4,5 g/dL; EAS: pH 6; 10 piócitos/campo, 15\nhemácias/campo. Considerando o caso clínico hipotético precedente, julgue o item subsecutivo.\nSão diagnósticos diferenciais nesse caso: púrpura trombocitopênica idiopática, leucemia\nlinfoblástica aguda, doença de Kawasaki.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-266460","number":"266460","sourceNumber":"266460","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Uma menina de 3 anos de idade foi encaminhada ao pronto-socorro de um hospital por\napresentar, subitamente, dor abdominal e manchas avermelhadas em membros inferiores. As\nmanchas progrediram rapidamente, acompanhadas por inchaço e dor, impedindo-a de caminhar. A\nmãe referiu resfriado comum havia cerca de duas semanas. No exame físico, o médico observou\nque a criança estava em bom estado geral, afebril, com indicadores antropométricos no escore Z=\n0, micropoliadenopatia cervical, abdome indolor à palpação, sem visceromegalias, com lesões\npurpúricas em membros inferiores, edema bilateral em pés e tornozelos e dor à movimentação\npassiva e ativa. Os exames complementares de diagnóstico mostraram: hematócrito: 40%;\nhemoglobina: 13 g%; leucometria 13.000/mm³ com diferencial normal; plaquetas: 400.000/mm³;\nuréia: 20 mg/dL; creatinina: 0,3 mg/dL; glicemia: 85 mg/dL; BT: 1 mg/dL; BD: 0,4 mg/dL; TGO: 30\n\nmg/dL; TGP: 10 mg/dL; PT: 7,5 g/dL; albumina: 4,5 g/dL; EAS: pH 6; 10 piócitos/campo, 15\nhemácias/campo. Considerando o caso clínico hipotético precedente, julgue o item subsecutivo.\nComprometimento renal grave, a curto prazo, é infrequente em casos como esse.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-266461","number":"266461","sourceNumber":"266461","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Uma menina de 3 anos de idade foi encaminhada ao pronto-socorro de um hospital por\napresentar, subitamente, dor abdominal e manchas avermelhadas em membros inferiores. As\nmanchas progrediram rapidamente, acompanhadas por inchaço e dor, impedindo-a de caminhar. A\nmãe referiu resfriado comum havia cerca de duas semanas. No exame físico, o médico observou\nque a criança estava em bom estado geral, afebril, com indicadores antropométricos no escore Z=\n0, micropoliadenopatia cervical, abdome indolor à palpação, sem visceromegalias, com lesões\npurpúricas em membros inferiores, edema bilateral em pés e tornozelos e dor à movimentação\npassiva e ativa. Os exames complementares de diagnóstico mostraram: hematócrito: 40%;\nhemoglobina: 13 g%; leucometria 13.000/mm³ com diferencial normal; plaquetas: 400.000/mm³;\nuréia: 20 mg/dL; creatinina: 0,3 mg/dL; glicemia: 85 mg/dL; BT: 1 mg/dL; BD: 0,4 mg/dL; TGO: 30\n\nmg/dL; TGP: 10 mg/dL; PT: 7,5 g/dL; albumina: 4,5 g/dL; EAS: pH 6; 10 piócitos/campo, 15\nhemácias/campo. Considerando o caso clínico hipotético precedente, julgue o item subsecutivo. É\nindicada que se faça uma biópsia renal na paciente para a pesquisa de depósitos mesangiais de\nimunocomplexos.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-266462","number":"266462","sourceNumber":"266462","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Uma menina de 3 anos de idade foi encaminhada ao pronto-socorro de um hospital por\napresentar, subitamente, dor abdominal e manchas avermelhadas em membros inferiores. As\nmanchas progrediram rapidamente, acompanhadas por inchaço e dor, impedindo-a de caminhar. A\nmãe referiu resfriado comum havia cerca de duas semanas. No exame físico, o médico observou\nque a criança estava em bom estado geral, afebril, com indicadores antropométricos no escore Z=\n0, micropoliadenopatia cervical, abdome indolor à palpação, sem visceromegalias, com lesões\npurpúricas em membros inferiores, edema bilateral em pés e tornozelos e dor à movimentação\npassiva e ativa. Os exames complementares de diagnóstico mostraram: hematócrito: 40%;\nhemoglobina: 13 g%; leucometria 13.000/mm³ com diferencial normal; plaquetas: 400.000/mm³;\nuréia: 20 mg/dL; creatinina: 0,3 mg/dL; glicemia: 85 mg/dL; BT: 1 mg/dL; BD: 0,4 mg/dL; TGO: 30\n\nmg/dL; TGP: 10 mg/dL; PT: 7,5 g/dL; albumina: 4,5 g/dL; EAS: pH 6; 10 piócitos/campo, 15\nhemácias/campo. Considerando o caso clínico hipotético precedente, julgue o item subsecutivo. O\nenvolvimento do sistema nervoso central ocorre em menos de 10% de casos como a da paciente\nem questão.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-263394","number":"263394","sourceNumber":"263394","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Um pré-escolar com 4 anos de idade foi diagnosticado com COVID-19 há 30 dias, sem\ncomplicações na época. Há 5 dias, tem tido febre diária, 38 a 40 °C, persistente. No segundo dia de\nfebre, apresentou língua em framboesa, linfadenite cervical unilateral (3 cm), tendo recebido, na\nocasião, dose única de penicilina benzatina. Hoje, quinto dia, é atendido no pronto-socorro com\npersistência da febre. Ao exame físico, encontra-se clinicamente hidratado, com hiperemia\nconjuntival bilateral não purulenta, exantema escarlatiniforme, edema em mãos e pés. Em face\ndesse quadro clínico, o exame complementar e o tratamento indicados são, respectivamente,","options":{"A":"sorologia para Epstein-Baar; corticoterapia via oral.","B":"ecocardiograma; aplicação de gamaglobulina via endovenosa.","C":"IgG e IgM para sarampo; reposição de vitamina A via endovenosa.","D":"reação em cadeia da polimerase para espiroquetas; doxiciclina via oral."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-263409","number":"263409","sourceNumber":"263409","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Uma mulher com 20 anos de idade procura atendimento hospitalar devido a quadro\nclínico iniciado há 2 meses com artrite, rash\nmalar, alopécia, além de anemia por doença crônica,\nleucopenia e proteinúria. A pesquisa do fator antínuclear revela-se positiva para Anti-Sm (título\n1:640 e padrão nuclear pontilhado grosso). As pesquisas de Anti-Jo-1, Anti-La e Anti-Ro\napresentam-se negativas. Em face desse quadro clínico, qual é a principal hipótese diagnóstica?","options":{"A":"Polimiosite.","B":"Síndrome Sjogren.","C":"Artrite reumatoide.","D":"Lúpus eritematoso sistêmico."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-291544","number":"291544","sourceNumber":"291544","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Uma mulher de 27 anos de idade, de etnia afrodescendente, retorna ao ambulatório de\nclínica médica para mostrar os resultados dos exames complementares solicitados na última\nconsulta. A paciente havia sido atendida em função de sintomas constitucionais (febre intermitente,\nmal-estar, anorexia, desânimo e artralgias) e importante queda de cabelos. Ao exame físico, havia\nsido observada a presença de sinovite em punhos, cotovelos, joelhos e tornozelos. Além de padrão\nde alopecia generalizada (eflúvio telógeno). Havia histórico familiar de artrite reumatoide, lupus\neritematoso e tireoidite de Hashimoto. A paciente negava tabagismo e etilismo, referindo apenas\nuso regular de contraceptivo hormonal oral. Os resultados dos exames complementares solicitados\nà ocasião da 1.ª consulta revelaram: hemoglobina = 10,2 g/dL (valor de referência: 12 a 15,5 g/dL);\ncontagem de plaquetas = 102 000/mm³ ( valor de referência: 150 000 a 400 000/mm3); leucograma\n(incluindo diferencial) normal; TSH = 8 UI/ml (valor de referência: 0,5 a 5,0 UI/ml); T4 livre = 1,2\nng/dL (valor de referência: 0,9 a 1,9 ng/dL); FAN = presente em título 1:640 (valor de referência <\n1:80), padrão periférico; anti-DNAds: presente em título 1:240 (valor de referência < 1:100); C3: 33\nmg/dL (valor de referência: 90 a 180 mg/dl); VDRL + 1:4 (valor de referência: negativo); IgG\nanticardiolipina: 12 GPL (valor de referência < 10 GPL); ureia: 44 mg/dL (valor de referência: 20 a\n40 mg/dL); creatinina = 1,2 mg/dL (valor de referência: 0,7 a 1,1 mg/dL); exame de urina tipo l com\nhematúria microscópica e proteinúria leve a moderada; SPOT urinário com proteinúria estimada de\n560 mg (valor de referência < 151 mg). Diante dos dados apresentados, a melhor explicação\ndiagnóstica para o caso é","options":{"A":"lúpus eritematoso sistêmico com síndrome do anticorpo antifosfolipídio.","B":"lúpus eritematoso sistêmico evoluindo com nefrite lúpica.","C":"hipotireoidismo associado com síndrome do anticorpo antifosfolipídio.","D":"glomerulonefrite aguda secundária a sífilis associada com hipotireoidismo."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-244474","number":"244474","sourceNumber":"244474","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Uma paciente de 55 anos de idade procurou atendimento ambulatorial em razão de\nartralgias, boca e olhos secos, com\nevolução há um ano. O exame físico evidenciou aumento\nbilateral da glândula parótida, presente no lado direito e no lado esquerdo da região parotídea. O\nhemograma completo era normal, porém VHS = 120 (VR = 10?40). Os testes de Schirmer e de rosa\nbengala foram positivos. Marcadores imunes: FAN positivo alto título, ANTI-RO e ANTI-LA\npositivos, anti-DNA negativo, fator reumatoide negativo. A ultrassonografia indica aumento bilateral\nda glândula submandibular e parótida com múltiplas lesões hipoecoicas, apontando vascularidade\nmuito alta, provavelmente apresentando distúrbio sistêmico como a Síndrome de Sjögren (SS). A\nsialografia revela focos difusos de sialectasias. No que tange a esse caso clínico e aos\nconhecimentos médicos correlatos, assinale a alternativa CORRETA:","options":{"A":"A SS é definida como uma destruição autoimune das glândulas exócrinas (salivares primárias e\nlacrimais), que produz as manifestações clínicas de boca seca, olhos secos (ceratoconjuntivite\nsicca) e, em mais de 50% dos casos, aumento da glândula parótida.","B":"As doenças mais comuns associadas à SS secundária são sarcoidose e esclerodermia. A SS\nprimária é mais comum em mulheres na faixa dos 50 e 60 anos de idade, mas pode afetar\nadolescentes e adultos jovens, além de homens.","C":"A paciente necessita de confirmação diagnóstica com os seguintes exames: biópsia de glândula\nparótida para definição da síndrome sicca, exames de imagem como PET-SCAN para descartar\nsíndrome sicca secundária e neoplasia, e biópsia de glândulas lacrimais.","D":"O tratamento farmacológico indicado para a paciente deve ser com inibidores de checkpoint\ncomo prevenção de envolvimento sistêmico da SS.","E":"A incidência de linfoma de células T é uma complicação comum aos portadores de SS primária,\nsendo mais prevalente nos pacientes idosos, após exposição prévia à cloroquina."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-206094","number":"206094","sourceNumber":"206094","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Assinale a alternativa CORRETA sobre a etiopatogenia do Lúpus Eritematoso\nSistêmico Juvenil (LESJ):","options":{"A":"O LESJ é caracterizado por perda da tolerância imunológica a vários autoantígenos e\nconsequente formação de imunocomplexos que se depositam nos tecidos, determinando\ninflamação em diferentes órgãos e sistemas.","B":"O LESJ envolve apenas o sistema adaptativo.","C":"A doença só pode ser diagnosticada após a adolescência.","D":"A exposição a poluentes atmosféricos e a ativação da doença em crianças e adolescentes com\nLESJ não tem relação."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-206111","number":"206111","sourceNumber":"206111","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Assinale a alternativa INCORRETA em relação ao Lúpus Eritematoso Sistêmico Juvenil\n(LESJ):","options":{"A":"O seguimento das crianças e adolescentes com LESJ deve ser rigorosamente realizado com\npediatra e reumatologista pediátrico.","B":"A hipertensão arterial sistêmica persistente tem sido associada com pior prognóstico e deve ser\nprontamente tratada.","C":"O pronto diagnóstico e o tratamento das infecções são essenciais para os pacientes com LESJ.","D":"As vacinas antipneumocócica e contra HPV são contraindicadas."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-177248","number":"177248","sourceNumber":"177248","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Paciente de 22 anos de idade, do sexo feminino, negra, busca um ambulatório de\nreumatologia após 6 meses de diagnóstico de lúpus eritematoso sistêmico, com relato de\nagravamento dos sintomas. Relata que, após exposição ao sol, percebeu a piora das manchas no\nrosto e o surgimento de quadro doloroso articular nos punhos, nos joelhos e nos tornozelos, além\ndo escurecimento da urina. Depois de realizada a avaliação laboratorial com hemograma,\nevidenciaram-se plaquetopenia, elevação de creatinina para 2,5 e cilindros hemáticos no exame de\nurina. Em relação ao quadro apresentado, a conduta a ser assumida deverá ser:","options":{"A":"Aguardar a urocultura e o início de antibioticoterapia de largo espectro.","B":"Administrar metilprednisolona, seguido de terapia com micofenolato e prednisona.","C":"Administrar prednisona hidroxicloroquina e prescrever analgésicos.","D":"Administrar metilprednisolona, seguido de terapia com rituximabe.","E":"Aguardar os exames laboratoriais para confirmar a agudização lúpica."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-168514","number":"168514","sourceNumber":"168514","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Um criança do sexo masculino com 6 anos de idade é internada em hospital para\ninvestigação de púrpura palpável, não\npruriginosa, com lesões de tamanhos variados, acometendo,\nbilateralmente, a região glútea e membros inferiores, incluido planta dos pés. Há um mês, as lesões\ncutâneas vêm aparecendo em surtos, com intervalos de uma semana. A mãe nega rigidez matinal e\nrelata que o quadro iniciou com dor abdominal difusa, às vezes definida como periumbilical em\ncólicas, com pesquisa de sangue oculto positiva nas fezes. A criança não apresenta febre; lesões\nde face ou mucosas, nem adenomegalias. Não houve uso de medicações antes do aparecimento\ndos sintomas. Ao exame, além da púrpura, apresenta edema e dor em joelhos e tornozelos. Entre\nos exames laboratorias, foram evidenciados leucocitoses discreta sem desvio à esquerda; anemia\nnormocítica e normocrômica, sem reticulocitose; número de plaquetas levemente aumentado;\nvelocidade de hemossedimentação e proteína C reativa levemente elevadas, além de pesquisa de\nantinuclear (FAN) negativo. Exame simples de urina apresentou hemtúria microscópica e\nproteinúria (+), anterior à internação, mas, no momento, o sedimento urinário está normal. De\nacordo com os dados clínicos e laboratorias do paciente, o diagnóstico e o tratamento adequados\nsão","options":{"A":"doença de Kawasaki, gamaglobulina endovenosa e ácido acetilsalicílico.","B":"lúpus eritematoso sistêmico juvenil; pulsoterapia com metilprednisolona.","C":"púrpura de Henoch-Schönlein; prednisona.","D":"artrite idiopática juvenil; ibuprofeno."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-159600","number":"159600","sourceNumber":"159600","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Acerca do Lúpus Eritematoso Sistêmico (LES), julgue o item a seguir: as\nmanifestações cardiovasculares associadas ao LES incluem miocardite, endocardite de\nLibman-Sacks, aterosclerose precoce e acelerada, fenômeno de Raynaud e pericardite.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-104744","number":"104744","sourceNumber":"104744","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Um homem de sessenta anos de idade, portador de neoplasia prostática recidivada\npós-cirurgia, em tratamento com\nquimioterapia, procurou a emergência por apresentar febre e\nmal-estar geral. O exame físico evidenciou emagrecimento, queda de cabelos e pele seca com\nalgumas lesões descamativas. Temperatura axilar de 38 °C; FC = 100 bpm; PA = 122/70 mmHg e\n\nFR = 18 mrpm. O hemograma mostra neutropenia importante de 600 cel/mm³. Considerando esse\ncaso hipotético, o diagnóstico mais provável é\nde:","options":{"A":"leucemia associada.","B":"desidratação.","C":"reação de hipersensibilidade ao esquema quimioterápico.","D":"infecção por gram-negativos.","E":"infecção virótica."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-104747","number":"104747","sourceNumber":"104747","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Um homem de sessenta anos de idade, portador de neoplasia prostática recidivada\npós-cirurgia, em tratamento com quimioterapia, procurou a emergência por apresentar febre e\nmal-estar geral. O exame físico evidenciou emagrecimento, queda de cabelos e pele seca com\n\nalgumas lesões descamativas. Temperatura axilar de 38 °C; FC = 100 bpm; PA = 122/70 mmHg e\nFR = 18 mrpm. O hemograma mostra\nneutropenia importante de 600 cel/mm³. Antes mesmo de\nreencaminhar esse paciente ao seu oncologista, deve-se instituir tratamento com","options":{"A":"Antifúngico.","B":"Antiviral de última geração.","C":"Quinolona.","D":"Anti-histamínico.","E":"Hidratação endovenosa."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-75527","number":"75527","sourceNumber":"75527","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Mulher com 35 anos de idade procura a Unidade Básica de Saúde com queixas de\nvermelhidão na face, que piora com a exposição solar, e dor em punhos e joelhos bilateralmente.\nAo exame apresenta eritema malar, diminuição do murmúrio vesicular na base direita, com macicez\nà percussão neste local, dor à mobilização, edema e rubor em joelhos e punhos. Sem alterações\nnos demais aspectos do exame físico. Traz hemograma recente com hematócrito = 35%,\nhemoglobina = 12 g/dl, leucócitos totais = 3.500/ml, com contagem diferencial normal.\n\nConsiderando a principal hipótese diagnóstica para o quadro da paciente, o autoanticorpo com\nmaior especificidade para a doença é:","options":{"A":"anti-Ro.","B":"anti-RNP.","C":"anti-DNA nativo.","D":"fator antinuclear.","E":"antifosfolípide."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-137604","number":"137604","sourceNumber":"137604","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Uma mulher branca de 22 anos vem à consulta ambulatorial com queixa de\ninchaço há uma semana, inicialmente nos pés, com piora progressiva. Atualmente, percebe\naté o rosto inchado. Há cerca de um mês refere astenia, náuseas, falta de apetite e malestar,\nbem como dores nos punhos e articulações interfalangeanas proximais. Ao exame,\nencontra-se em regular estado geral, hipocorada (++/4+), hidratada, temperatura axilar =\n37,7ºC. Murmúrio vesicular presente e simétrico, sem ruídos adventícios; ritmo cardíaco\n\nregular em 2 tempos, sem sopros, P A = 160 x 110 mmHg, FC = 120 bpm. Abdome flácido,\nsem visceromegalias. Edema de MMII ++/4+. T rouxe exame de sangue realizado no pronto\nsocorro há três dias, de acordo com o quadro a seguir (VER IMAGEM). Considerando a\nprincipal hipótese diagnóstica, a conduta no caso será solicitar","options":{"A":"sumário de urina, avaliação de função renal e pesquisa de autoanticorpos específicos (anti\n\n-Sm e anti -DNA nativo). Iniciar enalapril 10 mg/dia para controle da pressão arterial.","B":"avaliação do oftalmologista para investigação de uveíte, sumário de urina, proteína C reativa e\nVHS. Iniciar dieta hipossódica, com acompanhamento semanal da artrite.","C":"ecocardiograma bidimensional, radiografia de tórax e avaliação de função renal. Iniciar dieta e\nexercício físico, com retorno em um mês para reavaliar a pressão arterial.","D":"radiografia das mãos e punhos e auto-anticorpos como antipeptídeos citrulinados (anti-CCP) e\nfator reumatóide. Iniciar anti-inflamatórios não hormonais","E":"radiografia de tórax, cultura de orofaringe e anticorpo antiestreptolisina O. Iniciar\nanti-inflamatório\nnão esteroide para controle da febre e artrite"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":["question_bank/media/medcurso/med-clinica-medica-med-clm-21/137604.png"],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-138679","number":"138679","sourceNumber":"138679","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Mulher, com 20 anos de idade, branca, é recebida no pronto-socorro com queixa de\nedema há uma semana. Inicialmente, o edema\nera nos membros inferiores, porém, agora, nota a\nface edemaciada. Relata, ainda, diminuição do volume urinário, astenia, hiporexia, mal-estar e febre\nbaixa. Quanto aos antecedentes patológicos, artralgia de interfalangeanas proximais há cerca de\noito meses. Na ocasião, fez uso de prednisona com desaparecimento do quadro. Não usa\nnenhuma medicação no momento. O exame clínico demonstra estado geral regular, hipocorada\n(++/4), edema de membros inferiores (++/4) e de face. Ausculta pulmonar com murmúrio vesicular\npresente e simétrico, sem ruídos adventícios. Ausculta cardíaca com ritmo cardíaco regular, em 2\ntempos, sem sopros, Pressão arterial = 160 x 110 mmHg, Frequência cardíaca = 120 bpm. Abdome\nflácido, sem visceromegalias. Exames no pronto-socorro: Hemoglobina = 8,0 g/L, Hematócrito 24,0\n\n%, Leucócitos totais = 2.400 /mm3 (Segmentados= 84%, Bastões= 2%, Linfócitos = 8%, Eosinófi\nlos = 2%, Monócitos = 2%), Plaquetas =\n100.000 /mm3 (Valor de Referência = 150.000 ? 300.000\n\n/mm3 ). Ureia = 140 mg/dL, (Valor de Referência: 15-40 mg/dL), Creatinina = 2,0 mg/dL (Valor de\nReferência: 0,6-1,2 mg/dL), Potássio = 5,5 mEq/L (Valor de Referência: 3,5-5,0 mEq/L). Qual a\nhipótese diagnóstica para o caso?","options":{"A":"Endocardite infecciosa.","B":"Dengue","C":"Pielonefrite.","D":"Insuficiência renal crônica.","E":"Lupus Eritematoso Sistêmico."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-352191","number":"352191","sourceNumber":"352191","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"A fibromialgia é uma síndrome dolorosa crônica que acomete cerca de 5% da\npopulação geral. Marque a alternativa correta\nsobre os mecanismos e manifestações clínicas desta\ncondição clínica:","options":{"A":"Ocorre uma sensibilização central, ou seja, uma hiperexcitabilidade neuronal que causa resposta\ninadequada e amplificada aos estímulos periféricos.","B":"É uma doença relacionada a gatilhos ambientais, sem base genética associada.","C":"É uma doença que se caracteriza por disfunção, com estudos de imagem por Ressonância\nMagnética funcional (RMf) completamente normais.","D":"Manifestações como fadiga, disfunção de articulação temporomandibular (ATM), cefaleia são\nraros e quando presentes deve-se investigar outros diagnósticos diferencias."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-351605","number":"351605","sourceNumber":"351605","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Considere o caso a seguir: Lactente de 1 ano e 7 meses, masculino, apresenta quadro\nde febre iniciado há 6 dias, frequentemente\nacima de 39°C, associado ao aparecimento de\nexantema em tronco e a perda de apetite. Hiperemia conjuntival, lábios fissurados e bastante\nhiperemiados. Ao exame físico, o pediatra observa edemas em mãos e pés, além de proeminente\nlinfonodomegalia cervical bilateral, com maior linfonodo com cerca de 2 cm. O paciente\napresentava-se sem esforço respiratório, e sem alterações de ausculta pulmonar ou cardíaca.\n\nPreocupado com o quadro, o pediatra recomenda a internação da criança. Sobre o quadro acima\ndescrito, assinale a alterativa CORRETA:","options":{"A":"Recomenda-se a prescrição de imunoglobulina e ácido acetilsalicílico em dose anti-inflamatória.","B":"A despeito de não haver sopro cardíaco, face o quadro acima descrito a principal hipótese\ndiagnóstica é a de endocardite, provavelmente\nrelacionada a quadro de escarlatina incorretamente\nabordado.","C":"Os achados são característicos da miocardite causada pelo vírus da dengue, e exames\nlaboratoriais demonstrando plaquetose e aumento dos\nníveis de proteína C reativa podem ajudar a\nconsolidar o diagnóstico.","D":"Os achados são sugestivos de doença causada por vírus Coxsackie, sendo recomendado\napenas tratamento de suporte."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-346840","number":"346840","sourceNumber":"346840","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Mulher de 28 anos vai ao consultório para seguimento de lúpus eritematoso sistêmico.\nA manifestação ao diagnóstico foi nefropatia\nrenal classe 2, artrite, FAN 1/320 padrão nuclear\nhomogêneo e anti-DNA 1/80 (reduziu para 1/10 após o tratamento inicial). A última consulta ocorreu\n1 ano atrás. Está assintomática. Faz uso regular de hidroxicloroquina 400mg/dia e prednisona 5mg\nMID. O exame físico não apresenta anormalidades. Assinale a alternativa que apresenta um exame\npropedêutico que NÃO está indicado na avaliação periódica dessa paciente.","options":{"A":"Anti-DNA.","B":"Fator Antinúcleo (FAN).","C":"Campimetria visual automática.","D":"Relação albumina-creatinina na urina."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-337625","number":"337625","sourceNumber":"337625","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Paciente sexo feminino, 45 anos, relata que foi diagnosticada com artrite reumatoide há\nalguns anos devido a uma dor nos punhos e um fator reumatoide positivo. Não retornou ao médico\ne não realizou demais exames solicitados. Hoje encontra-se com piora da dor sendo considerada\nincapacitante pela paciente. Acorda pela manhã com dor em punhos e pés bilateralmente. Informa\nnão conhecer outras comorbidades. Ao exame não há sinovite, porém observa leve edema\narticular. Membros inferiores apresentam um padrão de hiperpigmentação heterogênea.\n\nApresenta-se claramente hipocorada. Exames: Hb:6,2, Ht:18%, GL: 3400, Plaq: 94000mm³, FR: 46,\nPCR: 28, VHS: 95mmHg, LDH:1450, reticulocíto: 210.000, Coombs negativo, Haptoglobina < 1,0,\nTGO: 102U/L, TGP: 132U/L, Cr: 0,08mg/dL, Ur: 32mg/dL, EAS: 3+ proteína sem outras\nanormalidades. Considerando o caso descrito, assinale a conduta CORRETA a ser adotada para\nessa paciente:","options":{"A":"Solicitar sorologia para hepatites e dosagem de IgM.","B":"Iniciar hidroxicloroquina para artrite reumatoide.","C":"Iniciar metotrexato e corticoide devido ao quadro agudo para artrite reumatoide.","D":"Iniciar prednisona 1mg/kg."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-337629","number":"337629","sourceNumber":"337629","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Paciente de 46 anos previamente hígida comparece ao pronto atendimento com\ndispneia súbita iniciada pela manhã, informa\nque não estava de repouso, nem em uso de nenhuma\nmedicação. Relata que foi recentemente submetida a uma realização de troca de prótese mamária,\nhá cerca de 7 dias. Refere apenas internação aos 28 anos por um dia para curetagem uterina após\num abortamento de 16 semanas sem causas definidas. Após diagnóstico de TEP a paciente é\nliberada para casa com uso de rivaroxabana. Realizada propedêutica ambulatorial com os\nseguintes resultados: Anticoagulante lúpico não reagente, anticardiolipina IgM: 12UI, IgG:10UI, IgA\n45UI, anti-beta-2 glicoproteína IgM: 42UI e IgG: 16UI. Sobre a possibilidade de diagnóstico de\nSAAF, é CORRETA afirmar que:","options":{"A":"A paciente já possui diagnóstico, possui dois eventos clínicos (TEP e abortamento maior de 10\nsemanas) associado a dois marcadores sorológicos de alto título (anticardiolipina IgA e anti-Beta-2\nglicoproteína IgM.","B":"A paciente ainda não possui diagnóstico devido a ausência de critério clínico: o TEP foi\nprovocado e são necessários mais de um\nepisódio de abortamento maior de 10 semanas. Além\ndisso é necessária a repetição dos exames 12 semanas após e avaliar a persistência da\npositividade (nesse caso apenas a anti-Beta-2 glicoproteína pontuaria como critério, uma vez que\napenas a anticardiolipina IgA encontra-se positiva).","C":"A paciente já possui diagnóstico, possui um evento clínico (abortamento maior que 10 semanas)\nassociado a dois marcadores sorológicos de alto título (anticardiolipina IgA e anti-Beta-2\nglicoproteína IgM).","D":"A paciente ainda não possui diagnóstico, apresenta um critério clínico (um episódio de\nabortamento maior de 10 semanas) e positividade\ninicial para um marcador sorológico (nesse caso\napenas a anti-Beta-2 glicoproteína pontuaria como critério, uma vez que apenas a anticardiolipina\nIgA encontra-se positiva). Para confirmar diagnóstico devem ser repetidos os exames após 12\nsemanas."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-337630","number":"337630","sourceNumber":"337630","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Paciente do sexo feminino, 53 anos, procura atendimento por apresentar quadro de\nrefluxo importante nos últimos 6 meses, relata\nque isso tem atrapalhado a rotina de sua vida diária.\nInforma que além disso apresenta períodos de diarreia alternada com constipação intestinal e que\nrecentemente iniciou uso de IECA prescrito na UBS devido a HAS, refere que até 6 meses atrás\nnão era hipertensa. Ao exame físico é observado cianose em três dedos da mão direita e pequenas\nulcerações digitais, e ainda telangiesctasias ungueais e esclerose cutânea. Sobre o diagnóstico\ndessa paciente, assinale a alternativa INCORRETA:","options":{"A":"Comumente pode apresentar hipertensão pulmonar.","B":"Trata-se de paciente que apresenta maior risco de neoplasia.","C":"Apresenta elevada positividade de anti-Ro.","D":"FAN é positivo em aproximadamente 95% dos pacientes com esclerose sistêmica."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-306696","number":"306696","sourceNumber":"306696","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Menino, 6 anos é levado ao PS com relato de quadro respiratório viral prévio há 10 dias\ncom remissão espontânea sendo realizado RT-PCR para Covid negativo. Hoje iniciou manchas\nvermelhas em membros inferiores e nádegas associado à dor abdominal e 2 episódios de vômito.\n\nAo exame: bom estado geral, hipocorado +/4, hidratado, afebril. Lúcido, cooperativo ao exame.\nPresença de lesões cutâneas eritematosas,\npetéquias e equimoses em membros inferiores, região\nglútea e pés. Dor e edema em tornozelos bilateralmente. Exames laboratoriais: Hb 11 / Htco 34,8 /\nLeuco 16.700 (NB 02/ NS 54 / Eo 03 / L 33 / M 08) PLQ 257.000 TAP 88% PTTk 26? PCR 22,0\n\nEAS ? pH 7,0 / DU 1010 / raros leucócitos / numerosas hemácias / (+) proteína / nitrito negativo /\nflora escassa/ Qual provável diagnóstico?","options":{"A":"Glomerulonefrite aguda pós estreptocócica","B":"Síndrome Hemolítico-urêmica","C":"Púrpura Henoch-Schonlein","D":"Lupus Eritematoso Sistêmico"},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-313278","number":"313278","sourceNumber":"313278","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"A síndrome da fibromialgia pode ser definida como uma síndrome:","options":{"A":"Dolorosa aguda, não inflamatória, de etiologia autoimune.","B":"Dolorosa aguda, inflamatória, de etiologia ligada ao colágeno.","C":"Dolorosa aguda, não inflamatória, de etiologia desconhecida.","D":"Dolorosa crônica, inflamatória, de etiologia desconhecida.","E":"Dolorosa crônica, não inflamatória, de etiologia desconhecida."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-314037","number":"314037","sourceNumber":"314037","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"O Lúpus Eritematoso Sistêmico (LES) é uma doença autoimune crônica multissistêmica\nque afeta, com maior frequência, mulheres em\nidade fértil, e ocorre em decorrência a danos\nteciduais mediados pelo sistema imune. Em relação ao Lúpus, assinalar a alternativa CORRETA:","options":{"A":"Artralgias e artrites erosivas são uma das características clínicas mais comuns do LES, sendo\nencontradas na maioria dos pacientes.","B":"As lesões discoides características do LES sempre aparecem na presença de manifestações\nsistêmicas.","C":"Os nódulos em valvas cardíacas é a manifestação cardíaca mais comum.","D":"O envolvimento renal é frequente no LES, sendo um indicador de pior prognóstico.","E":"O único sistema que não apresenta manifestações pelo LES é o sistema pulmonar."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-306725","number":"306725","sourceNumber":"306725","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"P.D.T, sexo feminino, 27 anos, vem à consulta médica por estar apresentando quadro\nde fadiga e perda de peso nos últimos 3\nmeses. Relata que nos últimos 2 meses vem apresentando\nmialgia e artralgia. Traz exames laboratoriais que demonstram: hemoglobina = 9.0g/dL, plaquetas =\n98.000/mm3, ureia = 28 e creatinina = 1.8. Diante deste quadro, foi solicitada a dosagem de fator\nantinuclear (FAN), que foi positivo. Com base no caso apresentado, marque a alternativa correta.","options":{"A":"A paciente apresenta diagnóstico incontestável de lupus eritematoso sistêmico e como\napresenta disfunção renal deverá receber glicocorticoides em doses elevadas.","B":"A paciente apresenta diagnóstico possível de lupus eritematoso sistêmico e como não apresenta\nsituação ameaçadora à vida deverá receber\ntratamento conservador.","C":"A paciente não preenche os critérios para diagnóstico de lupus eritematoso sistêmico, portanto,\noutras patologias devem ser pesquisadas, com\ngrande possibilidade de fibromialgia ser o\ndiagnóstico.","D":"A paciente não apresenta diagnóstico de lupus eritematoso sistêmico, uma vez que os sintomas\nsão inespecíficos e a positividade de fator\nantinuclear pode ocorrer em várias situações"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-260698","number":"260698","sourceNumber":"260698","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Uma paciente de 24 anos, com diagnóstico de lúpus eritematoso sistêmico, foi atendida\ncom quadro de hipertensão arterial, edema\nperiférico e palidez cutânea. Seus exames mostraram:\nHT 24%, Hb 8,0 g%, leucócitos 3.200/mm3, plaquetas 78.000/mm3, ureia 75 mg%, creatinina 2,0\nmg%, albumina 2,3 g%, colesterol total 265 mg%, sedimento urinário com PTN 3+ e 10\nhemácias/campo e proteinúria de 4,5 g/24h. Realizou uma biópsia renal que mostrou proliferação\ncelular mesangial, nas alças capilares, difusamente, com importante infiltrado tubulointersticial e\npresença de crescentes celulares em mais de 50% dos glomérulos. Em relação ao caso, é\nCORRETO afirmar que:","options":{"A":"Anticorpos anticitoplasma de neutrófilos comumente vêm positivos nestes casos.","B":"Pulsoterapia com corticoide, quando associado com hidroxicloroquina, leva à remissão da nefrite\nna maioria dos casos.","C":"Uma microscopia de imunofluorescência mostrará deposição de IgG linear nas alças capilares.","D":"Pulsoterapia com corticoide, quando associado a ciclofosfamida ou micofenolato mofetil são\nboas opções de tratamento para remissão da\nnefrite.","E":"A paciente tem padrão histológico típico de nefrite lúpica classe V."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-283922","number":"283922","sourceNumber":"283922","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Uma paciente de 10 anos é hospitalizada por dor abdominal e pelo ressurgimento de\núlceras dolorosas e rasas, com eritema circundante, comprometendo mucosa bucal, gengiva, lábios\ne língua. Observam-se, ainda, úlceras genitais em grandes lábios. Também apresenta dores,\nhiperemia e edema em joelho direito e tornozelo esquerdo que recorrem a cada 15 dias. O mais\nprovável diagnóstico desta paciente é:","options":{"A":"Dermatomiosite juvenil.","B":"Doença de Behçet.","C":"Síndrome inflamatória multissistêmica.","D":"Síndrome de Sjögren.","E":"Síndrome de Kawasaki."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-227078","number":"227078","sourceNumber":"227078","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Mulher de 25 anos se queixa de dor e edema no punho direito, no joelho esquerdo e na\n2ª articulação metacarpofalangeana da mão\ndireita, com rigidez matinal de 15 minutos nas mãos.\n\nApresenta astenia, intolerância ao esforço físico, anorexia, e perdeu 5kg em 4 meses. Relata\nepisódios de palidez e cianose das pontas\ndos dedos se baixas temperaturas. Há 3 semanas surgiu\nedema nas pernas e na face. Nega quaisquer outros sintomas, desconhece doenças prévias e\nnega uso regular de medicamentos. Ao exame físico, PA: 150 X 86mmHg, FC 98bpm, FR 17ipm,\nSpO? 98%. Alerta, orientada, mucosas hipocoradas e hidratadas. Exame respiratório,\ncardiovascular e abdominal sem anormalidades. Há edema, rubor, dor à palpação da 2ª articulação\nmetacarpofalangeana direita e do punho direito, onde também se observa redução da amplitude de\nmobilidade. O joelho esquerdo apresenta derrame articular. Há edema maleolar simétrico. Exames\nde laboratório: hemoglobina 10,2g/dL, HCM 29pg, VCM 90fL, CHCM 33g/dL, leucócitos 3.560/mm³,\nneutrófilos segmentados 980/mm³, plaquetas 123.000/mm³, proteína C reativa 15mg/dL, creatinina\n1,5mg/dL, ureia 17mg/dL, albumina 2,4g/dL, fator reumatoide 35, anti-CCP negativo, anti-SSA\npositivo, fator antinuclear 1:640, anti-SSB positivo, anti-DNA nativo positivo, anti-Sm positivo,\n\nanti-RNP negativo, C3 54mg/dL, C4 5mg/dL, coombs direto positivo, lactato desidrogenase 130,\nbilirrubina total 0,5, reticulócitos 1,2%. Exame de urina: proteína 4+, 34 hemácias por campo, com\n25% de codócitos, 12 piócitos/campo. Considerando o caso descrito, assinale a alternativa que\napresenta a hipótese diagnóstica MAIS PROVÁVEL para essa paciente:","options":{"A":"Artrite reumatoide.","B":"Esclerose sistêmica.","C":"Lúpus eritematoso sistêmico.","D":"Síndrome de Sjögren."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-246724","number":"246724","sourceNumber":"246724","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Em indivíduos portadores de esclerose sistêmica, as estruturas mais acometidas pela\ndoença, além da pele, são:","options":{"A":"Rins e fígado","B":"Pleura e pericárdio","C":"Rins e sistema nervoso central","D":"Trato gastrointestinal e pulmões","E":"Íleo terminal e úvea"},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-227102","number":"227102","sourceNumber":"227102","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"A doença de Kawasaki é uma vasculite que, às vezes, envolve as artérias coronárias e\ntende a ocorrer em lactentes e crianças de 1 a 8 anos. Sobre a doença de Kawasaki, assinale a\nalternativa INCORRETA:","options":{"A":"O tratamento é feito com ácido acetilsalicílico e globulina imune intravenosa.","B":"A doença de Kawasaki é uma vasculite de artérias de tamanho grande.","C":"O diagnóstico é baseado em critérios clínicos, acompanhados de ecocardiograma.","D":"O diagnóstico é feito se a febre durou ? 5 dias associados a outros critérios como conjuntivite\nbilateral."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-243027","number":"243027","sourceNumber":"243027","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Criança de cinco anos, sexo masculino, apresenta dor abdominal, artralgia, hematúria e\nlesões avermelhadas que não somem a digito pressão em membros inferiores e nádegas.\n\nHemograma normal com 250.000 plaquetas. Qual o diagnóstico?","options":{"A":"purpura trombocitopenica idiopática.","B":"purpura trombocitopenica trombótica.","C":"purpura de henoch-shonlein.","D":"meningococcemia.","E":"sarampo."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-220315","number":"220315","sourceNumber":"220315","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Criança de 5 anos, previamente hígida, é levada a um pronto atendimento por\napresentar, há 5 dias, quadro abdominal,\nedema e dor no tornozelo direito, associados à presença\nde lesões purpúricas em membros inferiores e nádegas. Hemograma realizado mostrou discreta\nleucocitose com contagem de plaquetas e hemoglobina normais. Assinale a alternativa que\napresenta a PRINCIPAL hipótese diagnóstica para essa criança:","options":{"A":"Púrpura de Henoch-Schölein.","B":"Lúpus eritematoso sistêmico.","C":"Púrpura trombocitopênica autoimune.","D":"Leucemia linfocítica aguda."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-220319","number":"220319","sourceNumber":"220319","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Criança com 2 anos é internada por apresentar quadro de febre de 39°C há 6 dias, sem\nmelhora com o uso de antitérmicos. Recebeu avaliação médica por 2 vezes, com diagnóstico de\namigdalite viral. Exame físico mostrou criança com regular estado geral, prostrada, com\nlinfadenopatia cervical de 2,5 cm de diâmetro, exantema maculopapular difuso, edema de mãos e\npés, conjuntivite bilateral não supurativa e presença de hiperemia labial e de orofaringe com língua\nem framboesa. Hemograma com leucocitose com predomínio de neutrófilo, contagem de plaquetas\nnormais e provas de atividades inflamatórias aumentadas (VHS, proteína C reativa). Considerando\no caso descrito, assinale a alternativa que apresenta a PRINCIPAL hipótese diagnóstica:","options":{"A":"Doença de Kawasaki.","B":"Escarlatina.","C":"Artrite idiopática juvenil.","D":"Mononucleose infecciosa."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-202762","number":"202762","sourceNumber":"202762","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Uma paciente de 24 anos, com diagnóstico de lúpus eritematoso sistêmico, foi atendida\ncom quadro de hipertensão arterial, edema\nperiférico e palidez cutânea. Seus exames mostraram:\nHT = 24%; Hb = 8,0 g%; leucócitos = 3.200/mm³; plaquetas = 78.000/mm³; ureia = 75 mg%;\ncreatinina = 2,0 mg%; albumina = 2,3 g%; colesterol total = 265 mg%; sedimento urinário com PTN\n3+ e 10 hemácias/campo e proteinúria de 4,5 g/24h. Realizou uma biópsia renal que mostrou\nproliferação celular mesangial, nas alças capilares, difusamente, com importante infiltrado\ntubulointersticial e presença de crescentes celulares em mais de 50% dos glomérulos. Em relação\nao caso, é CORRETO afirmar que:","options":{"A":"A paciente tem padrão histológico típico de nefrite lúpica classe V.","B":"Anticorpos anticitoplasma de neutrófilos comumente vêm positivos nestes casos.","C":"Pulsoterapia com corticoide, quando associada com hidroxicloroquina, leva a remissão da nefrite\nna maioria dos casos.","D":"Pulsoterapia com corticoide, quando associada a ciclofosfamida ou micofenolato mofetil são\nboas opções de tratamento para remissão da\nnefrite.","E":"Uma microscopia de imunofluorescência mostrará deposição de IgG linear nas alças capilares."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-215132","number":"215132","sourceNumber":"215132","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Menino de 4 anos é internado por apresentar febre de 39°C por 6 dias, conjuntivas\nhiperemiadas, sem secreções, exantema polimorfos, fissuras labiais, edemas de mãos e pés,\nfissuras labiais e adenopatia cervical. O tratamento visa prevenir qual complicação?","options":{"A":"Endocardite bacteriana.","B":"Aneurisma de coronária.","C":"Insuficiência hepática.","D":"Edema cerebral.","E":"Estenose de valva mitral."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-187510","number":"187510","sourceNumber":"187510","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Menino de 4 anos de idade foi levado ao pediatra porque têm febre há 9 dias. Ao\nexame físico nota-se hiperemia conjuntival\nbilateral não purulenta, palmas das mãos e plantas dos\npés com eritema e edema indurado, fissuras labiais, \"rash\" maculo-papular eritematoso em tronco e\nmembros, e adenopatia cervical à esquerda (de 2 cm de diâmetro). Exames laboratoriais\nmostraram leucocitose com neutrofilia, trombocitose, VHS= 55 mm/h, PCR= 10 mg/dl, TGO = 80\nU/L e TGP= 60 U/L, hipoalbuminemia, hiponatremia. Qual o diagnóstico mais provável?","options":{"A":"Difteria.","B":"Doença de Lyme.","C":"Artrite reumatoide.","D":"Doença de Kawasaki.","E":"Lúpus eritematoso sistêmico."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-172543","number":"172543","sourceNumber":"172543","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Criança de 3 anos iniciou há 6 dias febre alta, hiperemia conjuntival bilateral não\nsecretiva, ressecamento dos lábios, eritema de língua, gânglios palpáveis à esquerda de região\ncervical (não palpável à direita) e exantema maculopapular difuso. Sobre essa doença NÃO\npodemos afirmar:","options":{"A":"Trata-se de uma doença de vasos de médio calibre, etiopatogenia viral, autolimitada, requerendo\napenas tratamento com corticosteroides e\nsintomáticos.","B":"Diagnóstico é clínico, não sendo necessária a biópsia de gânglio.","C":"Ecocardiograma basal deve ser realizado no momento da doença aguda e repetido após, no\nseguimento periódico na avaliação cardiovascular.","D":"Os objetivos do tratamento são reduzir a inflamação e evitar a formação de aneurismas\ncoronarianos."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-149134","number":"149134","sourceNumber":"149134","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Paciente 16 anos, com história de sinusites de repetição (mais de 8 episódios), rinite\nalérgica, faringoamigdalites (a última em abril/16) tratada com amoxicilina/clavulanato.\n\nEm julho/16 apresentou otite média complicada com mastoidite, sendo iniciado uso de\nclaritromicina. Ao término do tratamento, não\nhouve melhora, persistência da febre e dos sintomas,\ncom surgimento de artralgia de grandes articulações motivando a internação em outro hospital,\nquando foi medicada\n\ninicialmente com levofloxacina (sem relato de melhora), substituído por ceftriaxona (usou 3 dias e\nfoi liberada com cefuroxime oral por mais 10 dias). Agora é internada HECI com queixas de dor\nabdominal, surgimento de lesões papulares e violáceas inicialmente em membros e no dorso,\nprogredindo até face, tronco, indolores e que não desaparecem a digitopressão, além da\npersistência do quadro febril (VER IMAGENS). Diante do exposto é qual é o diagnóstico clínico?","options":{"A":"Trata-se de púrpura de Henoch-Schonlein.","B":"Trata-se de síndrome de Stevens-Jhonson.","C":"Sepse por estreptococos.","D":"Reação Urticarifome por alergia a ceftriaxone.","E":"Há necessidade de biópsia de pele para confirmação diagnóstica."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":["question_bank/media/medcurso/med-clinica-medica-med-clm-21/149134.png"],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-155373","number":"155373","sourceNumber":"155373","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Esclerose sistêmica, com comprometimento visceral grave e hipertensão pulmonar,\nestá relacionada mais especificamente ao seguinte\nautoanticorpo:","options":{"A":"Topoisomerase I.","B":"Centrômero.","C":"RNA Polimerase III.","D":"U3-RNP.","E":"U1-RNP."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-155374","number":"155374","sourceNumber":"155374","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Marque a opção que indica o anti-inflamatório mais implicado em evento adverso de\nmeningite asséptica, em paciente com Lúpus Eritematoso Sistêmico:","options":{"A":"Ibuprofeno.","B":"Diclofenaco.","C":"Cetoprofeno.","D":"Indometacina.","E":"Nimesulida."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-148559","number":"148559","sourceNumber":"148559","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"A Doença de Kawasaki é uma vasculite febril aguda da infância. Observe as afirmativas\nabaixo e marque a sentença correta.","options":{"A":"A Doença de Kawasaki acomete principalmente crianças com mais de seis anos de idade.","B":"A Doença de Kawasaki é uma doença que provoca uma vasculite transitória e não leva a\nsequelas vasculares.","C":"A doença de Kawasaki pode causar vasculite grave de todos os vasos sanguíneos, mas\npredominantemente afeta as artérias de médio calibre, com predileção pelas artérias coronarianas.","D":"A doença de Kawasaki pode causar vasculite de todos os vasos sanguíneos, mas predomina\nnas artérias de pequeno calibre do cérebro.","E":"Na Doença de Kawasaki, o tratamento com imunoglobulina não está indicado."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-77591","number":"77591","sourceNumber":"77591","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Paciente do sexo masculino, 68 anos, com história de há seis meses apresentar\nsinusite recorrente, estenose subglótica, surdez de\ncondução e neurossensorial, nódulos\npulmonares com cavitação e proptose. Qual o marcador da provável doença?","options":{"A":"Antiproteinase-3.","B":"Fator antinuclear.","C":"Anti-CCP.","D":"PPD.","E":"Antimieloperoxidase."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-363888","number":"363888","sourceNumber":"363888","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Paciente de 38 anos, sexo masculino, com quadro de dor aguda no membro inferior\ndireito iniciada há 2 horas. Nega doenças prévias.\nTabagista 30 anos-maço e etilista social. Ao\nexame físico apresenta frialdade e palidez no membro inferior direito e ausência de pulsos tibiais.\nDiante do quadro clínico apresentado, qual é o diagnóstico?","options":{"A":"Trombose venosa profunda do membro inferior direito.","B":"Phlegmasia Alba Dolens.","C":"Doença de Buerger.","D":"Doença de Cockett."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-354817","number":"354817","sourceNumber":"354817","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Leia o relato do caso clínico a seguir. Criança, 8 anos de idade, sexo feminino, é levada\npelos pais ao atendimento pediátrico na unidade básica de saúde por apresentar quadro de\npetéquias e manchas em membros inferiores, dor abdominal e hematúria, confirmada por exame de\nurina simples. Ao exame físico apresenta-se com estado geral preservado, abdome flácido com\nruídos hidroaéreos presentes, discreta dor a mobilização de joelhos, lesões purpúricas palpáveis\n(maioria petéquias, com algumas equimoses) em membros inferiores, região glútea e poucas em\nabdome inferior. De acordo com o caso apresentado a hipótese diagnóstica é","options":{"A":"púrpura de Henoch-Schonlein.","B":"púrpura trombocitopênica imunológica.","C":"púrpura fulminante.","D":"púrpura da Doença de Von Willebrand."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-354840","number":"354840","sourceNumber":"354840","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Leia o relato do caso clínico a seguir. Paciente A.R., feminina, 35 anos de idade,\ncasada, cabeleireira, nega comorbidades, nega\nalergia a medicamentos, nega etilismo, nega\ntabagismo e nega consumo de outras drogas, sedentária; S1. Paciente refere dolorimento nos\núltimos sete dias em mandíbula direita, mandíbula esquerda, cervical, ombro direito, antebraço\ndireito, coluna torácica (dorsal), abdômen, coluna lombar e perna direita. Nega dor nos últimos 7\ndias em: ombro esquerdo, braços, tórax anterior, quadris, coxas e perna esquerda. Paciente refere\nainda, nos últimos 7 dias, fatigabilidade moderada, sono não reparador com cansaço intenso ao\ndespertar, sintomas cognitivos moderados (dificuldade de concentração e déficit em memória).\n\nEntre outros sintomas refere que há mais de 6 meses experimenta intenso incômodo por cefaleias,\nhumor deprimido e câimbras musculares no\nabdômen inferior. A anamnese acima, no modelo\nSOAP, foi muito bem redigida para a hipótese de fibromialgia por abordar o índice de dor difusa\n(IDD) e escala de severidade dos sintomas (Escala de Gravidade, ESS) de acordo com o bem\nestabelecido Critério do Colégio Americano de 2010/2011, revisado em 2016. De acordo com o\nrelato, o IDD e a ESS da paciente são, respectivamente,","options":{"A":"8 e 6.","B":"8 e 10.","C":"9 e 10.","D":"10 e 9."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-363986","number":"363986","sourceNumber":"363986","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"A pesquisa dos autoanticorpos anti-DNA de dupla hélice (anti-dsDNA) é útil não apenas\npara o diagnóstico, mas também para o\nseguimento de pacientes com Lúpus Eritematoso Sistêmico\n(LES), sobretudo na suspeita de envolvimento renal. A técnica recomendada para detecção, nesse\ncaso, é a imunofluorescência indireta, usando como substrato","options":{"A":"as células HEp-2.","B":"imprint de fígado de camundongos.","C":"células de câncer de laringe.","D":"a Crithidia luciliae."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-331959","number":"331959","sourceNumber":"331959","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Mulher, 28 anos, avaliada por dor em região inguinal esquerda há três semanas, que\npiora à deambulação. Sem outras queixas. Antecedentes pessoais: lúpus eritematoso sistêmico\ncom nefrite, tratada com pulsos de corticoide nos últimos dez anos e em uso de prednisona 10 mg\ncomo manutenção, associada à hidroxicloroquina. Exame físico: PA 120x78 mmHg, FC 80 bpm.\n\nDesconforto discreto em região inguinal esquerda com a movimentação da articulação coxofemoral.\nRestante do exame físico normal.\nRadiograma de quadril normal. Considerando a hipótese\ndiagnostica de necrose avascular de cabeça de fêmur, é correto:","options":{"A":"O radiograma de quadril normal afasta a hipótese diagnóstica.","B":"A ressonância nuclear magnética de quadril identifica lesões incipientes.","C":"O exame padrão-ouro para diagnostico é a cintilografia com leucócitos marcados.","D":"A substituição da prednisona por prednisolona retarda a progressão da lesão."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-339763","number":"339763","sourceNumber":"339763","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Uma paciente de 28 anos apresenta úlceras orais dolorosas há dois anos e mais\nrecentemente passou a se queixar de\nborramento visual, lesões em membros inferiores e episódios\nde hemoptise. A investigação detectou panuveite, eritema nodoso e aneurismas em ramos da\nartéria pulmonar. Qual o diagnóstico mais provável para esse caso?","options":{"A":"Doença de Goodpasture (doença antimembrana basal glomerular).","B":"Granulomatose com polianglite (granulomatose de Wegener).","C":"Doença de Behçet.","D":"Sifilis.","E":"Crioglobulinemia."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-342631","number":"342631","sourceNumber":"342631","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Um homem de 40 anos apresenta edema e parestesia nos membros inferiores,\nacompanhados de dispneia e cefaleia diária há 4 semanas. Ao exame, observam-se PA =\n220x160mmhHg e congestão pulmonar. Apresenta hemoglobina = 5g/dL, ureia = 230mg/dL,\ncreatinina = 6mg/dL e sedimento urinário com hematúria dismórfica. Em 24 horas, evoluiu com\ninsuficiência respiratória, hemoptise, mesmo após hemodiálise e hemotransfusão. Quais são as\nprincipais hipóteses diagnósticas e condutas nesse caso?","options":{"A":"granulomatose com poliangiite; pulsoterapia com metilprednisolona (MP) 1g por 3 dias e\nciclofosfamida a e, se possível, plasmaférese","B":"poliangiite microscópica ou vasculite de Churg-Strauss; pulsoterapia com MP 1g por 5 dias e\nrituximabe","C":"glomerulonefrite rapidamente progressiva hemorragia alveolar; imunoglobulina intravenosa,\ncorticosteroide 1 mg/kg/d e ciclofosfamida","D":"sindrome de Evans; pulsoterapia com MP 1g por 3 dias e prednisona 1 mg/kg/d"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-334808","number":"334808","sourceNumber":"334808","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Embora o Lupus Eritematoso sistêmico seja mais comum entre mulheres entre 20 e 40\nanos, cerca de 5% dos casos ocorrem na infância. Segundo o Colégio Americano de Reumatologia\nsão necessários pelo menos 4 critérios para o diagnóstico desta doença, que são:","options":{"A":"rash malar, plaquetopenia (<100.000/mm³), anti-Sm Positivo e úlceras Orais/nasofaringeas.","B":"atrofia muscular, poliartrite, leucocitose (>20.000 em 2 ocasiões) e contagem de CD4<50.","C":"disfagia, sinal de Gottron, plaquetopenia (<150.000/mm³) e rash cutâneo.","D":"anemia ferropriva acentuada, livedo reticular, prurido e rash cutâneo."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-342648","number":"342648","sourceNumber":"342648","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Uma criança de 3 anos iniciou, há 6 dias, febre alta, hiperemia conjuntival bilateral não\nsecretiva, ressecamento dos lábios, eritema de língua, gânglios palpáveis à esquerda da região\ncervical (não palpável à direita) e exantema maculopapular difuso. Sobre essa doença não se\npodemos afirmar que:","options":{"A":"trata-se de uma doença de vasos de médio calibre, etiopatogenia viral, autolimitada, requerendo\napenas tratamento com corticosteroides e\nsintomáticos","B":"o diagnóstico é clínico, não sendo necessária a biópsia de gânglio","C":"ecocardiograma basal deve ser realizado no momento da doença aguda e repetido após, no\nseguimento periódico na avaliação cardiovascular","D":"os objetivos do tratamento são reduzir a inflamação e evitar a formação de aneurismas\ncoronarianos"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-339819","number":"339819","sourceNumber":"339819","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"N.C., 5 anos, previamente hígida, é internada em um hospital terciário para a\ninvestigação de febre iniciada há 6 dias. Como\nsintomas associados, apresentava rash\nmaculopapular, principalmente em tronco; hiperemia e lacrimejamento ocular; edema nas mãos e\npés e linfoadenomegalia cervical indolor à esquerda, com diâmetro aproximado de 2 cm. Qual a\ncomplicação mais grave associada a esse quadro?","options":{"A":"Estenose de válvula mitral","B":"Pericardite","C":"Vasculite coronariana","D":"Miocardiopatia hipertrófica","E":"Endocardite infecciosa"},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-302829","number":"302829","sourceNumber":"302829","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Um paciente de 40 anos foi admitido ao hospital com queixas de febre, perda de peso,\nsurgimento de lesões cutâneas e dor neuropática de forte intensidade, há três meses. Relatava\nhistória de asma e rinossinusite há seis anos, de difícil controle, requerendo cursos frequentes de\ncorticoide oral. Ao exame físico, observam-se lesões purpúricas elevadas e dolorosas em membros\ninferiores, e o exame neurológico foi compatível com mononeurite multiplex. Qual dos achados\nabaixo não seria compatível com o caso descrito?","options":{"A":"Eosinofilia >1500/mm³.","B":"Níveis reduzidos de complemento.","C":"ANCA positivo.","D":"Tomografia de tórax mostrando infiltrados e nódulos pulmonares não cavitários.","E":"Biópsia cutânea, mostrando vasculite necrotizante com infiltrado eosinofílicocolectomia."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-317919","number":"317919","sourceNumber":"317919","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Os aneurismas da artéria pulmonar estão associados mais comumente a qual das\nseguintes doenças?","options":{"A":"Doença de Behçet.","B":"Aterosclerose.","C":"Poliarterite nodosa.","D":"Síndrome de Ehlers-Danlos."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-316318","number":"316318","sourceNumber":"316318","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"JSM, sexo masculino, 52 anos, dá entrada no PS relatando fadiga, cansaço, perda de\npeso de 10kg nos últimos 6 meses, fraqueza\nnos membros inferiores e sintomas respiratórios\nrecorrentes. Foram solicitados exames laboratoriais que apresentavam: tgo 34 tgp 44, HTC 44, HB\n12, Leuco 1000, bastão 1% plaquetas: 230.000, anti dna negativo, anti mp negativo, sorologias\nvirais hepatite B, C e HIV 1 2 negativo, eletroforese de proteína normal, c anca ++, Cr 5,4 k 7,1 Na\n145 Ur 240 PH 7,1 BIC 10, EAS com presença de proteína +++, leve hematúria. Tc de tórax com\nlesão em vidro fosco e nódulos em pulmão. Encaminhado à UTI, por apresentar rebaixamento do\nnível de consciência e diurese < 0,5ml/kg/h em 6h de observação. Diante do caso, qual o provável\ndiagnóstico e possível tratamento a ser realizado?","options":{"A":"Síndrome de goodpasture, hemodiálise urgência e plasmaférese.","B":"Nefropatia por LES, imunossupressão com corticoide.","C":"Nefropatia por amiloidose, prednisona, suporte clínico e hemodiálise urgência.","D":"Granulomatose de Wegner, imunossupressão corticoide + ciclofosfamida e hemodiálise\nurgência."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-317167","number":"317167","sourceNumber":"317167","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Mulher de 24 anos com quadro de rash malar, lesões eritematosas em braços e região\nsuperior de tórax, poliartralgia de mãos e pés de caráter inflamatório, edema de membros inferiores\ne face e espumúria. Refere que o quadro iniciou após falecimento da mãe. Ao exame: BEG,\nemagrecida, afebril, eupnéica. Eritema malar poupando sulco nasolabial e lesões eritematosas em\nbraços e tronco. MVF sem RA. FC 80; PA 170/100 mmHG. MMII com edema 2+/4+, panturrilhas\nlivres. Exames complementares: Hb 9, Ht 27, VCM 85, HCM 30, leucócitos 4500, linfócitos 1500,\nplaquetas 200ml/mm3: C3 30 (VR 90-180); C4 4 (VR 16-38); FAN nuclear pontilhado grosso;\n\nanti-Sm reagente. anti-DNA 1/640; coombs direto positivo; bilirrubinas totais de 2,4 mg/dl (VR 0,2 -\n1,1) e indireta de 2,0 mg/dl (VR 0,2-0,8), ferro sérico e ferritnina sérica normal; EAS com\nhematúria,\nproteinúria e cilindros hemáticos; proteinúria de 24 horas de 3 g (volume 2000 ml). Em relação ao\nquadro hematológico, qual o diagnóstico?","options":{"A":"Anemia de doença crônica","B":"Anemia carencial","C":"Anemia hemolitica auto-imune","D":"Anemia hereditária"},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-294280","number":"294280","sourceNumber":"294280","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"O padrão nuclear pontilhado grosso com placa cromossômica de células em metáfase\nnão corada, exibido no exame de\nimunofluorescência indireta em células HEp-2, está em geral\nassociado a quais anticorpos?","options":{"A":"Anti-DNA e anti-Scl-70.","B":"Anti-Scl-70 e anti-Ro.","C":"Anti-Ro e anti-U1-RNP.","D":"Anti-U1-RNP e anti-Sm."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-313212","number":"313212","sourceNumber":"313212","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Uma paciente de 21 anos, branca, sem comorbidades, há 3 meses apresenta, de\nmaneira re corrente, aftas dolorosas na\nboca e, nas 2 últimas semanas, ulceração na vulva, bem\nmais dolorosa que as da boca. Acompanhando o quadro, notou perda da acuidade visual à direita.\nEm recente consulta com o oftalmologista, foi diagnosticada uveíte anterior. Com base nessa\nsituação hipotética, assinale a alternativa que apresenta a melhor hipótese diagnóstica para a\npaciente:","options":{"A":"doença de Behçet","B":"tuberculose ocular","C":"uveite herpética","D":"citomegalovirose"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-317954","number":"317954","sourceNumber":"317954","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Mulher de 35 anos apresenta edema difuso e depressível das mãos e dos pés,\nespessamento da pele proximal às\narticulações metacarpofalangeanas e fenômeno de Raynaud,\nde início há um ano. O perfil de autoanticorpos mostra FAN de padrão nucleolar (título 1:640) e\nanticorpo antitopoisomarese I em altos títulos. Considerando-se a principal hipótese diagnóstica\npara essa paciente, o tratamento farmacológico de primeira linha recomendado para o fenômeno\nde Raynaud é:","options":{"A":"Nifedipino.","B":"Fluoxetina.","C":"Losartana.","D":"Pentoxifilina."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-313213","number":"313213","sourceNumber":"313213","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Uma mulher, de 34 anos, há 6 meses precisa de líquidos para facilitar a deglutição. Faz\nseguimento com oftalmologista por ?irritação? e sensação de ?areia nos olhos?, sendo\nidentificadas ulcerações corneanas na última avaliação. Há 2 meses, tem tido dor e rigidez nas\narticulações das mãos e dos punhos. Ao exame físico, observam-se artrite em punhos, 2º e 3º\nmetacarpofalangianas bilateralmente, mucosa oral seca e dentes em mau estado de conservação.\nQual é o exame mais indicado para o diagnóstico?","options":{"A":"biópsia sinovial de punho","B":"biópsia de glândula salivar","C":"pesquisa de fator reumatoide","D":"pesquisa de fator antinuclear"},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-317955","number":"317955","sourceNumber":"317955","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Para um paciente com anticorpos antifosfolípides positivos (tripla positividade) em duas\nocasiões com intervalo de 12 semanas, que apresenta trombose arterial, como AVE, infarto do\nmiocárdio ou isquemia arterial periférica, recomenda-se o uso de:","options":{"A":"Rivaroxabana, com alvo de INR entre 3 e 4.","B":"Varfarina, com alvo de INR entre 3 e 4.","C":"Apixabana, com alvo de INR entre 2 e 3.","D":"Varfarina, com alvo de INR entre 2 e 3."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-313214","number":"313214","sourceNumber":"313214","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Uma paciente de 52 anos, G2P2, menopausada há 5 anos, apresenta úlcera genital\ndolorosa, de fundo necrótico, com hiperemia local. Tem histórico de apresentar lesões orais como\n\"aftas\" (SIC) recorrentemente. O clínico geral solicitou alguns exames complementares, a saber:\nVDRL (negativo), HIV (negativo), Gram e citologia da lesão (inespecífico). O diagnóstico mais\nprovável é:","options":{"A":"cancro mole","B":"sífilis primária","C":"doença de Behçet","D":"líquen escleroatrófico"},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-313215","number":"313215","sourceNumber":"313215","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Com relação ao Lúpus Eritematoso Sistêmico (LES), analise as seguintes assertivas: I -\nA pesquisa de lúpus anticoagulante e anticorpos anticoagulina é importante no diagnóstico da\nsíndrome antifosfolípide. II - O difosfato de cloroquina está indicado no tratamento do lúpus com\nacometimento cutâneo e articular. III - Quadros clínicos graves de glomerulonefrite lúpica podem\nser tratados tanto com ciclofosfamida quanto com micofenolato de mofetila. IV - A administração de\ncorticoides e imunossupressores constitui o tratamento padrão na síndrome antifosfolípide. Estão\ncorretas:","options":{"A":"II,III","B":"III, IV","C":"I, II, III","D":"I, II, IV"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-313231","number":"313231","sourceNumber":"313231","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Um menino de 4 anos vem apresentando lesões purpúricas em membros inferiores há\n2 dias. Qual é o achado laboratorial e a\ncomplicação aguda mais frequente?","options":{"A":"plaquetopenia; sepse","B":"alteração no mielograma; infiltração metastática","C":"coagulograma alterado e epistaxe; gengivorragia","D":"número de plaquetas normal; vasculite intestinal"},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-316368","number":"316368","sourceNumber":"316368","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Paciente com diagnóstico de fibromialgia procura atendimento médico na clínica da\nfamília e durante a consulta médica, relata que não melhorou completamente com a prescrição de\nmedidas não farmacológicas (exercícios, aeróbico, hidroginástica, acupuntura) como orientado e\nprescrito em consultas anteriores. Diante do caso, qual medicação de uso contínuo estaria mais\nindicada?","options":{"A":"Paracetamol 500 mg de 8/8h.","B":"Ibuprofeno 600 mg de 12/12h.","C":"Diazepam 10 mg 2 x ao dia.","D":"Amitriptilina 25 mg, antes de dormir."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-311969","number":"311969","sourceNumber":"311969","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Pré-escolar de quatro anos, sexo masculino, é internado para tratamento de febre\nelevada há seis dias (T. ax: 39,5ºC), palidez,\nfadiga, associados à conjuntivite sem exsudato,\neritema de boca e mãos, linfadenite cervical unilateral (3cm) e língua em framboesa. O tratamento\nvisa evitar","options":{"A":"aneurisma da artéria coronariana.","B":"insuficiência renal.","C":"endocardite aguda.","D":"hepatite fulminante."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-295426","number":"295426","sourceNumber":"295426","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Qual exame a seguir é o mais específico para diagnóstico de lúpus eritematoso\nsistêmico?","options":{"A":"Anti-Sm.","B":"Anti-La.","C":"FAN.","D":"Anti-RNP."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-273125","number":"273125","sourceNumber":"273125","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Paciente homem, 40 anos, apresenta fadiga, hiporexia, perda de peso, febre, sudorese\nnoturna, calafrios, poliartralgia migratória e\nfraqueza muscular, presença de púrpura palpável; entre\nos sintomas neurológicos há neuropatia periférica. Considerando o diagnóstico na forma grave,\nquanto ao tratamento é CORRETO afirmar:","options":{"A":"Tratar com pulso de corticosteroides e ciclofosfamida, com possibilidade de uso de plasmaférese\ne imunoglobulina para casos selecionados.","B":"Tratar com metotrexato ou azatioprina e corticosteroides em baixas doses.","C":"Na fase inicial, utilizar azatioprina, metotrexato ou leflunomida.","D":"Na fase inicial, utilizar micofenolato de mofetila, imunoglobulina EV, hidroxiureia (como\nutilizada\nem outras síndromes hipereosinofílicas),\nrituximabe, interferona-alfa, terapia anti-lgE, anti-lL-5 ou\nplasmaférese."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-273126","number":"273126","sourceNumber":"273126","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Paciente com esclerose sistêmica difusa, dá entrada no hospital com crise renal\nesclerodérmica. Nesse caso:","options":{"A":"Deve-se entrar com uso de captopril, em uma dose mínima de 300 mg/dia, para manter os níveis\nde creatinina sérica > 3 mg/dL.","B":"Deve-se iniciar a diálise imediatamente, para se obter rápido controle da PA e tentar manter os\nníveis de creatinina sérica < 3 mg/dL.","C":"Deve-se entrar com uso de captopril, em uma dose que pode chegar a 300 mg/dia, para se obter\nrápido controle da PA e tentar manter os níveis de creatinina sérica < 3 mg/dL.","D":"Deve-se iniciar a diálise imediatamente, para se obter rápido controle da PA e tentar manter os\nníveis de creatinina sérica > 3 mg/dL."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-281991","number":"281991","sourceNumber":"281991","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Paciente, sexo feminino 22 anos, iniciou quadro de aumento de volume e temperatura\nem articulações dos punhos e joelhos associado a\nrubor em regiões malares e alopecia. Associa-se\nedema em face e membros inferiores - cacifo (++/++++) e urina com \"aspecto espumoso\" - sic.\n\nForam realizados exames laboratoriais que constataram: hemoglobina = 10; leucócitos = 3000;\nneutrófilos = 2500; linfócitos = 500;\nplaquetas = 120.000; VHS = 88; creatinina = 2,5; FAN=\nreagente = 1:1280- nuclear homogêneo; EAS = leucócitos = 16.250, hemácias = 520.000, presença\nde cilindros hemáticos; proteinúria de 24 horas = 5,0 g/24h. Qual o diagnóstico clínico e melhor\nconduta?","options":{"A":"Lúpus eritematoso sistêmico. Iniciar pulsoterapia com azatioprina (150mg/dia) e decadron\n(4,0mg-8/8h por 03 dias).","B":"Psoríase (forma eritrodérmica). Iniciar metotrexato (15mg/semana), ácido fólico (5mg/semana) e\nglicocorticoides em altas doses.","C":"Lúpus eritematoso sistêmico. Iniciar pulsoterapia com metilprednisolona por 03 dias e pulsos\nmensais de ciclofosfamida.","D":"Síndrome do anticorpo antifosfolipídio. Anticoagulação plena com heparina de baixo peso\nmolecular (enoxaparina) e iniciar sulfato de hidroxicloroquina."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-274775","number":"274775","sourceNumber":"274775","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Paciente de 32 anos, sexo masculino, dá entrada no pronto atendimento com quadro\nde confusão mental e tremor de extremidades.\nFamiliar refere que paciente apresenta quadro de\nnáuseas e vômitos há três dias. Ao abordar o paciente você percebe que o mesmo está corado,\nanictérico, acianótico e afebril. Na ausculta, o que chama atenção é um atrito pericárdico e níveis\ntensionais elevados. Considerando que, previamente, o paciente era saudável e com exames de\nbioquímica geral normais, e que, o contexto clínico é agudo, uma hipótese diagnóstica plausível e\nmais provável seria:","options":{"A":"neoplasia cerebral.","B":"febre reumática.","C":"lúpus eritematoso sistêmico.","D":"meningite viral."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-258186","number":"258186","sourceNumber":"258186","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"O teste de imunofluorescência indireta empregando o protozoário Crithidia luciliae como\nsubstrato tem grande especificidade para o diagnóstico de determinada doença difusa do tecido\nconjuntivo. Essa doença e o anticorpo detectado através deste teste são, respectivamente:","options":{"A":"Esclerose sistêmica ? anti-Scl-70.","B":"Síndrome de Sjögren ? anti-Ro.","C":"Artrite reumatoide ? anti-CCP.","D":"Lúpus eritematoso sistêmico ? anti-DNA nativo."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-277467","number":"277467","sourceNumber":"277467","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Um paciente de 1 ano, com quadro de vermelhidão pelo corpo e febre há 7dias, ao\nexame físico, apresenta conjuntivite, língua\navermelhada e lifonodomegalia. Nota-se, também,\ndescamação de mãos e pés. Qual o diagnóstico mais provável?","options":{"A":"varicela","B":"citomegalovirose","C":"doença de Kawasaki","D":"sarampo"},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-274515","number":"274515","sourceNumber":"274515","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"A vasculite por imunoglobulina A (IgA), conhecida como púrpura de Henoch-Schönlein,\nenvolve vasos predominantemente de pequeno\ncalibre, com acometimento preferencial cutâneo,\narticular, gastrintestinal e renal. Em relação à Púrpura de Henoch-Schoenlein pode-se AFIRMAR:","options":{"A":"Presença de melena indica a ocorrência de perfuração intestinal nesses pacientes.","B":"A presença de púrpuras palpáveis relacionadas à plaquetopenia.","C":"A artrite é a manifestação predominante, porém não migratória.","D":"O tratamento baseia-se em analgésicos e corticoides para os casos mais graves."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-274819","number":"274819","sourceNumber":"274819","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Lactente sexo masculino, 12 meses de idade, conduzido ao pronto socorro com história\nde febre alta persistente há 7 dias,\nirritabilidade e exantema difuso. Há 5 dias evoluiu associado ao\nquadro com hiperemia conjuntival, sem secreção, e boca ressecada com fissuras. Nega doenças\nanteriores. Ao exame: irritado, choroso, eupnéico, febril, hidratado, anictérico, acianótico. Sem\nrigidez de nuca. Oroscopia: fissuras e hiperemia labial e de orofaringe, proeminência das papilas\nlinguais, ausência de aftas, úlceras ou exsudatos. Presença de gânglio palpável cervical posterior a\nesquerda, unilateral, 2 cm de diâmetro. Presença de exantema polimórfico, predominante em tronco\ne períneo, sem vesículas. Hiperemia conjuntival bilateral, sem secreção. Frequência cardíaca: 160\nbpm. Frequência respiratória: 40 ipm. Sem alterações na ausculta pulmonar ou cardíaca. Exames\nlaboratoriais mostram hemograma: hemoglobina 9,8 mg/dl (Valor de Referência (VR): 11-14 mg/dl),\nhematócrito 30% (VR: 33-45%), VCM (Volume Corpuscular Médio): 69,2 (VR: 75-100), leucócitos\n\n23.300 mm3 (VR: 6000-17500 mm3), bastões 4%, segmentados 81%, eosinófilos 0%, monócitos\n\n6%, linfócitos 9%. Plaquetas 450.000 ml/mm3 (VR: 200-500). VHS (velocidade de\nhemossedimentação): 120mm (VR: até 20mm). PCR\n(proteína C reativa): 90 mg/dl (VR: menor que\n0,5 mg/dl). Qual o diagnóstico mais provável?","options":{"A":"Doença de Kawasaki.","B":"Escarlatina.","C":"Adenite bacteriana.","D":"Meningite."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-274820","number":"274820","sourceNumber":"274820","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Escolar sexo masculino, 7 anos de idade, com história de tosse seca e coriza iniciado\nhá 20 dias, sem febre, evoluindo com\nmelhora progressiva. Há 15 dias iniciou dor articular nos\njoelhos associado a edema, vermelhidão e dificuldade de movimentação, com migração da dor e\nedema para tornozelos há 10 dias. Há 7 dias apareceu lesões predominante em membros inferiores\ne nádegas, cor vermelho arroxeada, elevada, que não desaparece a dígito pressão, nega prurido.\n\nNega febre. Pressão arterial: 90/60 mm/Hg (percentil 50 para idade). Exames laboratoriais:\nhemograma com hemoglobina de 10 mg/dl (VR:\n11-14), leucócitos 18.000 mm3 (VR: 7.000-15.000),\nsem desvio. Plaquetas 350.000 (VR: 140.000-400.000). Urina 1: com presença de hematúria,\nleucocitúria, proteína presente. VHS: 15 mm (VR: até 20 mm). PCR: 20 mg/dl (VR: menor 1,0\nmg/dl). Qual diagnóstico mais provável?","options":{"A":"Púrpura trombocitopenica idiopática.","B":"Síndrome de Behçet.","C":"Artrite idiopática infantil.","D":"Vasculite por lgA."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-248899","number":"248899","sourceNumber":"248899","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Em geral, não se esperam resultados favoráveis com a administração de\nglicocorticoides em pacientes acometidos por:","options":{"A":"arterite de células gigantes (arterite temporal)","B":"dermatopolimiosite","C":"esclerodermia (esclerose sistêmica)","D":"polimialgia reumática"},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-248900","number":"248900","sourceNumber":"248900","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Com relação ao Lúpus Eritematoso Sistêmico (LES), analise as seguintes assertivas: I -\nA pesquisa de lúpus anticoagulante e anticorpos anticoagulina é importante no diagnóstico da\nsíndrome antifosfolípide. II - O difosfato de cloroquina está indicado no tratamento do lúpus com\nacometimento cutâneo e articular. III - Quadros clínicos graves de glomerulonefrite lúpica podem\nser tratados tanto com ciclofosfamida quanto com micofenolato de mofetila. IV - A administração de\ncorticoides e imunossupressores constitui o tratamento padrão na síndrome antifosfolípide. Estão\ncorretas:","options":{"A":"II,III","B":"III, IV","C":"I, II, III","D":"I, II, IV"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-231940","number":"231940","sourceNumber":"231940","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Das doenças a seguir, qual apresenta risco maior de desenvolvimento de linfomas\nquando comparado à população geral?","options":{"A":"Lúpus eritematoso sistêmico.","B":"Doença de Behçet.","C":"Síndrome de Sjögren.","D":"Policondrite recidivante.","E":"Doença mista do tecido conjuntivo."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-246530","number":"246530","sourceNumber":"246530","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Entre os autoanticorpos encontrados no Lúpus Eritematoso sistêmico, qual apresenta\nmaior associação com nefrite lúpica?","options":{"A":"Anti-DNA dupla-hélice.","B":"Anti-histonas.","C":"Anti-SSA.","D":"Anti-SSB.","E":"Anti-RNP."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-246532","number":"246532","sourceNumber":"246532","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Assinale a alternativa incorreta sobre fibromialgia (FM).","options":{"A":"A presença de dor difusa é fundamental para o diagnóstico de pacientes com suspeita de FM.","B":"A polissonografia deve ser solicitada de rotina para os pacientes com FM.","C":"A termografia não deve ser utilizada como ferramenta diagnóstica nos pacientes com FM.","D":"Os pacientes com FM devem ser avaliados quanto a transtorno de humor.","E":"Os pontos dolorosos ainda podem ser úteis no diagnóstico de FM, quando associados a\nsintomas funcionais."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-241701","number":"241701","sourceNumber":"241701","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Mulher de 44 anos com sintomas crônicos de dores musculares generalizadas, fadiga,\ninsônia e déficit de memória recente. Exame físico com achado de artralgia em quadril\nbilateralmente e em joelho direito, leve limitação articular, sem sinais inflamatórios. Sobre o\nprovável diagnóstico, pode-se afirmar que:","options":{"A":"anormalidades na rotina laboratorial são comuns.","B":"antidepressivos tricíclicos e relaxantes musculares podem ser benéficos.","C":"doença reumatológica pré-existente associa-se a menor risco da doença.","D":"higiene do sono e atividade física são indicadas conforme a gravidade.","E":"anticonvulsivantes apresentam benefício questionável."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-247417","number":"247417","sourceNumber":"247417","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Sobre a doença mista do tecido conjuntivo afirma-se que:","options":{"A":"a sua prevalência seja maior do que lúpus e esclerose sistêmica, acometendo preferencialmente\nmulheres.","B":"a presença de anticorpos anti-RNP e anti-dsDNA são obrigatórios para a confirmação\ndiagnóstica.","C":"não há tratamento padrão, sendo adaptável conforme as manifestações clínicas mais\nprevalentes.","D":"inicialmente descrita como doença grave, hoje é doença de curso indolente e prognóstico\nmelhor."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-232240","number":"232240","sourceNumber":"232240","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Assim como em outras doenças reumáticas autoimunes, a presença de autoanticorpos\nna esclerose sistêmica auxilia na caracterização\ndas formas clínicas e no prognóstico da doença.\nNesse contexto,","options":{"A":"o padrão de imunofluorescência mais comum do FAN é o citoplasmático.","B":"o anticorpo anticentrômero, na forma cutânea limitada, relaciona-se com o risco de hipertensão\npulmonar.","C":"a presença de anticorpo antitopoisomerase I está associada a doença sistêmica grave e crise\nrenal.","D":"o anticorpo anti-RNA polimerase III, na forma cutânea difusa, relaciona-se com o risco de\ndoença intersticial."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-252762","number":"252762","sourceNumber":"252762","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Em relação à esclerodermia, marque a alternativa INCORRETA:","options":{"A":"A crise renal esclerodérmica ocorre em 10 a 15% dos pacientes. Sua patogênese envolve\nvasculopatia obliterante e estreitamento do lume\ndas artérias arqueadas e interlobulares renais. O\nseu tratamento consiste em evitar medicações nefrotóxicas e o uso de inibidores da enzima\nconversora de angiotensina.","B":"Autoanticorpos antinucleares estão presentes em quase todos os pacientes e podem ser\ndetectados no início da doença. Autoanticorpos\ncontra topoisomerase I (SCI-70) e centrômetro são\nmuito específicos para a esclerose sistêmica.","C":"A doença pulmonar intersticial pode ser encontrada em até 90% dos pacientes na necropsia e\nem 85% pela tomografia computadorizada. Os fatores de risco para esse acometimento incluem:\nsexo feminino, indivíduos brancos e pequeno comprometimento da pele.","D":"O fenômeno de Raynaud é a complicação extracutânea mais frequente e se caracteriza por\nepisódios de vasoconstrição reversível nos dedos das mãos e dos pés."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-252777","number":"252777","sourceNumber":"252777","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Pré-escolar de 3 anos, sexo masculino, é levado pela mãe ao pronto-atendimento com\nhistória de febre alta há 11 dias associada a caroço no pescoço que apareceu no terceiro dia de\nfebre e conjuntivite bilateral. Foi examinado, no início do quadro, por pediatra que prescreveu\namoxicilina 50 mg/kg/dia, sem melhora. Ao exame físico, encontra-se febril, com adenomegalia\ncervical à direita medindo 2 cm, sem sinais flogísticos, hiperemia de conjuntiva sem exsudato,\nedema em mãos e pés, lábios secos com fissuras. Diante da principal hipótese diagnóstica, deve\nser instituído rapidamente tratamento com:","options":{"A":"Outro antibiótico.","B":"Antiviral.","C":"Imunoglobulina.","D":"Antifúngico."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-201929","number":"201929","sourceNumber":"201929","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Uma mulher de 25 anos, casada e com 2 filhos, chega ao posto de saúde para consulta\neletiva relatando dor em todo o corpo há 3 meses, de início após mudança de emprego, fadiga\nconstante, cefaléia, sensação de edema nos dedos das mãos, parestesias e sono não reparador.\n\nAssinale a alternativa correta, que apresenta a conduta inicial mais adequada, considerando o caso\nclínico:","options":{"A":"solicitar hemograma e TSH e iniciar analgésico comum e relaxante muscular","B":"iniciar paracetamol e codeína","C":"iniciar anti-inflamatório não hormonal e orientar consulta com psicólogo","D":"solicitar radiografia de mãos e punhos e iniciar anti-inflamatório hormonal","E":"iniciar antidepressivo e orientar exercícios físicos"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-218235","number":"218235","sourceNumber":"218235","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Homem, 23 anos, sem vícios, com história de amigdalites de repetição, refere edema\nde membros inferiores com início há 30 dias.\nAvaliação laboratorial com os seguintes resultados: Cr\n\n= 1,8 mg/dl; Ur = 72 mg/dl; Na+ = 138 mEq/L; k+ = 4,0 mEq/L; C3 = 56 mg/dl (VR: 90 a 180 mg/dl);\nC4 = 8 mg/dl (VR: 10 a 40 mg/dl); glicemia\n= 106 mg/dl; albumina = 3,0 g/dl; triglicerídeos = 102\nmg/dl; colesterol total = 234 mg/dl. EAS: hematúria = 23.000, leucocitúria = 56.000, proteinúria =\n50.\nProteinúria de 24h = 4,0 g. USG de rins e vias urinárias: normal. Realizado biópsia renal com\npresença de crescentes celulares e proliferação celular difusa na microscopia óptica e padrão\n\n?fullhouse? na imunofluorescência. Assinale a opção correta de diagnóstico e o seu exame\nlaboratorial auxiliar, respectivamente:","options":{"A":"Glomerulonefrite lúpica; Fator Antinúcleo (FAN).","B":"Nefropatia por IgA; eletroforese de imunoglobulinas.","C":"Glomerulonefrite pós-estreptocócica; anti-astreptolisina O (ASLO).","D":"Síndrome de Goodpasture; dosagem de anticorpo anti-MBG."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-201948","number":"201948","sourceNumber":"201948","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Considere uma mulher de 40 anos, com quadro de mialgia generalizada, inchaço\narticular, cansaço, insônia, formigamento e\ndormência em MMSS. Ao exame físico: avaliação\nneurológica e articular dentro da normalidade. Exames laboratoriais, como PCR, VHS, TSH, T4 livre\ne fator antinúcleo normais. Qual é o diagnóstico mais provável?","options":{"A":"fibromialgia","B":"gota","C":"polimialgia reumática","D":"polimiosite","E":"artrite reumatoide"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-217005","number":"217005","sourceNumber":"217005","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Com relação ao manejo clínico dos pacientes com complicações isquêmicas do lúpus\neritematoso sistêmico, no SNC, assinale a alternativa correta.","options":{"A":"A pesquisa de anticardiolipina e anticoagulante lúpico é dispensável.","B":"Na vasculite lúpica está indicada pulsoterapia com metilprednisolona 500 mg/dia por 3 dias.","C":"Se confirmada síndrome do anticorpo antifosfolípide, deve-se anticoagular por curto prazo.","D":"Doppler de carótidas, ECG e ecocardiograma são recomendados em casos selecionados.","E":"A ciclofosfamida pode ser necessária nas formas mais graves."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-210589","number":"210589","sourceNumber":"210589","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Sobre o tratamento do Lúpus Eritematoso Sistêmico (LES), assinale a alternativa\ncorreta.","options":{"A":"Os antimaláricos são úteis no controle das erupções cutâneas e dos sistemas articulares.","B":"Os corticoesteroides sistêmicos são indicados na anemia e leucopenia da doença crônica.","C":"A psicose induzida por corticoide implica na pronta suspensão do medicamento.","D":"A ciclofosfamida é mais eficaz que o micofenolato no tratamento da nefrite lúplica.","E":"Na síndrome antifosfolípide associada ao LES é indicado o uso contínuo de AAS."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-216453","number":"216453","sourceNumber":"216453","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Paciente do sexo masculino, 55 anos, procura atendimento referindo secreção nasal\nsanguinolenta, tosse, hemoptise e dispneia. Ao exame físico, apresenta púrpura e nódulos\nsubcutâneos em membros inferiores e conjuntivite. Exames mostram aumento importante da ureia\ne creatinina, aumento do VHS e ANCA antiproteinase 3 positivo. Radiografia de tórax mostra\ninfiltrados pulmonares difusos. O diagnóstico mais provável é:","options":{"A":"Síndrome de Churg-Strauss.","B":"Arterite de Takayasu.","C":"Granulomatose de Wegener.","D":"Arterite de células gigantes."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-216457","number":"216457","sourceNumber":"216457","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"A doença mista do tecido conjuntivo se caracteriza pela combinação de achados\nclínicos do lúpus eritematoso sistêmico,\nartrite reumatoide, polimiosite e esclerodermia. O anticorpo\nque caracteriza essa doença é o:","options":{"A":"Anti-RNP-U1.","B":"Anti-Ro/SS-A.","C":"Anti-La/SS-B.","D":"Anti-CCP (anticorpos contra peptídeos citrulinados cíclicos)."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-216553","number":"216553","sourceNumber":"216553","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Os anticorpos anti-DNA nativo e anti-RO/SSA são mais específicos para as seguintes\ndoenças, respectivamente:","options":{"A":"Doença mista do tecido conjuntivo; lúpus eritematoso sistêmico.","B":"Lúpus eritematoso sistêmico; esclerodermia.","C":"Doença mista do tecido conjuntivo; síndrome de Sjögren.","D":"Lúpus eritematoso sistêmico; síndrome de Sjögren."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-214203","number":"214203","sourceNumber":"214203","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Criança de 36 meses atendida em serviço de emegência pela segunda vez nos últimos\ncinco dias, Pais referem que há 6 dias criança iniciou febre alta ( 39 a 39,5°C) e persistente,\nirritabilidade e dor abdominal. No segundo dia de febre notaram discreta hiperemia conjuntival\nbilateral, hiperemia de lábios, além de piora do choro e recusa para caminhar e, no terceiro dia,\ncriança apresentou exantema uriticariforme pruriginoso. Pais procuraram, então, o serviço de\nemergência pela primeira vez, onde foram realizados exames laboratoriais que evidenciaram\nleucocitose com prodomínio de polimorfonucleres e PCR (proteína C reativa) aumentada. Foi feito\ndiagnóstico de ''infecção bacteriana'' e prescrito amoxicilina na dose de 50 mg/kg/dia. Paciente\nevoluiu com persistência dos sintomas e retorna hoje para reavaliaçao. Médico plantonistca\nobserva ao exame físico: criança irritada e chorosa, hiperemia conjuntival bilateral não exsudativa,\nedema de mãos e pés, exantema urticariforme predominantemente em tronco. cavidade oral com\nhiperemia de orofaringe, língua ''em framboesa''. edemaciada e fissura em lábios. Neste caso a\nprincipal conduta para reduzir risco de complicações é","options":{"A":"internação hospitalar para antibioticoterapia endovenosa com ampliação do espectro\nantimicrobiano","B":"realização de ecocardiografia transtoracica para confirmação diagnostica.","C":"administração de imunoglobulina endovenona na dose de 2g/kg de peso em associação com\nácido acetilisalicilico.","D":"internação hospitalar para observação clínica rigorosa e suspensão da antibioticoterapia por não\nhaver evidencias clínicas de infecção bacteriana."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-216622","number":"216622","sourceNumber":"216622","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"A.L.S., sexo feminino, 37 anos de idade, vai ao ambulatório de clínica médica\nqueixando-se de dificuldade em movimentar os\ndedos das mãos. Refere episódios de dores\narticulares, com edema das mesmas, além de disfagia de condução e dispneia com tosse seca.\nRelata que sua mãe é portadora de artrite reumatoide. Ao exame físico apresentava pele lisa e\nbrilhante em mãos e alteração da mímica facial. Para estudo da disfagia foi solicitado uma\nmanometria de esôfago que mostrou ondas deglutitórias de baixa amplitude, sendo diagnosticada\ncom peristalse esofagiana ineficaz. A principal hipótese diagnóstica é:","options":{"A":"Esclerodermia.","B":"Lúpus eritematoso sistêmico.","C":"Artrite reumatoide.","D":"Espondiloartropatia degenerativa."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-202696","number":"202696","sourceNumber":"202696","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Pacientes com síndrome antifosfolípide e, pelo menos, um episódio de trombose\nvenosa profunda, na presença de anticorpos\nantifosfolípides positivos em duas ocasiões, devem\nser anticoagulados para manter a INR (razão normalizada internacional) entre:","options":{"A":"1,0 e 2,0.","B":"1,5 e 2,5.","C":"2,0 e 3,0.","D":"3,0 e 4,0."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-201699","number":"201699","sourceNumber":"201699","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"A fibromialgia é uma afecção crônica, caracterizada pela presença de dor difusa e\ngeneralizada, cujo tratamento medicamentoso deve incluir:","options":{"A":"Analgésicos comuns, como o paracetamol, e anti-inflamatórios não hormonais, efetivos no\ntratamento de sensibilização central.","B":"Antidepressivos tricíclicos, como a amitriptilina, em doses superiores a 50 mg/dia, efetiva no\ntratamento da dor, da fadiga, além de melhorar o sono.","C":"Anticonvulsivantes, como a pregabalina e a gabapentina, benéficos na redução da dor e na\nmelhora do padrão do sono.","D":"Hipnóticos não diazepínicos, como o zolpidem, que bloqueia o reflexo nociceptivo espinal,\ndevendo ser mantido por tempo prolongado."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-215002","number":"215002","sourceNumber":"215002","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Menina de 6 anos, com história de aparecimento de lesões nas pernas e nos glúteos\npruriginosas e indolores há 3 dias, refere dor e inchaço nos joelhos e tornozelos e dor abdominal\ndifusa tipo cólica. Ao exame físico: em bom estado geral, corada, hidratada, com T = 36,8°C, FC =\n90bpm e FR = 14irpm. O abdome é flácido, com ruídos hidroaéreos normais; a pele revela lesões\npapulares palpáveis que não desaparecem à digitopressão em membros inferiores e glúteos; os\nmembros inferiores mostram artrite do tornozelo direito; e o hemograma não tem alterações. Duas\ncomplicações frequentes são:","options":{"A":"doença renal e doença intestinal","B":"uveíte e artrite crônica","C":"doença renal e artrite crônica","D":"uveíte e doença intestinal"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-215005","number":"215005","sourceNumber":"215005","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Com relação ao Lúpus Eritematoso Sistêmico (LES), analise as seguintes assertivas: I -\nA pesquisa de lúpus anticoagulante e anticorpos anticoagulina é importante no diagnóstico da\nsíndrome antifosfolípide. II - O difosfato de cloroquina está indicado no tratamento do lúpus com\nacometimento cutâneo e articular. III - Quadros clínicos graves de glomerulonefrite lúpica podem\nser tratados tanto com ciclofosfamida quanto com micofenolato de mofetila. IV - A administração de\ncorticoides e imunossupressores constitui o tratamento padrão na síndrome antifosfolípide. Estão\ncorretas:","options":{"A":"II,III","B":"III, IV","C":"I, II, III","D":"I, II, IV"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-205595","number":"205595","sourceNumber":"205595","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Sobre as características clínicas do Lúpus Eritematoso Sistêmico Juvenil (LESJ),\nassinale a alternativa CORRETA:","options":{"A":"O LESJ apresenta curso clínico evolutivo menos agressivo em comparação com as populações\nde adultos com LES.","B":"Os diagnósticos diferenciais incluem apenas as doenças pediátricas agudas causando as\nalterações nos mecanismos imunorreguladores.","C":"O paciente com LESJ pode apresentar úlceras orais localizadas no palato, na boca, na língua ou\nnas narinas na ausência de outras causas,\ncomo por exemplo, vasculite.","D":"O LESJ apresenta-se principalmente na forma crônica."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-214186","number":"214186","sourceNumber":"214186","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"A erupção facial conhecida como \"Rash malar\" ou \"Rash em asas de borboleta\" é uma\nmanifestação cutânea que pode ser encontrada em:","options":{"A":"Doença de Basedow-graves.","B":"Sífilis terciária.","C":"Hanseníase.","D":"Lúpus erítematoso sistémico."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-178803","number":"178803","sourceNumber":"178803","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"A poliartrite nodosa (PAN) pode estar associada ao vírus da hepatite B. Qual, dos\nseguintes exames, se apresentaria positivo?","options":{"A":"Anti-HBe.","B":"HBeAg.","C":"Anti-Hbs.","D":"Anti-HBc.","E":"ANCA."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-174516","number":"174516","sourceNumber":"174516","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Dayane, 6 anos, apresenta há três dias lesões purpúricas palpáveis avermelhadas nas\npernas que somem a digitopressão, urina\navermelhada associadas a dor abdominal que piora ao se\nalimentar e dor nos joelhos. Antecedentes pessoais de gripe há uma semana, até os três anos teve\ntrês infecções de urina. Tem como antecedentes familiares nada digno de nota. Ao exame físico:\nREG, cianose central 2+/4+, taquicardica, anictérica, afebril, taquidispneica leve, edemaciada\n4+/4+, com pressão aferida acima do percentil 99 para o sexo, idade, peso e estatura, pupilas\nisocóricas e fotorreagentes, aparelho cardiovascular: BRNF em 2 T s/ sopros. MV + bilateral com\nestertores finos bibasais, abdome normotenso, levemente doloroso à palpação, fígado a 4 cm do\nRCD, RHA+. Estase de jugulares, perfusão periférica de 5 segundos, pulsos finos. Para tratar\nadequadamente esta paciente, é correta a prescrição de:","options":{"A":"Dobutamina e furosemida para reduzir a PA em 1/3 nas primeiras 24 h.","B":"Nitroprussiato de sódio e diurético para reduzir 20 a 25 % da PA nos primeiros minutos.","C":"Nitroprussiato de sódio e diurético para reduzir 10 a 15 % da PA nos primeiros minutos.","D":"Dobutamina e furosemida para tratar o quadro de insuficiência cardíaca associado a edema\nagudo de pulmão e apenas após estabilização\ndo quadro, rever os níveis pressóricos novamente."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-174153","number":"174153","sourceNumber":"174153","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"De acodo com os critérios de classificação, revisados em 2006, a síndrome antifoslípide\npode ser classificada de maneira específica e\ndefinitiva quando apresenta um critério clínico e um\ncritério laboratorial. Dentre os critérios laboratoriais, inclui-se a presença de anticorpos\nanticardiolipinas (lgG e/ou lgM) em títulos médios ou altos, em duas ou mais ocasiões, com um\nintervalo mínimo predefinido. De acordo com esses critérios revisados, quais são os parâmetros\nconsiderados para os títulos e para o intervalo de detecção?","options":{"A":"Títulos maiores que 40 GPL ou MPL; intervalo de, pelo menos, doze semanas.","B":"Títulos maiores que 20 GPL ou MPL; intervalo de, pelo menos, doze semanas.","C":"Títulos maiores que 40 GPL ou MPL; intervalo de, pelo menos, seis semanas.","D":"Títulos maiores que 20 GPL ou MPL; intervalo de, pelo menos, seis semanas."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-173542","number":"173542","sourceNumber":"173542","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"No lúpus eritematoso sistêmico, o espectro do envolvimento do sistema nervoso é\namplo e engloba uma série de condições neuropsiquiátricas. Na nova atualização dos critérios da\ndoença, de 2012, algumas manifestações neurológicas foram incluídas, entre as quais estão:","options":{"A":"Disfunção cognitiva e psicose.","B":"Mielite e polirradiculopatia desmielinizante aguda.","C":"Hipertensão intracraniana benigna e convulsão.","D":"Neuropatia periférica e estado confusional agudo."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-174165","number":"174165","sourceNumber":"174165","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Mulher de 49 anos apresenta poliartrite crônica, fenômeno de Raynaud,\nfotossensibilidade, esclerodactilia e miosite. Os exames\nlaboratoriais mostram: hemograma com\nanemia e leucopenia; VHS aumentada; FAN = padrão nuclear pontilhado grosso (> 1/640);\n\nanti-DNA negativo; anti-Sm/Ro/La = negativos; anti-RNP positivo e em títulos altos; C3 e C4\nnormais; EAS com leucocitúria, apenas. A principal hipótese diagnóstica para essa paciente é:","options":{"A":"lúpus eritematoso sistêmico.","B":"esclerose sistêmica.","C":"doença mista do tecido conjuntivo.","D":"artrite reumatoide."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-182455","number":"182455","sourceNumber":"182455","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Uma paciente de 52 anos, G2P2, menopausada há 5 anos, apresenta úlcera genital\ndolorosa, de fundo necrótico, com hiperemia local. Tem histórico de apresentar lesões orais como\n\"aftas\" (SIC) recorrentemente. O clínico geral solicitou alguns exames complementares, a saber:\nVDRL (negativo), HIV (negativo), Gram e citologia da lesão (inespecífico). O diagnóstico mais\nprovável é:","options":{"A":"cancro mole","B":"sífilis primária","C":"doença de Behçet","D":"líquen escleroatrófico"},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-186508","number":"186508","sourceNumber":"186508","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Mulher de 26 anos, nulípara, portadora de Lupus Eritematoso Sistêmico - forma\ncutâneo articular, em uso de Sulfato de\nHidroxicloroquina - 400mg/dia, prednisona - 5,0 mg/dia.\nIniciou quadro de edema de membros inferiores há 60 dias e nos últimos 07 dias, edema de face.\nAo exame físico: peso de 64 kg, pressão arterial de 170x90mmHg, frequência cardíaca de 120\nbpm. Exame laboratoriais evidenciam: proteinúria de 24 horas = 9,0 g/24 horas, eas = hematúria =\n1000.000/ml, leucócitos: 90.000/ml, VHS = 100 na 1ª hora, creatinina - 1,8mg/dl, anti-DNA-nativo\nreagente (1:80), C3 e C4 com níveis reduzidos. Diante do quadro acima, qual o tratamento mais\nadequado para nefrite lúpica (tratamento de indução)?","options":{"A":"Belimumabe como tratamento de indução e azatioprina como tratamento de manutenção.","B":"Azatioprina em pulso e glicocorticoides em altas doses (60mg/dia), por 06 meses.","C":"Pulsoterapia com metilprednisolona (IV) - 1000mg/dia por 3 dias consecutivos e Azatioprina\nassociado a prednisona (1mg/kg), com redução gradual da dose.","D":"Pulsoterapia com metilprednisolona (IV) - 1000mg/dia por 03 dias consecutivos e Micofenolato\nMofetil - (2 a 3g/dia) associado prednisona\n(1mg/kg), com redução gradual da dose."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-182456","number":"182456","sourceNumber":"182456","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Com relação ao Lúpus Eritematoso Sistêmico (LES), analise as seguintes assertivas: I -\nA pesquisa de lúpus anticoagulante e anticorpos anticoagulina é importante no diagnóstico da\nsíndrome antifosfolípide; II - O difosfato de cloroquina está indicado no tratamento do lúpus com\nacometimento cutâneo e articular; III - Quadros clínicos graves de glomerulonefrite lúpica podem\nser tratados tanto com ciclofosfamida quanto com micofenolato de mofetila. IV - A administração de\ncorticoides e imunossupressores constitui o tratamento padrão na síndrome antifosfolípide. Estão\ncorretas:","options":{"A":"II,III","B":"III, IV","C":"I, II, III","D":"I, II, IV"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-183243","number":"183243","sourceNumber":"183243","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Com relação à doença de Buerger, assinale a alternativa INCORRETA:","options":{"A":"Afeta predominantemente homens jovens, fumantes, com cerca de 30 anos.","B":"Tem havido incidência crescente em mulheres, provavelmente por aumento no hábito de fumar\ndas mesmas.","C":"Os elementos diagnósticos incluem início da doença antes dos 45 anos, exposição ao fumo,\nausência de lesões arteriais proximal ao joelho ou cotovelo e ausência de outros fatores de risco\nateroscleróticos.","D":"As lesões oclusivas são tipicamente vistas em artérias grandes e médias."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-182437","number":"182437","sourceNumber":"182437","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"As doenças que têm indicação, com comprovação eficaz, do uso de imunoglobulina\nintravenosa polivalente são:","options":{"A":"doença de Kawasaki, síndrome de Guillain-Barré e infecção pelo parvovírus B19","B":"infecção pelo vírus sincicial respiratório, varicela e tétano","C":"infecção pelo HIV, citomegalovírus e hepatite B","D":"varicela, hepatite A e doença de Kawasaki"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-187516","number":"187516","sourceNumber":"187516","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Em um paciente com suspeita de Esclerose Sistêmica, observa-se que:","options":{"A":"é necessário o início imediato de corticoterapia para o controle da doença.","B":"pacientes na forma difusa em estágios iniciais, principalmente aqueles tratados com corticóide,\ntêm maior risco de desenvolver crise renal.","C":"o fenômeno de Raynauld é uma manifestação rara e tardia nesta doença.","D":"a evolução de fibrose é exclusivamente cutânea, não havendo tal ocorrência em demais\nsistemas."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-156975","number":"156975","sourceNumber":"156975","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Sobre a púrpura de Henoch-Scholein, pode-se dizer que:","options":{"A":"O uso de corticoesteroide está indicado em casos de artrite com limitação da deambulação.","B":"O comprometimento renal é precoce, acometendo o paciente nos primeiros dias da doença.","C":"O uso de anti-histamínicos tem bom resultado na resolução do quadro purpúrico.","D":"A detecção e a remoção de possíveis agentes etiológicos (medicamentos, processos\ninfecciosos e alimentos) é importante."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-150728","number":"150728","sourceNumber":"150728","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Qual das desordens reumatológicas, a seguir, mais frequentemente desenvolve\nhipertensão pulmonar?","options":{"A":"Artrite reumatoide.","B":"Lúpus eritematoso sistêmico.","C":"Esclerodermia.","D":"Espondilite anquilosante."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-160480","number":"160480","sourceNumber":"160480","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Homem de 48 anos apresenta fraqueza, mialgias, artralgias e episódios recorrentes de\nfebre, de início há 6 meses. Há 2 semanas notou aparecimento de livedo reticular, nódulos\nsubcutâneos e úlceras em membros. O principal diagnóstico é:","options":{"A":"Arterite de Takayasu.","B":"Poliarterite nodosa.","C":"Síndrome de Churg-Strauss.","D":"Granulomatose de Wegener."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-150734","number":"150734","sourceNumber":"150734","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"O sistema de complemento constitui um grande número de proteínas plasmáticas\nproduzidas pelo fígado. No lúpus eritematoso sistêmico, a dosagem do complemento é um\nexcelente parâmetro para o monitoramento da atividade da doença e resposta terapêutica,\ndevendo-se dosar, em particular, os componentes:","options":{"A":"C1 e C2.","B":"C2 e C3.","C":"C3 e C4.","D":"C2 E C4."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-157337","number":"157337","sourceNumber":"157337","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Para a definição diagnóstica de Doença de Kawasaki, uma criança deverá apresentar\nfebre com duração de pelo menos 5 dias e:","options":{"A":"Eritema das palmas das mãos, exantema polimorfo, língua com aspecto de morango e\nlinfadenopatia cervical unilateral maior que 1,5 cm.","B":"Hiperemia conjuntival bulbar sem exsudato, edema de mãos e pés, lesões papulo-vesiculares\ndifusas, linfadenopatia inguinal bilateral de 2,0 cm.","C":"Fenômeno de Raynaud, úlceras orais e genitais, edema de mãos e pés e exantema polimorfo.","D":"Artrite migratória, eritema marginado, cardite e nódulos subcutâneos.","E":"Púrbura palpável, artrite, angina intestinal e eritema polimorfo."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-156434","number":"156434","sourceNumber":"156434","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"A presença de púrpura palpável ou petéquias, com predomínio em membros inferiores\né critério mandatório para diagnóstico de qual\npatologia?","options":{"A":"Doença de Kawasaki","B":"Púrpura de Henoch-Schönlein","C":"Síndrome hemolítico Uremica","D":"Lupus eritematoso sistêmico"},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-128003","number":"128003","sourceNumber":"128003","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"O paciente é um homem de 58 anos que está internado em um hospital geral, para uma\ncirurgia de hérnia inguinal. Encontra-se em bom estado geral. O exame físico é normal, exceto por\nalguns nódulos em região cervical, 1 x 1 cm, indolores, não aderidos a planos profundos. O Ht é\n42%; plaquetas = 335.000/mm; leucócitos = 50.000/mm³; granulócitos = 4%; monócitos = 1%;\nlinfócitos = 95%. Marque a alternativa com a hipótese diagnóstica mais provável para o caso\ndescrito acima:","options":{"A":"Leucemia Linfocítica Crônica (LLC).","B":"Leucemia Mieloide Crônica (LMC).","C":"Leucemia Linfocítica Aguda (LLA).","D":"Leucemia Mieloide Aguda (LMA)."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-127711","number":"127711","sourceNumber":"127711","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Considerando a mielofibrose primária, qual situação está relacionada a um melhor\ncomportamento clínico e prognóstico?","options":{"A":"Mutação JAK2.","B":"Mutação na região CARL.","C":"Mutação MPL.","D":"Presença da proteína de fusão BCR-ABL."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-127704","number":"127704","sourceNumber":"127704","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"A pesquisa de anticorpos contra componentes celulares (FAN) é um exame laboratorial\nimportante na triagem das doenças difusas do tecido conjuntivo. Na interpretação desse exame,\ndeve-se levar em consideração que:","options":{"A":"O valor do título é uma informação mais importante do que o padrão de fluorescência, na\ndeterminação da relevância clínica.","B":"O padrão de fluorescência nucleolar apresenta correlação, principalmente, com a doença\nesclerose sistêmica.","C":"O padrão de fluorescência nuclear pontilhado fino denso é o marcador da doença mista do\ntecido conjuntivo.","D":"O padrão nuclear pontilhado grosso é um padrão de fraca relevância clínica e é raramente\nobservado nas doenças difusas do tecido\nconjuntivo."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-127648","number":"127648","sourceNumber":"127648","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Chega para avaliação uma criança de seis anos com história de dor em joelhos e\ntornozelos há cerca de uma semana,\nassociada a manchas avermelhadas nos braços e nas\npernas. Ao exame, são evidenciadas lesões maculopapulares avermelhadas que não desaparecem\nà digitopressão. As plaquetas estão normais ao hemograma. O médico faz o diagnóstico de\npúrpura de Henoch-Schönlein. Na doença diagnosticada:","options":{"A":"O comprometimento articular de pequenas articulações ocorre em cerca de 60-80% dos casos.","B":"O comprometimento da função hepática está presente em cerca de 50% dos casos.","C":"A presença de manifestação renal, em geral, é um indicador de pior prognóstico.","D":"A biópsia da lesão demonstra infiltrado de eosinófilos."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-109182","number":"109182","sourceNumber":"109182","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"No tratamento de uma criança com neutropenia febril, o esquema antibiótico inicial\nempírico mais indicado é:","options":{"A":"Meropenem + ampicilina.","B":"Cefadroxil + claritromicina.","C":"Ceftriaxona + ampicilina.","D":"Ceftazidima + amicacina."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-101167","number":"101167","sourceNumber":"101167","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Paciente com leucemia mieloide crônica em uso de imatinibe, 400 mg/dia. No terceiro\nmês de tratamento apresenta Hb: 9,0 g/dl;\nGB: 12.300, com 1% de mielócitos, 2% de\nmetamielócitos, 18% de bastões, 40% de segmentados, 2% de eosinófilos, 2% de basófilos, 35%\nde linfócitos, 10% de monócitos e 450.000/ul de plaquetas. Baço não palpável, com traube\nocupado. No caso desse paciente, qual é a conduta indicada?","options":{"A":"Manter imatinibe 400 mg/dia e agendar retorno em três meses.","B":"Manter imatinibe 400 mg/dia e agendar retorno em um mês para checar aderência.","C":"Elevar a dose de imatinibe para 600 mg/dia.","D":"Trocar imatinibe para inibidor de tirosina quinase de segunda geração (dasatinibe ou\nnilotinibe)."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-110231","number":"110231","sourceNumber":"110231","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Um homem de 37 anos procurou atendimento médico com história de dois meses de\nastenia, cansaço fácil e gengivorragia. Após avaliação médica, fez hemograma que evidenciou\nquadro de pancitopenia. O exame anatomopatológico de medula óssea mostrou uma celularidade\nmedular de 20%, compatível com o diagnóstico de aplasia de medula óssea. Qual alternativa define\na aplasia de medula óssea como grave?","options":{"A":"Presença de sintomas B: febre, emagrecimento ou sudorese profusa noturna.","B":"Nível de hemoglobina menor que 6,0 g/dL e contagem de plaquetas menor que 30.000/uL.","C":"Contagem absoluta de neutrófilos menor que 500 células/uL e contagem de plaquetas menor\nque 20.000/uL.","D":"Contagem absoluta de neutrófilos menor que 1.000 células/uL, contagem de plaquetas menor\nque 30.000/uL e nível de hemoglobina menor que\n8,0 g/dL."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-109381","number":"109381","sourceNumber":"109381","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"A leucemia mielocítica aguda é responsável por cerca de 11% dos casos de leucemia\nnos EUA. A infiltração gengival (hipertrofia\ngengival) é mais observada, dentre os subtipos, no\nseguinte:","options":{"A":"M1.","B":"M2.","C":"M3.","D":"M4."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-61734","number":"61734","sourceNumber":"61734","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Um contador de 44 anos de idade vem visitá-lo tendo sido diagnosticado,\nrecentemente, leucemia linfocítica crônica. Ele\npesquisou sua doença na internet e leu que\nnormalmente acontece nos idosos, com idade média de 72 anos. Quais dos seguintes fatores na\nsua história pregressa e antecedentes possivelmente podem ter contribuído para o seu diagnóstico\nnuma idade tão precoce?","options":{"A":"Ele trabalhava numa área de exposição à energia nuclear.","B":"Ele tinha uma infecção crônica por Epstein-Barr vírus três anos atrás.","C":"Ele foi tratado com methotrexate para doença inflamatória intestinal quatro anos atrás.","D":"Sua mãe morreu de linfoma não Hodgkin."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-62708","number":"62708","sourceNumber":"62708","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Um paciente de 70 anos apresentou alterações em eletroforese de proteínas e foi\nencaminhado para avaliação. Sem queixas ou alterações ao exame físico. Apresenta hemograma\ncom Hb:13,0, GB: 6.000/ul e plaquetas de 150.000/ul. Eletroforese de proteínas com albumina de\n4,0 g/dl, gamaglobulinas de 3,5 g/dl, com pico monoclonal IgG/Kappa, cálcio sérico normal,\ncreatinina de 1,5, glicemia de 135,0. Inventário ósseo mostra osteopenia leve. Mielograma mostra\ninfiltração por 15% de plasmócitos anaplásicos. O diagnóstico, nesse caso, é:","options":{"A":"Síndrome de POEMS.","B":"Mieloma múltiplo indolente.","C":"Mieloma múltiplo sintomático.","D":"Pico monoclonal de significado indeterminado."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-62740","number":"62740","sourceNumber":"62740","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Paciente de 59 anos relata emagrecimento de 15 quilos em oito meses e desconforto\nabdominal, com dores em hipocôndrio\nesquerdo. Ao exame, está descorado, leve, emagrecido,\nsem adenomegalias e baço a 5 cm do rebordo costal esquerdo. Hemograma com Hb: 8,0 g/dl, GB:\n22.000/uL, com blastos: 00%, promielócitos: 00%, mielócitos: 03%, metamielócitos: 02%, bastões:\n\n14%, segmentados: 60%, eosinófilos: 01%, basófilos: 00%, linfócitos: 17%, monócitos: 03%,\nplaquetas: 450.000/uL, eritroblastos 10/100 GB.\nMielograma mostrou-se inconclusivo. Análise\nmolecular mostra PCR para BCR-ABL negativo, PCR para mutação JAK2 negativa. Cariótipo em\nandamento. Com base nesses dados, qual é o diagnóstico?","options":{"A":"Mielofibrose primária.","B":"Leucemia mieloide crônica.","C":"Linfoma esplênico.","D":"Trombocitemia essencial."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-63215","number":"63215","sourceNumber":"63215","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Em relação às leucemias, é correto afirmar:","options":{"A":"As leucemias mieloides agudas correspondem a 50% das leucemias na infância.","B":"O pico de incidência da leucemia linfoide aguda ocorre em menores de 1 ano e em\nadolescentes.","C":"Hipertrofia gengival, coagulação intravascular disseminada e cloromas são manifestações\nclínicas mais frequentes na leucemia linfoide aguda.","D":"As translocações t (4;11) e t (9;22) estão relacionadas ao melhor prognóstico nas leucemias\nlinfoides agudas.","E":"A neutropenia febril é uma complicação frequente do tratamento quimioterápico das leucemias,\nsendo necessária intervenção rápida com início\nde antibioticoterapia endovenosa."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-47810","number":"47810","sourceNumber":"47810","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Uma idosa refere fraqueza há dois meses e apresenta esplenomegalia a 2 cm da borda\ncostal esquerda. O hemograma mostrou Hb - 9 g/dl, Leuc. - 4.200/ul (50% de neutrófilos, 42% de\nlinfócitos e <1% de monócitos) e Plaq. - 50.000/ul. O mielograma revelou medula normocelular,\ncom predomínio de eritroblastos atípicos, 20% de sideroblastos em anel de 3% de blastos. Foi\nrealizado o tratamento com vitaminas B12, B6 e ácido fólico, porém, sem resposta e com piora da\nanemia e da plaquetopenia. Nesse caso, qual é o diagnóstico?","options":{"A":"Leucemia mieloide aguda.","B":"Anemia sideroblástica.","C":"Síndrome de deleção do 5q (Síndrome do 5q-).","D":"Síndrome mielodisplásica."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-34004","number":"34004","sourceNumber":"34004","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Paciente com 70 anos de idade, com quadro de mal-estar, descoramento\ncutaneomucoso e fraqueza. Exames mostram Hb:\n9,7 g/dl, Leucócitos: 2800/ul, Neutrófilos:\n1.900/ul, Plaquetas: 100.000/ul; Mielograma: medula óssea hipercelular, com diseritropoiese\nmoderada em série vermelha, série granulocítica com disgranulopoiese moderada com 4% de\nmieloblastos e ausência de bastonetes de Auer, série megacariocítica sem alterações. Segundo a\nOrganização Mundial de Saúde (WHO ? OMS), trata-se de um caso de:","options":{"A":"Citopenia refratária com displasia de múltiplas linhagens.","B":"Anemia refratária com excesso de blastos em transformação.","C":"Anemia refratária com excesso de blastos tipo I.","D":"Anemia refratária com excesso de blastos tipo II."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-34074","number":"34074","sourceNumber":"34074","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Criança com seis anos de idade, há um mês vem apresentando febre, dor nos\nmembros inferiores associada à palidez\ncutâneo-mucosa. Realizou hemograma e mielograma com\ndiagnóstico de leucemia linfoide aguda. Na leucemia linfoide aguda:","options":{"A":"A presença de tumores em tecidos moles, chamados de cloromas, constitui um dos indicadores.","B":"As manifestações osteoarticulares são raras e, quando presentes, fazem diagnóstico diferencial\ncom artrite reumatoide juvenil e febre\nreumática.","C":"Os sintomas iniciais comuns incluem febre, palidez (anemia) e sinais de sangramento (petéquias\ne equimoses).","D":"A dor osteoarticular, na maioria das vezes, cede com repouso e anti-inflamatórios não\nhormonais."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-9328","number":"9328","sourceNumber":"9328","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"A transfusão de concentrado de plaquetas está indicada na seguinte situação:","options":{"A":"pré-operatório de apendicite com contagem plaquetária de 55.000/Ul","B":"púrpura trombocitopênica imune com gengivorragia e contagem plaquetária de 5.000/Ul","C":"quimioterapia para leucemia linfoide aguda com febre e contagem plaquetária de 15.000/Ul","D":"aplasia de medula óssea com sangramento da esclerótica e contagem plaquetária de 11.000/Ul"},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-273980","number":"273980","sourceNumber":"273980","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Com relação às colagenoses, assinale a alternativa CORRETA:","options":{"A":"É importante monitorizar contagem de linfócitos, recorrência de edema de parótidas,\nlinfadenomegalias e perfil da eletroforese de\nproteínas séricas e urinárias nos pacientes com\nsíndrome de Sjögren primária, pois a mudança no seu perfil pode sugerir possibilidade de evolução\npara linfoma.","B":"Muito mais importante que saber o padrão do Fator Antinuclear (FAN), é saber a sua titulação,\npois o padrão do FAN de nada importa se este\nestiver em títulos baixos.","C":"O fenômeno de Raynaud é um desarranjo do sistema nervoso autônomo, no controle dos\ncalibres dos vasos sanguíneos, que ocorre\nexclusivamente em extremidades do corpo, como mãos\nou pés.","D":"Pacientes que irão receber prednisona em dose ? 7,5 mg por mais de 3 meses e menos de 1\nano não precisam ser submetidos a profilaxia\npara osteoporose, pois o risco de osteoporose nos\nusuários de corticoide ocorre principalmente após 1 ano de uso."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-250229","number":"250229","sourceNumber":"250229","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"A Síndrome do Anticorpo Antifosfolípide (SAAF) é uma doença autoimune\ncaracterizada por uma série de manifestações\nclínicas, na maioria das vezes relacionadas direta ou\nindiretamente ao estado de hipercoagulabilidade. Em relação à SAAF, assinale a alternativa\nINCORRETA:","options":{"A":"A trombose de veia hepática está entre as manifestações clínicas.","B":"Dentre os critérios obstétricos da doença: a presença de 3 ou mais abortos espontâneos antes\nde 10 semanas de gestação.","C":"A dosagem de antibeta-2-glicoproteína não faz parte dos critérios diagnósticos.","D":"Está relacionada à insuficiência placentária."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-216385","number":"216385","sourceNumber":"216385","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Uma das dúvidas mais recorrentes para médicos internistas é a diferenciação entre\nquadro infeccioso e atividade de doença\nreumatológica. Supondo uma paciente lúpica em uso de\nprednisona 20 mg/dia, que evolua com quadro febril agudo e infiltrado pulmonar novo, haverá\nindiscutível de antibioticoterapia em caso de:","options":{"A":"Procalcitonina abaixo de 0,1 ng/mL.,","B":"Leucocitose no hemograma.","C":"Títulos de FAN abaixo de 1:1280.","D":"Queda de 15 para 11 pontos na escala de coma de Glasgow."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-216402","number":"216402","sourceNumber":"216402","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Sobre a Síndrome do Anticorpo Antifosfolipídio, é CORRETO afirmar:","options":{"A":"O infarto agudo do miocárdio é o evento arterial mais frequente nos pacientes com esta\nsíndrome.","B":"Pacientes com tromboembolismo venoso mais comumente se apresentam com trombose do\nseio sagital superior.","C":"Embora seja uma doença trombótica, é comum elevar o tempo de tromboplastina parcial\nativada.","D":"A doença mista do tecido conjuntivo é a colagenose mais classicamente associada a esta\nsíndrome."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-155440","number":"155440","sourceNumber":"155440","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Criança, 6 anos de idade, dá entrada na emergência com queixa de manchas no corpo,\nque se caracteriza por púrpura palpável,\npredominando em região glútea e membros inferiores, dor\nem articulações, edema de mãos e pés, dor abdominal e hematúria. Qual o diagnóstico MAIS\nPROVÁVEL?","options":{"A":"Doença de Kawasaki.","B":"Dermatopolimiosite.","C":"Artrite idiopática juvenil.","D":"Lúpus eritematoso sistêmico.","E":"Púrpura de Henoch-Schölein."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-155344","number":"155344","sourceNumber":"155344","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"A doença de Kawasaki é uma vasculite multissistêmica com quadro clínico e\nlaboratorial e complicações conhecidas, mas\nde etiologia ainda não definida. Com relação ao\ndiagnóstico dessa doença, identifique os critérios a seguir como ''V'' (verdadeiro) ou ''F''\n(falso): ( )\nFebre de duração maior do que 5 dias. ( ) Conjuntivite purulenta. ( ) Exantema polimorfo. ( )\nAdenomegalia cervical não supurativa. ( ) Alterações de mucosa oral. Assinale a alternativa que\napresenta a sequência CORRETA, de cima para baixo:","options":{"A":"F, V, V, F, V","B":"V, F, V, V, F","C":"F, V, F, F, V","D":"V, F, V, V, V","E":"V, V, F, V, F"},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-131916","number":"131916","sourceNumber":"131916","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Em um paciente do sexo masculino com 32 anos de idade, asma, sinusopatia, nódulos\nsubcutâneos em face ventral do antebraço esquerdo, infiltrados pulmonares migratórios e mais de\n\n1.000 eos./ml no hemograma, há mais chance de positividade de qual exame?","options":{"A":"p-ANCA.","B":"c-ANCA.","C":"Sorologia para Aspergillus.","D":"Cultura de escarro para Aspergillus.","E":"Exame parasitológico de fezes."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-105713","number":"105713","sourceNumber":"105713","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Adolescente de 15 anos apresenta, há 3 semanas, febre alta, adinamia, equimoses em\nmembros inferiores, hemoglobina 10 g/dl, leucócitos 50.000/mm³, neutrófilos 5.000/mm³, presença\nde blastos e plaquetas 35.000/mm³. Qual o exame importante para o diagnóstico?","options":{"A":"Coombs direto e indireto.","B":"Mielograma.","C":"Biópsia de medula óssea.","D":"Coagulograma.","E":"Eletroforese de hemoglobina."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-28268","number":"28268","sourceNumber":"28268","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Em qual das situações abaixo podemos encontrar aumento dos níveis séricos de\nvitamina B12?","options":{"A":"Policitemia vera","B":"Insuficiência pancreática;","C":"Síndrome de Zollinger-Ellison;","D":"Diphyllobothrium latum (infestação maciça)","E":"Metformina (uso prolongado)"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-342407","number":"342407","sourceNumber":"342407","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Na esclerodermia generalizada com comprometimento cutâneo difuso, uma das\nprincipais complicações são:","options":{"A":"Telangiectasias","B":"Calcinose cutânea","C":"Doença Pulmonar Intersticial","D":"Fenômeno de RAYNAUD","E":"Esclerodactilia"},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-311489","number":"311489","sourceNumber":"311489","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Qual a alteração cutânea mais típica na SAF (síndrome do anticorpo antifosfolipídeo)?","options":{"A":"Eritema nodoso.","B":"Livedo reticularis.","C":"Púrpura palpável.","D":"Nódulos subcutâneos.","E":"Eritema marginatum."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-308636","number":"308636","sourceNumber":"308636","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Qual das seguintes vasculites de pequenos vasos está associada à Hepatite C em\ncerca de 95% dos casos?","options":{"A":"Púrpura de Henoch-scholein","B":"Granulomatose de Wegener.","C":"Síndrome de Churg-Strauss.","D":"Poliangiíte microscópica.","E":"Crioglobulinemia essencial tipo II."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-302077","number":"302077","sourceNumber":"302077","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Os anticorpos antinucleares são comumente encontrados em uma variedade de\ndoenças reumáticas, incluindo o Lúpus Eritematoso\nSistêmico (LES). Assinale a opção CORRETA\nsobre o manejo diagnóstico das colagenoses.","options":{"A":"Trombocitopenia, derrame pleural, úlceras orais e FAN com titulação > 1:160 sugere diagnóstico\nde lúpus.","B":"O Fator Antinuclear (FAN) positivo tem especificidade de 98% para lúpus.","C":"FAN positivo com eritema em heliótropo é fortemente sugestivo de lúpus.","D":"A presença de anticorpos anti-Ro e anti-La exclui o diagnóstico de lúpus.","E":"A confirmação diagnóstica para LES inclui FAN positivo e complementos séricos diminuídos."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-302078","number":"302078","sourceNumber":"302078","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Sobre a esclerodermia podemos afirmar:","options":{"A":"Na síndrome CREST a hipertensão pulmonar é mais rara.","B":"A corticoterapia sistêmica alivia queixas álgicas e rigidez articular, modifica a progressão da\ndoença e seu uso está indicado na dose de\n1mg/Kg dia.","C":"O Fenômeno de Raynaud, claudicação intermitente e tromboflebite é tríade comum na\nesclerodermia.","D":"Para as formas de esclerodermia localizada (morfeia) a corticoterapia tópica, análogos da\nvitamina D (calcipotriol, cacitriol) e o imiquimode 5% são empregados.","E":"A lesão cutânea só estará presente na forma focal da doença e o fenômeno de Raynaud é\nachado sempre presente na esclerodermia sistêmica\nou focal."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-302085","number":"302085","sourceNumber":"302085","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Síndrome da Fadiga Crônica (SFC) é uma condição de diagnóstico clínico cujo principal\nsintoma é a presença de fadiga (cansaço) intensa que pode piorar com a atividade física ou mental,\nmas não melhora com o repouso\n\n(https://www.reumatologia.org.br/orientacoes-ao-paciente/sindrome-da-fadiga-cronica/). Qual das\nseguintes opções é um tratamento benéfico para a síndrome ora em tela?","options":{"A":"bupropiona","B":"terapia cognitivo comportamental","C":"doxiciclina","D":"fluoxetina","E":"olanzapina"},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-278931","number":"278931","sourceNumber":"278931","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Mulher de 48 anos comparece à Unidade Básica de Saúde solicitando laudo médico\npara afastamento de atividades laborativas, pois\nnão consegue trabalhar devido a quadro de fadiga\ncrônica, astenia, boca seca, tonturas, rigidez articular matinal, dor articular generalizada há\nmais de\n4 meses e cefaleia. Ao exame, constata-se dor à palpação em proeminências ósseas e em porções\nmediais de segmentos musculares. A hipótese diagnóstica mais provável é:","options":{"A":"Esclerodermia","B":"Fibromialgia","C":"Lúpus eritematoso sistêmico","D":"Hipotireoidismo","E":"Síndrome de Sjögren"},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-244669","number":"244669","sourceNumber":"244669","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Em relação à fibromialgia, é INCORRETO afirmar:","options":{"A":"Distúrbios do sono são pouco frequentes.","B":"Cursa com fadiga mental e/ou física ao despertar.","C":"A prevalência é maior em mulheres e a idade média é de 49 anos.","D":"Acomete com mais frequência familiares, parente consanguíneos, podendo afetar crianças.","E":"A síndrome miofascial é importante manifestação satélite."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-252410","number":"252410","sourceNumber":"252410","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"No Lúpus eritematoso sistêmico, para melhor avaliar e monitorar a evolução da doença,\ndevemos utilizar preferencialmente os seguintes parâmetros:","options":{"A":"Autoanticorpo anti-DNA e redução do complemento C3","B":"Aumento do FAN e PCR","C":"Melhora do quadro de poliartralgia e aumento do FAN","D":"Presença de artralgias e redução do complemento C3","E":"Autoanticorpo anti-histona e redução do complemento C3"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-203270","number":"203270","sourceNumber":"203270","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Paciente com diagnóstico prévio de esclerodermia, com comprometimento cutâneo\ndifuso, dá entrada em pronto-socorro com\nhipertensão maligna, oligúria, edema e insuficiência\nrenal. Médico emergencista faz diagnóstico de crise renal de esclerodermia. Recomenda-se iniciar:","options":{"A":"Losartan.","B":"Clonidina.","C":"Nitroprussiato de sódio.","D":"Captopril.","E":"Carvedilol."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-203612","number":"203612","sourceNumber":"203612","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"A hipótese diagnóstica para uma criança de 5 anos, apresentando artralgia/artrite, dor\nabdominal, hematúria e lesões cutâneas purpúricas, é:","options":{"A":"Púrpura de Henoch Schonlein.","B":"Glomerulonefrite difusa aguda.","C":"Síndrome de Alport.","D":"Nefrite lúpica.","E":"Síndrome nefrótica."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-184846","number":"184846","sourceNumber":"184846","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"As Vasculites associadas ao Anticorpo Anticitoplasma de Neutrófilo (ANCA) se\ncaracterizam por um grupo de doenças que se caracterizam pelos seguintes achados\netiopatogênicos, EXCETO:","options":{"A":"Histologicamente por vasculite necrotizantes de vasos de pequeno calibre","B":"Por frequentes depósitos de imunocomplexos nas paredes dos vasos afetados.","C":"Acometem predominantemente adultos.","D":"A fração C5a do complemento participam do processo inflamátório.","E":"Tal inflamação acontece principalmente no trato respiratório superior e inferior e os rins."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-184828","number":"184828","sourceNumber":"184828","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Paciente de 26 anos na 14ª semana de gestação da entrada no hospital com quadro de\ndor súbita, intensa, ventilatório dependente na base do hemitórax direito, dispneia e hemoptóicos,\nD-dimero 875 ng/ml e Angio-CT tórax, confirma diagnóstico de TEP (Tromboembolismo Pulmonar).\nPaciente relata 2 perdas fetais espontâneas, uma na 28ª semana e a outra na 32ª semana de\ngestação. Qual o fator etiopatogênico mais provável?","options":{"A":"Coriocarcinoma gestacional","B":"Anticorpo Antifosfolipides","C":"Mutação do Fator V de Leiden","D":"Mutação G20210A da Protrombina","E":"Metástase de tumor de tireoide"},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-177467","number":"177467","sourceNumber":"177467","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Assinale a alternativa que aponta correlação correta entre manifestação clínica do lúpus\neritematoso sistêmico e o tratamento indicado na referida situação","options":{"A":"nefrite lúpica classe II -> pulsoterapia com metilprednisolona","B":"pleurite -> anti-inflamatório não-esteroidal","C":"anemia hemolítica autoimune -> hidroxicloroquina","D":"poliartrite -> prednisona 1mg/Kg/dia","E":"endocardite de Libmas-Sacks -> rituxmab"},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-175041","number":"175041","sourceNumber":"175041","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Paciente feminina de 39 anos, referindo há um ano xeroftalmia, xerostomia e cáries de\nrepetição. Diante do exposto, quais os exames mais apropriados para confirmar o diagnóstico?","options":{"A":"Anti-La e Fundoscopia","B":"Anti-RNP e Teste Rosa-Bengala","C":"Fator antinuclear e Fundoscopia","D":"Anti-Sc170 e teste de Schirmer","E":"Anti-Ro e Teste de Schirmer"},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-177542","number":"177542","sourceNumber":"177542","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Paciente de 38 anos evoluindo há 12 dias com dispneia e tosse progressivas,\nassociadas à febre baixa e outros sintomas\nconstitucionais, começou a observar há 6 dias urina de\naspecto escurecido. Procura atendimento após observar redução do volume urinário, trazendo um\nEAS solicitado por amigo médico, onde se observa hematúria e cilindros hemáticos. Ao exame,\nencontra-se levemente hipocorado, anictérico, com discreto edema de MMII. PA de 160 x 90\nmmHg. Ausculta respiratória com crepitações finas em metades inferiores de ambos os pulmões.\n\nExames iniciais revelam hemograma com 13.000 leucócitos, sem desvio, creatinina de 2,1 mg/dl;\npotássio de 5,8 mg/dl; sódio de 134 mg/dl; bilirrubina total em 1,0 mg/dl. A radiografia de tórax à\nadmissão é mostrada a seguir. Levando em consideração o quadro clínico do paciente e o\nconhecimento clínico acerca das doenças citadas nas opções abaixo, qual constitui hipótese mais\nplausível para o paciente?","options":{"A":"Poliangiite microscópica.","B":"Poliarterite nodosa.","C":"Síndrome de Goodpasture.","D":"Leptospirose.","E":"Trombose de veia renal."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":["question_bank/media/medcurso/med-clinica-medica-med-clm-21/177542.png"],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-160412","number":"160412","sourceNumber":"160412","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Uma jovem de 30 anos apresenta febre baixa, fadiga, artrite em mãos (bilateral),\ndispneia e dor pleurítica retroesternal.\nExames laboratoriais mostram: (Conforme imagem do\ncaderno de questões). Foi realizado um ecocardiograma que mostrou lâmina de líquido em\npericárdio e pleura à esquerda. A radiografia de tórax mostra apenas pequeno derrame pleural à\nesquerda. Das opções a seguir, qual exame deve ser solicitado para obter o diagnóstico?","options":{"A":"Fator reumatoide.","B":"Anti-Ro.","C":"Anti-DNA.","D":"Anti-La.","E":"Mucoproteínas séricas."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":["question_bank/media/medcurso/med-clinica-medica-med-clm-21/160412.png"],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-160419","number":"160419","sourceNumber":"160419","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Uma jovem de 30 anos apresenta febre baixa, fadiga, artrite em mãos (bilateral),\ndispneia e dor pleurítica retroesternal.\nExames laboratoriais mostram: (Conforme imagem do\ncaderno de questões). Foi realizado um ecocardiograma que mostrou lâmina de líquido em\npericárdio e pleura à esquerda. A radiografia de tórax mostra apenas pequeno derrame pleural à\nesquerda. Das opções a seguir, a conduta mais apropriada é prescrever:","options":{"A":"Prednisona 0,25 a 0,50 mg/kg/dia.","B":"Pulsoterapia metilprednisolona 10 mg/kg.","C":"Ácido acetilsalicílico 500 mg 6/6h.","D":"Penicilina G benzatina.","E":"Prednisona 1 mg/kg/dia."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":["question_bank/media/medcurso/med-clinica-medica-med-clm-21/160419.png"],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-160429","number":"160429","sourceNumber":"160429","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"A emergência pediátrica recebe um escolar de 8 anos queixando-se de dores\nabdominais difusas, que pioram às refeições. No\nexame físico, o médico residente observa \"lesões\npalpáveis e avermelhadas\" que se manifestam predominantemente nos membros inferiores e na\nregião glútea. Suspeita de \"artrite\" nos tornozelos. Nos exames laboratoriais encontra leucocitose\ndiscreta e VHS de 45 mm (na primeira hora). Marque diagnóstico mais provável.","options":{"A":"Púpura trombocitopênica.","B":"Doença de Kawasaki.","C":"Púrpura de Henoch-Schonlein.","D":"Artrite reumatoide.","E":"Poliarterite nodosa."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-362852","number":"362852","sourceNumber":"362852","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Paciente de quatro anos apresenta febre há 6 dias, persistente, associada à\nlinfadenomegalia, exantema escarlatiniforme, edema\nde mãos e pés, além de língua em framboesa\ne hiperemia conjuntival bilateral sem secreção. Conforme relato, o diagnóstico mais provável e o\nseu respectivo tratamento são:","options":{"A":"escarlatina e amoxicilina oral.","B":"doença de Kawasaki e imunoglobulina humana associada ao uso de ácido acetilsalicílico.","C":"artrite idiopática juvenil e anti-inflamatório não esteroidal.","D":"mononucleose e sintomáticos."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-330839","number":"330839","sourceNumber":"330839","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Paciente jovem de 19 anos com LES, com plano de engravidar. Quais autoanticorpos\npodem interferir diretamente na gravidez?","options":{"A":"Anti SM, anti Beta 2 glicoproteína 1, anticoagulante lúpico.","B":"Anti Beta 2 glicoproteína 1, anti SSA/RO, anticoagulante lúpico.","C":"Anticoagulante lúpico, anti RNP, anti SSA/RO.","D":"Anti SM, anti RNP, anti SSA/RO."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-330841","number":"330841","sourceNumber":"330841","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Mulher de 19 anos apresenta febre de longa duração, astenia, perda de peso, evolui\ncom claudicação intermitente no braço esquerdo\napós pequenos esforços e aumento da pressão\narterial no braço direito. Exames revelam leucocitose moderada, VHS 100 mm/h e PCR 21 mg/L. O\ndiagnóstico mais provável e o exame complementar mais indicado para elucidar o caso são:","options":{"A":"Doença de Takayasu/ angioRM.","B":"Arterite temporal/ angioRM.","C":"Aortite infecciosa/ arteriografia.","D":"Displasia fibromuscular/ arteriografia."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-327351","number":"327351","sourceNumber":"327351","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Lactente, masculino, 18 meses de idade, previamente hígido, foi levado à UPA com\nhistória de febre alta (39,2oC), iniciada\nhá 3 dias, acompanhada de tosse seca, rinorreia e\ncongestão ocular não exudativa. Vacinas em dia. Ao exame, apenas hiperemia de orofaringe e\nmembranas timpânicas. O médico solicitou Rx de tórax, com resultado normal. Liberou a criança\npara casa com Paracetamol, soro fisiológico para as narinas e higiene ocular, medicação que já\ncostumava utilizar na criança. Paciente não apresentou melhora, persistindo com o quadro. Após 2\ndias, evoluiu com dor abdominal difusa, diarreia (fezes semilíquidas 5x/dia, amareladas, sem muco,\npus ou sangue, odor incaracterístico), hiperemia difusa em face, tronco e membros, edema em\nface, mãos e pés, eritema de mucosa oral e fissuras labiais. Retornou à UPA sendo atendido por\noutro profissional. Ao exame: REG, febril (Tax: 39oC) taquicárdico, hiperemia ocular bilateral,\nanictérico e acianótico. Otoscopia mostrou hiperemia. Orofaringe com hiperemia e língua em\nframboesa. Pescoço com linfonodos palpáveis à direita, sendo o maior com 1,5 cm de diâmetro e\nsem sinais flogísticos. AR: MV fisiológico, sem ruídos adventícios. ACV: RCR, 2t, sem sopros.\n\nTempo de enchimento capilar menor que 3 segundos. Abdome plano, simétrico, sem dor à\npalpação profunda e sem visceromegalias. Genitália masculina sem alteração. SN sem sinais\nmeníngeos. Pele com exantema difuso polimorfo, indolor e não pruriginoso e sinal de Nikolsky\nnegativo. Qual a principal hipótese diagnóstica?","options":{"A":"Doença de Kawasaki","B":"Escarlatina","C":"Sarampo","D":"Toxoplasmose"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-313423","number":"313423","sourceNumber":"313423","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Considerando os autoanticorpos e marcadores reumáticos, o painel que mais\ncaracteriza a doença mista do tecido conjuntivo é:","options":{"A":"Fator reumatoide positivo, anti-SSA (RO) presente, anti-SSB (LA) presente.","B":"FAN positivo, fator reumatoide presente, anti-RNP presente.","C":"FAN positivo, anti-SM presente, anti-RNP presente.","D":"FAN positivo, anti-SCL presente, anti-RNA polimerase I, II e III."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-258918","number":"258918","sourceNumber":"258918","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Paciente, 23 anos, em acompanhamento ambulatorial por Lupus Eritematoso\nSistêmico. Em consulta de rotina, refere\ndiscreto edema de membros inferiores e traz exames para\nchecagem. Hemoglobina: 11 g/dL, creatinina: 2,1, ureia: 84. EAS: presença de hematúria (10\nhemácias por campo) e traços de proteínas. Proteinúria de 24h: 750 mg/24h. Presença de\nHipocomplementemia e anti-dsDNA. Na hipótese de Nefrite Lúpica e de acordo com o Consenso da\nSociedade Brasileira de Reumatologia para diagnóstico, manejo e tratamento da Nefrite Lúpica,\ncom base nos critérios clínicos e laboratoriais, pode-se inferir a classe histológica dessa paciente\ncomo:","options":{"A":"Glomerulonefrite Mesangial Mínima Classe I.","B":"Glomerulonefrite Membranosa Classe V.","C":"Glomerulonefrite Proliferativa Difusa Classe IV.","D":"Esclerose Avançada Classe VI."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-288144","number":"288144","sourceNumber":"288144","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"O Lúpus Eritematoso Sistêmico (LES) é uma doença autoimune na qual órgão e células\nsofrem algum dano mediado por autoanticorpos e imunocomplexos acoplados aos tecidos. Em\nrelação ao LES, assinale a afirmativa CORRETA.","options":{"A":"Se dois critérios estiverem presentes, como erupção malar e fotossensibilidade, o diagnóstico de\nLES pode ser concluído.","B":"Anti-Ro (SS-A) é muito prevalente na doença (98%), sendo muito específico do LES e pouco\nrelacionado ao lúpus cutâneo.","C":"90% dos pacientes são representados por mulheres em idade fértil.","D":"O acometimento renal pelo LES não ocorre."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-258944","number":"258944","sourceNumber":"258944","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Menino, 3 anos de idade, deu entrada em UPA de Cuiabá, acompanhado por sua mãe,\ncom história de quadro de tosse seca há 10 dias, acompanhado de coriza e febre (39° C), 3-4 picos\ndiários, não cedendo com o uso de dipirona (10 gotas). A tosse e a coriza melhoraram em 3 dias,\nentretanto a febre persistiu e notou aumento de volume da região retroauricular esquerda, dolorosa\ne cerca de 2 cm. Evoluiu com aparecimento de hiperemia ocular e periorbitária bilateral, eritema em\nmãos e pés, hipertrofia de papilas linguais, eritema e fissuras labiais, recusa alimentar e edema\nnos\npés. Nos últimos dias, mãe notou que a criança ficou mais irritada, queixou de dor e edema nos\njoelhos, com aumento de temperatura local, surgiu exantema maculopapular em região dorsal,\ngenitália, mãos e pés. Quais critérios clínicos para o diagnóstico de Doença de Kawasaki estão\npresentes no caso?","options":{"A":"Hiperemia conjuntival, exantema, eritema de mucosa orofaringe, linfonodomegalia cervical,\neritema e edema de mãos e pés.","B":"Hiperemia conjuntival, eritema de mucosa oral e faríngea, linfonodomegalia cervical, dor e\nedema de joelho.","C":"Hiperemia conjuntival, exantema, tosse e coriza, linfonodomegalia cervical, dor e edema de\njoelhos.","D":"Hiperemia conjuntival, hipertrofia de papilas linguais, eritema de mucosa faríngea, tosse e\ncoriza,\ndor e edema de joelhos."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-267339","number":"267339","sourceNumber":"267339","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"A.S., 13 anos, vem ao ambulatório de pediatria com queixa de dor e edema de\narticulações interfalangianas proximais bilaterais,\njoelhos e punhos há 3 semanas, associado a\nfebre esporádica, emagrecimento e fadiga. Relata aparecimento de lesões indolores em palato e\nmanchas vermelhas em membros inferiores que não desaparecem à digitopressão. Apresenta\ntambém eritema em face que piora com a exposição solar. Ao exame físico, regular estado geral,\nhipocorada (2?/4?), hidratada, eupneica, afebril. PA: 140 x 100 mmHg, FC: 120 bpm, FR: 20 irpm.\nEdema de membros inferiores (2?/4?). Aparelho respiratório: expansibilidade preservada, som claro\npulmonar, ausculta pulmonar sem alterações. Aparelho cardiovascular: pulsos amplos e simétricos,\nritmo cardíaco em 2T, bulhas hipofonéticas, sem sopros. Abdome sem visceromegalias.\n\nOsteoarticular: artrite de articulações interfalangianas proximais bilaterais, joelhos (sinal da\ntecla\npositivo) e punhos. Oroscopia: lesão ulcerada em palato. Quais alterações nos exames\ncomplementares corroboram com a principal hipótese diagnóstica?","options":{"A":"Relação proteína/creatinina urinária 1,0, dosagem de complemento baixa, ecocardiograma:\nderrame pericárdico, FAN positivo.","B":"EAS com proteinúria e hematúria, dosagem de complemento elevada, hemograma com\nlinfopenia, FAN positivo.","C":"EAS com cilindros granulosos, dosagem complemento elevada, RX de tórax com cardiomegalia,\nFAN positivo.","D":"EAS com proteinúria e hematúria, dosagem de complemento baixa, hemograma com linfocitose\ne trombocitose, FAN positivo."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-247659","number":"247659","sourceNumber":"247659","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"O Lúpus Eritematoso Sistêmico (LES) é uma doença sistêmica que pode acometer\ntambém o sistema cardiovascular. Qual é a\nalteração cardíaca mais frequente nos pacientes com a\ndoença?","options":{"A":"Endocardite verrucosa de Libman-Sacks.","B":"Miocardite grave.","C":"Pericardite, com ou sem derrame pericárdico.","D":"Maior risco de doença coronária."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-247663","number":"247663","sourceNumber":"247663","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Sobre os critérios diagnósticos do Lúpus Eritematoso Sistêmico (LES), assinale a\nafirmativa correta.","options":{"A":"Estão validados os critérios diagnósticos para LES do Colégio Americano de Reumatologia,\ncriados em 1997, que nunca foram atualizados e\nos critérios diagnósticos denominados SLICC, de\n2012. Ambos têm sensibilidade e especificidade abaixo de 90%.","B":"Conforme os critérios SLICC, são necessários pelo menos quatro critérios ou biópsia mostrando\nnefrite lúpica associada à positividade para\no FAN ou Anti-DNA (ds). Nesses critérios, a alopécia foi\nincluída como critério clínico.","C":"Alterações inflamatórias como aumento do PCR e do VHS são úteis no diagnóstico do LES.","D":"FAN, Anti-DNA (ds), dosagem de complemento (C3, C4 e CH50), Anti-Sm e Anti-RO (SS-A) são\núteis no diagnóstico."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-247665","number":"247665","sourceNumber":"247665","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Assinale a alternativa que correlaciona corretamente os anticorpos encontrados em\ndoenças reumáticas autoimunes sistêmicas.","options":{"A":"Síndrome Antifosfolípideo secundária a LES: VDRL, Anti-Jo1, Anticardiolipina IgG e IgM,\nAnticoagulante lúpico e Anti-beta2 glicoproteína.","B":"Esclerose Sistêmica: Anti-Scl 70; Anti-TPO e p-ANCA.","C":"Artrite Reumatoide: Antipeptídeo citrulinado cíclico, FAN, Anticentrômero e Fator Reumatoide.","D":"Lúpus Eritematoso Sistêmico: Anti nucleossomo, FAN, Anti-DNA (ds) e Anti-Sm."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-221136","number":"221136","sourceNumber":"221136","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"C.G.S., sexo feminino, 31 anos, admitida no PA com exacerbação de quadro de\nartralgia interfalangianas proximais das mãos,\npunhos, joelhos e tornozelos que iniciou há cinco\nmeses. Há um mês notou a presença de febre diária, diarréria mucosa e HAS quando foi atendida\nna UPA e passou a usar Enalapril. HPP: 01 abortamento espontâneo na 11ª semana de gestação,\nTVP há 5 anos, história de ter apresentado há 3 anos quadro de púrpura em MMII com melhora\nespontânea em menos de 60 dias sem tratamento médico na época. Paciente nega hepatite,\nalterações cardiovasculares e/ou pulmonares. HF: sem histórico relevante. Em relação ao quadro\napresentado, assinale a afirmativa correta.","options":{"A":"Lúpus eritamatoso sistêmico é o diagnóstico devido ao envolvimento articular que é a\nmanifestação mais frequente e hipertensão pulmonar a complicação mais comum, denominada\nsíndrome do pulmão encolhido.","B":"Púrpura Trombocitopênica Idiopática (PTI) é a hipótese principal pelo predomínio no sexo\nfeminino e esquimose é o sinal\ncaracterístico, especialmente nos MMII. Os processos infecciosos,\nespecialmente o pulmonar, tendem a exacerbar o quadro de PTI.","C":"A doença de Hodgkin deve ser a primeira hipótese pelo quadro de febre, diarreia e dispneia em\npaciente com história de evento tromboembólico associado a abortamento prévio. Geralmente,\nafeta mais mulheres na 3ª década de vida.","D":"Síndrome Antifosfolípide é a principal hipótese do caso, confirmada pela presença de um critério\nclínico, trombose vascular; títulos moderados/altos de anticorpo anticardiolipina ou anticorpo\nanticoagulante lúpico devem ser investigados."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-214600","number":"214600","sourceNumber":"214600","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Paciente com as seguintes manifestações de vasculite: sinusopatia, queda do dorso\nnasal, nódulos pulmonares, disfunção renal com\nsedimento renal ativo. Qual é a principal hipótese\ndiagnóstica?","options":{"A":"Granulomatose com poliangiite (Wegener).","B":"Poliangiite microscópica.","C":"Arterite de células gigantes.","D":"Granulomatose eosinofílica com poliangiite (Churg-Strauss)."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-214007","number":"214007","sourceNumber":"214007","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Julgue as afirmações abaixo: I - Lúpus Eritematoso Sistêmico (LES) é doença crônica\nmultissistêmica mediada por autoanticorpos e que acomete principalmente mulheres na menacme.\nII - O FAN é um exame particularmente útil para diagnóstico do LES, esclerodermia,\npolimiosite/dermatomiosite e Síndrome de Sjogren, porém pode estar positivo em pessoas sem\ndoença. III - O diagnóstico da LES deve ser prioritariamente clínico através de alterações\nhematológicas, alterações no exame da Urina do tipo 1 e dosagem de autoanticorpos. São\nverdadeiras:","options":{"A":"Apenas a alternativa I.","B":"Alternativas I e II.","C":"Alternativas I e III.","D":"Todas as alternativas."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-221043","number":"221043","sourceNumber":"221043","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Na prática diária, o conhecimento das manifestações clínicas e laboratoriais de doenças\nsemelhantes é fundamental para o diagnóstico e tratamento corretos. Em relação à doença e sua\nsintomatologia, numere a coluna da direita de acordo com a da esquerda. 1- Artrite idiopática\njuvenil; 2- Doença reumática; 3- Lupus eritematoso sistêmico; 4- Púrpura de Henoch-Schönlein; 5-\nDoença de Kawasaki; ( ) Úlcera de mucosa, serosites, proteinúria, artrite, anemia hemolítica,\nanticorpo anti-Sm e antifosfolípide positivos. ( ) Febre por pelo menos 5 dias, conjuntivite\nasséptica\nbilateral, ressecamento nos lábios, alteração da mucosa oral, edemas nas mãos e pés e\nadenomegalia cervical. ( ) Febre alta diária intermitente por mais de 15 dias, exantema macular,\natrito pericárdico, hepatoesplenomegalia, monoartrite após algumas semanas, fator reumatoide\nnegativo. ( ) Artrite migratória, nódulos subcutâneos, cardite e movimentos involuntários. ( )\nArtrite\ntransitória, lesões micro-hemorrágicas palpáveis, geralmente nas nádegas e membros inferiores\nque aparecem em surtos, hematúria. Assinale a sequência correta.","options":{"A":"1, 3, 2, 5, 4","B":"3, 5, 1, 2, 4","C":"2, 3, 4, 1, 5","D":"3, 4, 1, 2, 5"},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-208544","number":"208544","sourceNumber":"208544","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Homem, 32 anos, caucasoide, referindo episódios de artrite envolvendo joelhos e\ntornozelos há 2 anos. Há um ano passou a apresentar episódios recorrentes de turvação visual\ncom comprometimento da acuidade. Antecedentes pessoais: trombose venosa profunda em\nmembro inferior direito e lesões ulceradas orais há 6 meses. Exame físico: úlceras e lesões\nacneiformes cutâneas em tronco. Exame oftamológico: uveíte posterior bilateral. A hipótese\ndiagnóstica mais provável:","options":{"A":"artrite reumatoide","B":"gota","C":"espondilite anquilosante","D":"arterite de células gigantes","E":"doença de Behçet"},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-181581","number":"181581","sourceNumber":"181581","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Paciente do sexo feminino, 22 anos, sabidamente portadora de Lúpus Eritematoso\nSistêmico, apresenta-se à consulta com relato de que\nhá cerca de dez dias iniciaram dores e perda\nsúbita e progressiva de força em membros inferiores, associado também à déficit sensorial e\ndisfunção urinária. Impõe-se como hipótese diagnóstica Mielite Transversa secundária ao LES.\nQual o tratamento inicial mais adequado?","options":{"A":"Tratar com Prednisona oral na dose de 1 mg/kg/dia, nos primeiros 20-30 dias.","B":"Tratar com Prednisona oral na dose de 0,5 mg/kg/dia, nos primeiros 20-30 dias.","C":"Tratar com Imunoglobulina ou plasmaférese.","D":"Tratar com Metilprednisolona na dose de 1.000 mg/dia, EV, por 3-5 dias."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-181091","number":"181091","sourceNumber":"181091","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Considerando os auto-anticorpos e marcadores reumáticos, o painel que mais\ncaracteriza a Doença Mista do Tecido Conjuntivo é:","options":{"A":"Fatore reumatoide positivo, anti-SSA (RO) presente, anti-SSB (LA) presente;","B":"FAN positivo, Fator Reumatoide presente, anti-RNP presente;","C":"FAN positivo, anti-SM presente, anti-RNP presente;","D":"FAN positivo, anti-SCL presente, anti-RNA polimerase I, II e III."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-158143","number":"158143","sourceNumber":"158143","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Paciente, sexo feminino, 21 anos, com quadro clínico e laboratorial de nefrite lúpica foi\nsubmetida à biópsia renal. Apresentou elevação da creatinina sérica 2,7mg/dL (sem outra causa)\nassociada à proteinúria > 0,5g/24h, hipertensão arterial sistêmica recente (PA = 150 x 100 mmHg),\nsedimento urinário ativo, hipocomplementemia e presença de anticorpo antidsDNA. A respeito da\nclasse histológica, com base nos critérios clínicos e laboratoriais, segundo a classificação da\nnefrite\nlúpica da International Society of Nephrology/Renal Pathology Society 2003, marque a alternativa\nCORRETA:","options":{"A":"Esclerose avançada - Classe I.","B":"Nefrite Lúpica Mesangial Mípima - Classe V.","C":"Nefrite Lúpica Mesangial Proliferativa - Classe I.","D":"Glomerulonefrite Difusa - Classe IV."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-247125","number":"247125","sourceNumber":"247125","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Mãe traz sua filha de 12 anos de idade ao ambulatório de reumatologia devido à queixa\nde, há 4 meses, apresentar episódios\nsúbitos de palidez e coloração azulada nas pontas dos dedos\ndas mãos, acompanhados de dormência e formigamento. Após algum tempo, percebeu edema nas\nmãos, simétrico e indolor, evoluindo com dor nas articulações dos dedos e espessamento da pele.\nNotou o aparecimento de uma mancha oval com halo avermelhado e centro esbranquiçado,\naparentemente linear, da mão para o membro superior. Há 3 semanas, começou com tosse seca e\ndispneia aos esforços, procurou atendimento médico, sendo solicitado Fator Antinuclear (FAN) com\nresultado positivo e raios X de tórax com fibrose intersticial pulmonar, predominante em bases\npulmonares, sendo encaminhada para tratamento. Ante às possíveis hipóteses diagnósticas, qual é\na principal suspeita?","options":{"A":"Esclerose sistêmica juvenil.","B":"Artrite idiopática juvenil.","C":"Lúpus eritematoso sistêmico juvenil.","D":"Síndrome de Sjögren.","E":"Poliarterite nodosa da criança."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-214047","number":"214047","sourceNumber":"214047","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Doenças reumatológicas geralmente envolvem o sistema cardiovascular e podem\nresultar em complicações pericárdicas, miocárdicas, valvulares ou arteriais. Sendo assim, é\nVERDADEIRO afirmar que:","options":{"A":"Na arterite de células gigantes a inflamação geralmente envolve aorta distal na saída das\nartérias renais sendo raros presença e envolvimento em aorta proximal e cúspides da válvula\naórtica.","B":"Espessamento não infeccioso da válvula, geralmente na face arterial da válvula mitral e no lado\narterial da válvula aórtica, é conhecido como endocardite de Libman-Sacks, encontrada em\npacientes com doença de Behçet.","C":"As manifestações clínicas das lesões da Libman-Sacks, como endocardite infecciosa ou embolia\nperiférica, são raras.","D":"A esclerodermia tipicamente resulta em inflamação da aorta torácica e seus ramos, levando à\ndilatação aneurismática das artérias subclávia e carótida.","E":"Hipertensão pulmonar pode se desenvolver em muitos distúrbios reumatológicos, sendo\nparticularmente muito incomum na esclerodermia, devendo-se buscar outros diagnósticos mais\nprováveis."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-183449","number":"183449","sourceNumber":"183449","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Considerando este caso, qual a principal hipótese diagnóstica? Criança de 4 anos de\nidade apresentando equimoses e petéquias em membros inferiores, nádegas e tronco há cerca de\n3 dias, em bom estado geral e com dor em tornozelos bilateralmente. Nega tanto história de\nsangramento previamente quanto história familiar para sangramento. Realizado hemograma,\nobservou-se: Hb 11.3 g/dl; leucócitos: 12.000/mm³ (segmentados 40%; eosinófilos 3%; linfócitos\n50%; monócitos 7%) e plaquetas: 400.000/mm³.","options":{"A":"Trombocitopenia primária imune.","B":"Meningococcemia.","C":"Doença de Kawasaki.","D":"Púrpura de Henoch-Schönlein.","E":"Leucemia."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-151592","number":"151592","sourceNumber":"151592","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Em relação aos autoanticorpos no Lúpus Eritematoso Sistêmico (LES), correlacione as\nduas colunas e assinale a alternativa com a\nsequência CORRETA: (1) Anti-Ro; (2) Anti-histona; (3)\nAnti-DNA; (4) Anti-Sm; (5) Anti-La. ( ) Diagnóstico; ( ) LES neonatal; ( ) LES induzido por drogas;\n( )\nSíndrome de Sjögren; ( ) Acometimento renal do LES.","options":{"A":"1, 5, 3, 2, 4.","B":"4, 1, 2, 5, 3.","C":"1, 2, 4, 3, 5.","D":"4, 1, 5, 2, 3."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-151043","number":"151043","sourceNumber":"151043","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Paciente 38 anos, feminina, internada para investigação e tratamento Trombose\nVenosa Profunda (TVP) em MID. Refere tratamento\npara hanseníase há dois anos, G:II P:I A:I,\nabortamento este espontâneo no primeiro trimestre de gestação com presença de pré-eclâmpsia\nnas duas gestações. Nega uso de anticoncepcional oral, pratica atividade física regular, mantendo\nalimentação balanceada e IMC adequado. A paciente nega cirurgia recente ou demais\ncomorbidades. Com base nos dados apresentados, a investigação de trombofilias, em especial a\nsíndrome do anticorpo antifosfolípide (SAF), é mandatória. Em relação a esse assunto, marque a\nassertiva ERRADA:","options":{"A":"A síndrome do anticorpo antifosfolípede (SAF) deve ser considerada provável devido história de\ntromboembolismo venoso e morbidade gestacional.","B":"Para diagnóstico de SAF é necessário a presença de pelo menos um critério laboratorial:\nanticorpo anticardiolipina IgG ou IgM,\nanticoagulante lúpico e/ou anticorpo anti-beta2 glicoproteína I\nIgG ou IgM, presente em duas ou mais ocasiões, com intervalo mínimo de 12 semanas.","C":"A presença de história de Hanseníase não pode ser considerada como fator de risco para a\npresença de anticorpos antifosfolípides.","D":"Na fisiopatologia da SAF um evento primordial é a ativação do endotélio vascular\nimunomediada, com criação de ambiente\nendotelial propício para oclusões trombóticas vasculares."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-155632","number":"155632","sourceNumber":"155632","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"A doença de Kawasaki é uma vasculite aguda de etiologia desconhecida. Febre por\nmais de cinco dias e quatro outros fatores listados abaixo fecham diagnóstico. Qual é a única\nalternativa que não faz parte dos critérios diagnósticos?","options":{"A":"Conjuntivite não purulenta.","B":"Língua framboesiforme, eritema e edema de orofagite, fissuras labiais.","C":"Linfonodomegalia cervical.","D":"Trombocitopenia.","E":"Eritema e edema de mãos e pés com descamação periungueal."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-107611","number":"107611","sourceNumber":"107611","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Paciente masculino, 68 anos, sem comorbidades significativas, apresenta achado de\nexame físico de esplenomegalia (6 cm abaixo do\nRCE). Seu hemograma mostra: Hb 14 g%,\nLeucócitos 78.000/mm³ (Blastos 2%, promielócitos 3%, mielócitos 7%, meta 8%, bastões 10%,\n\nsegmentados 45%, eosino 3%, baso 5%, linfo 15%, mono 2%),Plaquetas:850.000/mm³. Qual a\nconduta adequada ao caso?","options":{"A":"Solicitar recoleta, pois o quadro clínico não é compatível com o exame.","B":"Encaminhar o paciente ao Pronto-Socorro, pois se trata de reação leucemoide.","C":"Solicitar pesquisa do gene de fusão BCR abl por PCR em sangue periférico.","D":"Solicitar Cariótipo com Banda G de sangue periférico.","E":"Indicar tratamento imediato com mesilato de imatinibe."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-107693","number":"107693","sourceNumber":"107693","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Paciente masculino, 76 anos, procura Serviço de Pronto Atendimento com história de\nfraqueza progressiva há 15 dias. Há 7 dias, observou equimoses esparsas não relacionadas a\ntraumas. Há 2 dias, iniciou com febre e queda do estado geral. Antecedente de DM e HAS há 5\nanos, usando Metformina e Losartan. O exame físico mostra palidez +++/4+, Tax = 38,4 C, PA =\n90/60 mmHg, FC 120 bpm, ausência de linfonodomegalias, abdome flácido com baço palpável 3\ncm RCE, equimoses grandes esparsas pelo corpo. O Hemograma inicial mostra: Hb 7 g% VCM 90,\nLeucócitos 1.700/mm³ (30% neutrófilos, linfócitos 65% e Monócitos 5%), Plaquetas 20.000/mm³.\n\nQual a conduta?","options":{"A":"Triagem de foco infeccioso, iniciar antibioticoterapia empírica e indicar punção aspirativa de\nmedula óssea.","B":"Triagem de foco infeccioso, iniciar antibioticoterapia empírica e solicitar sorologias para\nhepatites\ncrônicas e leishmaniose.","C":"Triagem de foco infeccioso e indicar antibioticoterapia empírica, aguardar o antibiograma e\nobservar evolução.","D":"Iniciar antibioticoterapia empírica imediata e indicar transfusão de concentrado de hemácias e\nplaquetas.","E":"Transfusão de concentrado de hemácias e plaquetas e indicar biópsia de medula óssea."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-111798","number":"111798","sourceNumber":"111798","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Masculino, 40 anos, natural e procedente de Rio Verde de Mato Grosso (MS), casado,\nzelador, refere que há 2 meses apresenta\nfebre, hiporexia, astenia, perda ponderal (8kg nesse\nperíodo). Ao exame físico: regular estado geral e nutricional, hipocorado, febril (temperadura\naxilar\nde 38°C), anictérico, fígado palpável a 3,0 cm do rebordo costal direito e baço palpável a 6,0 cm do\nrebordo esquerdo. Exames: hemoglobina de 7,6 g/dL, leucócitos 1230/mm³, plaquetas 90.000/mm³,\nAST 90 U/L, ALT 99 U/L, RNI 1,8 albumina 2,5 g/dL, globulina 3,7 g/dL e creatinina 0,8 mg/dL. Em\nesfregaço delgado de aspirado de medula óssea após coloração de Giemsa foram observadas\nformas amastigotas. Qual o diagnóstico desse paciente?","options":{"A":"Histoplasmose disseminada.","B":"Chagas agudo.","C":"Febre tifóide.","D":"Malária.","E":"Leishmaniose visceral."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-107595","number":"107595","sourceNumber":"107595","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Paciente, 19 anos, com quadro de poliartralgia e polimialgia há 2 anos, refere sono não\nrestaurador associado ao quadro clínico. Nega sinais de artrite. Nega febre. Ao exame físico, não\napresenta sinais de artrite e o exame físico sistêmico está inalterado. Com base nessas\ninformações, escolha a alternativa CORRETA:","options":{"A":"O diagnóstico é fibromialgia, não é necessário realização de exames complementares e deve-se\niniciar o tratamento com antidepressivos, sendo a sertralina a primeira escolha.","B":"A principal hipótese diagnóstica é fibromialgia e deve-se solicitar hemograma, TSH, provas de\natividade inflamatória para avaliação inicial do caso e exclusão de diagnósticos diferenciais.","C":"O exame de FAN é fundamental para análise diagnóstica e sua positividade confirma o\ndiagnóstico de LES.","D":"O encontro de resultado de TSH alterado não tem relação causal com o quadro clínico.","E":"Deve-se solicitar avaliação da ortopedia, visto a queixa de dor articular."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-111730","number":"111730","sourceNumber":"111730","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Qual é um fator de bom prognóstico associado ao diagnóstico de leucemia linfoide\naguda na criança?","options":{"A":"Leucócitos em número maior que 50,000/mm³.","B":"Idade entre 1 e 10 anos.","C":"Doença em sistema nervoso central ao diagnóstico.","D":"Leucemia de linhagem T.","E":"Translocações cromossômicas na faixa 11q23."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-60178","number":"60178","sourceNumber":"60178","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Em diversos cenários clínicos da medicina interna, uma enfermidade reumática\nautoimune deve ser lembrada como diagnóstico\npossível para explicar os sinais e os sintomas dos\npacientes. Para qual situação descrita as informações adicionais de interrogatório complementar ou\nde laboratório não são suficientes para fortalecer a probabilidade de doença reumática autoimune?","options":{"A":"Paciente de 30 anos, há 6 meses com episódios de febre recorrente mensal de efervescência\nespontânea, emagrecimento, artralgias, placas\navermelhadas no corpo e diarreia. Informações:\nintensa prostração durante a febre, lesões de pele não fixas e piora com o aumento de\ntemperatura, bom estado geral, hiperferritinemia.","B":"Mulher gestante secundigesta, com aumento de níveis pressóricos no terceiro trimestre da\ngestação e edema de membros inferiores.\nInformação de proteinúria, elevação da VHS e anemia\n(Hb 10).","C":"Paciente com hepatite C apresentando pequenas lesões purpúricas em membros inferiores.\n\nInformação de hipergamaglobulinemia policlonal e fator reumatoide positivo.","D":"Paciente com dois abortamentos prévios de início de gestação. Histórico de livedo reticular\nracemoso e enxaqueca.","E":"Paciente masculino jovem, com episódio de acidente vascular cerebral. Informação: aftas orais\ndolorosas recorrentes."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-34513","number":"34513","sourceNumber":"34513","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Em relação à Neutropenia Febril, assinale a alternativa incorreta.","options":{"A":"Define-se febre como temperatura axilar superior a 38ºC e neutropenia como a contagem de\nneutrófilos absoluta de menos de 500/mm³ ou 1000/mm³ com tendência a queda, em duas\namostras separadas.","B":"Neutropenia Grave é aquela com contagem inferior a 200 cel/mm³.","C":"Uso de sondas no trato urinário e gastrointestinal são fatores complicadores na Neutropenia\nFebril.","D":"Mucosite com alteração da integridade da mucosa agrava o quadro.","E":"Pacientes submetidos a transplantes de medula não estão sujeitos à Neutropenia Febril mesmo\nusando quimioterápicos."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-330488","number":"330488","sourceNumber":"330488","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"A fibromialgia é um diagnóstico frequente na atenção primária. A dor\nmusculoesquelética difusa e crônica é a principal\nqueixa relacionada. Sobre esta condição é\nERRADO afirmar:","options":{"A":"Além da dor, pode-se citar fadiga, alteração do sono, rigidez matinal, parestesias, sensação\nsubjetiva de edema e distúrbios cognitivos como sintomas relacionados","B":"Amitriptilina e ciclobenzaprina reduzem a dor, embora não sejam capazes de melhorar a\ncapacidade funcional dos pacientes","C":"Está comumente associada a outras comorbidades, dentre elas depressão e ansiedade,\nsíndrome da fadiga crônica e síndrome do cólon irritável","D":"Os pacientes devem ser incentivados a realizarem exercícios físicos pelo menos duas vezes por\nsemana"},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-330496","number":"330496","sourceNumber":"330496","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Mulher de 18 anos apresenta edema acentuado dos membros inferiores. Desconhece\ncomorbidades e nega o uso de medicamentos. Ao exame físico, PA 150/94mmHg, FC 76bpm, FR\n16ipm, SpO2 95% (em ar ambiente). Há edema palpebral, na parede abdominal e nos membros\ninferiores. Palpam-se pequenos linfonodos indolores nas cadeias cervicais, axilares e inguinais. Os\nsons respiratórios estão reduzidos em ambas as bases dos hemitórax. Algumas articulações\ninterfalangeanas proximais apresentam-se com o volume aumentado, hiperemiadas e dolorosas à\npalpação. EXAMES DE LABORATÓRIO: Hg 12,2g/dL; LG 1890/mm³; NS 896/mm³; linfócitos\n320/mm³; Plaq 109.800/mm³; creat 2,8mg/dL; sódio 135mEq/L; potássio 4,8mEq/L; LDH 540U/L;\nácido úrico 9,3mg/dL; albumina sérica 2,3g/dL; C3 26; C4 3; FAN 1/320 padrão nuclear\nhomogêneo; exame de urina: proteína 3+; hemoglobina negativo; 8 leucócitos/campo; 3\nhemácias/campo. Assinale a alternativa que apresenta uma conduta INADEQUADA nesse caso:","options":{"A":"Prescrever enalapril","B":"Prescrever furosemida","C":"Prescrever glicocorticoide","D":"Solicitar biópsia renal"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-330497","number":"330497","sourceNumber":"330497","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Mulher de 18 anos apresenta edema acentuado dos membros inferiores. Desconhece\ncomorbidades e nega o uso de medicamentos. Ao exame físico, PA 150/94mmHg, FC 76bpm, FR\n16ipm, SpO2 95% (em ar ambiente). Há edema palpebral, na parede abdominal e nos membros\ninferiores. Palpam-se pequenos linfonodos indolores nas cadeias cervicais, axilares e inguinais. Os\nsons respiratórios estão reduzidos em ambas as bases dos hemitórax. Algumas articulações\ninterfalangeanas proximais apresentam-se com o volume aumentado, hiperemiadas e dolorosas à\npalpação. EXAMES DE LABORATÓRIO: Hg 12,2g/dL; LG 1890/mm³; NS 896/mm³; linfócitos\n320/mm³; Plaq 109.800/mm³; creat 2,8mg/dL; sódio 135mEq/L; potássio 4,8mEq/L; LDH 540U/L;\nácido úrico 9,3mg/dL; albumina sérica 2,3g/dL; C3 26; C4 3; FAN 1/320 padrão nuclear\nhomogêneo; exame de urina: proteína 3+; hemoglobina negativo; 8 leucócitos/campo; 3\nhemácias/campo. Assinale a alternativa que apresenta o diagnóstico MAIS PROVÁVEL nesse\ncaso:","options":{"A":"Glomeruloesclerose segmentar focal","B":"Linfoma","C":"Lupus eritematoso sistêmico","D":"Nefropatia por lesão mínima"},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-301216","number":"301216","sourceNumber":"301216","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Homem de 24 anos queixa-se de astenia, hiporexia e perda de 5 kg em três meses. Há\n15 dias, apresenta tosse oligoprodutiva com\nescarro hemoptoico e dispneia aos esforços.\n\nDesconhece doenças prévias. Ao exame físico: PA 150/94 mmHg, FC 86 bpm, FR 22 ipm, SpO2\n92% (em ar ambiente). Exames de laboratório:\nhemoglobina: 8,3 g/dl; leucócitos totais: 10.450/mm³;\nplaquetas: 210.000/mm³; proteína C-reativa: 45 mg/L; creatinina: 2,3 mg/dl; ureia: 26 mg/dl;\nalbumina sérica: 2,9 g/dl; FAN: positivo até título 1:80 com padrão nuclear pontilhado fino: ANCA:\nreagente com padrão perinuclear; exame de urina: proteína 3+, 34 hemácias/campo, 12\npiócitos/campo. Presença de cilindros hemáticos. Assinale a alternativa que apresenta um\ndiagnóstico diferencial INADEQUADO para este paciente.","options":{"A":"Lúpus eritematoso sistêmico.","B":"Poliangiite microscópica.","C":"Poliarterite nodosa.","D":"Síndrome de Goodpasture."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":["question_bank/media/medcurso/med-clinica-medica-med-clm-21/301216.png"],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-301217","number":"301217","sourceNumber":"301217","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Mulher de 47 anos queixa-se de dores no dorso, membros superiores e inferiores, baixa\nenergia e insônia há um ano. Nega febre, emagrecimento ou sudorese noturna. Descreve episódios\nparoxísticos de mudança de cor nas pontas dos dedos das mãos por alguns minutos, que se\ntornam pálidos e, em seguida, azulados, quando expostos ao frio. É portadora de transtorno\ndepressivo e faz uso de fluoxetina. O exame físico não apresenta anormalidades. Exames de\nlaboratório: Hb 13,4g/dL; Leucócitos totais: 7.840/mm³; Plaquetas 198.000/mm³; Proteína C reativa\n3mg/dL; TSH 1,4UI/mL; cálcio iônico 1,23mmol/L; anti-HIV Não Reagente; HBsAg Não Reagente,\nanti-HCV Não Reagente; FAN reagente até titulo 1:320 com padrão nuclear pontilhado fino denso.\nConsiderando a hipótese diagnóstica mais provável para essa paciente, assinale a alternativa que\napresenta uma opção terapêutica MAIS ADEQUADA.","options":{"A":"Amitriptilina","B":"Azatioprina","C":"Codeína","D":"Prednisona"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-174642","number":"174642","sourceNumber":"174642","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Em geral, NÃO se esperam resultados favoráveis com a administração de\nglicocorticoides em pacientes acometidos por:","options":{"A":"Arterite de células gigantes (arterite temporal).","B":"Dermatopolimiosite.","C":"Esclerodermia (esclerose sistêmica).","D":"Polimialgia reumática."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-139680","number":"139680","sourceNumber":"139680","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Em paciente com crioglobulinemia mista associada a hepatopatia crônica causada pelo\nvírus da hepatite C espera-se encontrar, EXCETO:","options":{"A":"Acometimento renal com predomínio de glomerulonefrite.","B":"Neuropatia periférica.","C":"Níveis séricos reduzidos de C3 e elevados de C4.","D":"Púrpura palpável."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-55309","number":"55309","sourceNumber":"55309","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Mulher de 67 anos de idade queixa-se de dor esternal, sensação de aumento do\nvolume abdominal e astenia. Já foi hospitalizada\numa vez para colecistectomia. Iniciou há 30 dias\nuso de captopril para hipertensão arterial. Ao exame físico nota-se aumento do baço (cerca de 12\ncm abaixo do rebordo costal esquerdo), sem hepatomegalia. Não se palpam linfonodos. Não são\nvistas petéquias ou hematomas. O hemograma demonstra contagem de leucócitos de\n95.000/microL, com 15% de neutrófilos bastonados, 28% de neutrófilos segmentados, 10% de\nmetamielócitos, 5% de mielócitos, 4% de blastos, 4% de eosinófilos e 8% de basófilos. A\nhemoglobina é de 15 g/dl e a contagem de plaquetas, de 750.000/microL. Qual é o diagnóstico\nMAIS PROVÁVEL?","options":{"A":"Leucemia mieloide aguda.","B":"Leucemia mieloide crônica.","C":"Leucemia linfoide crônica.","D":"Reação leucemoide ao captopril."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-52413","number":"52413","sourceNumber":"52413","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Paciente de 47 anos, masculino, portador de leucemia linfoide aguda, vem ao Pronto\nAtendimento com quadro de prostração e febre de 39,2°C. Realizou quimioterapia endovenosa há\nnove dias. Nega disúria, tosse ou expectoração e diarreia. Hemograma mostra contagem global de\nleucócitos de 300/microL. Um regime de tratamento empírico inicial para esse paciente deve incluir\nqual das opções abaixo?","options":{"A":"Azitromicina.","B":"Polimixina.","C":"Amicacina e claritromicina.","D":"Cefepima."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-31462","number":"31462","sourceNumber":"31462","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Criança de 8 anos de idade, com diagnóstico de leucemia linfoblástica aguda em\ntratamento de fase final de remissão.\nEncontra-se no domicílio há 12 dias, quando apresenta pico\nfebril de 39ºC. É examinado no serviço de urgência, cujo exame físico não apresenta evidência de\ninfecção além de febre (38,5ºC). Solicita hemograma que revela: Hb = 8,8 g%; Htc = 24%;\nleucócitos = 1.600; neutrófilos = 10%; linfócitos = 90%. A conduta CORRETA, neste caso, é:","options":{"A":"Internar e iniciar antibioticoterapia para cobertura de bactérias Gram-negativas.","B":"Internar para observação clínica.","C":"Internar para propedêutica de infecção e iniciar antibioticoterapia para cobrir bactérias\nGram-positivas e negativas.","D":"Orientar os pais acerca da benignidade do quadro e marcar retorno em 48 horas."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-372269","number":"372269","sourceNumber":"372269","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"A Síndrome de Sjögren é uma doença autoimune caracterizada principalmente por\nalterações glandulares levando a xerostomia, xeroftalmia, entre outros sintomas. Essa patologia\ntambém está relacionada ao aumento de 40 vezes o risco de uma neoplasia em relação às\npessoas que não a possuem. Qual é essa neoplasia relacionada à Síndrome de Sjögren?","options":{"A":"Leucemia Mieloide Aguda.","B":"Leucemia Linfoide Aguda.","C":"Linfoma de Hodgkin.","D":"Linfoma não Hodgkin.","E":"Leucemia Linfoide Crônica."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-355424","number":"355424","sourceNumber":"355424","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Paciente do sexo feminino, 22 anos, admitida num hospital público devido a dor\nabdominal, náuseas, dispneia e febre. Trata-se\nde uma paciente portadora de Lúpus Eritematoso\nSistêmico (LES) e Síndrome do Anticorpo Antifosfolípide (SAAF), em anticoagulação. Não\napresentava tosse. Ao exame físico, encontrava-se hipocorada e hipoxêmica, porém estável\nhemodinamicamente. Exames admissionais revelaram hemoglobina de 7.4g/dL, além de proteína C\nreativa e velocidade de hemossedimentação elevados. Realizada tomografia tóraco-abdominal que\nnão revelou alterações e o exame de urina apresentou resultado inocente. No segundo dia de\nadmissão, paciente intercorre com sonolência, piora da dispneia e hipoxemia, além de hipotensão.\nExames da urgência revelaram hemoglobina de 2.6g/dL, além de lactato desidrogenase elevado,\nhiperbilirrubinemia e RNI de 5. Valores de C3 e C4 encontram-se consumidos. Com relação ao\natendimento ofertado a esta paciente, assinale a alternativa correta.","options":{"A":"A pesquisa de Coombs direto será negativa.","B":"A pulsoterapia com metilpredinisolona está indicada.","C":"A transfusão de concentrado de hemácias está proscrita pela hemólise.","D":"A anticoagulação plena deve ser mantida neste contexto devido a presença de SAAF."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-359319","number":"359319","sourceNumber":"359319","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Paciente do sexo masculino, 47 anos, procura atendimento médico especializado, após\ninúmeras tentativas de tratamento de uma sinusite crônica, sem sucesso. Ao evoluir com destruição\nde septo nasal e tosse com hemoptoicos, sem histórico de tabagismo, o médico assistente pensou\nem uma síndrome vasculite e incluiu, em sua propedêutica, anticorpos anticitoplasma de\nneutrófilos, com resultado positivo. Assinale a alternativa que apresenta o diagnóstico MAIS\nprovável.","options":{"A":"Poliangeíte microscópica.","B":"Síndrome de Churg-Strauss.","C":"Granulomatose com poliangeíte.","D":"Púrpura de Henoch-Schoenlein."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-369757","number":"369757","sourceNumber":"369757","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Paciente de 31 anos, sexo feminino, apresenta úlceras em mucosa oral recorrentes, dor\narticular compatível com poliartrite e inflamação cutânea. Qual diagnóstico mais provável","options":{"A":"Artrite reumatóide","B":"Doença de sjogren","C":"Doença de Behçet","D":"Lupus eritematoso sistêmico"},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-372576","number":"372576","sourceNumber":"372576","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Criança de 2 anos com febre há 8 dias, sem melhora com antibioticoterapia de largo\nespectro que está usando há mais de 3 dias.\nApresenta língua em framboesa, lábios hiperemiados,\nressecados e com fissuras, linfadenomegalia cervical, congestão ocular bilateral, hiperemia palmar\ne plantar com edema endurado de mãos. Baseado no diagnostico que essa história clinica sugere e\npara se evitar a sua complicação mais temida o tratamento desta criança deverá ser feito com:","options":{"A":"aciclovir venoso.","B":"AAS e gamaglobulina.","C":"anfotericina B.","D":"penicilina cristalina."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-359265","number":"359265","sourceNumber":"359265","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"As Doenças Exantemáticas são de grande prevalência e importância na faixa etária\npediátrica. Dentre elas, encontramos a Doença de Kawasaki, uma vasculite primária, aguda e\nautolimitada, das mais comuns em crianças e que representa a principal causa de cardiopatia\nadquirida nessa faixa etária, sendo assim, seu diagnóstico e propedêutica adequada são de\nextrema importância para a não complicação das crianças afetadas. É CORRETO afirmar que os\ncritérios clínicos diagnósticos da doença de Kawasaki, além da febre persistente por pelo menos 5\ndias, devem conter pelo menos 4 dos seguintes:","options":{"A":"Alteração de lábios e cavidade oral, hiperemia conjuntival, alteração de extremidades, exantema\npolimorfo e linfadenopatia cervical ? 1,5cm.","B":"Alteração de lábios e cavidade oral com presença obrigatória de enantema em mucosa faríngea,\nhiperemia conjuntival, alteração de extremidades, exantema polimorfo e linfadenopatia cervical ?\n1,5cm.","C":"Alteração de lábios e cavidade oral, hiperemia conjuntival com ou sem exsudato, alteração de\nextremidades, exantema polimorfo e linfadenopatia cervical ? 1,5 cm.","D":"Alteração de lábios e cavidade oral, hiperemia conjuntival, alteração de extremidades, exantema\npolimorfo e linfadenopatia cervical ? 2cm."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-359263","number":"359263","sourceNumber":"359263","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"As Doenças Exantemáticas são de grande prevalência e importância na faixa etária\npediátrica. Dentre elas, encontramos a Doença de Kawasaki, uma vasculite primária, aguda e\nautolimitada, das mais comuns em crianças e que representa a principal causa de cardiopatia\nadquirida nessa faixa etária, sendo assim, seu diagnóstico e propedêutica adequada são de\nextrema importância para a não complicação das crianças afetadas. Em relação ao tratamento da\ndoença de Kawasaki, assinale a alternativa CORRETA.","options":{"A":"A imunoglobulina humana intravenosa deve ser administrada apenas nos primeiros 10 dias de\ndoença, independente da presença de febre ou elevação de VHS e PCR.","B":"O tratamento com AAS deve ser mantido em doses moderadas a altas até o quinto dia afebril.","C":"Não há evidência científica de associação de corticoterapia, independente da gravidade ou do\nrisco de aneurisma coronariano.","D":"O tratamento é feito com imunoglobulina humana intravenosa em dose única de 2g/Kg, até o 10º\ndia de febre."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-359262","number":"359262","sourceNumber":"359262","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"As Doenças Exantemáticas são de grande prevalência e importância na faixa etária\npediátrica. Dentre elas, encontramos a Doença\nde Kawasaki, uma vasculite primária, aguda e\nautolimitada, das mais comuns em crianças e que representa a principal causa de cardiopatia\nadquirida nessa faixa etária, sendo assim, seu diagnóstico e propedêutica adequada são de\nextrema importância para a não complicação das crianças afetadas. Em torno de aproximadamente\n70 a 80% dos pacientes com doença de Kawasaki preenchem os critérios clínicos diagnósticos\nestabelecidos pela American Heart Association e pela European League Against\nRheumatism/Pediatric Rheumatology European Society. Entretanto, o restante dos 20 a 30% dos\ncasos pode não apresentar o quadro típico, sendo denominados \"formas incompletas ou atípicas\".\nNesse caso, assinale a alternativa que CORRETAMENTE indica alguns dos exames laboratoriais\nque também auxiliam no diagnóstico.","options":{"A":"VHS>40mm/ 1ª hora e PCR > 3mg/dL; plaquetas < 150.000/mm3 (após 7 dias de doença);\nleucocitose > 15.000/mm3; hiponatremia e\ndimensões coronarianas por meio do Z-escore > 2,5 ao\necocardiograma.","B":"VHS>40mm/ 1ª hora e PCR > 3mg/dL; plaquetas > 450.000/mm3 (após 7 dias de doença); TGP\n\n> 50U/L; albumina < 3g/dL e hiponatremia.","C":"VHS >80mm/ 1ª hora e PCR > 30mg/dL; plaquetas > 450.000/mm3 (após 7 dias de doença) e\nhiponatremia.","D":"VHS>40mm/ 1ª hora e PCR > 3mg/dL; plaquetas > 450.000/mm3 (após 7 dias de doença);\nalbumina < 3g/dL; piúria estéril;\nhipernatremia; e dimensões coronarianas por meio do Z-escore >\n2,5 ao Ecocardiograma."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-330301","number":"330301","sourceNumber":"330301","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Mulher de 27 anos vai ao PS queixando-se de lombalgia direita muito intensa, náuseas\ne vômitos. É portadora de lupus eritematoso\nsistêmico e está em uso de prednisona 10mg ao dia e\nhidroxicloroquina 400mg ao dia. Nega internações recentes. Ao exame físico, PA: 100x60mmHg,\nFC:128bpm, FR: 26ipm, SpO? 94% (aa). Apresenta-se alerta e orientada. O exame cardiovascular\nrevela ritmo cardíaco taquicárdico; as extremidades estão aquecidas e apresentam o enchimento\ncapilar imediato. O exame respiratório revela taquipneia, sem esforço e ausculta normal. O exame\ndo abdome não revela anormalidades. A punho-percussão revela dor na região lombar direita.\n\nExames de laboratório: Hemoglobina: 8,3g/dL (VR 12-16d/dL); Leucócitos: 14.780/mm³\n(4.000-11.000/mm³); neutrófilos: 10.890/mm³ (1.500-7.000/mm³); plaquetas: 78.000/mm³\n(150.000-450.000mm³); creatinina: 2,2mg/dL; ureia: 54mg/dL; bilirrubina total: 3,4mg/dL\n\n(<1,2mg/dL); bilirrubina direta: 2,0mg/dL (<0,4mg/dL). Assinale a alternativa que apresenta uma\nconduta INCORRETA:","options":{"A":"Solicitar TC abdominal total na urgência.","B":"Prescrever hidrocortisona parenteral.","C":"Prescrever antibiótico parenteral de espectro adequado.","D":"Prescrever transfusão de concentrado de hemácias."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-346216","number":"346216","sourceNumber":"346216","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Manifestações cutâneas, serosites, alopécia, manifestações neurológicas e outras,\npodem ser sintomas do lúpus eritematoso sistêmico. Qual o anticorpo mais sensível e o mais\nespecífico dessa patologia, respectivamente?","options":{"A":"Anti-Ro e FAN.","B":"FAN e Anti-SM.","C":"Anti-CCP e FAN.","D":"FAN e Anti-CCP.","E":"FAN e Anti-Ro."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-330306","number":"330306","sourceNumber":"330306","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Mulher de 28 anos vai ao consultório para seguimento de lúpus eritematoso sistêmico.\nA manifestação ao diagnóstico foi nefropatia\nrenal classe 2, artrite, FAN 1/320 padrão nuclear\nhomogêneo e anti-DNA 1/80 (reduziu para 1/10 após o tratamento inicial). A ultima consulta ocorreu\n1 ano atrás. Está assintomática. Faz uso regular de hidroxicloroquina 400mg/dia e prednisona 5mg\nMID. O exame físico não apresenta anormalidades. Assinale a alternativa que apresenta um exame\npropedêutico que NÃO está indicado na avaliação periódica dessa paciente.","options":{"A":"Anti-DNA.","B":"Fator Antinúcleo (FAN).","C":"Campimetria visual automática.","D":"Relação albumina-creatinina na urina."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-330314","number":"330314","sourceNumber":"330314","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Criança de 2 anos, sexo masculino, previamente hígido, é levado a uma consulta\nhospitalar com um pediatra por apresentar há 7\ndias quadro de febre (38?39°C) remitente,\nsurgimento de um caroço em região cervical, unilateral. Lesão de pele tipo rash maculopapular\ndifuso. Familiares ainda notaram dedos das mãos e pés com edema e dolorosos. Exame físico\nrealizado mostrou criança regular estado geral, irritado ao manuseio, exantema maculopapular\ndifuso, mais intenso em região do tronco e extremidades, linfadenopatia cervical direita de 3 cm,\nnão supurativo, hiperemia ocular bilateral e presença de hiperemia importante de orofaringe à\noroscopia, lábios com hiperemia e fissura, além de edemas de mãos e pés. Hemograma realizado\npela família mostrou leucocitose com neutrofilia. Considerando o caso apresentado, a MELHOR\nconduta para esse paciente é de:","options":{"A":"Iniciar imunoglobulina endovenosa + Ácido Acetilsalicílico (AAS).","B":"Iniciar prednisona + anti-histamínico oral.","C":"Iniciar cefazolina por 7 dias.","D":"Iniciar oxacilina + amicacina."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-260541","number":"260541","sourceNumber":"260541","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Paciente de 25 anos, proveniente de serrania, deu entrada em nosso serviço com\nquadro de febre há 3 meses, além do\nsurgimento de púrpura palpável nos membros inferiores e\ndescarga nasal sanguinolenta. O RX de tórax demonstrou nódulos pulmonares com cavitação\ncentral. Qual exame sorológico elucidará o diagnostico?","options":{"A":"C-anca.","B":"B-Panca.","C":"FAN.","D":"Crioglobulinas."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-259394","number":"259394","sourceNumber":"259394","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Homem de 58 anos, motorista, comparece ao pronto atendimento com relato de início\nhá cerca de 48 horas, de dispneia\nincapacitante com hemoptoicos de moderado volume. Informa\nhipertensão arterial prévia, porém de controle irregular. Tabagista ativo (50 anos/maço). Refere\nantecedente de rinossinusopatia crônica e frequentes episódios de artrite em joelhos bilaterais, com\nuso de anti-inflamatórios regularmente. Desconhece antecedentes laboratoriais. Refere associado\nao quadro manchas violáceas em membros inferiores. Ao exame: hipocorado (++/4+), hidratado,\njugulares planas a 45o, sem adenopatias ou baqueteamento digital, manchas violáceas em\nmembros inferiores. Sons respiratórios com crepitações meso-teleinspiratórias bilaterais,\nsaturimetria de 88% em ar ambiente. RCR, 2T, Frequência cardíaca: 115bpm, Pressão arterial:\n160/80mmhg. Exames laboratoriais: creatinina: 4,5 mg/dL, uréia 120mg/dL, Sódio: 140meq/L,\nPotassio: 5,5meq/L, cloretos: 110meq/L, Leucograma: 10.500 cels /mm3 (85% neutrófilos, 10%\nlinfócitos) plaquetas: 100.000 mm3 Hb:9,0g/dL Ht:28% HCO3 (venoso): 19meq/L Nt proBNP: 400\npg/ml (valor de referência: até 400 pg/ml) Urina rotina: proteínas ++++/4+ hemácias: 20 hemácias\npor campo presença de cilindros hemáticos. Leucócitos: campos repletos. Tomografia de tórax em\nalta resolução: áreas difusas de consolidação e vidro fosco bilaterais. Considerando a síndrome\nmais provável, assinale a alternativa que apresenta a melhor opção terapêutica inicial:","options":{"A":"Oxigenioterapia, início de Nitroglicerina endovenosa e diurético de alça.","B":"Oxigenioterapia, coleta de marcadores laboratoriais inflamatórios, uso de antiparasitários e\ninício\nde Metilprednisolona (1 g por 3 dias consecutivos).","C":"Oxigenioterapia, coleta de culturas (hemocultura e urocultura), protocolo de sepse para foco\nurinário.","D":"Oxigenioterapia, coleta de culturas (hemocultura e urocultura), protocolo de sepse para foco\nurinário e início imediato de terapia renal substitutiva."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-260555","number":"260555","sourceNumber":"260555","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Criança de 2 anos com febre há 8 dias, sem melhora com antibioticoterapia de largo\nespectro que está usando há 5 dias. Apresenta língua em framboesa, lábios hiperemiados,\nressecados e com fissuras, linfadenomegalia cervical, congestão ocular bilateral, hiperemia palmar\ne plantar com edema indurado de mãos. O diagnóstico mais provável é:","options":{"A":"Escarlatina.","B":"Urticária.","C":"Doença de Kawasaki.","D":"Síndrome da Pele Escaldada."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-266587","number":"266587","sourceNumber":"266587","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Mulher de 25 anos se queixa de edema generalizado iniciado há 2 semanas, que\nevoluiu com piora progressiva. Relata\nhiporexia e astenia nesse período. Desconhece ser portadora\nde doenças atuais ou prévias e não fez uso de quaisquer medicamentos ou drogas. Ao exame\nfísico, PA: 160 x 92 mmHg, FC: 97 bpm, FR: 22 ipm, SpO2: 98% (em ar ambiente). As mucosas\nestão descoradas, ictéricas e hidratadas. Há edema na face, pálpebras e membros inferiores. O\nexame respiratório revela sons inaudíveis em ambas as bases do hemitórax. Exames de\nlaboratório: material sangue: Hb: 6,8 g/dl; Hct: 23,3%; VCM: 98 fl; HCM: 31 pg; CHCM: 32 g/dl;\nRDW: 18,3%; LG: 3.400/mm³; neutrófilos segmentados: 1.234/mm³; linfócitos: 659/mm³; Plq:\n201.000/mm³; PCR: 28 mg/dl; FAN reagente: 1:640 padrão nuclear homogêneo; anti-DNA\nreagente; anti-SSA reagente; anti-SSB reagente; anti-Sm reagente; anca reagente; C3: 34mg/dl\n(90?170 mg/dl); C4: 2 mg/dl (VR: 12?36 mg/dl); anticitomegalovírus IGM: 1,3 (VR reagente ? 1),\nIgG: 450 (VR reagente ? 5,9). Exame de urina: densidade: 1.020; ph: 6,0; nitrito negativo;\nproteínas\n\n++++; hemoglobina +++; 4 piócitos/campo, 145 hemácias/campo; presença de cilindros hemáticos.\nAssinale a alternativa que apresenta o\ndiagnóstico etiológico MAIS PROVÁVEL para essa paciente.","options":{"A":"Citomegalovirose sistêmica.","B":"Lúpus eritematoso sistêmico.","C":"Síndrome de Sjögren.","D":"Vasculite associada ao ANCA."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-266588","number":"266588","sourceNumber":"266588","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Mulher de 25 anos se queixa de edema generalizado iniciado há 2 semanas, que\nevoluiu com piora progressiva. Relata\nhiporexia e astenia nesse período. Desconhece ser portadora\nde doenças atuais ou prévias e não fez uso de quaisquer medicamentos ou drogas. Ao exame\nfísico, PA: 160 x 92 mmHg, FC: 97 bpm, FR: 22 ipm, SpO2: 98% (em ar ambiente). As mucosas\nestão descoradas, ictéricas e hidratadas. Há edema na face, pálpebras e membros inferiores. O\nexame respiratório revela sons inaudíveis em ambas as bases do hemitórax. Exames de\nlaboratório: material sangue: Hb: 6,8 g/dl; Hct: 23,3%; VCM: 98 fl; HCM: 31 pg; CHCM: 32 g/dl;\nRDW: 18,3%; LG: 3.400/mm³; neutrófilos segmentados: 1.234/mm³; linfócitos: 659/mm³; Plq:\n201.000/mm³; PCR: 28 mg/dl; FAN reagente: 1:640 padrão nuclear homogêneo; anti-DNA\nreagente; anti-SSA reagente; anti-SSB reagente; anti-Sm reagente; anca reagente; C3: 34mg/dl\n(90?170 mg/dl); C4: 2 mg/dl (VR: 12?36 mg/dl); anticitomegalovírus IGM: 1,3 (VR reagente ? 1),\nIgG: 450 (VR reagente ? 5,9). Exame de urina: densidade: 1.020; ph: 6,0; nitrito negativo;\nproteínas\n\n++++; hemoglobina +++; 4 piócitos/campo, 145 hemácias/campo; presença de cilindros hemáticos.\nAssinale a alternativa que apresenta os achados histológicos MAIS PROVÁVEIS de serem\nencontrados à biópsia renal nessa paciente.","options":{"A":"Glomeruloesclerose segmentar focal.","B":"Glomerulonefrite esclerosante avançada.","C":"Glomerulonefrite membranoproliferativa difusa.","D":"Nefropatia membranosa."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-259410","number":"259410","sourceNumber":"259410","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Quanto a Doença de Kawasaki, marque a alternativa CORRETA:","options":{"A":"Na fase aguda, os pacientes apresentam anemia, leucocitose com desvio para esquerda,\nelevação de títulos de reagentes de fase\naguda. A dosagem de plaquetas é normal na primeira\nsemana, evoluindo para trombocitopenia a partir da segunda semana da doença.","B":"A imunoglobulina deve ser usada na fase aguda da doença, preferencialmente nos primeiros 7 a\n10 dias de doença.","C":"Trata-se de vasculite primaria sistêmica que tem como achado patognomônico o aneurisma de\nartéria coronariana.","D":"A principal faixa etária de acometimento é dos 6 aos 9 anos, com risco aumentado em até 20\nvezes nos irmãos de crianças acometidas em\nrelação a população em geral."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-260560","number":"260560","sourceNumber":"260560","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Em relação a Púrpura de Henoch Schonlein, assinale a alternativa INCORRETA:","options":{"A":"As lesões cutâneas ( púrpuras ) geralmente são simétricas e ocorrem em áreas dependentes da\ngravidade (membros inferiores) ou em pontos de pressão (nádegas).","B":"O envolvimento musculoesquelético, incluindo artrite e artralgias, é comum. A artrite tende a ser\nautolimitada e oligoarticular, com predileção pelos membros inferiores.","C":"O acometimento gastrointestinal é comum e pode incluir dor abdominal, vômitos, diarreia, íleo\nparalítico e melena.","D":"A Plaquetopenia é de moderada a severa."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-266589","number":"266589","sourceNumber":"266589","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Mulher de 25 anos se queixa de edema generalizado iniciado há 2 semanas, que\nevoluiu com piora progressiva. Relata\nhiporexia e astenia nesse período. Desconhece ser portadora\nde doenças atuais ou prévias e não fez uso de quaisquer medicamentos ou drogas. Ao exame\nfísico, PA: 160x92mmHg, FC: 97bpm, FR: 22ipm, SpO2 98% (em ar ambiente). As mucosas estão\ndescoradas, ictéricas e hidratadas. Há edema na face, pálpebras e membros inferiores. O exame\nrespiratório revela sons inaudíveis em ambas as bases do hemitórax. Exames de laboratório:\nMaterial Sangue: Hb 6,8g/dL; Hct: 23,3%; VCM: 98fL; HCM: 31pg; CHCM: 32g/dL; RDW: 18,3%;\nLG: 3.400/mm³; Neutrófilos segmentados: 1.234/mm³; Linfócitos: 659/mm³; Plq.: 201.000/mm³;\nPCR: 28mg/dL; FAN reagente: 1:640 padrão nuclear homogêneo; anti-DNA reagente; anti-SSA\nreagente; anti-SSB reagente; anti-Sm reagente; anca reagente; C3 34mg/dL (90-170mg/dL); C4\n2mg/dL (VR: 12-36mg/dL); anti-Citomegalovírus IGM 1,3 (VR reagente >=1) IgG 450 (VR reagente\n\n>=5,9). Exame de urina: densidade 1.020; ph 6,0; nitrito negativo; proteínas ++++; hemoglobina\n\n+++; 4 piócitos/campo, 145 hemacias/campo; presença de cilindros hemáticos. Para investigação\nda anemia apresentada pela paciente, foram\nsolicitados os seguintes exames: LDL: 1.200UI/L (VR:\n120-246UI/L); BT: 4,2mg/dL; BD: 0,4mg/dL; Reticulócitos: 23,2%, Coombs direto positivo; Ferro\nsérico: 52mcg/dL (VR: 65-175mcg/dL); Ferritina 650ng/mL (VR: 10-291ng/mL); Capacidade total de\nligação do ferro: 198mcg/dL (250-425mcg/dL). Assinale a alternativa que apresenta a conduta\nimediata MAIS APROPRIADA para o tratamento da anemia:","options":{"A":"Prescrição de eritropoietina.","B":"Prescrição de glicocorticoide.","C":"Reposição de ferro pela via parenteral.","D":"Transfusão de concentrado de hemácias."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-260610","number":"260610","sourceNumber":"260610","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Os distúrbios motores do esôfago são um grupo de patologias distintas que possui\ncaracterísticas peculiares. O distúrbio motor do esôfago que caracteriza -se por associação de\nesfincter esofágico inferior hipotônico + contrações esofágicas fracas é chamado de :","options":{"A":"Acalasia.","B":"Motilidade esofagiana ineficaz.","C":"Lesão esofágica da esclerodermia.","D":"Espasmo esofagiano difuso."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-253905","number":"253905","sourceNumber":"253905","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Assinale a condição em que você espera encontrar numerosos cilindros hemáticos ao\nexame do sedimento urinário:","options":{"A":"Glomerulopatia proliferativa difusa lúpica","B":"Amiloidose","C":"Glomerulopatia membranosa primária","D":"Glomerulopatia com lesão mínima"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-238656","number":"238656","sourceNumber":"238656","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Em um plantão na enfermaria, um médico admite criança de 3 anos de idade para\ninvestigação de quadro febril. Mãe relata febre persistente, de início há nove dias. Refere que, no\ninício do quadro, os olhos ficaram vermelhos, sem eliminação de secreção, agora já em melhora.\nAo exame físico, observa-se ainda exantema micropapular difuso, eritema dos lábios com língua\nem framboesa, nódulo cervical à direita medindo cerca de 2 cm, sem sinais flogísticos e edema e\neritema das mãos, sem outras alterações, hemodinamicamente estável. Mãe negou comorbidades,\nalergias ou uso de medicações. Vacinação em dia. Diante do quadro apresentado, qual a conduta\nmais indicada?","options":{"A":"Solicitar sorologias para as doenças exantemáticas mais comuns e aguardar para diagnóstico\npreciso, antes de iniciar qualquer tratamento.","B":"Solicitar exames laboratoriais, como VHS, PCR, hemograma e ecocardiograma; contudo,\nresultados não devem atrasar o início do tratamento.","C":"Iniciar tratamento com imunoglobulina (2 g/kg, dose única) e AAS em altas doses (80-100\nmg/kg), que deve ser mantido por no mínimo um\nano após diagnóstico.","D":"Aguardar realização de ecocardiograma para posteriormente avaliar início do tratamento\nespecífico com imunoglobulina e AAS."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-201641","number":"201641","sourceNumber":"201641","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Uma mulher de 35 anos se queixa de dor nas articulações das mãos e joelhos, com\nrigidez matinal de 30 minutos, além de boca e\nolho secos. O exame físico revela edema e rubor nas\n2ª, 3ª e 4ª articulações interfalangeanas distais de ambas as mãos e no joelho direito. Há lesão\neritematosa e elevada nas bochechas, nariz, queixo e pescoço. Sem outras anormalidades. Os\nexames laboratoriais são: Hg = 10,2 g/dl; leucócitos = 2.780/mm³; neutrófilos = 1.110/mm³;\nlinfócitos\n\n= 450/mm³; plaquetas = 145.000/mm³; desidrogenase láctica = 100 U/L (VR < 248U/L); bilirrubinas\ntotais = 0,8 mg/dl; reticulócitos = 1,3%; FAN\n= 1/640; padrão nuclear = homogêneo; anti-DNA =\n1/320; anti-SSA = reagente; anti-SSB = não reagente; fator reumatoide = 18 U/L (VR < 8 U/L);\n\nanti-CCP = não reagente; Coombs direto reagente; anticoagulante lúpico reagente. Considerando\nesse caso e o diagnóstico dessa paciente, marque\na alternativa CORRETA:","options":{"A":"A presença do anticoagulante lúpico firma o diagnóstico da síndrome do anticorpo antifosfolípide\nnesse caso.","B":"O anti-DNA nativo pode ser marcador de atividade de doença em alguns pacientes.","C":"A presença do fator reumatoide indica artrite reumatoide em atividade.","D":"O anticorpo anti-SSA reagente estabelece o diagnóstico da Síndrome de Sjögren primária nesse\ncaso."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-210433","number":"210433","sourceNumber":"210433","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Paciente, sexo feminino, 28 anos, estudante de medicina com diagnóstico de Lúpus\nEritematoso Sistêmico (LES), forma cutâneo-articular, procura entender um pouco mais de sua\npatologia nas aulas de imunologia da sua faculdade. Nos exames complementares já realizados,\nverifica-se FAN positivo (1:160), padrão pontilhado fino, anti-Ro e anti-La positivos. Em relação\naos\naspectos imunológicos dessa patologia é CORRETO afirmar:","options":{"A":"Mecanismo de lesão do LES é a autoimunidade, assim podemos afirmar que existe uma maior\nprobabilidade de desenvolverem outras doenças de autoimunidades, órgãos específicos como:\ntireoidite de Hashimoto, miastenia gravis, vitiligo e anemia perniciosa.","B":"Diversas anormalidades no sistema imune são descritas no LES, como um aumento de\ninterleucinas IL-2 e TGF-beta, estimulando os linfócitos T CD4+ e CD8+.","C":"Um mecanismo imune fortemente associado ao LES é a deficiência dos componentes do\ncomplemento como C1q, C2 e C4, responsável por uma diminuição da apoptose das células e uma\nmaior formação de autoanticorpos.","D":"O principal defeito no sistema imune do paciente com LES é a imunidade celular, que estimula\nlinfócitos citotóxicos a não reconhecerem os antígenos do próprio organismo."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-203917","number":"203917","sourceNumber":"203917","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Menina de 11 anos é internada na enfermaria devido ao surgimento de rash malar,\nanemia e plaquetopenia. Segundo a mãe, ela\nestá sendo acompanhada no posto de saúde há 2\nmeses e está em uso de sulfato ferroso, mas como não viu melhora decidiu levá-la ao pronto\natendimento e acabou sendo internada para investigação. Ao exame, a criança está hipocorada,\nhidratada, acianótica, anictérica, abdômen com hepatomegalia de 4 cm do rebordo costal, ausência\nde linfadenomegalias, eritema descamativo na região malar bilateralmente. Os exames mostravam\numa hemoglobina de 8,0, número de plaquetas de 95.000/mm³ e leucopenia. Assinale a alternativa\nque apresenta o critério CORRETO que permitirá diagnosticar e classificar a provável patologia da\npaciente do caso descrito:","options":{"A":"Anticorpos antinucleares negativos.","B":"Resposta ao uso de corticoterapia.","C":"Serosite (pleurite e/ou pericardite).","D":"Proteína C reativa normal."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-178284","number":"178284","sourceNumber":"178284","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Mulher, 25 anos, apresenta rash malar, alopécia difusa, febre ocasional e dispneia. Ao\nexame encontrava-se hipocorada (+/4+) e\nedemaciada (+/4+). Exames: Hemoglobina 9.6g/dL;\nHematócrito 28.2%; VCM 90fl; 3400 leucócitos/mm3 (1500 linfócitos/mm3); 150 mil plaquetas/mm3.\nSumário de urina com proteinúria 2+ e hematúria 2+; função renal e transaminases normais; FAN +\n1/640; anti-DNA positivo; C3 e C4 reduzidos; PCR normal e VHS 45mm/h. Paciente evolui com\npiora da dispneia e apresenta alguns hemoptoicos. Radiografia de tórax apresenta infiltrado\npulmonar alveolar, principalmente em bases. Gasometria arterial apresenta hipóxia e lactato\nnormal. Após realizar intubação orotraqueal, qual é a melhor conduta frente a esse caso?","options":{"A":"Iniciar antibioticoterapia para cobertura de infecção respiratória, principal causa de\ninsuficiência\nrespiratória entre lúpicos.","B":"Iniciar prednisona 1mg/kg/dia e cobertura antimicrobiana de largo espectro pela gravidade do\ncaso.","C":"Realizar pulsoterapia com metilprednisolona, se houver melhora após 48 horas com\nantibioticoterapia de largo espectro.","D":"Realizar pulsoterapia com metilprednisolona concomitante com antibioticoterapia de largo\nespectro, pela gravidade do caso.","E":"Iniciar prednisona 1mg/kg/dia e pulsoterapia com ciclofosfamida. Não iniciar antibioticoterapia,\npois claramente não há infecção associada."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-184604","number":"184604","sourceNumber":"184604","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Mulher de 22 anos com quadro crônico de dores articulares e ulceras orais. Ela já\nrealizou biópsia renal e vários cursos de terapia imunossupressora. Urina: proteinúria 3+. Qual o\nlocal do rim mais provável por ser responsável pela proteinuria?","options":{"A":"Tubulo distal","B":"Glomerulo","C":"Intersticio","D":"Tubulo proximal"},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-181281","number":"181281","sourceNumber":"181281","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"O lúpus eritematoso sistêmico (LES) pode-se manifestar inicialmente com diferentes\nquadros clínicos e / ou laboratoriais, nos\nquais esse diagnóstico deve ser sempre lembrado. Em\nrelação ao diagnóstico de LES, é correto afirmar:","options":{"A":"A presença de apenas 3 dos 11 critérios apresenta baixa sensibilidade.","B":"O fator antinuclear (FAN) é um exame de alta sensibilidade, mas de baixa especificidade.","C":"Em pacientes com FAN positivo, a presença de anticorpos anti-Ro/SSA e anti-La/SSB constitui\num critério diagnóstico adicional.","D":"Mesmo que o número mínimo de critérios necessários para o diagnóstico seja alcançado, é\nnecessário investigar a presença de todos, pois o número de critérios influencia no esquema de\ntratamento."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-179097","number":"179097","sourceNumber":"179097","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Paciente, sexo feminino, 28 anos, estudante de medicina com diagnóstico de Lúpus\nEritematoso Sistêmico (LES), forma cutâneo articular, procura entender um pouco mais de sua\npatologia nas aulas de imunologia da sua faculdade. Nos exames complementares já realizados,\nverifica-se FAN positivo (1:160), padrão pontilhado fino, anti- Ro e anti-La positivos. Em relação\naos\naspectos imunológicos dessa patologia pode ser afirmado que:","options":{"A":"Mecanismo de lesão do LES é a autoimunidade, assim podemos afirmar que existe uma maior\nprobabilidade de desenvolverem outras doenças de autoimunidades órgãos específicos como:\ntireoidite de Hashimoto, miastenia gravis, vitiligo e anemia perniciosa.","B":"Diversas anormalidades no sistema imune são descritas no LES, como um aumento de\ninterleucinas IL-2 e TGF-beta, estimulando os linfócitos T CD4+ e CD8+.","C":"Um mecanismo imune fortemente associado ao LES é a deficiência dos componentes do\ncomplemento como C1q, C2 e C4, responsável por uma diminuição da apoptose das células e uma\nmaior formação de autoanticorpos.","D":"O principal defeito no sistema imune do paciente com LES é a imunidade celular, que estimula\nlinfócitos citotóxicos a não reconhecerem os antígenos do próprio organismo."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-153121","number":"153121","sourceNumber":"153121","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Mulher 25 anos, portadora de Lúpus Eritematoso Sistêmico diagnosticado há dois anos,\nevoluiu com episódio confirmado de Trombose Venosa Profunda em Membro Inferior Esquerdo\napós iniciar inadvertidamente anticoncepcional hormonal oral de alta dosagem. Três meses após\nconcluir o período de anticoagulação plena com warfarínicos, realizou coagulograma que\nevidenciou TTPa alargado, que não corrigiu após o teste da mistura. O anticorpo mais\nprovavelmente associado a este quadro é:","options":{"A":"Anti-fator VIII.","B":"Anti-ß2-glicoproteína-1.","C":"Anti-DNAds.","D":"Anti-Ro.","E":"Anti-U1RNP."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-158318","number":"158318","sourceNumber":"158318","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Paciente sexo feminino, 29 anos procura UPA em decorrência de úlceras em mucosa\noral com recorrência frequente. A anamnese\nidentificou quadro de dor articular múltipla compatível\ncom poliartrite e áreas de inflamação cutânea. Internado na UTI devido a meningite asséptica. Qual\ndiagnóstico provável?","options":{"A":"Doença de Behçet.","B":"Lupus eritematoso sistêmico.","C":"Artrite reumatoide.","D":"Fibromialgia."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-159466","number":"159466","sourceNumber":"159466","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Na Insuficiência Renal Aguda (IRA), muitas medidas são comuns às diversas etiologias,\ncomo: manejo da volemia, da acidose, dos\ndistúrbios eletrolíticos, da uremia, suspensão de drogas\nnefrotóxicas e diálise, quando necessário. Porém algumas condições exigem tratamentos\nespecíficos. Assinale a alternativa que apresenta CORRETAMENTE a condição e o tratamento a\nserem adotados para paciente com IRA:","options":{"A":"Crise renal da esclerodermia ? inibidor da enzima conversora da angiotensina.","B":"Rabdomiólise ? alopurinol.","C":"Síndrome hemolítica-urêmica ? antibióticos para E. coli e Shigella.","D":"IRA pós-contraste ? acetilcisteína."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-158230","number":"158230","sourceNumber":"158230","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"A pesquisa de autoanticorpos contra antígenos celulares (FAN-Hep-2), historicamente\ndenominado fator antinuclear (FAN), é importante teste no manejo de pacientes com doenças\nreumatológicas. Em relação ao uso clínico do FAN-Hep-2, assinale a alternativa INCORRETA:","options":{"A":"Os níveis séricos do FAN podem ser utilizados para acompanhar a atividade de doença.","B":"Apresenta alta sensibilidade nos casos de lúpus eritematoso sistêmico e esclerose sistêmica.","C":"Não é específico de doenças reumatológicas e pode resultar positivo em pacientes com quadros\ninfecciosos e neoplásicos diversos.","D":"O valor preditivo positivo do FAN depende da probabilidade pré-teste de que o paciente tenha\ndeterminada doença reumatológica."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-158170","number":"158170","sourceNumber":"158170","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Criança com 6 anos, sexo masculino, é internado com quadro de dor abdominal,\nperiumbilical e surgimento de lesões\npurpúricas palpáveis em membros inferiores e nádegas com\ncinco dias de evolução. Sua mãe relata que dez dias antes do início desse quadro a criança estava\ngripada. Exame solicitado mostrou: leucócitos de 15.600, 87% segmentados, 12% linfócitos, 1%\nmonócito plaquetas de 264.000, hemoglobina de 13 g/dl, ureia 24 e creatinina 0,4%. Considerando\no caso descrito, assinale a alternativa que apresenta o diagnóstico MAIS provável.","options":{"A":"Púrpura tromocitopênica auto imune.","B":"Leucemia linfocítica aguda.","C":"Dengue.","D":"Púrpura de Henoch-Schölein."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-158276","number":"158276","sourceNumber":"158276","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"São critérios para diagnóstico da doença de Kawasaki, exceto:","options":{"A":"Ausência de febre;","B":"Hiperemia conjuntival bilateral;","C":"Adenomegalia cervical aguda com diâmetro igual ou superior a 1, 5 cm;","D":"Alterações de lábios e cavidade oral."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-135600","number":"135600","sourceNumber":"135600","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Sobre a Leucemia Linfoide Aguda (LLA), marque V para as sentenças verdadeiras e F\npara as falsas: ( ) Na suspeita de doença reumatológica, é recomendado somente iniciar\ncorticosteroides após a coleta de mielograma; ( ) A dor óssea é muito frequente, geralmente ocorre\nem membros, principalmente superiores, e pode tornar-se muito intensa; ( ) A dor óssea pode\nocorrer em qualquer horário do dia e é de difícil controle com analgésicos habituais.","options":{"A":"V, V, V.","B":"V, F, V.","C":"F, V, F.","D":"F, F, V."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-103097","number":"103097","sourceNumber":"103097","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Criança de dois anos foi admitida com quadro de febre há 6 dias, alterações na mucosa\noral, língua em framboesa e edema de pés e\nmãos. Estava em uso de amoxicilina desde o segundo\ndia da doença e não apresentava melhora. Considerando o caso apresentado, assinale a\nalternativa CORRETA:","options":{"A":"Se apresentar uma conjuntivite purulenta, deve-se pensar seriamente na hipótese de doença de\nKawasaki.","B":"Esse edema pode fazer parte de uma Glomerulonefrite Difusa Aguda Pós-Estreptocócica\n(GNDAPE), pois apresenta a língua em framboesa,\ncaracterística da escarlatina.","C":"A manutenção da febre, apesar do uso de antibióticos, pode ser devida a uma resistência à\namoxicilina, e o edema de mãos e pés é típico de um edema angioneurótico, que fala a favor de\numa farmacodermia.","D":"A realização de um ecocardiograma faz-se necessária, mesmo que a criança não apresente\nalterações na ausculta."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-105969","number":"105969","sourceNumber":"105969","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Marque a alternativa incorreta:","options":{"A":"Tanto a Leucemia Linfoide Aguda (LLA) quanto à Leucemia Mieloide Aguda (LMA) podem estar\nassociadas a fatores ambientais ou genéticos.","B":"A leucemia aguda representa 25 a 30% dos casos de câncer em pediatria e a LLA responde por\n80 % dos casos de leucemia.","C":"Na LMA os fatores de risco considerados favoráveis são: idade menor que 1 ano e SÍNDROME\nde DOWN.","D":"A LLA tem seu pico de incidência entre 6 meses a 2 anos."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-105974","number":"105974","sourceNumber":"105974","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Com relação às plaquetas, um valor entre 150.000 e 450.000 / mm³ é considerado\nnormal em: I ? RNS SADIOS. II ? LACTENTES.\nIII- CRIANÇAS. IV- ADOLESCENTES. Estão\n\ncorretas apenas afirmativas:","options":{"A":"I E II","B":"E IV","C":"II E III","D":"I,II,III,IV"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-79289","number":"79289","sourceNumber":"79289","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Nas afirmativas abaixo, marque ?V? para as verdadeiras e ?F? para as falsas e, a\nseguir, marque a alternativa que contém a\nsequência de respostas CORRETA. ( ) Colite fulminante\n(forma grave de colite por clostridium) pode ser causa de megacólon tóxico e perfuração intestinal.\nSuspeita clínica quando dor abdominal difusa, diarreia, distensão abdominal, febre, hipovolemia,\nacidose lática e leucocitose. ( ) Hipertrigliceridemia é a 3ª causa mais prevalente de pancreatite\naguda, após álcool e cálculos biliares. O risco de pancreatite inicia-se quando a trigliceridemia\nsupera em torno de 500 mg/dl e torna-se muito aumentado se trigliceridemia maior que 1000 mg/dl.\nO foco do tratamento é reduzir para menos de 500 mg/dl. ( ) Diabetes mellitus malcontrolado,\nalcoolismo, obesidade, gestação, pancreatite prévia e histórico de dislipidemia sugerem diagnóstico\nde pancreatite secundária à hipertrigliceridemia. Clinicamente, a apresentação da pancreatite é\nsimilar às de outras causas. ( ) A mielodisplasia é risco para anemia, infecção e sangramento, bem\ncomo progressão para leucemia mieloide aguda, geralmente refrataria ao tratamento. A maioria dos\npacientes morrem por consequência da insuficiência da medula óssea e não pela transformação\nleucêmica. ( ) Abuso de álcool poderá comprometer a hematopoiese e gerar pancitopenia. A\nanemia, frequentemente macrocítica, correlaciona-se à desnutrição e deficiência de folato.\n\nTrombocitopenia e, principalmente, leucopenia, correlacionam-se mais com hiperesplenismo.","options":{"A":"V, F, F, V, V.","B":"F, F, F, F, F.","C":"V, V, V, V, V.","D":"V, V, V, F, F."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-79296","number":"79296","sourceNumber":"79296","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Marque a alternativa INCORRETA:","options":{"A":"Tomografia computadorizada não é requerida no primeiro dia para diagnóstico de pancreatite\naguda. É exame importante em período\nposterior, principalmente na pesquisa de necrose\npancreática.","B":"Fator estimulador de colônia de granulócitos tem bom efeito no tratamento de neutropenia,\ndemonstrando impacto na sobrevida na maioria das situações clínicas.","C":"Hipertireoidismo subclínico está associado a risco aumentado de fibrilação atrial.","D":"Hipotireoidismo subclínico pode ser assintomático ou oligossintomático e pode estar associado a\nmaior risco cardiovascular."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-80803","number":"80803","sourceNumber":"80803","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Maria Beatriz, 19 anos, tem pressões arteriais no braço direito de 152 x 104 mmHg e no\nbraço esquerdo de 93 x 58 mmHg. É obesa, especialmente no abdome. Tem percebido febre (2\npicos febris a cada semana de 38,6°C) e \"falta de energia\". O apetite diminuiu e emagreceu 7 kg\nnos últimos três meses. O pulso radial à esquerda é fino e a extremidade é fria. Assinale a\nalternativa INCORRETA:","options":{"A":"As causas secundárias de hipertensão arterial devem ser suspeitadas quando aparecem antes\ndos 20 anos de idade.","B":"A história clínica e o exame físico nos direcionam para uma doença que acomete as artérias\nsubclávias, configurando as diferenças dos valores de pressão arterial entre os braços.","C":"O diagnóstico mais provável é de arterite de Takayasu \"em atividade de doença\". A velocidade\nde hemossedimentação acelerada e arteriografia\nrevelando estenose da artéria subclávia esquerda\nconfirmam essa hipótese.","D":"O lúpus eritematoso sistêmico é um diagnóstico a ser considerado. A positividade do FAN e\nnegatividade do p-ANCA definem o diagnóstico.","E":"A displasia fibromuscular pode explicar os achados clínicos e é identificada angiograficamente\ncom aparência de \"rosário\"."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-87971","number":"87971","sourceNumber":"87971","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Uma mulher de 60 anos procura o Clínico Geral com relato de epistaxes de repetição e\ndor lombar. Ela vem observando epistaxes intermitentes há 6 semanas. A epistaxe é um problema\nrecente em sua vida. Ela vem tendo dor na região toracolombar nos últimos 3 meses, mas nega ter\nsofrido qualquer traumatismo antes de seu surgimento. A paciente também observou uma grande\nequimose e um hematoma na coxa esquerda, que apareceram após um traumatismo mínimo. A\npaciente sempre foi uma mulher saudável e ativa, e não tem internações anteriores. Entretanto, nos\núltimos 4 meses vem se sentindo progressivamente mais cansada e há 2 meses não consegue\nmais fazer suas atividades domésticas. Ultimamente, começou a ter problemas de constipação,\nanorexia, e admite uma perda de peso de 5 quilos nas últimas 3 a 5 semanas, tendo chegado a 50\nquilos de peso. O exame revela uma temperatura de 37°C, pulso 90, pressão arterial 130/70 mmHg\ne 18 incursões respiratórias por minuto. A paciente tem um aspecto de doente crônico, mas está\natenta e bem orientada. As conjuntivas, a mucosa oral e as palmas das mãos estão pálidas. Os\nexames laboratoriais iniciais foram: Hb: 9,0 g/dl, Htc: 27%; contagem de reticulócitos de 3%;\nleucometria de 3000 /mm3 com diferencial normal; contagem de plaquetas de 27.000/mm3. O\nesfregaço sanguíneo revelou hemácias de morfologia normal, porém com significativa formação de\nrouleaux. EAS: urina clara, amarela, com densidade de 1010, ausência de glicose ou proteína;\nausência de células ou bactérias no sedimento. A radiografia de tórax mostrou uma lesão lítica na\nclavícula esquerda, osteopenia difusa e fraturas compressivas em várias vértebras torácicas. As\nradiografias laterais da coluna revelaram fraturas compressivas de T-11 e T-12. Os resultados do\nlaboratório mostram: VHS: 120 mm/h; creatinina: 4,2 mg/dl; proteínas totais: 9,3 g/dl; albumina: 2,7\ng/dl, globulinas: 6,6 g/dl; cálcio: 11,2 mg/dl; LDH: 600 U/L; A análise quantitativa das\nimunoglobulinas demonstra: IgG: 5.300 mg/dl, IgA: 47 mg/dl, IgM: 23 mg/dl. A análise de urina de\n24 horas demonstra 1,4 g de proteínas identificadas como cadeias leves kapa de imunoglobulinas.\nMielograma e biópsia de medula óssea: observado o aumento acentuado de plasmócitos (37% de\nplasmócitos). Baseado na descrição do caso e nos exames laboratoriais qual o diagnóstico:","options":{"A":"Leucemia Mieloide Crônica.","B":"Mieloma Múltiplo.","C":"Linfoma.","D":"Policitemia Vera."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-89142","number":"89142","sourceNumber":"89142","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Paciente de 12 anos, sexo masculino, cor branca, com diagnóstico de LLA (Leucemia\nLinfoide Aguda). O hemograma revelou anemia, plaquetopenia e leucocitose (32.000 leuc/mm³).\nEm relação a esse quadro, qual dos fatores sugere pior prognóstico?","options":{"A":"Idade de 12 anos.","B":"Sexo masculino.","C":"Raça branca.","D":"Bicitopenia no hemograma."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-347400","number":"347400","sourceNumber":"347400","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Uma mulher com 52 anos comparece à consulta médica na unidade básica de saúde\ncom queixa de dores musculoesqueléticas\ncrônicas, mal localizadas, difusas, acima e abaixo da\ncintura. Refere que o quadro tem cerca de 4 meses de evolução, tendo surgido aparentemente\napós episódio de dengue (não grave). A paciente também refere fadiga e quadro depressivo há\nlonga data, além de transtorno da articulação temporomandibular e síndrome do intestino irritável.\nRelata apetite preservado. Seu exame físico é normal, salvo por dor à compressão e palpação\nmuscular difusa. Digno de nota é que a simples insuflação do esfigmomanômetro leva a dor\nsignificativa em ponto localizado cerca de 2 centímetros distais do epicôndilo lateral do membro\nsuperior avaliado. Além disso, há dor à compressão digital bilateral nos pontos de inserção dos\nmúsculos subocciptais, no ponto médio da borda superior de ambos os músculos trapézios, sobre a\nborda medial das escápulas, nos quadrantes superiores externos das nádegas, posteriormente às\neminências trocantéricas dos fêmures, sobre a 2ª articulação condroesternal direita e sobre as\npartes moles localizadas superior e medialmente a ambos os joelhos. Não há alterações no\nhemograma completo, nem na dosagem de proteína C reativa, T4 livre, TSH e velocidade de\nhemossedimentação. No caso apresentado, qual o diagnóstico dessa paciente?","options":{"A":"Fibromialgia","B":"Hipotireoidismo subclínico.","C":"Transtorno psicossomático.","D":"Transtorno depressivo maior."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-349173","number":"349173","sourceNumber":"349173","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Uma mulher de 19 anos vai a uma consulta devido a edema de membros inferiores. Ela\nrelata que teve gestação sem intercorrências, embora tenha feito apenas duas consultas de\n\npré-natal. Contudo, 1 mês após o parto, procurou atendimento médico devido à persistência e piora\nprogressiva do edema de membros inferiores, que, inicialmente, atribuiu à gravidez. Ao exame\nfísico, apresenta edema depressível de membros inferiores e pressão arterial de 130 x 80 mmHg.\n\nOs exames laboratoriais apresentam urina de rotina com proteína positiva (4+/4+); proteinúria de\n24h de 4g (valor de referência [VR]: < 150\nmg/24h); colesterol total de 300 mg/dL (VR: < 200\nmg/dL); colesterol HDL de 20 mg/dL (VR: > 35 mg/dL); triglicerídeos de 280 mg/dL (VR: < 150\nmg/dL); glicemia de jejum de 201 mg/dL (VR: < 100 mg/dL); albumina de 1,8 g/dL (VR: 3,5 a 5,2\ng/dL); pesquisa de autoanticorpos FAN positiva com padrão nuclear homogêneo e título de 1:640.\nO diagnóstico sindrômico e o diagnóstico etiológico mais prováveis são, respectivamente,","options":{"A":"síndrome nefrótica; diabetes mellitus.","B":"síndrome nefrítica; síndrome de Sjogren.","C":"síndrome nefrítica; trombose de veia renal.","D":"síndrome nefrótica; lúpus eritematoso sistêmico."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-349171","number":"349171","sourceNumber":"349171","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Um menino de 3 anos encontra-se em consulta em serviço de especialidades com\nhistória de ter apresentado quadro\nautolimitado de rinofaringite há 9 dias. Na ocasião, foi realizado\npainel viral por meio de RT-PCR para SARS-CoV-2, Vírus Sincicial Respiratório e Influenza A e B, o\nqual resultou negativo para todas as doenças. Há 1 dia, o paciente está apresentando petéquias e\nequimoses não pruriginosas em extremidades inferiores e em região glútea associadas à artralgia e\nà limitação de movimento em joelhos e tornozelos, além de dor abdominal peri-umbilical\nintermitente. Sua responsável refere, ainda, que hoje o menino teve um episódio de vômito\n\npós-prandial. Sua pressão arterial apresenta-se sem alterações. Exames complementares,\nhemograma completo, parasitológico de fezes,\ncoagulograma, ureia e creatinina normais.\nApresenta ASLO negativo e seu resultado de urina de rotina mostra hematúria +, proteinúria +, sem\npiúria. Diante do quadro desse paciente, qual é a hipótese diagnóstica mais provável?","options":{"A":"Glomerulonefrite pós-estreptocócica.","B":"Síndrome-hemolítico urêmica.","C":"Lúpus eritematoso sistêmico.","D":"Vasculite por IgA."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-347450","number":"347450","sourceNumber":"347450","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Uma paciente com 35 anos faz tratamento em um ambulatório de referência em\nreumatologia devido a esclerose sistêmica,\nforma difusa. Faz uso regular de medicações como\nprednisona e metotrexato. Há 3 meses, ela apresenta dor torácica em queimação, retroesternal,\nassociada à sensação de regurgitação, disfagia e episódios de tosse seca principalmente ao deitar.\nO diagnóstico e a conduta para esse caso são, respectivamente,","options":{"A":"pleurite; radiografia de tórax.","B":"angina instável; cateterismo coronariano.","C":"dismotilidade esofágica; manometria esofágica.","D":"doença intersticial pulmonar; tomografia computadorizada de tórax."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-318593","number":"318593","sourceNumber":"318593","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Uma mulher com 33 anos de idade procura o ambulatório de clínica médica devido a\ndores articulares há 3 meses. Refere o acometimento de mãos (interfalangianas proximais e\nmetacarpofalangianas), punhos e joelhos. Ao exame físico, apresenta sinais de artrite nessas\narticulações. Foram solicitados exames laboratoriais para a investigação diagnóstica e os\nresultados são apresentados a seguir. Diante desses achados clínicos e laboratoriais, quais são,\nrespectivamente, o autoanticorpo relacionado ao FAN apresentado e o diagnóstico pertinente ao\ncaso?","options":{"A":"Anti-DNA nativo; lúpus eritematoso sistêmico.","B":"Anti-CCP; artrite reumatoide.","C":"Anti-Scl-70; esclerose sistêmica.","D":"Anti-Ro; síndrome de Sjögren."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":["question_bank/media/medcurso/med-clinica-medica-med-clm-21/318593.png"],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-318595","number":"318595","sourceNumber":"318595","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Uma criança com 3 anos de idade, sexo masculino, iniciou, segundo relato de sua mãe,\nfebre há cerca de 5 dias. Durante o exame clínico, o pediatra observou conjuntivite bilateral,\nexantema polimorfo, língua em framboesa, lábios avermelhados, fissurados e secos, edema duro\ndos dedos de pés e mãos e adenopatia cervical, além de descamação das extremidades.\n\nConsiderando a descrição desse caso, a principal hipótese diagnóstica é:","options":{"A":"Escarlatina.","B":"Mononucleose.","C":"Eritema infeccioso.","D":"Doença de Kawasaki."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-319984","number":"319984","sourceNumber":"319984","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Mulher de 32 anos, professora de educação básica, procurou assistência médica, com\nqueixas de dores generalizadas pelo corpo e dificuldade para dormir. Não faz uso de nenhum\nmedicamento para doenças crônicas. Encontra-se de licença médica há 6 meses e ainda não\nobteve grande melhora. Refere que acorda exausta. Nega febre. Diz já ter sido muito ativa,\ntrabalhando em 4 escolas ao mesmo tempo, entretanto tem medo de retornar ao trabalho e voltar a\nter dores mais fortes. O exame físico mostrou-se normal, à exceção da dor à pressão em diversos\ngrupamentos musculares em todo o corpo, sem sinal de bloqueio articular ou de inflamação\narticular. Foram realizados alguns exames laboratoriais, que resultaram normais, incluídos TSH,\nVHS e proteína C reativa ultrassensível. Provavelmente, trata-se de","options":{"A":"polimiosite.","B":"fibromialgia.","C":"fadiga crônica.","D":"polimialgia reumática."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-352587","number":"352587","sourceNumber":"352587","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Criança de 7 anos de idade, previamente hígida, sexo masculino, é levada, ao pronto\natendimento com quadro de lesões violáceas em pés e pernas, associadas à febre baixa e artralgia\nem tornozelos, de aparecimento há 2 dias. Ao exame físico, presença de petéquias e lesões\npurpúricas elevadas de até 4 mm, que não desaparecem à digitopressão, em membros inferiores e\nnádegas, edema difuso em tornozelos, dor e edema testicular bilateral, sem outros achados\nanormais. Solicitados exames complementares: hemograma sem alterações, velocidade de\nhemossedimentação 110 mm/1a hora, PCR 9 (normal até 0,5), desidrogenase lática 250 (normal\n\naté 350), urina 1 com 30 hemácias/campo (normal até 5), proteínas 2+, leucócitos 4/campo, nitrito\nnegativo. Diante do quadro exposto, assinale a alternativa que contém a principal hipótese\ndiagnóstica:","options":{"A":"Vasculite por IgA.","B":"Sepsis.","C":"Lúpus eritematoso sistêmico juvenil.","D":"Púrpura Trombocitopênica imune."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-355180","number":"355180","sourceNumber":"355180","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Na infância, as manifestações clínicas iniciais mais frequentes da doença mista do\ntecido conectivo são","options":{"A":"disfagia e dor musculoesquelética.","B":"poliartrite e fenômeno de Raynaud.","C":"\"\"rash\"\" malar e fraqueza muscular.","D":"fenômeno de Raynaud e \"\"rash\"\" malar.","E":"dor musculoesquelética e fadiga."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-331183","number":"331183","sourceNumber":"331183","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Menina de 12 anos de idade é levada à consulta médica por sua mãe com queixa de\nqueda de cabelo, eritema malar, astenia e\nartralgia em joelhos. Realizou ecocardiograma com\nderrame pericárdico moderado. O pediatra levantou a hipótese diagnóstica de lúpus eritematoso\nsistêmico pediátrico (LESp) e solicitou exames complementares para confirmação. Em relação às\nalterações laboratoriais presentes do LESp, é correto afirmar que a(o)","options":{"A":"Fator Antinuclear (FAN) é altamente específico e pouco sensível.","B":"anti-Sm é inespecífico, porém está presente em todos os pacientes com LESp.","C":"anti-DNA está associado à atividade de doença, principalmente à nefrite lúpica.","D":"consumo de complemento é patognomônico de nefrite lúpica, estando associado a prognóstico\nda doença.","E":"alteração hematológica mais frequente no LESp é a leucocitose com linfopenia relativa, estando\nassociada à atividade de doença."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-302583","number":"302583","sourceNumber":"302583","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Em relação à síndrome de Kawasaki, é INCORRETO afirmar:","options":{"A":"Os processos patológicos que estão presentes na vasculopatia correspondem a arterite\nnecrotizante, vasculite subaguda/crônica e proliferação luminal de miofibroblastos.","B":"Eritema e edema em face correspondem a um dos 5 sinais clínicos para diagnóstico da\nsíndrome, segundo a American Heart Association.","C":"O ecocardiograma é um exame obrigatório.","D":"Sinais indiretos, como PCR e VHS elevada, podem ser considerados, para diagnóstico, em\ncasos inconclusivos.","E":"Infliximabe é uma terapia alternativa em caso de falta de resposta à imunoglobulina humana."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-276680","number":"276680","sourceNumber":"276680","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"O fenômeno Raynaud é uma resposta vascular exagerada à temperatura fria ou ao\nestresse emocional. O fenômeno se manifesta\nclinicamente por alterações de cor acentuadamente\ndemarcadas da pele dos dígitos. Todas as seguintes drogas podem precipitar ou exacerbar o\nfenômeno de Raynaud, EXCETO:","options":{"A":"Amlodipina.","B":"Ergotamina.","C":"Cisplatina.","D":"Bleomicina.","E":"Interferon."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-277732","number":"277732","sourceNumber":"277732","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Mulher de 30 anos procura atendimento devido a hipótese diagnóstica de lúpus\neritematoso sistêmico. Relata início de rash\nmalar, alopecia e artrite há 4 meses, além de\nleucopenia detectada no hemograma. A pesquisa de autoanticorpos foi positiva, com título 1:640 e\npadrão nuclear pontilhado grosso. O anticorpo que deve ser solicitado é o","options":{"A":"anti-Sm.","B":"anti-Ro.","C":"anti-P.","D":"anti-La.","E":"anti-Scl-70."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-277735","number":"277735","sourceNumber":"277735","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Paciente, 25 anos, sexo feminino, admitida com quadro de hemiplegia à direita e afasia,\nquadro iniciado há 6 horas. Possui antecedente mórbido pessoal de quatro abortamentos prévios.\n\nO diagnóstico e a melhor conduta, respectivamente, são","options":{"A":"acidente vascular encefálico devido a síndrome do anticorpo antifosfolípide; realização de\ntomografia de crânio sem contraste e dosagem de anticoagulante lúpico, anticardiolipina e\nantibeta-2-glicoproteína I, os anticorpos devem ser repetidos em 12 semanas.","B":"mielite transversa devido a síndrome do anticorpo antifosfolípide; realização de pulsoterapia com\ncorticoide.","C":"acidente vascular encefálico devido a síndrome do anticorpo antifosfolípide; realização de\ntomografia de crânio com contraste e dosagem de anticoagulante lúpico, anticardiolipina e\nantibeta-2-glicoproteína I somente na fase aguda do evento.","D":"paralisia de Todd; indicação de craniotomia descompressiva de urgência.","E":"mielite transversa devido a síndrome do anticorpo antifosfolípide; realização de plasmaférese de\nurgência."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-276694","number":"276694","sourceNumber":"276694","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Paciente de 23 anos com quadro de ulcerações bucais e genitais recorrentes, muito\ndolorosas e profundas, com base necrótica central amarelada. Após 10 dias com uso de\nsintomáticos as lesões desapareceram sem deixar cicatrizes. Assinale a Síndrome que\ncorresponde a este quadro clínico.","options":{"A":"Doença de Kawasaki","B":"Síndrome do arco aórtico","C":"Síndrome de superposição da poliangiite","D":"Síndrome de Behçet","E":"Síndrome de Reiter"},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-277785","number":"277785","sourceNumber":"277785","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Menino de 4 anos de idade apresenta febre alta e de difícil controle há 6 dias,\nassociada a exantema macular disseminado,\neritema conjuntival bilateral, enantema de mucosa\noral e edema de pés e mãos. Ao exame físico, regular estado geral, ausência de secreção ocular,\ncom gânglio cervical, de 2 cm de diâmetro do lado direito. Com base no caso descrito, assinale a\nalternativa que contém a primeira escolha de tratamento e uma complicação para a principal\nhipótese diagnóstica.","options":{"A":"Penicilina G benzatina/abscesso retrofaríngeo.","B":"Ganciclovir/hepatite.","C":"Imunoglobulina humana endovenosa/aneurisma de artéria coronária.","D":"Sintomáticos/hemorragia.","E":"Metilprednisolona endovenosa/endocardite."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-227625","number":"227625","sourceNumber":"227625","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Paciente do sexo feminino, 23 anos, procura atendimento médico com quadro de dor\niniciada há aproximadamente 2 semanas, sem histórico de trauma, localizada em quadril à direita e\njoelhos bilateralmente onde observam-se sinais flogísticos progressivamente piores. Os exames\niniciais mostraram anemia, trombocitopenia, PCR aumentado, além de radiografia do quadril\nmostrando sinais de osteonecrose da cabeça do fêmur direito. Após admissão hospitalar a paciente\nrealizou um painel laboratorial de autoanticorpos que mostrou os seguintes resultados: FAN\n(positivo); anti-dsDNA (positivo); anti-Sm (negativo); anti-Ro (negativo); anti-La (negativo);\nanticardiolipina (negativa); anticoagulante lúpico (negativo). Com base nas informações acima, o\ndiagnóstico CORRETO é:","options":{"A":"Síndrome antifosfolípide.","B":"Artrite reumatoide.","C":"Lúpus eritematoso sistêmico.","D":"Doença mista do tecido conjuntivo.","E":"Esclerose sistêmica."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-240469","number":"240469","sourceNumber":"240469","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Jovem de 25 anos, sexo feminino, em avaliação devido à astenia, apresentou a\npesquisa de autoanticorpos (FAN) positiva, com padrão nuclear pontilhado fino denso em título\n1:80. A conduta do médico assistente deve ser","options":{"A":"informar que a paciente tem lúpus eritematoso sistêmico.","B":"solicitar anti-DNA dupla hélice.","C":"solicitar anti-Sm.","D":"informar que o resultado não indica a presença de doença autoimune.","E":"solicitar avaliação de um reumatologista."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-230927","number":"230927","sourceNumber":"230927","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Menino de 2 anos de idade, apresenta febre alta e de difícil controle associada à\nirritabilidade há 6 dias. Ao exame físico, exantema máculo-papular disseminado, hiperemia\nconjuntival bilateral, hiperemia de orofaringe, hiperemia palmo-plantar. Assinale a alternativa que\ncontém a principal hipótese diagnóstica e seu tratamento de primeira escolha:","options":{"A":"Doença de Kawasaki/ imunoglobulina humana endovenosa.","B":"Mononucleose/ sintomáticos.","C":"Escarlatina/ penicilina G Benzatina.","D":"Zika/ sintomáticos."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-227696","number":"227696","sourceNumber":"227696","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Menino de 6 anos de idade, apresenta lesões purpúricas em membros inferiores,\nassociadas a febre moderada, artrite de\ntornozelos e dor abdominal. Nega sangramentos e mantem\nbom estado geral. Atendido em pronto socorro, onde realizou os seguintes exames: Hemograma\n(Hb 12mg/dL/ Ht 36%, Leucócitos 8.000 com 35% de segmentados, 25% de linfócitos, 2% de\neosinófilos, Plaquetas 350.000), VHS 55 mm na primeira hora, PCR negativo, Urina 1: presença de\n10 hemácias por campo, sem outras alterações. Em relação ao caso, assinale a alternativa que\ncontém o diagnóstico mais provável:","options":{"A":"Púrpura Trombocitopênica imune","B":"Meningococcemia","C":"Dengue","D":"Leucemia","E":"Púrpura de Henoch-Schönlein"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-215738","number":"215738","sourceNumber":"215738","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"São características clínicas e laboratoriais do Lupus eritematoso sistêmico:","options":{"A":"aspectos imunológicos ligados à disfunção de linfócitos T são exuberantes.","B":"pode estar associada à endocardite de Libman-Sacks abacteriana.","C":"lesões anátomo-patológicas do tipo \"casca de cebola\" podem estar presentes principalmente no\nfígado desses pacientes.","D":"o comprometimento articular é pouco frequente, esse é um dos aspectos que explica a rara\ndeformidade articular e o desaparecimento de sintomas de artrite após a instituição do tratamento.","E":"a mialgia é a manifestação clínica mais frequente e ocorre em cerca de 90% dos pacientes e\ncostuma acompanhar a evolução clínica do paciente."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-203742","number":"203742","sourceNumber":"203742","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Mulher de 24 anos apresenta história recorrente de aftas dolorosas orais e genitais,\nalém de lesões acneiformes em tronco e\nmembros superiores e artrite em punhos e tornozelos.\nOntem iniciou quadro de dor ocular à direita de forte intensidade, com turvação visual, eritema\nconjuntival e fotofobia. A medicação que deverá compor o esquema terapêutico da doença de base\né a:","options":{"A":"Tacrolimus.","B":"Ciclobenzaprina.","C":"Tofacitinib.","D":"Abatacepte.","E":"Colchicina."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-216128","number":"216128","sourceNumber":"216128","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"O Fenômeno de Raynaud pode ser observado em pacientes com Lúpus Eritematoso\nSistêmico (LES) e consiste em:","options":{"A":"ocorrência de nódulos imóveis, estéreis e habitualmente localizados no lado atrial da válvula\nmitral.","B":"ateroesclerose acelerada.","C":"glomerulonefrite sem hipercelularidade.","D":"tipo específico de pericardite inflamatória.","E":"episódios de vasoespasmo e oclusão das artérias digitais decorrente de exposição ao frio ou a\nestresse emocional."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-216138","number":"216138","sourceNumber":"216138","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"A Síndrome do Anticorpo Antifosfolipídeo (SAF) deve ser suspeitado em:","options":{"A":"paciente jovem com fenômeno de Raynaud.","B":"idosos com tromboflebites superficiais.","C":"homem jovem com eritema nodoso.","D":"presença de aticorpo de fotossensibilidade.","E":"perdas fetais recorrentes no segundo trimestre da gestação."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-216171","number":"216171","sourceNumber":"216171","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Entre os critérios diagnósticos do Lupus Eritematoso Sistêmico segundo o American\nCollege of Rheumatology revisados em 1997 estão:","options":{"A":"eritema malar, proteína C reativa > 100, glicosúria, Anti- DNA dupla hélice positivo.","B":"anemia, Convulsão, Eritema Malar e Úlcera Oral.","C":"fator reumatoide positivo, Tempo de Protrombina aumentado, Psicose, FAN positivo= 1: 80.","D":"anemia, hepatite auto-imune, eritema malar, valvopatia mitral.","E":"linfonodomegalia em cadeia inguinocrural, febre, anemia, dermatite."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-215916","number":"215916","sourceNumber":"215916","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Com relação ao Lupus Eritematoso Sistêmico, assinale a alternativa INCORRETA em\nrelação aos critérios disgnósticos imunológicos.","options":{"A":"FAN positivo.","B":"Hipocomplementemia.","C":"Anti- B2 glicoproteína positivo.","D":"Anti-SM positivo.","E":"Coombs direto positivo na presença de anemia hemolítica."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-175236","number":"175236","sourceNumber":"175236","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Paciente sexo feminino, 28 anos, procura atendimento médico relatando história de um\nano com aparecimento de lesões de pele\nassociadas a fraqueza e cansaço. Ao exame físico, foi\nobservado eritema malar, máculas de Gottron, esclerodactilia e diminuição da força muscular. De\nexames complementares, a paciente tem ecocardiograma demonstrando hipertensão pulmonar e\ntrouxe um exame de autoanticorpo anti-RNP positivo com titulação 1/3200. Com base nesse caso\nclínico, o diagnóstico e o padrão de FAN esperados são","options":{"A":"Esclerose sistêmica; padrão pontilhado fino.","B":"Doença mista do tecido conjuntivo; padrão homogêneo.","C":"Doença indiferenciada do tecido conjuntivo; padrão pontilhado grosseiro.","D":"Lúpus eritematoso sistêmico; padrão pontilhado fino.","E":"Doença mista do tecido conjuntivo; padrão pontilhado grosseiro."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-175230","number":"175230","sourceNumber":"175230","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"São anticorpos associados com o comprometimento renal e psiquiátrico em pacientes\ncom diagnóstico de lúpus eritematoso sistêmico\njuvenil","options":{"A":"Anti-DNA dupla hélice e Anti-P.","B":"Anti-RNP e Anti-La.","C":"Anti-Ro e Anti-DNA hélice simples.","D":"Anticardiolipina e Anticoagulante lúpico.","E":"Anti-RNP e Anti-Ro."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-181798","number":"181798","sourceNumber":"181798","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Menina de 08 anos de idade, há 7 dias iniciou quadro de febre alta, associada a\nadenomegalia cervical (gânglio móvel, doloroso, fibroelástico, de 2 cm de diâmetro). No quinto dia\nde febre, foi atendida em serviço de urgência, recebeu diagnóstico de adenite bacteriana, sendo\nprescrito amoxacilina com clavulanato. No dia seguinte, evoluiu com exantema macular\ndisseminado, língua em framboesa e hiperemia de orofaringe, eritema conjuntival bilateral.\n\nNovamente atendida na urgência, a amoxacilina foi trocada por claritromicina devido a hipótese\ndiagnóstica de farmacodermia, porém sem melhora da febre. Sobre o caso, assinale a alternativa\ncorreta.","options":{"A":"A evolução desfavorável da paciente fala a favor de doença viral, devendo ser solicitadas\nsorologias virais, suspenso antibiótico e prescrito apenas sintomáticos.","B":"A paciente tem quadro clínico compatível com escarlatina, devendo receber uma dose de\npenicilina G benzatina e ser reavaliada em 72\nhoras (período esperado para resposta terapêutica).","C":"Trata-se de mononucleose com reação exantemática desencadeada pela amoxacilina,\ndevendo-se suspender o antibiótico, fazer tratamento de suporte e sintomáticos.","D":"A paciente preenche critérios para doença de Kawasaki, devendo receber imunoglobulina\nhumana endovenosa na dose de 2 g/Kg e ácido\nacetilsalicílico inicialmente em dose\n\nanti-inflamatória.","E":"Devem ser solicitados exames de triagem para doenças infecciosas e fazer diagnóstico\ndiferencial com Lúpus Eritematoso Sistêmico\nJuvenil caso não se encontre a causa dos sintomas."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-156664","number":"156664","sourceNumber":"156664","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"A primeira manifestação do lúpus neuropsiquiátrico ocorre:","options":{"A":"Tardiamente, como resultado de aterosclerose acelerada.","B":"Tardiamente, como resultado de influência concomitante dos anticorpos antifosfolipídeos e\naterosclerose.","C":"Como complicação tardia de lesão visceral.","D":"Nos primeiros 5 anos após o início da doença.","E":"Associada à presença de anticorpos antinucleossomos."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-159858","number":"159858","sourceNumber":"159858","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Considerando o tratamento da Nefrite Lúpica e que este depende da lesão histológica e\ndo grau de comprometimento glomerular, é\ncorreto afirmar que:","options":{"A":"na lesão mínima, classe II, faz-se necessário o uso de glicocorticoides por tempo prolongado.","B":"A classe V, ou membranosa não há necessidade de imunossupressão considerando que a\nevolução é satisfatória.","C":"A classe III, membrano proliferativa focal e IV membrano proliferativo difusa não podem ser\naglobadas para fim de terapêutica.","D":"O esquema sugerido pela National Institute of Health (NIH) consiste na dministração\nendovenosa de ciclofosfamida na dose de 0,75g\npor m2 de superfície corporal na forma de pulsos\nmensais e trimestrais num total de 24 meses.","E":"na biópisia com critérios de cronicidade elevados e poucas manifestações agudas faz-se\nnecessários a pulsoterapia com metilprednisolona 1 grama por 3 dias."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-156735","number":"156735","sourceNumber":"156735","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"O médico de plantão na enfermaria pediátrica avaliou uma adolescente de 12 anos, que\nfoi internada há um (1) dia com história de febre intermitente há um mês, associada à perda de\npeso, queda de cabelo e evoluindo com dor e edema em joelhos há uma semana. Ao exame físico,\napresentava palidez cutâneo-mucosa, artrite dolorosa em joelhos e tornozelo D, febre elevada\n(39°C) e adenomegalias. Os exames complementares iniciais demonstraram: Hb: 8,3 g/dl;\nleucócitos: 16000/mm³ (neutrófilos: 13%, linfócitos: 79%); plaquetas: 90.000/mm³; VHS: 80 mm;\nradiografia de joelhos: normal. Os exames necessários para a complementação diagnóstica são:","options":{"A":"Cultura do líquido sinovial e hemocultura.","B":"ASO, proteína C reativa e fator reumatoide.","C":"Anticorpos antinucleares, anti-DNA de dupla hélice e anti-Sm.","D":"Urina EAS, urocultura e mielograma.","E":"EAS e VDRL."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-104717","number":"104717","sourceNumber":"104717","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Paciente do sexo feminino, 43 anos, branca, com antecedente de sinusite de repetição,\nvem apresentando tosse produtiva e dispneia leve há\ncerca de 2 semanas. Há cerca de 4 dias o\nescarro tornou-se hemoptoico. Exame físico: regular estado geral, consciente e orientada, dispneica\nleve em repouso, afebril. Pressão arterial = 140 x 60 mmHg. SatO2 = 92% em ar ambiente.\n\nFrequência cardíaca = 92 bpm em repouso. Temperatura = 37,5ºC. Ausculta pulmonar: roncos e\nsubcrepitantes em terço médio do pulmão esquerdo. Ausculta cardíaca: bulhas cardíacas\nnormofonéticas, ritmo cardíaco regular em 2 tempos, sem sopro. Abdome: sem alterações.\n\nMembros inferiores: sem edemas, panturrilhas livres. Exames complementares: eletrocardiograma\nsem alterações; radiografia de tórax abaixo;\nhemoglobina = 11,3 g/dl; hematócrito = 34%; VCM = 88\nfl; leucócitos = 11.300/mm³ com 65% de segmentados; plaquetas = 320.000/mm³; ureia = 45 mg/dl;\ncreatinina = 0,7 mg/dl; urina simples = pH 6,0; densidade 1.025; proteínas +1; hemácias 45 por\ncampo; leucócitos: 8 por campo; FAN = negativo; C3 = 98 mg/dl (normal: 86-184 mg/dl); C4 = 24\nmg/dl (normal: 20-58 mg/dl); p-ANCA = negativo; c-ANCA = positivo; anti-HIV 1 e 2 = negativo;\npesquisa de BAAR e cultura de lavado broncoalveolar = negativos. Considerando-se a principal\nhipótese diagnóstica para o quadro clínico acima, o tratamento mais adequado é:","options":{"A":"Itraconazol.","B":"Prednisona e ciclofosfamida.","C":"Sulfametoxazol + trimetoprima.","D":"Ceftriaxona e clindamicina.","E":"Rifampicina, isoniazida, pirazinamida e etambutol."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":["question_bank/media/medcurso/med-clinica-medica-med-clm-21/104717.png"],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-88057","number":"88057","sourceNumber":"88057","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Paciente com quadro de anorexia associada à dor lombar em ambas as coxas há\naproximadamente 3 meses, com piora gradativa e impossibilidade de deambular há 2 semanas.\nApresenta-se hipocorado 2+/4+; desidratado 1+/4+; PA: 110 x 70 mmHg; FC: 88 bpm; FR: 12 irpm;\ntemperatura axilar: 36,5ºC. Exames laboratoriais de sangue mostram Hb: 9,9 g%; HT: 29%;\nleucócitos: 4.500/mm³; TGO: 32 U/l; TGP: 25 U/l; FA: 1.500 U/l; GGT: 15 U/l; glicose: 220 mg/dl;\nalbumina: 2,5 g/dl; globulina: 5,0 g/dl; Na: 137 mEq/L; K: 4,5 mEq/L; cálcio: 10,5 mg/dl. Com base\nneste caso, é CORRETO afirmar que:","options":{"A":"Aspirado de medula óssea mostrando 5% de plasmócitos fecha o diagnóstico de mieloma\nmúltiplo.","B":"O cálcio sérico corrigido encontra-se normal.","C":"Na síndrome de hiperviscosidade associada a mieloma múltiplo, pode-se encontrar\nsangramento nasal, visão borrada e confusão mental.","D":"Síndrome da compressão medular por plasmocitoma extramedular não deve ser suspeitada\nneste paciente.","E":"Dosagem de beta-2-microglobulina elevada, acima de 5,5 mg/L, confere melhor prognóstico."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-352687","number":"352687","sourceNumber":"352687","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Um homem de 62 anos de idade procura assistência médica em função de lesões\ncutâneas eritematosas nos membros inferiores, que\nsurgiram há 5 dias. Há uma semana\ndesenvolveu bronquite aguda e fez tratamento com cefuroxima 500mg 2 x dia. Os sintomas\nrespiratórios melhoraram, mas houve desenvolvimento de exantema. Ele não apresenta febre,\ncalafrios, dores articulares, mialgia e nem hematúria. Ao exame físico são identificadas numerosa\nlesões eritematosas palpáveis, que não empalidecem à compressão, medido de 1 a 5mm de\ndiâmetro. Nesse caso, qual o provável diagnóstico?","options":{"A":"Capilarite.","B":"Trombocitopenia induzida por fármacos.","C":"Purpura de Henoch-Schönlein.","D":"Ectima gangrenoso.","E":"Vasculite leucocitoclástica."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-371043","number":"371043","sourceNumber":"371043","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Lúpus eritematoso sistêmico (LES) e uma doença multi-sistêmica, auto-imune e\ncrônica, caracterizada por processo inflamatório\nde vasos e tecido conectivo com períodos de\nremissão e exacerbação, associada à presença de anticorpo antinúcleo (FAN), especialmente\ncontra o DNA dupla hélice. Suas manifestações são variáveis e seu curso clínico é imprevisível.\nQuando não tratada seu curso é progressivo e muitas vezes, fatal. I- Assim como do lúpus induzido\npor droga, a etiopatogenia do lúpus eritematoso sistêmico é bem estabelecida. II- É evidente que o\nlúpus resulta da interação de vários fatores como ambientais (p.ex., infecções virais, luz\nultravioleta,\ndrogas), alterações imunológicas (p.ex., alteração da função do linfócito B), genéticas (p.ex.,\ndeficiência de complemento) e hormonais (estrogênios e prolactina). III- A luz do sol não é\ncausadora de exacerbações de atividade da doença. A luz ultravioleta B tem múltiplos efeitos\nimportantes na sua patogênese, incluindo indução de apoptose dos queratinócitos. IV- A doença\npode ocorrer em qualquer faixa etária, sendo mais freqüente entre 15 e 25 anos, é rara abaixo dos\n5 anos de idade e incomum antes da adolescência. V- O lúpus é o protótipo de doença auto-imune\nsistêmica de herança poligênica caracterizada por perda da tolerância imunológica a vários\n\nauto-antígenos e formação de imunocomplexos que se depositam nos tecidos com consequente\ninflamação em diferentes órgãos e sistemas.","options":{"A":"Somente I, II e IV estão corretas.","B":"Somente II e IV estão corretas.","C":"Somente I e III estão corretas.","D":"Somente II, IV e V estão corretas.","E":"Todas estão corretas."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-371923","number":"371923","sourceNumber":"371923","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Sobre o Lupus eritematoso sistêmico, não se pode afirmar:","options":{"A":"A mielopatia é rara e mostra-se branda; a iniciação de terapia imunossupressora com\nglicocorticoides em baixas doses constitui o padrão de tratamento.","B":"As crises convulsivas de qualquer tipo podem ser causadas pelo lúpus; o tratamento torna\nnecessárias, com bastante frequência, as\nterapias anticonvulsivas e imunossupressoras. A psicose\npode ser a manifestação dominante do LES; ela deverá ser diferenciada da psicose induzida por\nglicocorticoides. A última costuma ocorrer nas primeiras semanas de terapia com estes fármacos,\ncom posologias diárias de 40 mg de prednisona ou equivalente; a psicose regride ao longo de\nvários dias após a redução ou a suspensão dos glicocorticoides.","C":"A população feminina é a mais acometida pela doença, sendo a maioria dos diagnósticos\nocorrendo entre os 15 - 40 anos de idade.Sobre","D":"A prevalência dos ataques isquêmicos transitórios, acidentes vasculares encefálicos e infarto do\nmiocárdio torna-se maior nos pacientes com LES. Esses eventos vasculares encontram-se\naumentados, porém não exclusivamente, nos pacientes de LES com anticorpos contra fosfolipídeos\n(anticorpos antifosfolipídeos), que estão associados a eventos trombóticos agudos e de\nhipercoagulabilidade.","E":"A manifestação mais comum do lúpus difuso no SNC é a disfunção cognitiva, como dificuldades\nde memória e raciocínio. As cefaleias também são\ncomuns. Quando lancinantes, elas indicam com\nfrequência uma exacerbação do LES; quando mais leves, mostram-se difíceis de diferenciar da\nenxaqueca ou das cefaleias tensionais."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-345541","number":"345541","sourceNumber":"345541","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Paciente procurou médico que diz ter como especialidade \"PERFORMANCE E\nLONGEVIDADE\". Como de rotina, esse profissional solicitou inúmeros exames laboratoriais do\npaciente. Preocupado com os resultados, principalmente em relação a um exame positivo, o\npaciente resolveu procurar um médico reumatologista, registrado no conselho, com RQE. Em\nrelação ao resultado positivo, o Reumatologista explicou que o anti SSA-Ro está presente em cerca\nde 90%, nos casos de:","options":{"A":"Artrite reumatoide.","B":"Lúpus eritematoso sistêmico.","C":"Artrite reumatoide e LES.","D":"Síndrome de Sjogren e Artrite reumatoide.","E":"Síndrome de Sjogren."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-344866","number":"344866","sourceNumber":"344866","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Paciente, sexo feminino, 15 anos, portadora de Lúpus Eritematoso Sistêmico, em uso\ncontínuo de prednisona. Vai em consulta com reumatologista que a acompanhada, queixando-se\nde dor em quadril esquerdo há 02 semanas. Considerando a hipótese diagnóstica, qual o melhor\nexame de imagem a ser solicitado?","options":{"A":"Ultrassonografia","B":"Tomografia","C":"Cintilografia","D":"Radiografia simples","E":"Ressonância Magnética"},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-326485","number":"326485","sourceNumber":"326485","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Sabrina, 5 anos, previamente hígida, foi internada em um hospital terciário para a\ninvestigação de febre iniciada há 6 dias. Apresentava também rash maculopapular, principalmente\nem tronco, hiperemia e lacrimejamento ocular, edema nas mãos e pés e linfoadenomegalia cervical\nindolor à esquerda, com diâmetro aproximado de 2cm. Qual a complicação mais grave associada a\nesse quadro?","options":{"A":"Estenose de válvula mitral.","B":"Pericardite.","C":"Vasculite coronariana.","D":"Miocardiopatia hipertrófica.","E":"Endocardite infecciosa."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-292020","number":"292020","sourceNumber":"292020","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Em relação ao Lúpus Eritematoso Sistêmico (LES), é CORRETO afirmar:","options":{"A":"O diagnóstico de LES pode ser feito com razoável probabilidade, se pelo menos 5 dos 11\ncritérios de classificação do lúpus eritematoso sistêmico estiverem presentes.","B":"É comum estabelecer o diagnóstico de LES preenchendo 5 critérios da tabela de classificação\ndo LES, mesmo com o FAN (fator antinúcleo)\nnegativo.","C":"As taxas de sobrevivência de dez anos estão em torno de 50%. Em um percentual pequeno dos\npacientes, a doença segue um curso recidivante e remitente.","D":"Situações de gravidade no LES como glomerulonefrite, anemia hemolítica, miocardite,\nhemorragia alveolar, envolvimento do sistema\nnervoso central e trombocitopenia grave requerem\ntratamento com corticosteroides em altas doses por longos períodos (ex.: meses).","E":"Nos últimos anos, a aterosclerose acelerada associada à inflamação crônica tornou-se uma das\nprincipais causas de morte."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-257207","number":"257207","sourceNumber":"257207","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Paciente, portadora de esclerodermia sistêmica, em uso de ciclofosfamida mensal,\nprocura serviço médico com quadro de cefaleia,\nescotomas visuais e elevação da pressão arterial\npara 160 x 110 mmHg. Um hemograma revelou Hb = 9,6 g/dl, leucócitos = 6.700 cél/mm³.\n\nPlaquetas = 65.000/mm³ com hematoscopia, revelando esquizócitos circulantes. Apresentava\nelevação da ureia e da creatinina. Frente ao\nquadro, qual dos medicamentos a seguir está mais\nindicado para resolução do problema agudo?","options":{"A":"Furosemida.","B":"Captopril.","C":"Nifedipina.","D":"Hidralazina.","E":"Propranolol."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-284484","number":"284484","sourceNumber":"284484","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Sobre Lúpus Eritematoso Sistêmico (LES) e os autoanticorpos utilizados para seu\ndiagnóstico, é INCORRETO afirmar que:","options":{"A":"O antirribossomal P está associado com ocorrência de depressão ou psicose devida ao lúpus no\nsistema nervoso central.","B":"O fator antinuclear é o melhor teste de rastreamento e testes repetidamente negativos tornam\nimprovável o diagnóstico de LES.","C":"O Anti-La está em geral associado ao anti-Ro e associa-se a maior risco de nefrite.","D":"O anti-RNP não é específico para LES e é mais comum em negros do que em brancos.","E":"O Anti-histona está presente, mais frequentemente, no lúpus fármaco-induzido que no LES."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-273878","number":"273878","sourceNumber":"273878","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Homem de 35 anos é avaliado por piora da sua tosse no último mês. Evolui com sibilos\nque necessitam de terapia de resgate em vários dias da semana, assim como piora da sua\ncongestão nasal e rinorreia. Tem antecedente de asma persistente moderada e rinite desde seus\n20 e poucos anos. Há um mês, o paciente fora submetido à cirurgia para reparo de uma lesão de\nseu ligamento cruzado anterior e, desde então, apresenta dor residual diariamente. Além disso,\napresenta sinusites de repetição. Não apresenta sintoma de doença do refluxo gastroesofágico.\n\nFaz uso de salbutamol SOS, formoterol/budesonida 12 + 400 mcg 2x/dia e ibuprofeno. Ao exame\nfísico, seus sinais vitais estão normais. SpO2\n97% em ar ambiente. Apresenta hiperemia conjuntival\ne pólipos nasais em ambas as narinas. Ausculta pulmonar evidencia sibilos expiratórios. O resto do\nexame físico é normal. Laboratório evidencia IgE = 265 U/ml (valor de referência = 0?90 U/ml).\n\nLeucometria de 4.000/µL com 10% de eosinófilos no diferencial. Qual o tratamento inicial MAIS\nAPROPRIADO?","options":{"A":"pHmetria de 24 horas.","B":"Adicionar montelucast.","C":"Suspender o ibuprofeno e adicionar prednisona.","D":"Polipectomia nasal.","E":"Adicionar brometo de tiotróprio."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-240932","number":"240932","sourceNumber":"240932","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Paciente do sexo feminino, 40 anos, diabética e portadora de lúpus, apresentando\nelevação recente dos níveis pressóricos,\nsedimento urinário ativo (hematúria dismórfica e cilindros\ncelulares), proteinúria = 1,1 g/24h, além de hipocomplementemia e anticorpo anti-DNA positivo.\n\nInfere-se padrão histológico compatível com:","options":{"A":"Nefropatia diabética.","B":"Nefropatia hipertensiva.","C":"Nefrite lúpica proliferativa mesangial.","D":"Nefrite lúpica difusa.","E":"Nefrite lúpica membranosa."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-218185","number":"218185","sourceNumber":"218185","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Sobre as vasculites, assinale a alternativa ERRADA:","options":{"A":"Constituem grupo heterogêneo de doenças caracterizadas por inflamação de parede dos vasos\nsanguíneos, geralmente produzindo sua ruptura ou oclusão, com o consequente prejuízo da\nirrigação dos tecidos e órgãos acometidos.","B":"Podem ser classificadas de acordo com o tamanho dos vasos acometidos, por exemplo,\nvasculites de pequenos vasos (arterite de\nTakayasu e arterite de células gigantes), arterite de\nmédios vasos (vasculites ligadas ao ANCA como a granulomatose de Wegener, poliangeíte\nmicroscópica e síndrome de Churg-Strauss) e finalmente vasculite de pequenos vasos (poliarterite\nnodosa, e vasculites primarias do sistema nervoso central).","C":"A granulomatose de Wegener é uma vasculite granulomatosa caracterizada pelo acometimento\nde vias aéreas superiores e inferiores, bem\ncomo os rins. Pode cursar com inflamação e infecções\nrecorrentes, resistentes aos antibióticos, sinusites com secreção purulenta, ulceração nasal e/ou\nepistaxe.","D":"A Poliangeíte microscópica é a causa mais comum da síndrome pulmão-rim, frequentemente\ncom hemorragia alveolar por capilarite pulmonar com\nhemoptóicos e dispnéia.","E":"A síndrome de Churg-Strauss cursa com rinite alérgica, pólipos nasais, doença obstrutiva de vias\naéreas, eosinofilia, glomerulonefrite e neuropatia periférica"},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-185325","number":"185325","sourceNumber":"185325","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Qual das seguintes assertivas não é esperada em uma paciente lúpica, com anemia\nhemolítica autoimune por anticorpos quentes:","options":{"A":"Coombs direto positivo para IgG e C3.","B":"Hemoglobinúria de grande monta.","C":"Hemólise predominantemente extravascular.","D":"Provas cruzadas pré-transfusionais persistentemente positivas.","E":"Boa resposta terapêutica com gamaglobulina hiperimune."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-187646","number":"187646","sourceNumber":"187646","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"O Lúpus Eritematoso Sistêmico (LES) muitas vezes se manifesta com lesão renal\nsignificativa. A apresentação mais comum da lesão renal associada ao LES é:","options":{"A":"Pielonefrite infecciosa.","B":"Doença tubulointersticial.","C":"Glomerulonefrite por imunocomplexos.","D":"Pielonefrite pseudomembranosa.","E":"Nefrite vascular."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-155842","number":"155842","sourceNumber":"155842","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Sobre as vasculites, assinale a alternativa ERRADA:","options":{"A":"Constituem grupo heterogêneo de doenças caracterizadas por inflamação da parede dos vasos\nsanguíneos, geralmente produzindo sua ruptura ou oclusão, com o consequente prejuízo da\nirrigação dos tecidos e órgãos acometidos.","B":"Podem ser classificadas de acordo com o tamanho dos vasos acometidos, por exemplo,\nvasculites de pequenos vasos (arterite de\nTakayasu e arterite de células gigantes), arterite de\nmédios vasos (vasculites ligadas ao ANCA como a granulomatose de Wegener, poliangiite\nmicroscópica e síndrome de Churg-Strauss) e finalmente vasculite de pequenos vasos (poliarterite\nnodosa, e vasculites primárias do sistema nervoso central).","C":"A granulomatose de Wegener é uma vasculite granulomatosa caracterizada pelo acometimento\nde vias áreas superiores e inferiores, bem\ncomo os rins. Pode cursar com inflamação e infecções\nrecorrentes, resistentes aos antibióticos, sinusites com secreção purulenta, ulceração nasal e/ou\nepistaxe.","D":"A poliangiite microscópica é a causa mais comum da síndrome pulmão-rim, frequentemente\ncom hemorragia alveolar por capilarite pulmonar com\nhemoptoicos e dispneia.","E":"A síndrome de Churg-Strauss cursa com rinite alérgica, pólipos nasais, doença obstrutiva de vias\naéreas, eosinofilia, glomerulonefrite e neuropatia periférica."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-161846","number":"161846","sourceNumber":"161846","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"A fibromialgia é uma síndrome dolorosa não-inflamatória, frequente e de fisiopatologia\nainda pouco esclarecida. Analise as assertivas\nabaixo e escolha a que define as afirmações\nCORRETAS. I) Trata-se de síndrome dolorosa caracterizada por alodínia (redução do limiar de dor)\ne hiperalgesia (sensação álgica com estímulo normalmente inócuo).; II) São frequentes a presença\nde parestesia, cãibras, rigidez articular e edema subjetivo (sensação de edema) nos membros e\nnas articulações, além do quadro álgico; III) quando da avaliação dos tender points, a dor não\nobrigatoriamente apresenta simetria, podendo acometer apenas um dimidio, e/ou apresentar\ndiferenças em sua intensidade.; IV) A presença de alterações no exame osteoarticular exclui o\ndiagnóstico de fibromialgia.; V) Seu diagnóstico é de exclusão, sendo confirmado apenas depois de\nexames laboratoriais e radiológicos normais.","options":{"A":"I, II, III","B":"II, III e IV","C":"I, III, IV","D":"II, III","E":"I, IV"},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-160603","number":"160603","sourceNumber":"160603","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Em relação a púrpura de Henoch-Schonlein assinale a alternativa correta:","options":{"A":"Não há indicação de corticoterapia nos casos leves, mesmo na ocorrência de hematúria","B":"Pulso de corticosteroides deve ser utilizado na fase inicial, na presença de manifestações\ncutâneas ulceradas ou necrosantes.","C":"Os imunossupressores: azatioprina e metotrexate estão indicados no tratamento da\nglomerulonefrite progressiva que ocorre na doença grave.","D":"As manifestações do trato digestório nunca precedem as manifestações cutâneas e articulares.","E":"A artrite não deve ser tratada com anti-inflamatórios não hormonais, exemplo ibuprofeno,\nnaproxeno pelo risco de lesão renal."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-109031","number":"109031","sourceNumber":"109031","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"As colagenoses podem cursar com acometimento renal de vários padrões distintos.\nAssinale a associação VERDADEIRA:","options":{"A":"A síndrome de Sjögren primária cursa com nefrite intersticial crônica, cursando com isostenúria e\nacidose tubular renal.","B":"A artrite reumatoide cursa comumente com glomerulonefrite difusa e síndrome nefrítica.","C":"O padrão de acometimento renal mais tipicamente visto em pacientes lúpicos é a necrose\ntubular aguda.","D":"A crise renal observada em pacientes com esclerose sistêmica é mais observada na forma\nlimitada da doença.","E":"O padrão de acometimento renal típico na espondilite anquilosante é a glomerulonefrite\nrapidamente progressiva."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-85909","number":"85909","sourceNumber":"85909","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Mulher, 25 anos, portadora de lúpus eritematoso sistêmico diagnosticado há dois anos,\nevoluiu com episódio confirmado de trombose venosa profunda em membro inferior esquerdo após\niniciar inadvertidamente anticoncepcional hormonal oral de alta dosagem. Três meses após concluir\no período de anticoagulação plena com warfarínicos, realizou coagulograma que evidenciou TTPa\nalargado, que não corrigiu após o teste da mistura. O anticorpo mais provavelmente associado a\neste quadro é:","options":{"A":"Antifator VIII.","B":"Antibeta-2-glicoproteína l.","C":"Anti-DNAds.","D":"Anti-Ro.","E":"Anti-U1-RNP."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-322098","number":"322098","sourceNumber":"322098","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"A doença de Kawasaki é uma vasculite sistêmica que afeta vários órgãos e sistemas.\nSobre esta doença, analise as alternativas\nabaixo. I ? A maior parte dos casos ocorre após os 5\nanos de idade. II ? Cursa com aumento do número de plaquetas. III ? As aftas orais não fazem\nparte dos critérios diagnósticos. Sobre esta situação selecione a opção CORRETA.","options":{"A":"As afirmativas I e II são verdadeiras. A afirmativa III é falsa.","B":"As afirmativas I e III são verdadeiras. A afirmativa II é falsa.","C":"As afirmativas II e III são verdadeiras. A afirmativa I é falsa.","D":"As afirmativas I, II e III são verdadeiras.","E":"As afirmativas I, II e III são falsas."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-295716","number":"295716","sourceNumber":"295716","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Sobre a esclerose sistêmica com envolvimento cutâneo difuso, assinale a alternativa\ncorreta. I - O envolvimento pulmonar ainda\nque grave, é raro, e se caracteriza por hipertensão\narterial pulmonar. II - A crise renal esclerodérmica é muito comum, com alta taxa de letalidade.\nIII -\nAs alterações gastrintestinais envolvem somente o trato superior especialmente o esôfago.","options":{"A":"As afirmativas I e II são verdadeiras. A afirmativa III é falsa.","B":"As afirmativas I e III são verdadeiras. A afirmativa II é falsa.","C":"As afirmativas II e III são verdadeiras. A afirmativa I é falsa.","D":"As afirmativas I, II e III são verdadeiras.","E":"As afirmativas I, II e III são falsas."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-257514","number":"257514","sourceNumber":"257514","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Paciente de 42 anos de idade, do sexo feminino, relata 5 meses de evolução de dor\ngeneralizada, com aumento progressivo da intensidade. A paciente relata que a dor é difusa, e não\nobservou artrite no período. Relata apresentar fadiga e insônia inicial desde o início do quadro.\n\nNega comorbidades, nega uso de medicação contínua. Relata ter feito uso de analgésicos comuns\npara tratamento da dor. Ao exame apresenta dor\nà palpação de pontos sensíveis, sem outras\nalterações. Foram solicitados exames de VHS, proteína c reativa, hemograma completo, TSH,\npainel metabólico, FAN, anti-ssa, anti-ssb, anti ccp, fator reumatóide, creatinofosfoquinase,\nsorologias para HIV e doença de Lyme, anti-HCV que foram normais. Considerando a hipótese\ndiagnóstica principal, avalie as asserções a seguir e a relação causal proposta entre elas. I ? De\nforma comprovada por testes, pacientes com a condição apresentam hiperalgesia e alodinia\nPORQUE II ? a presença de mediadores inflamatórios ativam a transdução de sinais nos\nnociceptores intracelulares, determinando o aumento na produção, transporte e inserção na\nmembrana de canais iônicos ativados quimicamente e ativados por voltagem, causando\nsensibilização periférica.","options":{"A":"As asserções I e II são proposições verdadeiras, e a segunda é uma justificativa da primeira.","B":"As asserções I e II são proposições verdadeiras, mas a segunda não é uma justificativa da\nprimeira.","C":"A asserção I é uma proposição verdadeira e a asserção II é uma proposição falsa.","D":"A asserção I é uma proposição falsa e a asserção II é uma proposição verdadeira.","E":"As asserções I e II são proposições falsas."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-232660","number":"232660","sourceNumber":"232660","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Pré-escolar de 4 anos com febre elevada contínua há 6 dias e manchas na pele há 3\ndias. Ao exame observa-se erupção cutânea difusa e polimórfica, conjuntivite não exsudativa,\nrachadura de lábios com faringite não exsudativa, edema distal de mãos e pés. Em relação ao\ncaso, analise as assertivas abaixo. I - Uma ecocardiografia é necessária para a confirmação\ndiagnóstica. PORQUE; II - Na fase subaguda desta doença pode ocorrer a formação de\naneurismas coronarianos.","options":{"A":"As asserções I e II são proposições verdadeiras, e a segunda e? uma justificativa da primeira.","B":"As asserções I e II são proposições verdadeiras, mas a segunda não e? uma justificativa da\nprimeira.","C":"A asserção I e? uma proposição verdadeira e a asserção II e? uma proposição falsa.","D":"A asserção I e? uma proposição falsa e a asserção II e? uma proposição verdadeira.","E":"As asserções I e II são proposições falsas."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-174198","number":"174198","sourceNumber":"174198","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Escolar de sete anos apresentou há duas semanas um quadro de coriza, tosse e febre,\nde involução espontânea. Há três dias iniciou\ncom manchas avermelhadas pelo corpo,\npredominantemente em membros inferiores, acompanhadas de artralgia e febre baixa, sem prurido.\nAo exame lesões cutâneas purpúricas, maculopapulosas eritematosas, petéquias e equimoses\npredominantemente em membros inferiores, nádegas, dorsos dos pés e palmas das mãos.\n\nApresentava, também, dor à manipulação, edema sem flogose em tornozelos e mãos e dificuldade\nde deambulação. Sobre esta doença podemos afirmar\nque.; pg. 868 (Nelson)","options":{"A":"é mais grave na criança do que no adulto.","B":"a evolução para doença renal terminal é comum.","C":"o uso de corticóides melhora a evolução da lesão renal.","D":"pode ocorrer também após picada de inseto e vacinação.","E":"as lesões purpúricas devem estar presentes desde o início do quadro para o diagnóstico."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-148995","number":"148995","sourceNumber":"148995","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Em relação à fibromialgia assinale o conceito que estaria incorreto:","options":{"A":"Existe depressão associada em até 80% dos casos.","B":"São entidades associadas enxaqueca, dor têmporo-mandibular e cistite intersticial.","C":"Entram no diagnóstico diferencial síndrome de Sjögren, hepatite C , hipotireoidismo e HIV.","D":"Têm demonstrado efetividade terapêutica analgésicos, anti-inflamatórios não hormonais,\namitriptilina, duloxetina e gabapentina.","E":"Cerca de 20% dos pacientes com doenças reumáticas inflamatórias e degenerativas têm\nfibromialgia associada uma vez que situações\ndolorosas atuam gerando estímulos que alteram os\nprocessos centrais de processamento de dor."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-355914","number":"355914","sourceNumber":"355914","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"A síndrome antifosfolipídeo (SAF) é uma trombofilia adquirida mediada por\nautoanticorpos, caracterizada por trombose arterial ou venosa recorrente e/ou morbidade\ngestacional. Entre as manifestações clínicas relacionadas a SAF é CORRETO afirmar que:","options":{"A":"A trombose venosa, seja superficial ou profunda, ocorre primariamente nos membros superiores\ne frequentemente leva à embolia cerebral.","B":"A trombose venosa dos membros apresenta-se como úlceras isquêmicas na perna, gangrena\ndigital e necrose óssea vascular.","C":"O livedo reticular é provavelmente causado pelo edema das arteríolas decorrente da obstrução\nde grandes artérias por trombos.","D":"A trombose arterial afeta mais comumente as artérias do cérebro e se manifesta como\nenxaquecas e distúrbios cerebrovasculares."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-354956","number":"354956","sourceNumber":"354956","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Uma das principais características da fibromialgia é:","options":{"A":"Resposta favorável, de forma rápida, à administração de baixas doses de corticosteroides","B":"Elevação de alterações laboratoriais e diagnóstico eminentemente clínico","C":"Curso com acentuada elevação de velocidade de hemossedimentação","D":"Perfil de autoanticorpos semelhante àquele encontrado no lúpus eritematoso sistêmico"},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-358570","number":"358570","sourceNumber":"358570","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Analise os casos clínicos descritos a seguir e responda a qual doença exantemática\ncada um se refere. Caso 01: Incubação: 1 a\n4 dias Febre baixa, mal-estar, perda do apetite, dor de\ngarganta, linfadenopatia, concomitante ao rash. Rash: lesões vesiculares em mucosa, palato e\nlíngua e exantema papulovesicular acometendo mãos e pés, eventualmente nádega e região\ngenital. Forma crostas e desaparece entre 5 a 10 dias Caso 02: Febre alta por, no mínimo, 5 dias,\nExantema polimorfo: rash Maculopapular, Alterações de extremidade: eritema e/ou edema em\nmãos e/ou pés nas fase aguda e/ou descamação em dedo de luva na convalescência, Conjuntivite\nbilateral não exsudativa, Adenomegalia cervical não supurativa com 1,5cm ou mais de diâmetro\nCaso 03: O estado geral mantém-se inalterado ou ocorrem sintomas inespecíficos, como mal-estar,\nfebre, náuseas e vômitos. As lesões cutâneas em geral são assintomáticas, raramente\npruriginosas, e possuem de 1 a 10 mm de diâmetro, podendo fundir-se em placas. Pode ocorrer\nlinfadenopatia e, mais raramente, hepatoesplenomegalia e/ou quadro de hepatite anictérica aguda¹\n³","options":{"A":"Caso 01: Varicela / Caso 02: Escarlatina / Caso 03: Gianoti Crosti.","B":"Caso 01: Impetigo Bolhoso / Caso 02: Escarlatina / Caso 03: Eritema Infeccioso.","C":"Caso 01: Impetigo Bolhoso / Caso 02: Doença de Kawasaki / Caso 03: Gianoti Crosti.","D":"Caso 01: Síndrome mão-pé-boca / Caso 02: Doença de Kawasaki / Caso 03: Gianoti Crosti.","E":"Caso 01: Síndrome mão-pé-boca / Caso 02: Escarlatina / Caso 03: Eritema Infeccioso."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-370717","number":"370717","sourceNumber":"370717","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"O Lúpus Eritematoso Sistêmico (LES) é uma doença autoimune em que órgãos e\ncélulas sofrem algum dano inicialmente mediado\npor autoanticorpos e imunocomplexos ligados aos\ntecidos. Para diagnóstico pode-se utilizar os critérios publicados pelo European League Against\nRheumatism/American College of Rheumatology Classification Criteria for Systemic Lupus\nErythematosus (EULAR/ ACR). Em relação a essa patologia e aos critérios citados, podemos\nafirmar:","options":{"A":"A prevalência é maior em mulheres, sendo necessária a presença de pelo menos 4 critérios,\ncom pelo menos um na categoria clínica e um na\ncategoria imunológica.","B":"Biópsia renal com nefrite lúpica classe II ou nefrite lúpica classe V; Lúpus cutâneo agudo;\nTrombocitopenia (contagem de plaquetas < 100.000/mcL) são critérios presentes no EULAR/ACR.","C":"Alteração de Creatinina; Pleurite, Anti-SM positivo são critérios presentes no EULAR/ACR.","D":"A presença de autoanticorpos, dentre eles o FAN, em um indivíduo sem sintomas clínicos deve\nser considerada diagnóstica para o LES.","E":"A presença de anemia é critério presente no EULAR/ACR, independente de outras\nespecificações."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-341627","number":"341627","sourceNumber":"341627","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Sobre os autoanticorpos relacionados ao Lúpus Eritematoso Sistêmico (LES), assinale\na alternativa que apresenta a CORRETA correlação\nentre as colunas: 1. Anti-Ro. 2. Anti-histona. 3.\nAnti-DNA. 4. Anti-Sm. 5. Anti-La. ( ) Síndrome de Sjögren. ( ) LES neonatal. ( ) Lesão renal. ( )\nEspecificidade. ( ) LES induzido por drogas. Assinale a alternativa que apresenta a CORRETA\ncorrelação entre as colunas:","options":{"A":"5-1-3-4-2.","B":"3-2-4-5-1.","C":"2-4-1-3-5.","D":"1-3-5-2-4."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-320897","number":"320897","sourceNumber":"320897","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Paciente feminina, 22 anos de idade, refere dores articulares, lesões de pele em face e\nmãos, queda de cabelo e perda de peso involuntária, há 6 meses. Deu entrada na Unidade de\npronto atendimento com queixa de edema generalizado, há 3 dias. O exame físico mostrou pressão\narterial 168/98 mmHg, ausculta cardíaca e pulmonar sem alterações, lesões cutâneas eritematosas\nlevemente elevadas em regiões malares bilateralmente, lesões eritematosas em face dorsal de\nmãos, sobre as falanges proximais e médias, artrite em 3ª interfalangiana de mão direita e 2ª e 3ª\nmetacarpofalangianas de mão esquerda, anasarca, com sinal do cacifo em membros inferiores\n3+|4. Hemograma com anemia leve e pesquisa de anticorpos antinucleares (FAN) 1:160 padrão\npontilhado fino (valor de referência: menor que 1:80), creatinina 2,2 mg/dL. Assinale a alternativa\nque apresenta, corretamente, o resultado mais útil para estabelecer o diagnóstico mais provável.","options":{"A":"VDRL 1:8 (valor de referência: não reagente).","B":"Anticorpo anticitoplasma de neutrófilo (ANCA) 1:20 padrão perinuclear (valor de referência: não\nreagente).","C":"Anticorpo anti-Ro 146 U (não reagente: inferior a 20 U).","D":"Anticorpo anti-DNA dupla-hélice 1:160 (não reagente: inferior a 1/10).","E":"Fator reumatoide 18,5 U (não reagente: menor que 7 U)."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-343242","number":"343242","sourceNumber":"343242","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Mulher jovem interna com história de múltiplos episódios de tromboses arteriais e\nvenosos, além de histórico de 3 abortos de repetição. Deve ser portadora de:","options":{"A":"Lúpus eritematoso sistêmico","B":"Artrite reumatoide","C":"Granulomatose de Wegener","D":"Esclerodermia"},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-337904","number":"337904","sourceNumber":"337904","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Mulher, 28 anos, previamente hígida, apresentou acidente vascular cerebral isquêmico.\nFaz uso de anticoncepção oral há 09 anos.\nHistória familiar de mãe com ?trombose? aos 54 anos,\nsem causa etiológica aparente. Exames laboratoriais: Hemograma, metabólico, funções hepática e\nrenal, normais, assim como o ecocardiograma. Considerando que este evento foi em leito arterial,\nqual das situações abaixo devemos investigar? (DENNIS L. KASPER, STEPHEN L. HAUSER, J.\nLARRY JAMESON . Medicina Interna de Harrison, parte 15, Seção 2 - 19.Ed? 2016)","options":{"A":"Deficiência de proteína C","B":"Deficiência de proteína S","C":"Deficiência de Antitrombina III","D":"Deficiência de Fator V de Leiden","E":"Anticoagulante lúpico"},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-342769","number":"342769","sourceNumber":"342769","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Homem, 52 anos, procura atendimento médico de urgência devido dispneia, tosse e\ndesconforto torácico há um mês, com piora progressiva, evoluindo há dois dias com episódios de\nhemoptise. Na história pregressa, refere dois episódios de sinusite no último ano. Ex-tabagista há 5\nanos, carga tabágica de 10 anos/maço. Achados positivos na revisão de sistemas: astenia e perda\nponderal não intencional de cerca de 12kg. Exames laboratoriais iniciais demonstraram (valores\nreferência entre parêntesis): Hb 9,8g/dL (13-17g/dL) Ht 30% (40-50%) VCM 84fL (81-98) Leucócitos\n\n10.300 (ate 10500); 30%linfócitos, 2% Bastões, 58% Neutrófilos; 280.000plaquetas. (120.000 -\n450.000) Na 140mg/dL (135-145) K 3,9mg/dL\n(3,5-5,1); Creatinina 2,3mg/dL(0,5-1,3) Uréia\n105mg/dL (10-30) Urina tipo I: Proteína +++/4 (negativo); Nitrito negativo; Leucócitos 70.000/mL\n(até 1000/ml) Hemácias 120.000/mL (até 10/ml); VHS 58mm (até 10mm) PCR ultrassensível 8mg/L\n(<1); Baseado na história clínica e achados laboratoriais iniciais, assinale a alternativa que\ncontém\napenas as assertivas corretas. I O diagnóstico de Granulomatose com Poliangeíte deve ser\nconsiderado. II A presença de leucocitúria e hematúria torna o diagnóstico de infecção do trato\nurinário o mais provável. III Os sintomas de astenia, perda ponderal, anemia e aumento de provas\ninflamatórias são inespecíficos, mas corroboram para a possibilidade de vasculite. IV A dosagem de\nANCA antiproteinase 3 é importante para o diagnóstico. V A biópsia do tecido acometido pode\nrevelar vasculite granulomatosa necrosante. Assinale a alternativa com todas as afirmações\ncorretas:","options":{"A":"Apenas I, II, II e IV.","B":"Apenas I, II, IV e V.","C":"Apenas I, IV e V.","D":"Apenas III, IV e V.","E":"Apenas I, III e V."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-346932","number":"346932","sourceNumber":"346932","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Sobre a doença de Kawasaki sabe-se que é uma vasculite que ocorre especialmente\nem menores de 5 anos de idade. A febre\npersistente por mais de 5 dias é um dos pontos principais\npara suspeitar da doença. Assinale a alternativa que apresenta os cinco critérios clássicos\ndiagnósticos para definição da doença:","options":{"A":"Alterações de extremidades (eritema de palmas das mãos e planta dos pés e edema),\nconjuntivite bilateral sem exudato,\nlinfadenopatia cervical (>1,5 cm), anemia com trombocitopenia,\nexantema polimorfo.","B":"Conjuntivite bilateral sem exudato, linfadenopatia cervical (>1,5 cm), alterações em lábios e\ncavidade oral (fissuras, ?língua em framboesa?), alterações de extremidades (eritema de palmas\ndas mãos e planta dos pés e edema), exantema polimorfo.","C":"Alterações de extremidades (eritema de palmas das mãos e planta dos pés e edema), artrite de\ngrandes articulações, alterações neurológicas focais, linfadenopatia cervical (>1,5 cm), anemia com\ntrombocitopenia","D":"Linfadenopatia cervical (>1,5 cm), alterações em lábios e cavidade oral (fissuras, ?língua em\nframboesa?), alterações do nível de consciência, exantema polimorfo, aneurismas de coronárias.","E":"Conjuntivite bilateral sem exudato, alterações em lábios e cavidade oral (?língua em\nframboesa?), alterações de extremidades (eritema de palmas das mãos e plantas dos pés e\nedema), exantema polimorfo, anemia com linfocitose."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-342715","number":"342715","sourceNumber":"342715","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Lactente de 2 anos de idade com história de febre diária (39ºC) há 7 dias. Refere\nmelhora apenas com dipirona. Há 6 dias lábios\navermelhados e erupção no corpo. Há 4 dias olhos\nvermelhos. Em consulta de Pronto Socorro suspeita de escarlatina. Prescrito penicilina benzatina,\nsem melhora. Ao exame físico: irritabilidade evidente, língua em framboesa e exantema\nmáculopapular em tronco. Em relação ao caso é correto afirmar que:","options":{"A":"O tratamento de escolha é a corticoterapia EV.","B":"A irritabilidade e as lesões cutâneas devem ser decorrentes de meningite meningocócica.","C":"Provavelmente é uma escarlatina resistente à penicilina benzatina, internar e tentar tratamento\ncom antibiótico EV.","D":"A principal complicação é cardíaca.","E":"A plaquetopenia que ocorre na fase subaguda é um achado comum."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-343324","number":"343324","sourceNumber":"343324","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"A crioglobulinemia essencial é muito mais frequente na:","options":{"A":"Hepatite A.","B":"Hepatite B.","C":"Hepatite C.","D":"Hepatite D."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-298744","number":"298744","sourceNumber":"298744","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Uma das mais importantes causas de morbimortalidade em pacientes portadores de\nlúpus eritematoso sistêmico é o acometimento\nglomerular através das diversas formas de\nmanifestação da nefrite lúpica. A forma mais comum e considerada a mais grave de nefrite lúpica é:","options":{"A":"Nefrite Lúpica Focal.","B":"Nefrite Lúpica Difusa.","C":"Nefrite Lúpica Membranosa.","D":"Nefrite Lúpica Proliferativa Mesangial."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-298748","number":"298748","sourceNumber":"298748","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Sobre as vasculites, assinale a alternativa CORRETA:","options":{"A":"A Púrpura de Henoch-Schonlein é uma vasculite associada ao ANCA, que se apresenta em\nadultos jovens, comprometendo pele e articulações, poupando rins e trato gastrointestinal.","B":"Lupus Eritematoso Sistêmico, Endocardite Bacteriana e Síndrome do Anticorpo Antifosfolípide\nsão exemplos de doenças que podem apresentar\nmanifestações clínicas simulando uma vasculite\nsistêmica primária.","C":"A Granulomatose de Wegener e a Síndrome de Churg Strauss são exemplos de vasculites\nprimárias de vasos de grande calibre.","D":"São descritas como vasculites de vasos de calibre variável: Granulomatose com poliangeíte (de\nWegener) e granulomatose eosinofílica com poliangeíte (Churg-Strauss)."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-314821","number":"314821","sourceNumber":"314821","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Um homem caucasiano de 55 anos é admitido no hospital onde você trabalha com\nqueixa de febre, perda de peso e dores nos\njoelhos. O histórico médico pregresso inclui episódios\nde epistaxes misturado a coriza, rinite frequente, cefaleias e dor no ouvido. A tomografia de seios\nnasais revela pansinusite. O paciente fez uso de 2 semanas de antibioticoterapia. A pressão arterial\né de 150/90 mmHg, pulso é de 82 bpm e o paciente está afebril. Os achados positivos de exame\nfísico incluem presença de sangue coagulado nas narinas, secreção leve no ouvido esquerdo e\ncrepitantes em ambos os pulmões. A creatinina sérica é de 4,5 mg/dL (era de 1,1 mg/dL há 1 mês).\ncANCA é positivo, mas ANA negativo. O parcial de urina mostra 1+ proteinúria, 3+ de hematúria,\n\n20-30 hemácias e presença de cilindros hemáticos. O raio-x de tórax demonstra infiltrados\nbilaterais. Baseado nas informações acima, qual\ndos seguintes achados é o MENOS provável no\ncaso do paciente em questão?","options":{"A":"Detecção de cANCA através de imunofluorescência indireta.","B":"Presença de glomerulonefrite crescêntica e com lesões necrotizantes segmentares e focais em\nmicroscopia óptica.","C":"Grau de perda de função renal é diretamente relacionado com o percentual de lesões\nnecrotizantes glomerulares.","D":"Ausência frequente de deposição de imunoglobulinas na microscopia por imunofluorescência."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-292343","number":"292343","sourceNumber":"292343","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Qual das doenças reumatológicas a seguir apresenta a maior associação com o\nfenômeno de Raynaud?","options":{"A":"Artrite reumatoide.","B":"Dermatomiosite.","C":"Esclerose sistêmica.","D":"Lúpus eritematoso sistêmico.","E":"Síndrome de Sjögren."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-303034","number":"303034","sourceNumber":"303034","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"São constituintes frequentes de granulomatose eosinofílica com poliangiíte exceto:","options":{"A":"Infiltrados pulmonares à tomografia computadorizada de tórax com presença de bronquiectasias\nde tração e cistos esparsos.","B":"Eosinofilia persistente.","C":"Asma de início tardio e de difícil controle.","D":"Infecções recidivantes de vias aéreas superiores.","E":"Mononeurites múltiplas."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-314879","number":"314879","sourceNumber":"314879","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"São possíveis diagnósticos diferenciais que devem sem lembrados em casos de\nsíndromes rim-pulmão, EXCETO:","options":{"A":"Vasculite de Churg-Strauss.","B":"Síndrome de Goodpasture.","C":"Síndrome de Sjögren.","D":"Púrpura de Henoch-Schölein."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-314881","number":"314881","sourceNumber":"314881","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"O lúpus eritematoso sistêmico é uma doença autoimune que acomete diversos órgãos\ne sistemas e em alguns casos, pode ter um\nprognóstico reservado, dependendo da agressividade\nda doença. Para seu diagnóstico, são utilizados alguns critérios, sendo um deles a presença de\nalguns possíveis anticorpos. Cada um desses anticorpos se relaciona de forma mais importante\ncom um padrão de evolução da doença ou de acometimento de alguns órgãos. Com relação aos\nanticorpos que podem estar presentes no lúpus, relacione o anticorpo com a evolução ou\nacometimento a que está mais frequentemente relacionado: A. Anti-DNA B. Anti-Sm C. Anti-Ro D.\nAnticorpo anticardiolipina E. Anti-histona. ( ) anticorpo mais específico para lúpus. ( ) comum no\nlúpus induzido por drogas.( ) associação com acometimento renal (nefrite lúpica). ( ) associação\ncom bloqueio atrioventricular total (BAVT) congênito. ( ) associação com a síndrome\nantifosfolipídea. A sequência que preenche corretamente as colunas é:","options":{"A":"A ? E ? B ? C ? D.","B":"A ? C ? B ? E ? D.","C":"B ? D ? A ? C ? E.","D":"B ? E ? A ? C ? D."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-313011","number":"313011","sourceNumber":"313011","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Para diagnóstico de Lupus Eritematoso Sistemico (LES) pode-se utilizar os critérios\npublicados pelo European League Against Rheumatism/American College of Rheumatology\nClassification Criteria for Systemic Lupus Erythematosus (EULAR/ACR). Qual alternativa contém\napenas critérios incluídos no EULAR/ACR","options":{"A":"Biópsia renal classe II ou nefrite lúpica classe V; Lúpus cutâneo agudo; Trombocitopenia\n(contagem de plaquetas < 100.000/mcL)","B":"Biópsia renal com nefrite Lúpica classe IV; anti-DNA positivo; Anemia hemolítica com COOBS\ndireto negativo","C":"Alteração de Creatinina; Pleurite; Anti-SM positivo","D":"C3 baixo ou C4 baixo; ANCA positivo; Leucopenia","E":"Lúpus cutâneo agudo; Proteinuria > 500mg/24h; Aumento de transaminases"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-304697","number":"304697","sourceNumber":"304697","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Homem, 47 anos, caucasiano, refere que há 02 meses vem apresentando quadro de\nfebre, emagrecimento, artralgias, dor torácica\npleurítica e dor mesogástrica. Uma semana antes, ele\nnotou parestesia e paresia da mão esquerda. A pressão arterial é de 150/95 mmHg, (era\npreviamente normotenso) e os exames laboratoriais revelam anemia da doença crônica, aumento\ndo VHS e PCR e leucocitose polimorfonuclear. O diagnóstico mais provável é:","options":{"A":"Arterite de células gigantes","B":"Poliarterite Nodosa","C":"Granulomatose de Wegener","D":"Sarcoidose","E":"Vasculite Cutânea Leucocitoclástica"},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-292151","number":"292151","sourceNumber":"292151","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Em relação à doença de Kawasaki, considere as afirmativas a seguir. I. Associados à\nfebre, são critérios diagnósticos: alterações de lábios e cavidade oral, hiperemia conjuntival,\nalteração de extremidades, exantema polimorfo e linfadenopatia cervical. II. No período febril, há\nindicação de ácido acetilsalicílico (AAS), em baixas doses, para inibir agregação plaquetária. III.\nA\nindicação de imunoglobulina humana endovenosa se restringe aos casos em que houver\ncomprometimento cardíaco. IV. Os exames séricos da fase aguda demonstram leucocitose com\nneutrofilia e aumento das provas inflamatória. Assinale a alternativa correta.","options":{"A":"Somente as afirmativas I e II são corretas.","B":"Somente as afirmativas I e IV são corretas.","C":"Somente as afirmativas III e IV são corretas.","D":"Somente as afirmativas I, II e III são corretas.","E":"Somente as afirmativas II, III e IV são corretas."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-261564","number":"261564","sourceNumber":"261564","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Sobre o Lúpus Eritematoso Sistêmico, seu quadro clínico, exames complementares e\nseus novos critérios diagnósticos (ACR/EULAR 2019) é CORRETO afirmar:","options":{"A":"Seu quadro clínico segue um padrão de evolução progressiva: doença inicia leve, passa para\nintermitente até chegar na última fase e mais severa da doença. Pode ser fatal.","B":"FAN maior ou igual a 1/80 é critério de entrada e os principais anticorpos específicos para lúpus\npodem estar presentes (Anti-DNA ou Anti-Smith).","C":"Pericardite não é considerada como uma manifestação cardiovascular da doença.","D":"Fenômeno de Raynaud é uma doença específica, não podendo estar presente no LES.","E":"Sem os anticorpos anti-fosfolipides não existe a possibilidade desenvolvimento de nefrite\nlúpica."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-261130","number":"261130","sourceNumber":"261130","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Em relação ao lúpus eritematoso neonatal, assinale a alternativa que apresenta\ncorretamente os anticorpos capazes de atravessar a barreira placentária:","options":{"A":"anti-Ro-ssA, anti-La-ssB.","B":"anti-scl70, anti-centrômero.","C":"anti-Sm, anti-La-ssB.","D":"anti-Jo1, anti-RNP."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-261133","number":"261133","sourceNumber":"261133","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Menino, 10 anos de idade com história de febre baixa, cefaléia e dor abdominal há 10\ndias. Começou a apresentar lesões de pele urticariformes, que evoluíram para petéquias e\npúrpuras. Ao exame apresenta púrpura palpável em região de membros inferiores e nádegas,\nedema e artrite em joelhos e tornozelos. Os exames laboratoriais mostram anemia leve, 18000\nleucócitos/mm³, plaquetas 160.000/mm³. Sobre o caso clínico é correto afirmar que o diagnóstico\ndesse paciente é:","options":{"A":"Doença de Kawasaki","B":"Meningococcemia.","C":"Púrpura de Henoch-Schonnlein.","D":"Poliarterite nodosa."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-266139","number":"266139","sourceNumber":"266139","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Criança de 7 anos, sexo feminino, branca. Vem ao ambulatório com queixa de manchas\nem pele de início há 10 dias. Nega uso de\nqualquer medicação. Sem comorbidades. Sem\nantecedentes de doenças prévias. História de avó com artrite reumatoide. Ao exame apresenta-se\ncom sinais vitais normais e desenvolvimento pondero-estatural no percentil 50%. Bom estado geral,\ncom lesões vermelhas, elevadas, indolores, não pruriginosas que não desaparecem à digitopressão\ncom predomínio em nádegas, pernas e coxas. Adenomegalias cervical e inguinal de 0,5?1 cm de\ndiâmetro, indolores, fibroelásticas. Exame neurológico normal. O diagnóstico mais provável é\n(Proped ciclo 3 vol 4 pág.: 13):","options":{"A":"Púrpura trombocitopênica idiopática.","B":"Meningococcemia.","C":"Púrpura de Henoch-Schönlein.","D":"Artrite idiopática juvenil.","E":"Lúpus eritematoso sistêmico juvenil."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-265448","number":"265448","sourceNumber":"265448","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Arterites ou Vasculites são doenças vasculares decorrentes de lesão endotelial geradas\npor agentes irritantes ou mecânicos ao\nendotélio vascular (venoso e principalmente arterial) e\npodem gerar alteração dos exames de prova inflamatória como proteína C reativa, velocidade de\nhemossedimentação e interleucinas, fatores que geram e estimulam mais lesão endotelial, auxiliam\nno diagnostico da doença alem de servirem de marcadores de controle pós-tratamento. Os agravos\npodem acometer vários órgãos, sendo os mais comuns rins e pulmão. Das arterites ou vasculites\nabaixo, qual não esta relacionada as alterações dos exames de prova inflamatória, ou seja, não\ngeram alterações especificas ou significativas na velocidade de hemossedimentação (VHS) e\ninterleucina-6 (IL - 6):","options":{"A":"Tromboangeíte obliterante.","B":"Poliarterite nodosa.","C":"Síndrome de Chung-Strauss.","D":"Granulomatose de Wegener.","E":"Arterite de Takaysu."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-261145","number":"261145","sourceNumber":"261145","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Mulher, 50 anos, G3P2A1, menopausada há 3anos em uso de isoflavona, apresenta\nlesões ulceradas, dolorosas em região genital.\nRefere apresentar lesões orais semelhantes já há\nalguns anos. Ao exame físico apresenta lesão ulcerada em grandes lábios com fundo necrótico e\nhiperemia local. Exames complementares realizados: VDRL (negativo), HIV (negativo), Gram e\ncitologia da lesão (inespecífico). O diagnóstico mais provável é:","options":{"A":"Cancro mole.","B":"Sífilis primária.","C":"Doença de Behçet.","D":"Síndrome de Reiter."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-265481","number":"265481","sourceNumber":"265481","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"A fibromialgia é uma síndrome dolorosa crônica, caracterizada por dor\nmusculoesqueléticas generalizada. Sobre essa doença, assinale a alternativa correta:","options":{"A":"Na sua fisiopatologia estão presentes mecanismos que amplificam a atividade inibitória de\nestímulos nociceptivos ( sensibilização central).","B":"Costumam estar presentes além da dor, fadiga, alterações do sono e do humor e edema\narticular presente no exame físico.","C":"O tratamento da dor deve ser realizado de maneira contínua, principalmente com o análogos de\nopióides, que apresentam melhor controle da dor.","D":"Os antidepressivos duais, como duloxetina e venlafaxina, apesar de amplamente utilizados na\nfibromialgia, não mostraram superioridade ao placebo.","E":"O combate ao sedentarismo e o estímulo aos exercícios físicos estão entre as medidas mais\nreconhecidas como essenciais para o tratamento."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-238924","number":"238924","sourceNumber":"238924","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Homem, 45 anos, em consulta médica, refere congestão nasal e sinusite recorrentes,\nalém de dispneia, tosse com hemoptise e\nemagrecimento de oito quilos no último ano. Os exames\nlaboratoriais mostraram anemia normocrômica e normocítica, trombocitose, Velocidade de\nHemossedimentação (VHS) elevada, aumento nos níveis de ureia e creatinina e sedimento urinário\ncom proteinúria e leucocitúria. Frente a este quadro clínico o diagnóstico é:","options":{"A":"Granulomatose de Wegener.","B":"Poliarterite nodosa.","C":"Arterite de Takayasu.","D":"Arterite de células gigantes."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-241994","number":"241994","sourceNumber":"241994","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Sobre o Lúpus Eritematoso Sistêmico é correto afirmar:","options":{"A":"Glomerulonefrite rapidamente progressiva é sinal de bom prognóstico.","B":"É mais comum em homens jovens.","C":"Serosite, úlceras orais, fotossensibilidade e ?rash? malar não são critérios diagnósticos.","D":"Anticorpos antinucleares são os anticorpos mais frequentes.","E":"Sempre usa-se corticóide para tratamento, em todos os casos."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-251007","number":"251007","sourceNumber":"251007","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Paciente do sexo feminino, 47 anos, tem diagnóstico de Hipertensão Arterial Sistêmica,\nfaz uso de Losartana 50 mg ao dia com bom\ncontrole da pressão arterial. Tem histórico de 3\ngestações que resultaram em dois partos vaginas e um abortamento no primeiro trimestre.\n\nProcurou atendimento de urgência, pois acordou com perda de força no dimidio esquerdo. Exame\nneurológico mostra força grau 3 membro superior esquerdo e grau 4 em membro inferior esquerdo,\nsem outras alterações. Tomografia de crânio mostra área de isquemia aguda em território de artéria\ncerebral média direita. Assinale a opção na qual consta exame que NÃO faz parte da investigação\netiológica do Acidente Vascular Encefálico neste caso.","options":{"A":"Pesquisa de anticoagulante lúpico e anticorpo anticardiolipina.","B":"Sorologia para HIV.","C":"Perfil lipídico e glicemia de jejum.","D":"Pesquisa de complemento C3 e C4."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-251012","number":"251012","sourceNumber":"251012","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Os critérios mais utilizados atualmente para diagnóstico de Lupus Eritematoso\nSistêmico (LES) são os publicados pelo\nSystemic Lupus International Collaborating Clinics (SLICC).\nBaseado nesses critérios, qual das opções abaixo NÃO representa critérios diagnósticos para LES:","options":{"A":"Artrite, trombocitopenia, proteinuria > 500mg/24h, Lupus cutâneo agudo.","B":"Proteinuria > 500mg/24h, hipocomplementenemia, Fator Antinuclear - FAN positivo, anti-DNA\npositivo.","C":"Biópsia renal com nefrite Lúpica classe 4 e imunofluorescência positiva, anti-DNA positivo.","D":"Anemia hemolítica, trombocitopenia, pleurite, Anti-SM positivo."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-253812","number":"253812","sourceNumber":"253812","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Para diagnóstico da Doença de Kawasaki usa-se a presença de febre por mais de cinco\ndias de duração e a presença de quadro dos cinco critérios maiores. Assinale entre as opções\nabaixo, aquela que apresenta quatro dos critérios maiores:","options":{"A":"edema de mãos e pés, hiperemia da conjuntiva ocular, exantema, adenite cervical","B":"descamação palmo plantar, esplenomegalia, adenomegalia cervical, petéquias","C":"descamação peri-ungueal, adenomegalia, hepatomegalia, artralgia","D":"aneurisma coronariano, trombocitose, PCR elevado, exantema","E":"exantema polimorfo, piúria estéril, esplenomegalia, icterícia"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-238456","number":"238456","sourceNumber":"238456","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Qual dos antidepressivos abaixo seria mais indicado para uma paciente portadora de\nfibromialgia, visando tanto o controle dos sintomas da depressão quanto da dor?","options":{"A":"Paroxetina 25mg por dia","B":"Pregabalina 75mg por dia","C":"Duloxetina 30mg ao dia","D":"Fluoxetina 20mg ao dia","E":"Gabapentina 300mg ao dia"},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-238951","number":"238951","sourceNumber":"238951","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Indique a alternativa que contenha, respectivamente, um critério maior e um menor para\no diagnóstico de Tromboangeíte Obliterante:","options":{"A":"Fenômeno de Raynaud, ausência de diabete.","B":"Ausência de hipertensão, tabagismo importante.","C":"Sexo masculino, Fenômeno de Raynaud.","D":"Tabagismo importante, sexo masculino."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-253836","number":"253836","sourceNumber":"253836","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Homem, 60 anos, procura é encaminhado para internamento hospitalar devido a\nnáuseas e vômitos associado a quadro de\nastenia de início recente. Na unidade de pronto\natendimento é diagnosticada insuficiência renal. Durante o internamento evolui com dispneia, tosse\ne desconforto torácico com piora progressiva, evoluindo com episódios de hemoptise. Na história\npregressa, refere dois episódios de sinusite no último ano. Ex-tabagista há 5 anos, carga tabágica\nde 10 anos/maço. Achados positivos na revisão de sistemas: perda ponderal não intencional de\ncerca de 8kg, urina mais escura nos últimos dias e redução do volume urinário. Exames\nlaboratoriais iniciais demonstraram: Hb 10g/dL; Ht 30%; VCM 84fL; HCM 28pg; Leucócitos 12.300\n(30%linfócitos, 2% Bastões, 58% Neutrófilos); 450.000plaquetas. Na 140mg/dL; K 3,8mg/dL;\nCreatinina 4,5,0mg/dL; U 165mg/dL; Parcial de Urina: Proteína +++/4; Nitrito negativo; Leucócitos\n70.000/mL; Hemácias 100.000/mL; VHS 58mm; PCR ultrassensível 8mg/L; Baseado na história\nclínica e achados laboratoriais iniciais, assinale a alternativa que contém apenas afirmações\ncorretas.","options":{"A":"O diagnóstico de Granulomatose com Poliangeíte deve ser considerado caso haja consumo de\ncomplemento","B":"O diagnóstico de Granulomatose com Poliangeíte deve ser considerado, a positividade de\nanticorpos anticitoplasma de neutrófilos (ANCA) corrobora esse diagnóstico","C":"Os sintomas de astenia, perda ponderal, anemia e aumento de provas inflamatórias são\nsugestivos de processo neoplásico pulmonar","D":"Em biópsia renal espera-se lesão túbulo intersticial difusa com pouco ou nenhum acometimento\nglomerular e imunofluorescência positiva para IgG com padrão granular.","E":"O tratamento imunossupressor não altera o curso da doença e deve ser retardado até\nestabilidade clínica."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-242059","number":"242059","sourceNumber":"242059","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Uma menina de 3 anos apresenta história de febre há 5 dias, eritema de conjuntiva sem\nsecreção, eritema palmo-plantar, enantema de boca, língua em framboesa, sem exsudato em\norofaringe e exantema escarlatiforme. Sobre esse caso, podemos afirmar que:","options":{"A":"O tratamento inicial deve ser feito com corticoide e ácido acetilsalicílico","B":"Para confirmação do diagnóstico é necessário ecocardiograma","C":"A plaquetose é encontrada na primeira semana da doença","D":"Pode evoluir com hidropsia da vesícula biliar","E":"O aneurisma coronariano aparece, geralmente, na primeira semana"},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-242060","number":"242060","sourceNumber":"242060","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"L.F.G., 5 anos, apresenta dor abdominal em cólicas há 5 dias. Ao exame clínico\napresenta-se em regular estado geral, com\nabdome flácido, dor abdominal difusa à palpação, sem\nsinais de localização e sem visceromegalias. Há 1 dia, iniciou com quadro de petéquias e sufusões\nhemorrágicas na região de nádegas e membros inferiores. O hemograma mostrou hematócrito\n36%, Hb: 12g/dL, leucócitps: 9.000/mm³ (bastões=0, segmentados=67%, eosinófilos=3%,\nlinfócitos=20%, monócitos=10%, plaquetas= 210.00/mm3. A hipótese diagnóstica mais provável é:","options":{"A":"Leucemia linfoblástica aguda","B":"Meningococcema","C":"Purpúra trombocitopênica idiopática","D":"Púrpura de Henoch ? Schonlein","E":"Eczema hemorrágico"},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-205737","number":"205737","sourceNumber":"205737","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Mulher branca, 28 anos, relata estar apresentando há seis semanas um quadro de\nfadiga e febre baixa. Ao exame físico observa-se linfonodomegalia. Sabe-se que aos 15 anos foi\nsubmetida à esplenectomia devido a trombocitopenia e que já sofreu três abortos, sendo o último\nseguido de trombose venosa. Quais seriam os testes mais úteis para estabelecer o diagnóstico\ndesta paciente:","options":{"A":"AAN, anti-SS-A e Anti-SS-B.","B":"AAN, anticorpos anticardiolipina e anti-DNA.","C":"Anticorpos antineutrófilos e anti-histona.","D":"Fator reumatóide, AAN e anti-SCL-70.","E":"AAN, fator reumatoide e anticorpo anti-Lyme."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-200189","number":"200189","sourceNumber":"200189","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"O teste laboratorial Fator Antinuclear (FAN) é utilizado para a investigação de doenças\nautoimunes. Assinale a alternativa que apresenta, corretamente, o quadro clínico que justifica a\nsolicitação do FAN.","options":{"A":"Mulher, 15 anos de idade, com dor em face anterior de joelhos. Ao exame físico, apresenta\ncrepitação articular em joelhos, sem outras alterações.","B":"Mulher, 20 anos de idade, cuja mãe morreu em decorrência de lúpus eritematoso sistêmico. Sem\nqueixas e exame físico normal.","C":"Mulher, 35 anos de idade, com queixa de dor generalizada, distúrbio do sono e fadiga. Exame\nfísico sem alterações.","D":"Mulher, 45 anos de idade, com dor em 1º carpometacarpiano da mão direita. Ao exame físico,\nnota-se crepitação ao realizar a rotação passiva do primeiro dedo.","E":"Mulher, 60 anos de idade, com queixa de dor generalizada, xerostomia e xeroftalmia. Exame\nfísico sem alterações."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-208993","number":"208993","sourceNumber":"208993","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"A fibromialgia é uma síndrome clínica que causa dor generalizada, alterações no humor\ne no sono. Sobre essa doença, assinale a\nalternativa correta.","options":{"A":"Os novos critérios diagnósticos elaborados em 2010 ainda incluem a contagem de 11 tender\npoints.","B":"O uso de analgésicos opióides, como codeína e tramadol, devem ser estimulados, pois\nmelhoram o retorno dos pacientes ao trabalho.","C":"Exercícios físicos de resistência e ganho de força, são os únicos que provaram ter benefício no\ncontrole da dor.","D":"Os antidepressivos tricíclicos, inibidores da recaptação de serotonina e duais, são\nrecomendados no tratamento dessa síndrome.","E":"Apesar de não haver exame disgnóstico para fibromialgia, é importante realizar exame de\nimagem para cada local de dor do paciente."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-199448","number":"199448","sourceNumber":"199448","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Em relação à púrpura de Henoch-Schönlein em crianças, assinale alternativa\nCORRETA.","options":{"A":"Púrpura palpável é critério obrigatório para diagnóstico, para o qual deve-se ter também três dos\nseguintes critérios: dor abdominal, artrite ou artralgia, envolvimento renal ou biópsia com\nvasculite\nleucocitoclástica.","B":"Orquite, epididimite e torção de testículo podem fazer parte das apresentações extrarrenais da\ndoença.","C":"Invaginação intestinal pode ocorrer em até 5% dos casos, sendo a ileocecal a topografia mais\ncomum.","D":"O hemograma pode evidenciar anemia, sendo que a contagem de plaquetas geralmente é\nnormal, embora possa ocorrer plaquetopenia em até 5% dos casos.","E":"Os corticosteroides devem ser usados no tratamento de artrite e do envolvimento\ngastrointestinal, sendo os anti-inflamatórios não\nhormonais reservados para os casos com\nenvolvimento renal."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-210023","number":"210023","sourceNumber":"210023","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Adolescente com infecção respiratória recente, inicia quadro de febre, artralgia,\nglomerulonefrite e lesões purpurinas palpáveis\nque predominam em membros inferiores e região\nglútea. Biópsia cutânea revela depósitos de IgA. Qual é o diagnóstico que se impõe com esses\nachados: (DENNIS L. KASPER, STEPHEN L. HAUSER, J. LARRY JAMESON . Medicina Interna de\nHarrison, parte 15, Seção 2 -19.Ed? 2016.).","options":{"A":"Poliarterite nodosa","B":"Púrpura de Henoch-Schölein","C":"Febre reumática","D":"Lúpus eritematoso sistêmico","E":"Púrpura hipergamaglobulinêmica de waldenström"},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-210039","number":"210039","sourceNumber":"210039","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Paciente de 45 anos é avaliado por perda de função renal progressiva 03 semanas. Era\npreviamente saudável até início de maio/2015, quando passou a apresentar febre diária de até 38\n\n°C, lesões avermelhadas pelo corpo e dores articulares. Procurou assistência logo no início, tendo\nsido conduzido como virose inespecífica.\nExames da época estavam normais. O uso do analgésico\nprescrito pelo médico (dipirona) aliviou sintomas, mas as queixas persistiram e ao longo do mês foi\nvárias vezes a emergência para reavaliação. Exames do restante de maio mostram aumento\nprogressivo dos níveis da creatinina, hemogramas persistentemente normais e marcadores\ninflamatórios (VHS e PCR) aumentados. No início do mês seguinte, passou a queixar-se,\naditivamente, de perda de força no pé esquerdo e no braço direito. Exames resgatados do início de\njunho/2015 confirmaram a contínua a perda da função renal, sendo detectado proteinúria (3+/4)\npela primeira vez em amostra isolada de urina em 15/06/15. Neste mesmo dia, os demais exames\nsolicitados anteriormente mantinham seus padrões, porém, os níveis de complemento (C3 e C4)\nestavam consideravelmente diminuídos. O paciente, foi, então, encaminhado a este serviço, sendo\navaliado em 26/06/2015. As queixas eram as já citadas. O exame físico mostrava púrpura palpável\nmembros inferiores e abolição dos reflexos tendinosos profundos e comprometimento importante da\nforça em membros inferior esquerdo e superior direito, sem outras alterações relevantes\ndetectadas. Exames de admissão tinham basicamente as mesmas alterações já citadas com\nressalva à piora da função renal. O padrão da evolução dos níveis séricos de Creatinina foi o\nseguinte: Com base nestes dados, qual das hipóteses abaixo representa a etiologia mais provável\npara este caso? (DENNIS L. KASPER, STEPHEN L. HAUSER, J. LARRY JAMESON . Medicina\n\nInterna de Harrison, parte 15, Seção 2 -19.Ed? 2016.).","options":{"A":"Crioglobulinemia","B":"Púrpura de Henoch-Schönlein","C":"Vasculite de Churg-Strauss","D":"Poliarterite Nodosa","E":"Granulomatose de Wegener"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":["question_bank/media/medcurso/med-clinica-medica-med-clm-21/210039.png"],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-217858","number":"217858","sourceNumber":"217858","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Lucas 5 anos, apresenta dor abdominal em cólicas há 5 dias. No exame clínico\napresenta-se em regular estado geral, abdome\nflácido, dor abdominal difusa à palpação, sem sinais\nde localização, baço e fígado não palpáveis; há 1 dia iniciou quadro de petéquias e sufusões\nhemorrágicas na região das nádegas e membros inferiores. Hemograma com hematócrito de 36%,\nHemoglobina de 12 g/dl, leucócitos 9.000/mm3 (B = 0; S = 67%; E = 3%, L = 20%; M = 10%)\nPlaquetas = 210.000/mm3. A hipótese diagnóstica mais provável é:","options":{"A":"Leucemia linfoblástica aguda.","B":"Meningococcemia.","C":"Púrpura trombocitopênica idiopática.","D":"Púrpura de Henoch-Schönlein."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-217901","number":"217901","sourceNumber":"217901","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Uma menina de 10 anos apresenta febre há 10 dias associada a artrite nos joelhos e\nnos tornozelos, nódulos subcutâneos no couro\ncabeludo e hiperemia de palma das mãos. O quadro\nevoluiu para movimentos coreicos. Exames realizados mostravam anemia, plaquetopenia,\nhematúria microscópica e ASLO = 250U Todd. Diante do exposto assinale a opção que apresenta o\ndiagnóstico mais provável:","options":{"A":"Frebre reumática.","B":"Dermatomiosite juvenil.","C":"Artrite reativa pós-estreptocócica.","D":"Lúpus eritematoso sistêmico juvenil."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-172591","number":"172591","sourceNumber":"172591","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Vasculite é um processo clinicopatológico caracterizado por inflamação e dano aos\nvasos sanguíneos. Um grupo amplo e heterogêneo de\nvasculites pode resultar desse processo.\nCom relação às vasculites e suas respectivas alterações clinicolaboratoriais, numere a coluna II de\nacordo com sua correspondência com a coluna I. Coluna I: 1. Poliarterite nodosa; 2. Poliangiite com\ngranulomatose (Wegener); 3. Poliangiite microscópica; 4. Takayasu; 5. Vasculite por IgA\n\n(Henoch-Schönlein). Coluna II: ( ) Vasculite necrotizante acometendo pequenos vasos (capilares,\nvênulas e arteríolas); glomerulonefrite e\ncapilarite pulmonar; ANCA antimieloperoxidase positivo. ( )\nVasculite de pequenos vasos caracterizada por púrpura palpável (mais comumente localizada nas\nnádegas e membros inferiores), artralgias, sinais e sintomas gastrointestinais e glomerulonefrite.\n( )\nVasculite granulomatosa com envolvimento do trato respiratório alto e baixo associada com\nglomerulonefrite; ANCA antiproteinase-3 positivo. ( ) Arteriografia com a presença de aneurismas\nde artérias de pequeno e médio calibre no rim, fígado e vasculatura visceral. ( ) Estenose de\nartérias de médio e grande calibre com forte predileção pela aorta e seus ramos. Assinale a\nalternativa que apresenta a numeração CORRETA na coluna da direita, de cima para baixo.","options":{"A":"5?3?1?4?2.","B":"3?5?1?2?4.","C":"4?3?5?1?2.","D":"3?5?2?1?4.","E":"5?1?2?4?3."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-172577","number":"172577","sourceNumber":"172577","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"O lúpus eritematoso sistêmico juvenil é uma doença multissistêmica, autoimune e\ncrônica com baixa incidência. As principais causas de morbimortalidade nessa enfermidade são\ndecorrentes do comprometimento de:","options":{"A":"fígado e rins.","B":"pulmão e rins.","C":"coração e fígado.","D":"rins e sistema hematológico.","E":"rins e sistema nervoso central."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-178460","number":"178460","sourceNumber":"178460","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"O acometimento renal é responsável por grande parte da morbidade no lúpus\neritematoso sistêmico. Boa parte dos pacientes\ncom nefrite lúpica classe IV apresenta ausência de\nresposta ou apenas resposta parcial com o esquema de tratamento de indução com pulsoterapia\nmensal com ciclofosfamida por 6 meses. Nesses casos, há necessidade de terapia de reindução\ncom uma droga alternativa. Qual dos medicamentos a seguir foi testado em estudo controlado\nrandomizado e demonstrou eficácia semelhante à ciclofosfamida, sendo a opção de escolha para\nreindução de nefrite lúpica refratária?","options":{"A":"Azatioprina.","B":"Ciclosporina.","C":"Micofenolato.","D":"Belimumabe.","E":"Rituximabe."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-179022","number":"179022","sourceNumber":"179022","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Mulher, 28 anos, negra, apresentando há 20 dias febre, ganho de peso, redução do\nvolume urinário, sangramento gengival e epistaxes. Teve o pré-parto pré-termo devido à eclâmpsia,\nhá cinco meses. Já apresentou dois abortamentos não investigados. Ao exame clínico,\n\nconstatou-se palidez cutâneo-mucosa, úlcera oral palatina, equimoses, poliadenopatia, edema\ngeneralizado, PA: 180/120 mmHg, FC: 120 bpm. Exames laboratoriais: Hb= 4,2 g/dl, Ht=17%, Urina\ntipo 1: proteínas +++; cilindros granulosos; Plaquetas=28.000 céls/mm3; Radiografia de tórax=\naumento da área cardíaca e borramento dos seios costofrênicos; Tempo de\nProtrombina=normal;TTPa= aumentado (paciente/controle=1,5). Os diagnósticos desta paciente\nsão: (Medicina Interna - Harrison - 19.ed. Parte 13 e Parte 15, Seção 2.)","options":{"A":"Poliarterite nodosa; infecção urinária.","B":"Síndrome do anticorpo antifosfolipídeo, coagulação intravascular disseminada; linfoma.","C":"Leucemia aguda; choque circulatório devido à infecção urinária","D":"Lúpus eritematoso sistêmico, nefrite lúpica; síndrome do anticorpo antifosfolipídeo","E":"Sida; choque séptico."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-159820","number":"159820","sourceNumber":"159820","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Paciente apresenta quadro agudo de comprometimento pulmonar e renal com dosagem\npositiva para ANCA-C. O diagnóstico de granulomatose com poliangeíte (Síndrome de Wegener) é\nconfirmado por inflamação granulomatosa em biópsia renal. Sobre o diagnóstico:","options":{"A":"É considerada uma vasculite de pequenos vasos, como a Poliangeíte microscópica e a vasculite\npor IgA.","B":"É considerada uma vasculite de pequenos vasos, como a poliangeíte nodosa e a arterite de\ncélulas gigantes.","C":"É considerada uma vasculite de médios vasos, como a Poliangeíte nodosa e a vasculite por IgA.","D":"É considerada uma vasculite de médios vasos, como a Poliangeíte microscópica e a doença de\nKawasaki."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-149994","number":"149994","sourceNumber":"149994","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"A síndrome dos anticorpos antifosfolípides é uma trombofilia adquirida mediada por\nautoanticorpos caracterizada por episódios recorrentes de trombose arterial e venosa. Um exame\nutilizado para o diagnóstico dessa síndrome é o anticorpo:","options":{"A":"Antibeta-2-glicoproteína.","B":"Antiaquaporina 4.","C":"Antitrombina.","D":"Antirreticulina IGA.","E":"Antiendomísio IGM."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-153204","number":"153204","sourceNumber":"153204","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"A forma de endocardite não bacteriana que pode ser observada nos pacientes com\nlúpus eritematoso sistêmico é denominada de:","options":{"A":"Loeffler.","B":"Libman-Sacks.","C":"Roth.","D":"Osler.","E":"Peutz-Jeghers."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-151321","number":"151321","sourceNumber":"151321","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Várias afecções devem ser incluídas no diagnóstico diferencial de doença de Kawasaki,\nEXCETO:","options":{"A":"Escarlatina.","B":"Artrite idiopática juvenil.","C":"Infecções virais (rubéola, sarampo,adenovírus, enterovírus, vírus Epstein-Barr).","D":"Síndrome de Stevens-Johnson.","E":"Síndrome de West."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-153231","number":"153231","sourceNumber":"153231","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"As vasculites são doenças raras na faixa etária pediátrica e podem ser classificadas de\nacordo com as manifestações cutâneas e sistêmicas. A síndrome vasculítica mais frequente em\ncrianças e adolescentes é a Púrpura de Henoch-Schönlein (PHS). A PHS também pode ser\nconhecida por:","options":{"A":"Poliangeite microscópica.","B":"Arterite de Takayasu.","C":"Púrpura trombocitopênica.","D":"Púrpura anafilactoide.","E":"Angeitegranulomatosa."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-153219","number":"153219","sourceNumber":"153219","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"O lúpus neonatal é um modelo de autoimunidade adquirida passivamente pela\npassagem transplacentária de anticorpos maternos pelo\nfeto. O quadro clínico caracteriza-se pelo\nlúpus cutâneo e/ou alteração cardíaca associada ou não a outras manifestações sistêmicas. O\nenvolvimento cardíaco mais frequente que encontramos é:","options":{"A":"Bloqueio cardíaco completo ou de 3° grau.","B":"Bloqueio Atrio Ventricular de 2° grau.","C":"Transposição de grandes vasos.","D":"Drenagem pulmonar anômala.","E":"Defeito do septo ventricular ou atrial ."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-130351","number":"130351","sourceNumber":"130351","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Em relação à leucemia linfoide aguda na infância, é CORRETO afirmar que:","options":{"A":"A hiperdiploidia associa-se a um mau prognóstico.","B":"85% dos casos são de origem T-derivada.","C":"O prognóstico é mais favorável para lactentes abaixo de um ano de vida.","D":"3 a 5% dos pacientes têm a translocação t(9:22)(q34;q11).","E":"A contagem de leucócitos acima de 50.000/mm\n3 indica prognóstico favorável."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-128945","number":"128945","sourceNumber":"128945","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Pré-escolar de quatro anos, sexo feminino, apresenta há seis semanas dor nos\nmembros inferiores e dificuldade de deambular. O\nquadro vem evoluindo com febre baixa\nintermitente, dor articular, palidez e episódios de epistaxe. Exame físico: hipocorada; equimoses\ndifusas em membros; linfadenomegalia cervical e inguinal; hepatoesplenomegalia. O exame\ncomplementar indicado inicialmente para a investigação diagnóstica é:","options":{"A":"Hemograma.","B":"Coagulograma.","C":"Cintigrafia óssea.","D":"Dosagem de ácido ascórbico.","E":"Pesquisa de anticorpo antinuclear."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-106066","number":"106066","sourceNumber":"106066","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Assinale a alternativa verdadeira a respeito da esclerodermia:","options":{"A":"Os órgãos mais comumente afetados na esclerose sistêmica são os pulmões, rins e sistema\nnervoso central.","B":"O fenômeno de Raynaud costuma ser a primeira manifestação e visto em mais de 80% dos\ncasos.","C":"A fadiga, perda de peso e principalmente febre são achados muito frequentes.","D":"Fibrose pulmonar e hipertensão pulmonar são manifestações comuns da esclerodermia, sendo a\nfibrose mais comum na forma limitada (CREST) e a hipertensão pulmonar na forma difusa.","E":"O anticorpo anti-Scl-70 (antitopoisomerase) é característico da esclerodermia, positivo em mais\nde 70% das formas difusas."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-102819","number":"102819","sourceNumber":"102819","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"As neoplasias malignas mais frequentes na criança diferem daquelas típicas do adulto.\nNa criança os tumores malignos tendem a\napresentar menos períodos de latência, crescem quase\nsempre rapidamente, são geralmente invasivos e respondem melhor à quimioterapia. Sobre as\nneoplasias na infância é correto afirmar que a mais prevalente é:","options":{"A":"Retinoblastoma.","B":"Leucemia linfoide.","C":"Leucemia mieloide.","D":"Linfoma de Hodgkin.","E":"Turmor de Wilms."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-79020","number":"79020","sourceNumber":"79020","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Homem de 20 anos de idade, procedente do nordeste, apresenta emagrecimento\nimportante há 6 meses, com aumento de volume\nabdominal. Refere episódios de fezes amolecidas,\nsem muco ou pus. Ao exame físico apresenta-se descorado (2+/4+) e com adenomegalia cervical;\no fígado está palpável a 5 cm do rebordo costal direito e a 6 cm do apêndice xifoide; o baço é\npalpável a 7 cm do rebordo costal esquerdo. Apresenta hemoglobina de 8,0 g/dl, hematócrito de 27\npor cento, leucócitos de 2.500/mm3, plaquetas de 60.000/mm3 e parasitológico de fezes positivo\npara ovos de Schistosoma mansoni. A conduta para este caso será:","options":{"A":"iniciar quimioterapia imediatamente, pois a doença já está em estadiamento avançado.","B":"medicar com oxamniquine e observar a melhora clínica e laboratorial que ocorrerá em 1 semana.","C":"realizar esplenoportografia para investigar uma possível hipertensão portal.","D":"realizar esplenectomia, para impedir um sequestro ainda maior de elementos sanguíneos.","E":"realizar mielograma com biópsia de medula óssea, para elucidar o diagnóstico."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-81735","number":"81735","sourceNumber":"81735","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Os cloromas podem ser encontrados em crianças portadoras de:","options":{"A":"Neuroblastoma.","B":"Rabdomiossarcoma.","C":"Leucemia mielocítica aguda.","D":"Melanoma.","E":"Glioma."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-81424","number":"81424","sourceNumber":"81424","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Homem, 58 anos, negro, procedente de Curitiba, é trazido ao pronto-socorro sonolento\ne confuso. Seu acompanhante relatou que o mesmo\nvem apresentando emagrecimento e dores\nósseas nos últimos meses, além de náuseas e vômitos há 3 dias. Ao exame físico: paciente\nconfuso e hipocorado ++/4+. Pulso: 84 bpm, PA: 130/80 mmHg, com restante do exame físico\nnormal. Hemograma, Hb: 8,0, normocitose e normocromia. Leucócitos: 4500/mm3 (Bt: 2%, Seg:\n65%, Eos: 1%, Baso: 0%, Linf: 28%, Mo: 4%). Plaquetas: 120.000/mm3. Presença de Roleaux.\n\nCreatinina: 3,5 mg/dl. Eletroforese de proteínas, Albumina: 2,5 mg/dl, ?1: 0,2 g/dl, ?2: 0,9 g/dl,\n?:\n1,2 g/dl, ?: 2,8 g/dl, com suspeita de\nparaproteína. Radiografia de tórax com osteoporose difusa em\nvértebras e arcos costais. Em relação a este caso clínico, qual a hipóstese diagnóstica e a\ninvestigação a ser proposta?","options":{"A":"metástase óssea, mapeamento do esqueleto por cintilografia óssea.","B":"osteomielite, hemocultura.","C":"metaplasia mieloide agnogênica, aspirado de medula óssea.","D":"mieloma múltiplo, imunoeletroforese de proteínas.","E":"doença de Hodgkin, pesquisa de células de Reed-Sternberg."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-58785","number":"58785","sourceNumber":"58785","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"As imunoglobulinas são produtos de células B diferenciadas e responsáveis pela via\nhumoral da resposta imune. Sobre as imunoglobulinas, é INCORRETO afirmar:","options":{"A":"A imunoglobulina M (IgM) é uma molécula grande, de alto peso molecular, que ativa o\ncomplemento pela via clássica.","B":"A imunoglobulina A (IgA) é predominante em secreções, presente na saliva e nas lágrimas.","C":"A imunoglobulina E (IgE) participa da resposta de hipersensibilidade imediata (tipo I) e está\nenvolvida nas respostas alérgicas e contra diversos parasitas.","D":"A imunoglobulina D (IgD) está presente em pequena concentração no plasma e cruza a barreira\nplacentária.","E":"A imunoglobulina G (IgG) representa aproximadamente 80% das imunoglobulinas séricas e é a\nprincipal responsável pela resposta imune secundária, após a reexposição ao antígeno."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-61318","number":"61318","sourceNumber":"61318","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Um homem de 19 anos é admitido no hospital, 2 semanas após completar o primeiro\nciclo de quimioterapia para tratamento de\nleucemia linfoide aguda. Sua temperatura é de 39°C e no\nseu exame físico não é encontrado nenhum sinal aparente de infecção, sua radiografia de tórax é\nnormal mostrando posicionamento de cateter port-o-cath em átrio direito, o hemograma mostra 300\nleucócitos totais/mm³. São coletadas culturas. Quais dos seguintes passos é o mais apropriado\npara este caso?","options":{"A":"Iniciar tratamento antiestafilocóccico pela possibilidade de bacteremia relacionada a cateter\ncentral.","B":"Administrar antibióticos de largo espectro visando cobertura para Gram-negativos entéricos e\nPseudomonas aeruginosa.","C":"Esperar resultados das culturas e outros exames diagnósticos, sabendo-se que a infecção neste\npaciente pode ser causada por qualquer microrganismo.","D":"Iniciar profilaxia oral para fungo e bactéria.","E":"Administrar antifúngico endovenoso."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-64150","number":"64150","sourceNumber":"64150","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Paciente que é submetido a transplante de medula óssea alogênico e/ou portador de\nleucemia mieloide aguda, no período de neutropenia severa tem grande risco do desenvolvimento\nde infecção. Em especial infecção fúngica invasiva. Das opções a seguir, qual exemplifica um fungo\nfilamentoso muito comum responsável por doença fúngica invasiva neste cenário?","options":{"A":"Candida glabrata.","B":"Candida albicans.","C":"Cryptococcus neoformans.","D":"Aspergillus fumigatus.","E":"Histoplasma capsulatum."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-60699","number":"60699","sourceNumber":"60699","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"A respeito da patologia oncológica na infância, assinale a alternativa CORRETA:","options":{"A":"A leucemia linfocítica aguda constitui a neoplasia maligna mais comum da infância.","B":"O tumor de Wilms, quando presente bilateralmente, tem pior prognóstico.","C":"O neuroblastoma ocorre com maior frequência em crianças maiores de 5 anos.","D":"Os tumores ósseos malignos são raros na puberdade devido ao efeito protetor que os picos\nhormonais têm sobre o desenvolvimento destas patologias.","E":"Os tumores primários do sistema nervoso central são muito raros na infância e se manifestam\nprincipalmente com sinais e sintomas de hipertensão intracraniana."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-32049","number":"32049","sourceNumber":"32049","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Paciente de 67 anos, sexo masculino, branco. Há 6 meses com história de\nemagrecimento, astenia progressiva e dor em\nhipocôndrio esquerdo. Ao exame clínico: palidez\ncutâneo-mucosa e baço palpável a 8 cm do rebordo costal esquerdo. Trouxe um hemograma com\nos seguintes dados: hemoglobina de 11 g/dl; VG = 33%; Leucócitos = 11.000, com diferencial\ndentro do normal; Plaquetas = 78.000/mm³. Descrição no hemograma com presença de dacriócitos\ne 3 eritroblastos. Dentre as hipóteses diagnósticas abaixo, qual é a mais provável?","options":{"A":"Leucemia mieloide crônica.","B":"Leucemia linfoide crônica.","C":"Mielodisplasia.","D":"Anemia aplástica.","E":"Mielofibrose primária."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-32235","number":"32235","sourceNumber":"32235","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Em relação às leucemias, é CORRETO afirmar que:","options":{"A":"As leucemias mieloides agudas correspondem a 50% das leucemias na infância.","B":"O pico de incidência da leucemia linfoide aguda ocorre em menores de 1 ano e em\nadolescentes.","C":"Hipertrofia gengival, coagulação intravascular disseminada e cloromas são manifestações\nclínicas mais frequentes na leucemia linfoide aguda.","D":"As translocações t(4;11) e t(9;22) estão relacionadas a melhor prognóstico nas leucemias\nlinfoides agudas.","E":"A neutropenia febril é uma complicação frequente do tratamento quimioterápico das leucemias,\nsendo necessária intervenção rápida com início\nde antibioticoterapia endovenosa."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-34453","number":"34453","sourceNumber":"34453","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Assinale a alternativa que corresponde às alterações cromossômicas de pior\nprognóstico nas crianças com leucemia linfoide aguda.","options":{"A":"Hiperdiploidia, cromossomo Filadélfia, t(4;11).","B":"Hipodiploidia, cromossomo Filadélfia, t(15;17).","C":"Hiperdiploidia, cromossomo Filadélfia, t(15;17).","D":"Hipodiploidia, cromossomo Filadélfia, t(4;11).","E":"Hipodiploidia, rearranjos dos genes TEL/AML1."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-32070","number":"32070","sourceNumber":"32070","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Sobre as leucemias na infância, assinale a alternativa INCORRETA:","options":{"A":"Os tumores extramedulares presentes na Leucemia Mielocítica são chamados cloromas.","B":"A imunofenotipagem pode definir a linhagem celular quando a morfologia é inconclusiva.","C":"Adenomegalia, sangramentos, artrite e dores ósseas são os sintomas mais frequentes da\nLeucemia Linfocítica Aguda.","D":"Os lactentes de baixa idade costumam ter pior prognóstico.","E":"A infiltração medular e de outros órgãos é muito frequente na Leucemia Linfocítica Aguda."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-22736","number":"22736","sourceNumber":"22736","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"No momento do diagnóstico de uma leucemia aguda em crianças, deve-se pesquisar\no acometimento do sistema nervoso central através\nde que exame?","options":{"A":"Exame neurológico completo.","B":"Tomografia de crânio.","C":"Ressonância magnética de crânio.","D":"Análise do liquor.","E":"Análise do liquor e ressonância magnética de crânio."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-22781","number":"22781","sourceNumber":"22781","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Qual é o tratamento de escolha para crianças com leucemia mieloide crônica?","options":{"A":"Busulfan.","B":"Mesilato de imatinibe.","C":"Interferon alfa.","D":"Citarabina.","E":"Transplante de medula óssea."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-22722","number":"22722","sourceNumber":"22722","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Com relação à Leucemia Linfocítica Crônica (LLC) todas as afirmativas estão corretas,\nEXCETO:","options":{"A":"A LLC tem baixa atividade mitótica.","B":"A deleção 17p está ligada a pior prognóstico.","C":"A deleção 13q está associada a pior prognóstico.","D":"A deleção 11q está associada a pior prognóstico.","E":"Anormalidades citogenéticas estão presentes em 40-50% dos casos de LLC."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-22751","number":"22751","sourceNumber":"22751","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Afirmamos que o paciente é portador de anemia aplástica grave quando apresenta\nmedula óssea hipocelular com hemograma mostrando:","options":{"A":"Neutrófilos: < 500/ul; Plaquetas: < 20.000/ul; Reticulócitos corrigidos: < 1%.","B":"Neutrófilos: < 500/ul; Plaquetas: 40.000/ul; Reticulócitos corrigidos: 60.000/ul.","C":"Neutrófilos: 1.000/ul; Plaquetas: 50.000/ul; Reticulócitos corrigidos: < 20.000/ul.","D":"Neutrófilos: > 1500/ul; Plaquetas: < 20.000/ul; Reticulócitos corrigidos: 50.000/ul.","E":"Neutrófilos: > 1.000/ul; Plaquetas: 150.000/ul; Reticulócitos corrigidos: 2%."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-22317","number":"22317","sourceNumber":"22317","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Criança com 2 anos de idade apresenta febre persistente, linfonodomegalia e\nhepatoesplenomegalia. Hemograma demonstra anemia, leucopenia e plaquetopenia. Aspirado de\nmedula óssea afastou a hipótese de leucemia. Foi então pensado em síndrome hemofagocítica.\nPara esse diagnóstico, espera-se encontrar:","options":{"A":"hipofibrinogenemia, hipertrigliceridemia, hiperferritinemia","B":"hiperfibrinogenemia, hipertrigliceridemia, ferritina normal","C":"hipofibrinogenemia, hipercolesterolemia, VCA-IgM anti Epstein-Barr reagente","D":"hiperfibrinogenemia, hipertrigliceridemia, ferritina diminuída","E":"hiperfibrinogenemia, hipercolesterolemia, ferritina normal"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-21-22322","number":"22322","sourceNumber":"22322","collectionBlock":"med:med-clinica-medica-med-clm-21","collectionLabel":"MED · MED CLM 21","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 21","subtopic":"","stem":"Criança com leucemia aguda apresenta Hb = 6,0 g/dl, leucócitos = 350.000/mm³,\nplaquetas = 15.000/mm³. Entre os cuidados\nemergenciais, sabe-se que NÃO deve ser prescrito:","options":{"A":"Transfusão simples de concentrado de hemácias.","B":"Leucoaférese.","C":"Concentrado de plaquetas.","D":"Corticoterapia.","E":"Exosanguineotransfusão."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 21/MED CLM 21.txt","sourceLabel":"MED · MED CLM 21","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 21","MED"],"answerSource":"explicit","commentDeferred":true}]};
